        public ActionResult Outer_color()
        {
            var userid = User.Identity.GetUserId();

            var vv = db.changecolors.Where(a => a.UserId == userid && a.Role == "ADMIN").ToList();
            if (vv.Count > 0)
            {
                ViewBag.insidecolor = vv.FirstOrDefault().adminandouterheadercolor ?? "";
            }
            //outside selected menu and mouse hover menu color
            var mm = db.tblMenuColors.ToList();
            if (mm.Count > 0)
            {
                ViewData["selected"] = mm.FirstOrDefault().SelectedColor;
                ViewData["menu"] = mm.FirstOrDefault().MenuColor;
            }
            else
            {
                ViewData["selected"] = "#c0c0c0";
                ViewData["menu"] = "#c0c0c0";
            }
            //seleted outside home color 
            var hh = db.changecolors.Where(a => a.UserId == userid && a.Role == "ADMIN").ToList();
            if (hh.Count > 0)
            {

                var cc = hh.FirstOrDefault().multipaloutercolor;
                if (cc == "" || cc == null)
                {
                    ViewData["first"] = "";
                    ViewData["second"] = "";

                }
                else
                {
                    string[] color = cc.Split(',', ')');
                    string hexcode = color[1].ToString();
                    string rgbcode = color[2].ToString();
                    ViewData["first"] = hexcode;
                    ViewData["second"] = rgbcode;

                }
                //ViewBag.insidecolor = vv.FirstOrDefault().adminandouterheadercolor;
            }
            else
            {
                ViewData["first"] = "#c0c0c0";
                ViewData["second"] = "#c0c0c0";
            }

            return View();
        }
        public ActionResult Outercolorchange(string color, string first, string second)
        {

            var userid = User.Identity.GetUserId();
            TempData["default"] = color;
            var outsidecolor = "";
            if (first != null && second != null)
            {
                first = "#" + first + "";
                second = "#" + second + "";
                TempData["first"] = first;
                TempData["second"] = second;
                outsidecolor = "linear-gradient(to right," + first + "," + second + ")";
            }
            var admin = "ADMIN";
            changecolor cc = new changecolor();
            var roletype = db.changecolors.Where(p => p.Role == admin).ToList();
            var role = roletype.Count == 0 ? "" : roletype.SingleOrDefault().Role;
            var v = db.changecolors.FirstOrDefault();
            if (role == admin)
            {
                var id = (from tbl in db.changecolors where tbl.UserId == userid select tbl).SingleOrDefault();
                id.UserId = string.IsNullOrWhiteSpace(userid) ? v.UserId : userid;
                id.Role = string.IsNullOrWhiteSpace(admin) ? v.Role : admin;
                id.adminandouterheadercolor = string.IsNullOrWhiteSpace(color) ? v.adminandouterheadercolor : color;
                id.multipaloutercolor = string.IsNullOrWhiteSpace(outsidecolor) ? v.multipaloutercolor : outsidecolor;
                db.SaveChanges();
                return RedirectToAction("Outer_color");
            }
            else
            {
                cc.UserId = userid;
                cc.Role = "ADMIN";
                cc.adminandouterheadercolor = color;
                cc.multipaloutercolor = outsidecolor;
                db.changecolors.Add(cc);
                db.SaveChanges();
                return RedirectToAction("Outer_color");
            }
        }
        public ActionResult OuterMenuColor(string selected, string menu)
        {
            selected = "#" + selected + "";
            menu = "#" + menu + "";
            TempData["selected"] = selected;
            TempData["menu"] = menu;
            tblMenuColor mcolor = new tblMenuColor();
            var vv = db.tblMenuColors.FirstOrDefault();
            if (vv != null)
            {
                vv.SelectedColor = string.IsNullOrWhiteSpace(selected) ? vv.SelectedColor : selected;
                vv.MenuColor = string.IsNullOrWhiteSpace(menu) ? vv.MenuColor : menu;
                db.SaveChanges();
                TempData["success"] = "Menu Color Changed successfully.";
                return RedirectToAction("Outer_color");
            }
            else
            {
                mcolor.MenuColor = selected;
                mcolor.SelectedColor = menu;
                db.tblMenuColors.Add(mcolor);
                db.SaveChanges();
                TempData["success"] = "Menu Color Uploaded successfully.";
                return RedirectToAction("Outer_color");
            }
        }
