        [HttpPost, ValidateInput(false)]
        public ActionResult Outside_Silder(string ddltype, string txtheading, string txtedit)
        {
            try
            {
                var count = db.tblSilders.Where(a => a.SilderType == ddltype).Count();
                if (count < 6)
                {
                    WebImage photo = null;
                    var newFileName = "";
                    var imagePath = "";
                    var imageThumbPath = "";

                    if (Request.HttpMethod == "POST")
                    {
                        photo = WebImage.GetImageFromRequest();
                        if (photo != null)
                        {
                            newFileName = Guid.NewGuid().ToString() + "_" +
                                Path.GetFileName(photo.FileName);
                            imagePath = @"\Outer_silder\" + newFileName;
                            //photo.Save(@"~\" + imagePath);

                            imageThumbPath = @"\Outer_silder\" + newFileName;
                            photo.Resize(1349, 496, false, true);
                            //preventEnlarge: true);
                            photo.Save(@"~\" + imageThumbPath);
                        }
                    }
                    tblSilder silder = new tblSilder();
                    silder.ImageHeading = string.IsNullOrWhiteSpace(txtheading) ? "" : txtheading;
                    silder.Content = string.IsNullOrWhiteSpace(txtedit) ? "" : txtedit;
                    silder.SilderType = ddltype;
                    silder.ImagePath = imageThumbPath;
                    silder.Date = DateTime.Now;
                    db.tblSilders.Add(silder);
                    db.SaveChanges();

                    ViewData["success"] = "File Uploaded successfully.";
                }
                else
                {
                    ViewData["success"] = "Only Upload 3 Images in " + ddltype + "";
                }
            }
            catch (Exception ex)
            {
                ViewBag.Message = "Error while uploading the files.";
            }

            var v = db.tblSilders.ToList();
            ViewBag.showimg = v;

            var imgcounter = db.tblSilders.Where(a => a.SilderType == "Silder1").Count();
            ViewBag.slider1 = imgcounter;
            var imgcounter1 = db.tblSilders.Where(a => a.SilderType == "Silder2").Count();
            ViewBag.slider2 = imgcounter1;
            var vv = db.tblSilders.ToList();
            ViewBag.showimg = vv;
            var silderImage1 = db.tblSilders.Where(a => a.SilderType == "Silder1").ToList();
            ViewBag.showsilder1 = silderImage1;
            var silderImage2 = db.tblSilders.Where(a => a.SilderType == "Silder2").ToList();
            ViewBag.showsilder2 = silderImage2;
            return View();
        }

        //admin layout theme — save/load JsonData/admin-layout-theme.json only
        [HttpPost]
        public JsonResult SaveAdminLayoutTheme(string themeJson)
        {
            try
            {
                if (string.IsNullOrWhiteSpace(themeJson))
                {
                    return Json(new { success = false, message = "Theme data is empty." }, JsonRequestBehavior.AllowGet);
                }

                var incoming = JObject.Parse(themeJson);
                var saved = new JObject
                {
                    ["id"] = string.IsNullOrWhiteSpace((string)incoming["id"]) ? "custom" : (string)incoming["id"],
                    ["name"] = string.IsNullOrWhiteSpace((string)incoming["name"]) ? "Custom" : (string)incoming["name"],
                    ["topbarBg"] = string.IsNullOrWhiteSpace((string)incoming["topbarBg"]) ? "#ffffff" : (string)incoming["topbarBg"],
                    ["sidebarBg"] = string.IsNullOrWhiteSpace((string)incoming["sidebarBg"]) ? "#0b1220" : (string)incoming["sidebarBg"],
                    ["topbarDark"] = incoming["topbarDark"] != null && incoming["topbarDark"].Type == JTokenType.Boolean
                        ? incoming["topbarDark"].Value<bool>()
                        : false,
                    ["sidebarDark"] = incoming["sidebarDark"] != null && incoming["sidebarDark"].Type == JTokenType.Boolean
                        ? incoming["sidebarDark"].Value<bool>()
                        : true
                };

                JSONReadWrite readWrite = new JSONReadWrite();
                readWrite.Write("admin-layout-theme.json", "~/JsonData/", saved.ToString(Formatting.Indented));

                return Json(new { success = true, theme = saved }, JsonRequestBehavior.AllowGet);
            }
            catch (Exception ex)
            {
                return Json(new { success = false, message = "Failed to save theme.", error = ex.Message }, JsonRequestBehavior.AllowGet);
            }
        }

        [HttpGet]
        public JsonResult GetAdminLayoutTheme()
        {
            try
            {
                JSONReadWrite readWrite = new JSONReadWrite();
                var json = readWrite.Read("admin-layout-theme.json", "~/JsonData/");
                var theme = JObject.Parse(json);
                return Json(new { success = true, theme = theme }, JsonRequestBehavior.AllowGet);
            }
            catch
            {
                var theme = new JObject
                {
                    ["id"] = "default",
                    ["name"] = "Classic",
                    ["topbarBg"] = "#ffffff",
                    ["sidebarBg"] = "#0b1220",
                    ["topbarDark"] = false,
                    ["sidebarDark"] = true
                };
                return Json(new { success = true, theme = theme }, JsonRequestBehavior.AllowGet);
            }
        }

        //admin theme
        [HttpPost]
        public JsonResult changetheme(string themetype)
        {
            try
            {
                if (themetype != null)
                {
                    //Get themes
                    JSONReadWrite readWrite = new JSONReadWrite();
                    List<Hlp_TC_Privacy> themes = JsonConvert.DeserializeObject<List<Hlp_TC_Privacy>>(readWrite.Read("themes.json", "~/JsonData/"));

                    //Update themes
                    foreach (var theme in themes)
                    {
                        theme.Id = (theme.Theme == themetype) ? 1 : 0;
                    }

                    //Save updated themes
                    string jSONString = JsonConvert.SerializeObject(themes);
                    readWrite.Write("themes.json", "~/JsonData/", jSONString);

                    return Json("Success", JsonRequestBehavior.AllowGet);
                }
                else
                {
                    return Json("Failed: Theme type is null.", JsonRequestBehavior.AllowGet);
                }
            }
            catch (Exception ex)
            {
                return Json("Failed: An error occurred while changing the theme.", JsonRequestBehavior.AllowGet);
            }
        }

