        public ActionResult app_colors_save(string otp, string bg1, string bg2, string fc)
        {
            var mess = "";
            try
            {
                var chj = db.appicons.ToList();
                if (chj[0].users.Trim() == otp.Trim() && !string.IsNullOrEmpty(chj[0].users))
                {

                    var iconData = db.appicons.FirstOrDefault();
                    if (iconData != null)
                    {
                        iconData.updatedate = DateTime.Now;
                    }



                    var chk = db.application_color.ToList();
                    if (chk.Count > 0)
                    {
                        var chk1 = db.application_color.SingleOrDefault();
                        chk1.background_color = bg1;
                        chk1.background_color2 = bg2;
                        chk1.font_color = fc;
                        db.SaveChanges();
                    }
                    else
                    {
                        application_color ac = new application_color();
                        ac.background_color = bg1;
                        ac.background_color2 = bg2;
                        ac.font_color = fc;
                        db.application_color.Add(ac);
                        db.SaveChanges();
                    }

                    db.SaveChanges();

                    mess = "Success";
                }
                else
                {
                    return Json("Otp not matched", JsonRequestBehavior.AllowGet);
                }
            }
            catch
            {
                mess = "Failed";
            }
            return Json(mess, JsonRequestBehavior.AllowGet);
        }
