                    id.UserId = string.IsNullOrWhiteSpace(userid) ? vv.UserId : userid;
                    id.Role = string.IsNullOrWhiteSpace(admin) ? vv.Role : admin;
                    id.LogoImage = string.IsNullOrWhiteSpace(imageThumbPath) ? id.LogoImage : imageThumbPath;
