                    {
                        newFileName = Guid.NewGuid().ToString() + "_" +
                            Path.GetFileName(photo.FileName);
                        var imagePath1 = @"\Outside_logo\" + newFileName;
                        imagePath = imagePath1.Replace(" ", string.Empty).Replace("(", string.Empty).Replace(")", string.Empty);
                        //photo.Save(@"~\" + imagePath);

                        var imageThumbPath1 = @"\Outside_logo\" + newFileName;
                        imageThumbPath = imageThumbPath1.Replace(" ", string.Empty).Replace("(", string.Empty).Replace(")", string.Empty);
                        photo.Resize(460, 460, false, true);
                        //preventEnlarge: true);
                        photo.Save(@"~\" + imageThumbPath);
                    }
                }

                if (sliderType == "LoginSlide1")
                {
                    var count = db.LoginSilders.Where(a => a.SilderType == "LoginSlide1").SingleOrDefault();

                    if (count != null)
                    {
                        LoginSilder silder = new LoginSilder();
                        count.SilderType = sliderType;
                        count.ImagePath = imageThumbPath;
                        count.Date = DateTime.Now;
                        count.Status = "N";
                        db.SaveChanges();
                    }
                    else
                    {
                        LoginSilder silder = new LoginSilder();
                        silder.SilderType = sliderType;
                        silder.ImagePath = imageThumbPath;
                        silder.Date = DateTime.Now;
                        silder.Status = "N";
                        db.LoginSilders.Add(silder);
                        db.SaveChanges();
                    }
                }
                else if (sliderType == "LoginSlide2")
                {
                    var count = db.LoginSilders.Where(a => a.SilderType == "LoginSlide2").SingleOrDefault();
                    if (count != null)
                    {
                        LoginSilder silder = new LoginSilder();
                        count.SilderType = sliderType;
                        count.ImagePath = imageThumbPath;
                        count.Date = DateTime.Now;
                        count.Status = "N";
                        db.SaveChanges();
                    }
                    else
                    {
                        LoginSilder silder = new LoginSilder();
                        silder.SilderType = sliderType;
                        silder.ImagePath = imageThumbPath;
                        silder.Date = DateTime.Now;
                        silder.Status = "N";
                        db.LoginSilders.Add(silder);
                        db.SaveChanges();
                    }
                }

            }
            catch
            {

            }


            return RedirectToAction("Outside_logo");
        }

        [HttpGet]
        public ActionResult LoginSilderIsStatus()
        {
            var chk = db.LoginSilders.ToList();
