        public ActionResult Outside_Menu()
        {
            showmenu show = new showmenu();
            show.check = (from pp in db.tblMenus
                          where pp.Role == "ADMIN" && pp.MenuName != "HOME"
                          select new CheckMenu
                          {
                              Id = (int)pp.Id,
