        [HttpPost]
        public ActionResult Outside_Menu(showmenu data)
        {
            var admin = "ADMIN";
            var userid = User.Identity.GetUserId();
            foreach (var item in data.check)
            {
                if (item.Checked == true)
                {
                    tblMenu vv = (from p in db.tblMenus
                                  where p.Id == (int)item.Id && p.Role == "ADMIN"
                                  select p).SingleOrDefault();

                    vv.MenuName = string.IsNullOrWhiteSpace(item.Name) ? vv.MenuName : item.Name;
                    vv.UserId = string.IsNullOrWhiteSpace(item.UserId) ? vv.UserId : item.UserId;
                    vv.Role = string.IsNullOrWhiteSpace(admin) ? vv.Role : admin;
                    vv.Status = "Y";
                    db.SaveChanges();
                    TempData["success"] = "Menu Uploaded Sucessfully.";
                }
                else
                {
                    tblMenu vv = (from p in db.tblMenus
                                  where p.Id == (int)item.Id && p.Role == "ADMIN"
                                  select p).SingleOrDefault();
                    vv.MenuName = string.IsNullOrWhiteSpace(item.Name) ? vv.MenuName : item.Name;
                    vv.UserId = string.IsNullOrWhiteSpace(item.UserId) ? vv.UserId : item.UserId;
                    vv.Role = string.IsNullOrWhiteSpace(admin) ? vv.Role : admin;
                    vv.Status = "N";
                    db.SaveChanges();
                    TempData["success"] = "Menu Uploaded Sucessfully.";
                }
            }
            showmenu show = new showmenu();
            show.check = (from pp in db.tblMenus
                          where pp.Role == "ADMIN" && pp.MenuName != "HOME"
                          select new CheckMenu
                          {
                              Id = (int)pp.Id,
                              Name = pp.MenuName,
                              Status = pp.Status,
                              Checked = pp.Status == "Y" ? true : false
                          }).ToList();
            return View(show);
        }
