        public ActionResult SilderIsStatus(string type, string sts)
        {
            try
            {
                switch (type)
                {
                    case "Silder1":
                        if (sts == "N")
                        {
                            var id = db.tblSilderIsStatus.Where(p => p.Silder1Status != sts).FirstOrDefault().Id;
                            tblSilderIsStatu Status1Silder = (from p in db.tblSilderIsStatus
                                                              where p.Id == id
                                                              select p).SingleOrDefault();
                            Status1Silder.Silder1Status = "N";
                            Status1Silder.Silder2Status = "Y";
                            db.SaveChanges();
                            return RedirectToAction("Outside_Silder");
                        }
                        else
                        {
                            var id = db.tblSilderIsStatus.Where(p => p.Silder1Status != sts).FirstOrDefault().Id;
                            tblSilderIsStatu Status1Silder = (from p in db.tblSilderIsStatus
                                                              where p.Id == id
                                                              select p).SingleOrDefault();
                            Status1Silder.Silder1Status = "Y";
                            Status1Silder.Silder2Status = "N";
                            db.SaveChanges();
                            return RedirectToAction("Outside_Silder");
                        }
                    case "Silder2":
                        if (sts == "N")
                        {
                            var id = db.tblSilderIsStatus.Where(p => p.Silder2Status != sts).FirstOrDefault().Id;
                            tblSilderIsStatu Status2Silder = (from p in db.tblSilderIsStatus
                                                              where p.Id == id
                                                              select p).SingleOrDefault();
                            Status2Silder.Silder1Status = "Y";
                            Status2Silder.Silder2Status = "N";
                            db.SaveChanges();
                            return RedirectToAction("Outside_Silder");
                        }
                        else
                        {
                            var id = db.tblSilderIsStatus.Where(p => p.Silder2Status != sts).FirstOrDefault().Id;
                            tblSilderIsStatu Status2Silder = (from p in db.tblSilderIsStatus
                                                              where p.Id == id
                                                              select p).SingleOrDefault();
                            Status2Silder.Silder1Status = "N";
                            Status2Silder.Silder2Status = "Y";
                            db.SaveChanges();
                            return RedirectToAction("Outside_Silder");
                        }

                    default:
                        return RedirectToAction("Outside_Silder");
                }
            }
            catch
            {

            }
            return RedirectToAction("Outside_Silder");
        }

        public ActionResult About_us_Content()
        {
            var userid = User.Identity.GetUserId();
            var result = db.tblAboutUsContents.Where(p => p.Role == "ADMIN").ToList();
            ViewBag.Aboutdata = result;

            var vv = db.tblAboutUsBackgroundColorChanges.Where(a => a.UserId == userid && a.Role == "ADMIN").ToList();
            if (vv.Count > 0)
            {
                var pp = vv.FirstOrDefault().MultipalAboutUsColor;
                string[] color = pp.Split(',', ')');
                string Hexcode = color[1].ToString();
                string Rgbcolor = color[2].ToString();
                ViewData["first"] = Hexcode;
                ViewData["second"] = Rgbcolor;
            }
            else
            {
                ViewData["first"] = "#c0c0c0";
                ViewData["second"] = "#c0c0c0";
            }
            return View();
        }
        [HttpPost, ValidateInput(false)]
        public ActionResult About_us_Content(string txtedit, string txtheading)
        {
            try
            {
                WebImage photo = null;
                var newFileName = "";
                var imagePath = "";
                var imageThumbPath = "";

                if (Request.HttpMethod == "POST")
                {
                    photo = WebImage.GetImageFromRequest();
                    if (photo != null)
                    {
                        newFileName = Guid.NewGuid().ToString() + "_" +
                            Path.GetFileName(photo.FileName);
                        imagePath = @"\About_Us_Images\" + newFileName;
                        //photo.Save(@"~\" + imagePath);

                        imageThumbPath = @"\About_Us_Images\" + newFileName;
                        photo.Resize(515, 270, false, true);
                        //preventEnlarge: true);
                        photo.Save(@"~\" + imageThumbPath);

                    }
                }
                var userid = User.Identity.GetUserId();
                var admin = "ADMIN";
                tblAboutUsContent about = new tblAboutUsContent();
                var roletype = db.tblAboutUsContents.Where(p => p.Role == admin).ToList();
                var role = roletype.Count == 0 ? "" : roletype.SingleOrDefault().Role;
                if (role == admin)
                {
                    var id = (from tbl in db.tblAboutUsContents where tbl.UserId == userid select tbl).SingleOrDefault();
                    id.Role = string.IsNullOrWhiteSpace(admin) ? id.Role : admin;
                    id.AboutContent = string.IsNullOrWhiteSpace(txtedit) ? id.AboutContent : txtedit;
                    id.AboutHeading = string.IsNullOrWhiteSpace(txtheading) ? id.AboutHeading : txtheading;
                    id.AboutImage = string.IsNullOrWhiteSpace(imagePath) ? id.AboutImage : imagePath;
                    db.SaveChanges();
                    TempData["success"] = "About Us Content Uploaded successfully.";
                }
                else
                {
                    about.Role = admin;
                    about.UserId = userid;
                    about.AboutContent = txtedit;
                    about.AboutHeading = txtheading;
                    about.AboutImage = imagePath;
                    db.tblAboutUsContents.Add(about);
                    db.SaveChanges();
                    TempData["success"] = "File Uploaded successfully.";
                }
                var vv = db.tblAboutUsBackgroundColorChanges.Where(a => a.UserId == userid && a.Role == "ADMIN").ToList();
                if (vv.Count > 0)
                {
                    var pp = vv.FirstOrDefault().MultipalAboutUsColor;
                    string[] color = pp.Split(',', ')');
                    string Hexcode = color[1].ToString();
                    string Rgbcolor = color[2].ToString();
                    ViewData["first"] = Hexcode;
                    ViewData["second"] = Rgbcolor;
                }
                else
                {
                    ViewData["first"] = "#c0c0c0";
                    ViewData["second"] = "#c0c0c0";
                }
            }
            catch
            {
                return View();
            }
            var result = db.tblAboutUsContents.Where(p => p.Role == "ADMIN").ToList();
            ViewBag.Aboutdata = result;
            return View();
        }

