                id.ContectColor = string.IsNullOrWhiteSpace(outsidecolor) ? id.ContectColor : outsidecolor;
                db.SaveChanges();
                ViewData["success"] = "Contect Us Background Color Changed successfully.";
                return RedirectToAction("Contect_Content");
            }
            else
            {
                color.UserId = userid;
