        public ActionResult OuterFooterColorchange(string first, string second)
        {
            first = "#" + first + "";
            second = "#" + second + "";
            TempData["first"] = first;
            TempData["second"] = second;
            var outsidecolor = "linear-gradient(to right," + first + "," + second + ")";
            tblfooterbackcolor color = new tblfooterbackcolor();
            var admin = "ADMIN";
            var userid = User.Identity.GetUserId();
            var roletype = db.tblfooterbackcolors.Where(p => p.Role == admin).ToList();
            var role = roletype.Count == 0 ? "" : roletype.SingleOrDefault().Role;
            if (role == admin)
            {
                var id = (from tbl in db.tblfooterbackcolors where tbl.UserId == userid select tbl).SingleOrDefault();
                id.Role = string.IsNullOrWhiteSpace(admin) ? id.Role : admin;
                id.UserId = string.IsNullOrWhiteSpace(userid) ? id.UserId : userid;
                id.FooterBackColor = string.IsNullOrWhiteSpace(outsidecolor) ? id.FooterBackColor : outsidecolor;
                db.SaveChanges();
                ViewData["success"] = "Footer Background Color Changed successfully.";
                return RedirectToAction("footer_Content");
            }
            else
            {
                color.UserId = userid;
                color.Role = admin;
                color.FooterBackColor = outsidecolor;
                db.tblfooterbackcolors.Add(color);
                db.SaveChanges();
                ViewData["success"] = "Footer Background Color Uploaded successfully.";
                return RedirectToAction("footer_Content");
            }
        }

        public JsonResult delfooterser(int Id)
        {
            if (Id != null && Id > 0)
            {
                var v = db.tblFooterServices.Single(m => m.Id == Id);
                db.tblFooterServices.Remove(v);
                db.SaveChanges();
                return Json("Success", JsonRequestBehavior.AllowGet);
            }
            else
            {
                return Json("Failed", JsonRequestBehavior.AllowGet);
            }

        }


