        [HttpPost]
        public ActionResult Gift_Card(string ddlCategory, string txtminimum, string txtmiximum, string txtfirst, string txtsecond, string txtthird, string txtfourth, string txtGift, string radiogroup)
        {
            var userid = User.Identity.GetUserId();
            try
            {

                WebImage photo = null;
                var newFileName = "";
                var imagePath = "";
                var imageThumbPath = "";

                if (Request.HttpMethod == "POST")
                {
                    photo = WebImage.GetImageFromRequest();
                    if (photo != null)
                    {
                        newFileName = Guid.NewGuid().ToString() + "_" +
                            Path.GetFileName(photo.FileName);
                        imagePath = @"\Gift_Card Images\" + newFileName;
                        //photo.Save(@"~\" + imagePath);

                        imageThumbPath = @"\Gift_Card Images\" + newFileName;
                        photo.Resize(312, 200, false, true);
                        photo.Save(@"~\" + imageThumbPath);
                    }
                }

                GiftCard gift = new GiftCard();
                if (txtfirst == null || txtfirst == "")
                {
                    gift.FirstAmt = 0;
                }
                else
                {
                    gift.FirstAmt = Convert.ToDecimal(txtfirst);
                }
                if (txtsecond == null || txtsecond == "")
                {
                    gift.SecondAmt = 0;
                }
                else
                {
                    gift.SecondAmt = Convert.ToDecimal(txtsecond);
                }
                if (txtthird == null || txtthird == "")
                {
                    gift.ThirdAmt = 0;
                }
                else
                {
                    gift.ThirdAmt = Convert.ToDecimal(txtthird);
                }
                if (txtfourth == null || txtfourth == "")
                {
                    gift.FourthAmt = 0;
                }
                else
                {
                    gift.FourthAmt = Convert.ToDecimal(txtfourth);
                }
                if (txtmiximum == null || txtmiximum == "")
                {
                    gift.MaximumAmt = 0;
                }
                else
                {
                    gift.MaximumAmt = Convert.ToDecimal(txtmiximum);
                }
                if (txtminimum == null || txtminimum == "")
                {
                    gift.MinimumAmt = 0;
                }
                else
                {
                    gift.MinimumAmt = Convert.ToDecimal(txtminimum);
                }
                gift.Category = ddlCategory;
                gift.GiftName = txtGift;
                gift.userid = userid;
                gift.type = radiogroup;
                gift.GiftImage = imageThumbPath;
                db.GiftCards.Add(gift);
                db.SaveChanges();
                TempData["success"] = "Gift Card Data Uploaded successfully.";
            }
            catch (Exception ex)
            {
                ViewBag.Message = "Error while uploading the files.";
            }
            var result = db.GiftCards.Where(p => p.userid == userid).ToList();
            ViewBag.giftdata = result;
            return View();
        }


