        [HttpPost]
        public ActionResult Edit_Giftcard(int ID, GiftCard gift)
        {
            try
            {
                if (gift.MinimumAmt >= 0 && gift.MaximumAmt >= 0 && gift.FirstAmt >= 0 && gift.SecondAmt >= 0 && gift.ThirdAmt >= 0 && gift.FourthAmt >= 0)
                {
                    WebImage photo = null;
                    var newFileName = "";
                    var imagePath = "";
                    var imageThumbPath = "";

                    if (Request.HttpMethod == "POST")
                    {
                        photo = WebImage.GetImageFromRequest();
                        if (photo != null)
                        {
                            newFileName = Guid.NewGuid().ToString() + "_" +
                                Path.GetFileName(photo.FileName);
                            imagePath = @"\Gift_Card Images\" + newFileName;
                            //photo.Save(@"~\" + imagePath);

                            imageThumbPath = @"\Gift_Card Images\" + newFileName;
                            photo.Resize(312, 200, false, true);
                            photo.Save(@"~\" + imageThumbPath);
                        }
                    }

                    var userid = User.Identity.GetUserId();
                    var giftcard = db.GiftCards.Single(a => a.ID == ID);
                    giftcard.Category = string.IsNullOrWhiteSpace(gift.Category) ? giftcard.Category : gift.Category;
                    giftcard.MinimumAmt = string.IsNullOrWhiteSpace(gift.MinimumAmt.ToString()) ? giftcard.MinimumAmt : gift.MinimumAmt;
                    giftcard.MaximumAmt = string.IsNullOrWhiteSpace(gift.MaximumAmt.ToString()) ? giftcard.MaximumAmt : gift.MaximumAmt;
                    giftcard.FirstAmt = string.IsNullOrWhiteSpace(gift.FirstAmt.ToString()) ? giftcard.FirstAmt : gift.FirstAmt;
                    giftcard.SecondAmt = string.IsNullOrWhiteSpace(gift.SecondAmt.ToString()) ? giftcard.SecondAmt : gift.SecondAmt;
                    giftcard.ThirdAmt = string.IsNullOrWhiteSpace(gift.ThirdAmt.ToString()) ? giftcard.ThirdAmt : gift.ThirdAmt;
                    giftcard.FourthAmt = string.IsNullOrWhiteSpace(gift.FourthAmt.ToString()) ? giftcard.FourthAmt : gift.FourthAmt;
                    giftcard.userid = userid;
                    giftcard.GiftName = string.IsNullOrWhiteSpace(gift.GiftName) ? giftcard.GiftName : gift.GiftName;
                    giftcard.GiftImage = string.IsNullOrWhiteSpace(imagePath) ? giftcard.GiftImage : imagePath;
                    db.SaveChanges();
                    return RedirectToAction("Gift_Card");
                }
                else
                {
                    ViewData["error"] = "Amount must be greater than zero";
                    return RedirectToAction("Edit_Giftcard");
                }

            }
            catch (Exception ex)
            {

            }
            return View();
        }
