        public ActionResult UpdateAepsMposStatus(int id, string flag)
        {
            var v = db.tbl_Holiday.Single(pp => pp.id == id);
            if (flag == "AEPS")
            {
                if (v.isAepsBlocked)
                {
                    v.isAepsBlocked = false;
                }
                else
                {
                    v.isAepsBlocked = true;
                }

            }
            if (flag == "MPOS")
            {
                if (v.isMposBlocked)
                {
                    v.isMposBlocked = false;
                }
                else
                {
                    v.isMposBlocked = true;
                }

            }
            db.SaveChanges();
            return RedirectToAction("Holidaycalendar");
        }
