        {
            try
            {
                var ad = db.Admin_details.Single(a => a.ID == hdidadmin);
                ad.Companyname = string.IsNullOrWhiteSpace(txtcompany) ? ad.Companyname : txtcompany;
                ad.Address = string.IsNullOrWhiteSpace(txtaddress) ? ad.Address : txtaddress;
                ad.pincode = txtzipcode;
                ad.State = State;
                ad.District = District;
