        public JsonResult DelereprofileDoc(int ID, string Docname)
        {
            if (ID > 0 && Docname == "Aadhaar")
            {
                var ad = db.Admin_details.Single(a => a.ID == ID);
                string path = Server.MapPath("~/" + ad.Aadhaarpath);
