            if (ID > 0 && Docname == "ServiceAgrrement")
            {
                var ad = db.Admin_details.Single(a => a.ID == ID);
                string path = Server.MapPath("~/" + ad.serciveaggrementpath);
                if (System.IO.File.Exists(path))
                {
                    System.IO.File.Delete(path);
                }
                ad.serciveaggrementpath = null;
                db.SaveChanges();
                return Json("Success", JsonRequestBehavior.AllowGet);
            }
            if (ID > 0 && Docname == "Signature")
