        //Change Password 


        [HttpGet]
        public ActionResult ChangePassword()
        {

            return View();
        }
        //
        // POST: /Manage/ChangePassword
        [HttpPost]
        [ValidateAntiForgeryToken]
        public async Task<ActionResult> ChangePassword([Bind(Prefix = "Item1")] ChangePasswordViewModel model, string OTp)
        {


            if (!ModelState.IsValid)
            {
                return View(model);
            }
            var result = await UserManager.ChangePasswordAsync(User.Identity.GetUserId(), model.OldPassword, model.NewPassword);
            if (result.Succeeded)
            {
                // change security code
                await UserManager.UpdateSecurityStampAsync(User.Identity.GetUserId());
                var userid1 = User.Identity.GetUserId();
                var chk22 = db.checklogouts.Where(a => a.userid == userid1).SingleOrDefault();
                if (chk22 == null)
                {
                    checklogout chlogout = new checklogout();
                    chlogout.userid = userid1;
                    chlogout.lastupdatedate = DateTime.UtcNow;
                    db.checklogouts.Add(chlogout);
                    db.SaveChanges();

                }
                else
                {
                    chk22.lastupdatedate = DateTime.UtcNow;
                    db.SaveChanges();
                }
                var user = await UserManager.FindByIdAsync(User.Identity.GetUserId());
                if (user != null)
                {
                    await SignInManager.SignInAsync(user, isPersistent: false, rememberBrowser: false);
                }
                TempData["success"] = "Your Password has been Changed Successfully";
                return RedirectToAction("ChangeSecurityPassword");
            }
            //AddErrors(result);
            //return View(model);
            try
            {
                TempData["error"] = ((string[])result.Errors)[0];
            }
            catch
            { }


            return RedirectToAction("ChangeSecurityPassword");

        }

        [HttpPost]
        public async Task<JsonResult> DisableTwoFactor(string UserRole, string btnVal, string UserrId)
        {
            if (UserRole.Contains("master"))
            {
                var RoleId = db.Roles.Where(a => a.Name == UserRole).SingleOrDefault().RoleId;
                var ch = db.UserRoles.Where(a => a.RoleId == RoleId).ToList();

                if (btnVal == "Y")
                {
                    foreach (var item in ch)
                    {


                        var servid = db.passcodesettings.Where(x => x.userid == item.UserId).SingleOrDefault();
                        if (servid != null)
                        {
                            servid.passcode = null;
                            servid.passcodetype = "OFF";
                            servid.expiretime = null;

                        }
                        await UserManager.SetTwoFactorEnabledAsync(item.UserId, true);
                    }
                    db.SaveChanges();

                }
                else
                {
                    foreach (var item in ch)
                    {
                        var passcodes = db.passcodesettings.Where(x => x.userid == item.UserId).SingleOrDefault();
                        if (passcodes != null)
                        {
                            passcodes.passcodetype = "OFF";
                            passcodes.expiretime = null;
                            passcodes.passcode = null;

                        }
                        await UserManager.SetTwoFactorEnabledAsync(item.UserId, false);
                    }
                    db.SaveChanges();
