                            servid.expiretime = null;
                            db.SaveChanges();

                        }


                        var RoleName = UserManager.GetRoles(UserrId);
                        return Json(RoleName, JsonRequestBehavior.AllowGet);
                    }

                }
                else
                {
                    if (UserrId != null || UserrId != "")
                    {
                        await UserManager.SetTwoFactorEnabledAsync(UserrId, false);
                        var passcodes = db.passcodesettings.Where(x => x.userid == UserrId).SingleOrDefault();
                        if (passcodes != null)
                        {
                            passcodes.passcodetype = "OFF";
                            passcodes.expiretime = null;
                            passcodes.passcode = null;
                            db.SaveChanges();

                        }
                        var RoleName = UserManager.GetRoles(UserrId);
                        return Json(RoleName, JsonRequestBehavior.AllowGet);
                    }
                }

            }
            return Json("Success", JsonRequestBehavior.AllowGet);
        }

