        public JsonResult GetTwoFactor(string UserRole)
        {
            if (UserRole.Contains("master"))
            {
                var results = (from users in db.Users
                               join master in db.Superstokist_details on users.UserId equals master.SSId.ToString()
                               join masterpasscode in db.passcodesettings on master.SSId equals masterpasscode.userid

                               select new TwoFactorEnabled
                               {
                                   UserId = users.UserId,
                                   Email = string.IsNullOrEmpty(master.FarmName) ? master.SuperstokistName : master.FarmName,
                                   Mobile = master.Mobile,
                                   TwoFactorEnable = users.TwoFactorEnabled,
                                   passcodetype = masterpasscode.passcodetype,
                                   UserRole = "master"
                               }).ToList();
                return Json(results, JsonRequestBehavior.AllowGet);

            }
            else if (UserRole.Contains("Dealer"))
            {
                var results = (from users in db.Users
                               join dealer in db.Dealer_Details on users.UserId equals dealer.DealerId.ToString()
                               join dealerpasscode in db.passcodesettings on dealer.DealerId equals dealerpasscode.userid

                               select new TwoFactorEnabled
                               {
                                   UserId = users.UserId,
                                   Email = string.IsNullOrEmpty(dealer.FarmName) ? dealer.DealerName : dealer.FarmName,
                                   Mobile = dealer.Mobile,
                                   TwoFactorEnable = users.TwoFactorEnabled,
                                   passcodetype = dealerpasscode.passcodetype,
                                   UserRole = "Dealer"
                               }).ToList();
                return Json(results, JsonRequestBehavior.AllowGet);

            }
            else if (UserRole.Contains("Retailer"))
            {
                var results = (from users in db.Users
                               join retailer in db.Retailer_Details.Where(aa => aa.ISDeleteuser == false) on users.UserId equals retailer.RetailerId.ToString()
                               join retailerpasscode in db.passcodesettings on retailer.RetailerId equals retailerpasscode.userid
                               select new TwoFactorEnabled
                               {
                                   UserId = users.UserId,
                                   Email = string.IsNullOrEmpty(retailer.Frm_Name) ? retailer.RetailerName : retailer.Frm_Name,
                                   Mobile = retailer.Mobile,
                                   TwoFactorEnable = users.TwoFactorEnabled,
                                   passcodetype = retailerpasscode.passcodetype,
                                   UserRole = "Retailer"
                               }).ToList();
                return Json(results, JsonRequestBehavior.AllowGet);

            }
            else if (UserRole.Contains("API"))
            {
                var results = (from users in db.Users
                               join api_user in db.api_user_details on users.UserId equals api_user.apiid.ToString()
                               join apipasscode in db.passcodesettings on api_user.apiid equals apipasscode.userid
                               select new TwoFactorEnabled
                               {
                                   UserId = users.UserId,
                                   Email = string.IsNullOrEmpty(api_user.farmname) ? api_user.username : api_user.farmname,
                                   Mobile = api_user.mobile,
                                   TwoFactorEnable = users.TwoFactorEnabled,
                                   passcodetype = apipasscode.passcodetype,
                                   UserRole = "API"
                               }).ToList();
                return Json(results, JsonRequestBehavior.AllowGet);

            }
            else if (UserRole.Contains("Whitelabel"))
            {
                var results = (from users in db.Users
                               join WhiteLabel in db.WhiteLabel_userList on users.UserId equals WhiteLabel.WhiteLabelID.ToString()
                               join Whitelabelpasscode in db.passcodesettings on WhiteLabel.WhiteLabelID equals Whitelabelpasscode.userid
                               select new TwoFactorEnabled
                               {
                                   UserId = users.UserId,
                                   Email = string.IsNullOrEmpty(WhiteLabel.FrmName) ? WhiteLabel.Name : WhiteLabel.FrmName,
                                   Mobile = WhiteLabel.Mobile,
                                   TwoFactorEnable = users.TwoFactorEnabled,
                                   passcodetype = Whitelabelpasscode.passcodetype,
                                   UserRole = "Whitelabel"
                               }).ToList();
                return Json(results, JsonRequestBehavior.AllowGet);

            }
            else
            {
                var results = (from users in db.Users
                               join master in db.Superstokist_details on users.UserId equals master.SSId.ToString()
                               join masterpasscode in db.passcodesettings on master.SSId equals masterpasscode.userid

                               select new TwoFactorEnabled
                               {
                                   UserId = users.UserId,
                                   Email = string.IsNullOrEmpty(master.FarmName) ? master.SuperstokistName : master.FarmName,
                                   Mobile = master.Mobile,
                                   TwoFactorEnable = users.TwoFactorEnabled,
                                   passcodetype = masterpasscode.passcodetype,
                                   UserRole = "master"
                               }).ToList();
                return Json(results, JsonRequestBehavior.AllowGet);
            }
        }

