        public ActionResult DomainExpirationche()
        {
            var websiteurl = db.Admin_details.FirstOrDefault().WebsiteUrl;
            string expiredate;
            try
            {
                var expire = db.Domain_Expiration.FirstOrDefault();
                expiredate = DomainExpirationchecker.Lookup(websiteurl);
                if (expiredate.Contains("Registry Expiry Date:"))
                {
                    expiredate = String.Format("{0}:{1}:{2}", expiredate.Split(':')[1].Trim(), expiredate.Split(':')[2].Trim(), expiredate.Split(':')[3].Trim());

                    var exp_date = DateTime.Parse(expiredate);
                    expiredate = exp_date.ToString("dd MMM yyy");
                    exp_date = DateTime.Parse(expiredate);

                    if (expire == null)
                    {
                        Domain_Expiration de = new Domain_Expiration();
                        de.ExpireDate = exp_date;
                        db.Domain_Expiration.Add(de);
                        db.SaveChanges();
                    }
                    else if (exp_date < DateTime.Now)
                    {
                        expire.ExpireDate = exp_date;
                        db.SaveChanges();
                    }
                }
                else
                {
                    throw new Exception("Domain Error");
                }

            }
            catch (Exception ex)
            {
                expiredate = "NO DATA";
            }
            return Json(new { expiredate = expiredate }, JsonRequestBehavior.AllowGet);
        }
        public ActionResult _business(string data)
        {

            DateTime from = DateTime.Now.Date;
            DateTime to = from.AddDays(1);
            if (data != null)
            {
                if (data == "lastday")
                {
                    from = from.AddDays(-1);
                    to = to.AddDays(-1);
                }
                else if (data == "today")
                {
                    from = DateTime.Now.Date;
                    to = from.AddDays(1);
                }
                else
                {
                    from = Convert.ToDateTime(data);
                    to = from.AddDays(1);
                }
            }
            //MultiviewDashboard model = new MultiviewDashboard();
            //model.total_bussiness= db.total_bussiness_dashboard(from, to).ToList();
            var ch = db.total_bussiness_dashboard(from, to).ToList();
            return PartialView(ch);
        }
        public ActionResult _business_Operator(string data, DateTime frmdate)
        {
            DateTime to = frmdate.AddDays(1);
            ViewBag.chk = data;
            var ch = db.total_bussiness_operatorwise(frmdate, to, data).ToList();
