            var MasteractivePer = act_master_perc;
            //whitelabel
            var white = (from hh in db.WhiteLabel_userList select hh).Count();
            var Activewhite = white;
            var Whiteactive = Activewhite;
            var Whiteinactive = 0;
            var WhiteTotal = Activewhite;
