                Masterinactive = Masterinactive,
                MasterTotal = MasterTotal,
                MasteractivePer = MasteractivePer,
                Dealeractive = Dealeractive,
                Dealerinactive = Dealerinactive,
                DealerTotal = DealerTotal,
                DealeractivePer = DealeractivePer,
                Reatileractive = Reatileractive,
                Retailerinactive = Retailerinactive,
                RetailerTotal = RetailerTotal,
                RetaileractivePer = RetaileractivePer,
                Apiactive = Apiactive,
                Apiinactive = Apiinactive,
                ApiTotal = ApiTotal,
                ApiactivePer = ApiactivePer,
                Whiteactive = Whiteactive,
                Whiteinactive = Whiteinactive,
                WhiteTotal = WhiteTotal,
                WhiteactivePer = WhiteactivePer
            });
        }
