        [HttpPost]
        public ActionResult levelvalue()
        {
            var total = db.Remain_Admin_balance.Single().VirtualAmount;
            var ch = db.Total_account().ToList();
            if (ch.Single().total != total)
            {
                decimal val = Convert.ToDecimal(total) - Convert.ToDecimal(ch.Single().total);
                decimal remain = (decimal)(db.Remain_Admin_balance.Single().RemainAmount);
                Remain_Admin_balance objCourse = (from p in db.Remain_Admin_balance
                                                  select p).SingleOrDefault();
                objCourse.RemainAmount = remain + val;
                db.SaveChanges();
            }
            return RedirectToAction("Dashboard");
        }

        [HttpPost]
        public ActionResult UpdateVirtualbal(string txtvirtual, string but)
        {
            if (but == "Adjust")
            {
                var total = db.Remain_Admin_balance.Single().VirtualAmount;
                var ch = db.Total_account().ToList();
                if (ch.Single().total != total)
                {
                    decimal val = Convert.ToDecimal(total) - Convert.ToDecimal(ch.Single().total);
                    decimal remain = (decimal)(db.Remain_Admin_balance.Single().RemainAmount);
                    Remain_Admin_balance objCourse = (from p in db.Remain_Admin_balance
                                                      select p).SingleOrDefault();
                    objCourse.RemainAmount = remain + val;
                    db.SaveChanges();
                }
                TempData["success"] = "update successfully";
                return RedirectToAction("Dashboard");
            }
            else
            {
                var virtuaval = db.Remain_Admin_balance.Single().VirtualAmount;
                var userid = User.Identity.GetUserId();
                decimal txtval = Convert.ToDecimal(txtvirtual);
                if (txtval >= virtuaval)
                {
                    Remain_Admin_balance obj = (from pp in db.Remain_Admin_balance
                                                where pp.admin == userid
                                                select pp).SingleOrDefault();
                    obj.VirtualAmount = txtval;
                    db.SaveChanges();

                    var total = db.Remain_Admin_balance.Single().VirtualAmount;
                    var ch = db.Total_account().ToList();
                    if (ch.Single().total != total)
                    {
                        decimal val = Convert.ToDecimal(total) - Convert.ToDecimal(ch.Single().total);
                        decimal remain = (decimal)(db.Remain_Admin_balance.Single().RemainAmount);
                        Remain_Admin_balance objCourse = (from p in db.Remain_Admin_balance
                                                          select p).SingleOrDefault();
                        objCourse.RemainAmount = remain + val;
                        db.SaveChanges();
                    }
                    TempData["success"] = "update successfully";
                    return RedirectToAction("Dashboard");
                }
                else
                {
                    TempData["error"] = "amount should be greater than";
                    return RedirectToAction("Dashboard");
                }
            }

        }

