        public ActionResult AllDetails_paging(string txt_frm_date, string txt_to_date)
        {
            if (txt_frm_date == null && txt_to_date == null)
            {
                txt_frm_date = DateTime.Now.ToString();
                txt_to_date = DateTime.Now.ToString();

            }
            DateTime frm = Convert.ToDateTime(txt_frm_date);
            DateTime to = Convert.ToDateTime(txt_to_date);
            txt_frm_date = frm.ToString("dd-MM-yyyy");
            txt_to_date = to.ToString("dd-MM-yyyy");

            string[] formats = new[] { "MM/dd/yyyy", "dd-MMM-yyyy",
                            "yyyy-MM-dd", "dd-MM-yyyy", "dd MMM yyyy" };
            DateTime dt = !string.IsNullOrWhiteSpace(txt_frm_date) ? DateTime.ParseExact(txt_frm_date, formats, CultureInfo.InvariantCulture, DateTimeStyles.None) : DateTime.Now;
            DateTime dt1 = !string.IsNullOrWhiteSpace(txt_to_date) ? DateTime.ParseExact(txt_to_date, formats, CultureInfo.InvariantCulture, DateTimeStyles.None) : DateTime.Now;
            DateTime frm_date = Convert.ToDateTime(dt).Date;
            DateTime to_date = Convert.ToDateTime(dt1).Date.AddDays(1);
            int pagesize = 26;
            var ok = db.show_all_account(Convert.ToDateTime(frm_date), Convert.ToDateTime(to_date), 1, pagesize).ToList();
            return View(ok);
        }

        public ActionResult Excel_AllDetails_paging(string txt_frm_date, string txt_to_date)
        {
            if (txt_frm_date == null && txt_to_date == null)
            {
                txt_frm_date = DateTime.Now.ToString();
                txt_to_date = DateTime.Now.ToString();

            }
            DateTime frm = Convert.ToDateTime(txt_frm_date);
            DateTime to = Convert.ToDateTime(txt_to_date);
            txt_frm_date = frm.ToString("dd-MM-yyyy");
            txt_to_date = to.ToString("dd-MM-yyyy");

            string[] formats = new[] { "MM/dd/yyyy", "dd-MMM-yyyy",
                            "yyyy-MM-dd", "dd-MM-yyyy", "dd MMM yyyy" };
            DateTime dt = !string.IsNullOrWhiteSpace(txt_frm_date) ? DateTime.ParseExact(txt_frm_date, formats, CultureInfo.InvariantCulture, DateTimeStyles.None) : DateTime.Now;
            DateTime dt1 = !string.IsNullOrWhiteSpace(txt_to_date) ? DateTime.ParseExact(txt_to_date, formats, CultureInfo.InvariantCulture, DateTimeStyles.None) : DateTime.Now;
            DateTime frm_date = Convert.ToDateTime(dt).Date;
            DateTime to_date = Convert.ToDateTime(dt1).Date.AddDays(1);
            int pagesize = 10000;
            var ok = db.show_all_account(Convert.ToDateTime(frm_date), Convert.ToDateTime(to_date), 1, pagesize).ToList();

            DataTable dataTbl = new DataTable();
            dataTbl.Columns.Add("Order Id", typeof(string));
            dataTbl.Columns.Add("Transation Full Details", typeof(string));
            dataTbl.Columns.Add("Admin Bal", typeof(string));
            dataTbl.Columns.Add("M/D Bal", typeof(string));
            dataTbl.Columns.Add("Distributor Bal", typeof(string));
            dataTbl.Columns.Add("Retailer Bal", typeof(string));
            dataTbl.Columns.Add("Api Bal", typeof(string));
            dataTbl.Columns.Add("W/L Bal", typeof(string));
            dataTbl.Columns.Add("Total", typeof(string));
            dataTbl.Columns.Add("Date & Time", typeof(string));
            if (ok.Count > 0)
            {
                foreach (var item in ok)
                {
                    dataTbl.Rows.Add(item.id, item.details, item.totaladmin, item.totalsuper, item.totaldlm, item.totalrem, item.totalapi, item.totalwhitelabel, item.total, item.tdate);
                }
            }
            else
            {
                dataTbl.Rows.Add("", "", "", "", "", "", "", "", "", "");
            }
            var grid = new GridView();
            grid.DataSource = dataTbl;
            grid.DataBind();
            Response.ClearContent();
            Response.Buffer = true;
            Response.AddHeader("content-disposition", "attachment; filename=All_Transcation_Virtual_Info.xls");
            Response.ContentType = "application/ms-excel";
            Response.Charset = "";
            StringWriter sw = new StringWriter();
            HtmlTextWriter htw = new HtmlTextWriter(sw);
            grid.RenderControl(htw);
            Response.Output.Write(sw.ToString());
            Response.Flush();
            Response.End();
            return View();
        }
