        public ActionResult DeleteProductGiftImage(int id)
        {
            int Curntmonth = DateTime.Now.Date.Month;
            int Curntyear = DateTime.Now.Date.Year;

            int Nxtmonth = DateTime.Now.AddMonths(1).Date.Month;
            int Nxtyear = DateTime.Now.AddMonths(1).Date.Year;

            try
            {
                var result = db.tblPruductGifts.Find(id);
                string idnotargetset = result.ProductName;
                var retexist = db.tblRetailerSetTargets.Where(x => x.Achived60 == idnotargetset || x.Achived70 == idnotargetset || x.Achived80 == idnotargetset || x.Achived90 == idnotargetset || x.Achived100 == idnotargetset && x.OfferType == "Giftitem" && x.Date.Value.Month == Curntmonth && x.Date.Value.Year == Curntyear || x.Date.Value.Month == Nxtmonth && x.Date.Value.Year == Nxtyear).FirstOrDefault();
                if (retexist == null)
                {
                    var dealerexist = db.tblDealerSetTargets.Where(x => x.Achive_60 == idnotargetset || x.Achive_70 == idnotargetset || x.Achive_80 == idnotargetset || x.Achive_90 == idnotargetset || x.Achive_100 == idnotargetset && x.OfferType == "Giftitem" && x.Date.Value.Month == Curntmonth && x.Date.Value.Year == Curntyear || x.Date.Value.Month == Nxtmonth && x.Date.Value.Year == Nxtyear).FirstOrDefault();
                    if (dealerexist == null)
                    {
                        var superExist = db.tblsuperstockistsettargets.Where(x => x.Achive_60 == idnotargetset || x.Achive_70 == idnotargetset || x.Achive_80 == idnotargetset || x.Achive_90 == idnotargetset || x.Achive_100 == idnotargetset && x.OfferType == "Giftitem" && x.Date.Value.Month == Curntmonth && x.Date.Value.Year == Curntyear || x.Date.Value.Month == Nxtmonth && x.Date.Value.Year == Nxtyear).FirstOrDefault();
                        if (superExist == null)
                        {
                            var apiIsExist = db.tblAPIsettargets.Where(x => x.Achive_60 == idnotargetset || x.Achive_70 == idnotargetset || x.Achive_80 == idnotargetset || x.Achive_90 == idnotargetset || x.Achive_100 == idnotargetset && x.OfferType == "Giftitem" && x.Date.Value.Month == Curntmonth && x.Date.Value.Year == Curntyear || x.Date.Value.Month == Nxtmonth && x.Date.Value.Year == Nxtyear).FirstOrDefault();
                            if (apiIsExist == null)
                            {
                                var imgname = result.ProductImages;
                                if (result != null)
                                {
                                    db.tblPruductGifts.Remove(result);
                                    int i = db.SaveChanges();
                                    if (i > 0)
                                    {
                                        System.IO.File.Delete(Request.PhysicalApplicationPath + "images/" + imgname);
                                        return Json("Success", JsonRequestBehavior.AllowGet);
                                    }
                                }
                            }
                        }
                    }
                }
                return Json("Failed", JsonRequestBehavior.AllowGet);
            }
            catch { return Json("Failed", JsonRequestBehavior.AllowGet); }
        }
