                dtt.Columns.Add("Retailer Updated Credit", typeof(string));
                dtt.Columns.Add("Comment", typeof(string));
                dtt.Columns.Add("UTR/Slip No.", typeof(string));
                dtt.Columns.Add("Date", typeof(string));
                DateTime fromto = to_date.AddDays(1);
                var respo = db.dealer_to_rem_fund_report(frm_date, fromto, usernm, "ALL", 1, 500).ToList().ToList();

                if (respo.Count > 0)
                {
                    foreach (var item in respo)
                    {
                        dtt.Rows.Add(item.FarmName, item.Frm_Name, item.Head, item.bal_type, item.balance, item.commission, item.balance, item.remain_pre_amount_dealer, item.remain_amount_dealer, item.remain_pre_amount, item.remain_amount, item.oldcrbalance, item.cr, item.comment, item.CollectionBy, item.rechargedate);
