            else
            {
                vmodel.master_to_dealer_report_BYAdmin_Result = db.Master_to_dealer_report_BYAdmin(frm_date, fromto, usernm, "ALL", 1, 500).ToList();
                //return View(vmodel);
                return new ViewAsPdf(vmodel);
            }

        }

