        public JsonResult SaveautoTransferamount(decimal transamnt, decimal minimiumset, int totalfundtrns, decimal Uptolimitt, string remid)
        {
            var AutoCreditTransfer = db.AutoCreditTransfers.Where(x => x.remid == remid).SingleOrDefault();
            if (AutoCreditTransfer != null)
            {
                AutoCreditTransfer.Rem_minimiumamnt = minimiumset;
                AutoCreditTransfer.transferamount = transamnt;
                AutoCreditTransfer.Totalfundytranfersete = totalfundtrns;
                AutoCreditTransfer.MaxCredit = Uptolimitt;
                db.SaveChanges();
            }
            return Json(new { minimiumbal = AutoCreditTransfer.Rem_minimiumamnt, transferamnt = AutoCreditTransfer.transferamount, totalfundtrsf = AutoCreditTransfer.Totalfundytranfersete, uptolimit = AutoCreditTransfer.MaxCredit }, JsonRequestBehavior.AllowGet);
        }

