            }


        }

        public async Task<ActionResult> AutoFundTransferMD()
        {
            // IEnumerable<Autofundtransfermodel> modes;
            Autofundtransfermodelviewmodel modes = new Autofundtransfermodelviewmodel();
            modes.autofundtransfermodel = await (from tbl in db.autofundtransfer_admnin_to_master
                                                 join tbl1 in db.Superstokist_details
