            var adminuserid = User.Identity.GetUserId();

            string transferids = GenerateUniqueTransectionID();
            var transferid = "AD" + transferids;



            TempData["transferadmintodealer"] = transferid;
            return Json(transferid, JsonRequestBehavior.AllowGet);
        }




        private static string GenerateUniqueTransectionID()
        {
            bool includeLowercase = false;
            bool includeUppercase = true;
            bool includeNumeric = true;
            bool includeSpecial = false;
            bool includeSpaces = false;
            int lengthOfPassword = 10;

            string transferids = PasswordGenerator.GeneratePassword(includeLowercase, includeUppercase, includeNumeric, includeSpecial, includeSpaces, lengthOfPassword);
            while (!PasswordGenerator.PasswordIsValid(includeLowercase, includeUppercase, includeNumeric, includeSpecial, includeSpaces, transferids))
            {
                transferids = PasswordGenerator.GeneratePassword(includeLowercase, includeUppercase, includeNumeric, includeSpecial, includeSpaces, lengthOfPassword);
            }

            return transferids;
        }
        [HttpGet]
        public ActionResult changeexptxnpass()
        {
            ViewData["MSG1"] = TempData["error"];
            ViewData["MSG1success"] = TempData["success"];
            TempData.Remove("error");
            TempData.Remove("success");
            var chktranss = db.admin_new_pass.SingleOrDefault();
            DateTime currenttime = DateTime.Now;
            DateTime lastchangedpassdtr = Convert.ToDateTime(chktranss.lastupdatetrans);
            lastchangedpassdtr = lastchangedpassdtr.AddDays(Convert.ToInt32(chktranss.transexpdays));
            var defaultht = Decrypt(chktranss.transpass);
            if (defaultht != "1111" && (lastchangedpassdtr >= currenttime))
            {
                return RedirectToAction("Fund_transfer");
            }
            return View();
        }

        [HttpPost]
        public ActionResult ReGenerateTxnypass([Bind(Prefix = "Item2")] ChangeTransactionViewModel model)
        {
            var oldpin = db.admin_new_pass.Single().transpass;
            var oldp = Decrypt(oldpin);
            if (oldp != model.Oldtransactionpass)
            {
                TempData["error"] = "Your Old Transaction Password does Not Match .Please Re-Enter Your Old Transaction Password ";
                return RedirectToAction("changeexptxnpass");
            }
            var msg = Encrypt(model.Newtransactionpass);

            var id = (from tbl in db.admin_new_pass
                      select tbl).SingleOrDefault();
            id.transpass = msg;
            id.lastupdatetrans = DateTime.Now;
            db.SaveChanges();
            var emailid = db.Admin_details.Single().email;
            var userid = db.Admin_details.Single().userid;
            try
            {
                CommUtilEmail emailsend = new CommUtilEmail();
                emailsend.EmailLimitChk(emailid, emailid, "Transaction Password", "Your New Transaction Password Is  " + model.Newtransactionpass, "No CallBackUrl");
            }
            catch { }
            TempData["success"] = "Your Transaction Password Send Successfully in Your Mail Id . Please Check Your Mail Id.";
            return RedirectToAction("changeexptxnpass");
        }

