        public JsonResult FetchDetails(string id)
        {
            var userlist = (from tbl in db.Dealer_Details
                            join tbl1 in db.Superstokist_details on tbl.SSId equals tbl1.SSId
                            where tbl.DealerId == id
                            select new
                            {
                                Name = tbl.DealerName,
                                farmname = tbl.FarmName,
                                mobile = tbl.Mobile,
                                EMAIL = tbl.Email,
                                ADDRESS = tbl.Address,
                                MDNAME = tbl1.FarmName


                            });
            return Json(userlist, JsonRequestBehavior.AllowGet);
        }

        public JsonResult FetchRetailerDetails(string id)
        {
            var userlist = (from tbl in db.Retailer_Details.Where(aa => aa.ISDeleteuser == false)
