        public ActionResult DealerMD_switch(string dealerid, string masterid)
        {
            int valss = 0;
            var msg = "";
            var oldssid = (db.Dealer_Details.Where(aa => aa.DealerId == dealerid).FirstOrDefault().SSId);
            if (oldssid.ToLower() != masterid.ToLower())
            {
                using (VastwebmultiEntities newdb = new VastwebmultiEntities())
                {
                    Dealer_Details objCourse = (from p in newdb.Dealer_Details
                                                where p.DealerId == dealerid
                                                select p).Single();
                    objCourse.SSId = masterid;
                    // objCourse.slab_name = slab;
                    valss = newdb.SaveChanges();
                    if (valss > 0)
                    {
                        tbl_Switch_DealerTOMD model = new tbl_Switch_DealerTOMD();
                        model.DealerID = dealerid;
                        model.OLDSuperStockistID = oldssid;
                        model.CurrentSuperstockist = objCourse.SSId;
                        model.SwitchDate = DateTime.Now;
                        db.tbl_Switch_DealerTOMD.Add(model);
                        db.SaveChanges();
                        msg = "Distributor Transfer SuccessFully.";
                        return Json(new { Success = "Success", msg = msg }, JsonRequestBehavior.AllowGet);
                    }
                }

                //   TempData["success"] = "Distributor Transfer SuccessFully.";
            }
            else
            {
                TempData["error"] = "Distributor Already Under This Master.";
                msg = "Distributor Already Under This Master.";
            }
            return Json(new { error = "error", msg = msg }, JsonRequestBehavior.AllowGet);
            //  return View();
        }

        [HttpPost]
        public ActionResult dealer_retailer_Switch(string remid, string dlmid)
        {
            var msg = "";
            int valss = 0;
            try
            {
                //var slab = "";
                //var chkslab = db.Slab_name.Where(a => a.createdby == dlmid).Any();
                //if (chkslab == false)
                //{
                //    TempData["slabname"] = "This Distributor Not Assign Any Slab";
