                //}
                //else
                //{
                //    slab = (from pp in db.Slab_name where pp.createdby == dlmid select pp.SlabName).First();
                //}

                var olddlmid = string.Empty;
                var objCourse = db.Retailer_Details.Where(aa => aa.ISDeleteuser == false).SingleOrDefault(p => p.RetailerId.ToLower() == remid.ToLower());
                olddlmid = objCourse.DealerId;
                //var retaileremail = objCourse.Email;
                try
                {
                    objCourse.DealerId = dlmid;
                    //objCourse.slab_name = slab;
