                        model.olddealerid = olddlmid;
                        model.Currentdealerid = objCourse.DealerId;
                        model.SwitchDate = DateTime.Now;
                        db.tblSwitch_RetailerDealer.Add(model);
                        db.SaveChanges();
                        msg = "Retailer Transfer SuccessFully.";

                    }
                }
                catch (Exception ex)
                {
                }
                ViewBag.dlmid = new SelectList(db.select_Dealer_for_ddl(), "Dealerid", "FarmName", null);
                ViewBag.remid = new SelectList(db.select_retailer_for_ddl("Admin"), "RetailerId", "Frm_Name", null);
                var newdlmid = objCourse.DealerId;
                if (olddlmid != newdlmid)
                {
                    var olddlmemailid = (db.Dealer_Details.SingleOrDefault(p => p.DealerId == olddlmid).Email);
                    var newdlmemailid = (db.Dealer_Details.SingleOrDefault(p => p.DealerId == newdlmid));
                    string retailerbody = "Congratulation ! Your Id '" + objCourse.Email + "' is Transfer Successfully to This Distributor. Distributor Id is '" + newdlmemailid.Email + "' and Mobile No is'" + newdlmemailid.Mobile + "'Please Contact As Soon as..";
                    new CommonUtil().Insertsendmail(objCourse.Email, "Your Id Transfer Successfully", retailerbody, retailerbody);

                    string Olddllmbody = "Your Retailer Id '" + objCourse.Email + "' & Mobile no '" + objCourse.Mobile + "' and Farm Name '" + objCourse.Frm_Name + "'  is Transfer to This Distributor Id '" + newdlmemailid.Email + "'.";
                    new CommonUtil().Insertsendmail(olddlmemailid, "Your Retailer Remove Successfully.", Olddllmbody, Olddllmbody);

                    string Newdllmbody = "Contratulation ! This Retailer Id '" + objCourse.Email + "' and Mobile no '" + objCourse.Mobile + "' is Added to Your Account.";
                    new CommonUtil().Insertsendmail(newdlmemailid.Email, "Retailer Added In Our Account.", Newdllmbody, Newdllmbody);



                    TempData["success"] = "Retailer Transfer SuccessFully.";

                    return Json(new { Success = "Success", msg = msg }, JsonRequestBehavior.AllowGet);
                }
                else
                {
                    msg = " Already Under .";
                    return Json(new { error = "error", msg = msg }, JsonRequestBehavior.AllowGet);
                }
            }
            catch (Exception ex)
            {
            }
            return Json(new { error = "error", msg = msg }, JsonRequestBehavior.AllowGet);

