            List<Retailer_Details> paarrentretailerid = db.Retailer_Details.Where(aa => aa.ISDeleteuser == false).ToList();
            List<Retailer_Details> Childretailerid = db.Retailer_Details.Where(aa => aa.ISDeleteuser == false).ToList();
            var reffersettingvmodel = from e in tblRefferalRetailerIncome
                                      join d in paarrentretailerid on e.ParrentRetailerID equals d.RetailerId into table1
                                      from d in table1.ToList()
                                      join i in Childretailerid on e.ChildRetailerID equals i.RetailerId into table2
                                      from i in table2.ToList()
                                      select new RefferalListViewModel
                                      {
                                          referalid = e.RefferalRetailerIncomeID,
                                          ParentReatilerID = e.ParrentRetailerID,
                                          childRetailerID = e.ChildRetailerID,
                                          ParrentRetailerName = d.RetailerName,
                                          childRetailerName = i.RetailerName,
                                          BenifitRecived = e.Benifitrecived.Value,
                                          sharingtype = e.Sharingtype,
                                          sharingvalue = e.sharingvalue.Value,
                                          PreParrentRetailerBalance = e.PreParrentRetailerBalance.Value,
                                          PostParrentRetailerBalance = e.PostParrentRetailerBalance.Value,
                                          RecivedDate = e.RecivedDate.Value,
                                          RefferedType = e.RefferalType


                                      };

            StringBuilder sb = new StringBuilder();

            foreach (var item in reffersettingvmodel)
            {
                sb.Append("<tr>");
                sb.Append("<td style='background-color: #B8DBFD;border: 1px solid #ccc'>" + item.childRetailerName + "</td>");
                sb.Append("<td style='background-color: #B8DBFD;border: 1px solid #ccc'>" + item.RefferedType + "</td>");
                sb.Append("<td style='background-color: #B8DBFD;border: 1px solid #ccc'>" + item.BenifitRecived + "</td>");
                sb.Append("<td style='background-color: #B8DBFD;border: 1px solid #ccc'>" + item.RecivedDate + "</td>");
                sb.Append("<td style='background-color: #B8DBFD;border: 1px solid #ccc'>" + item.ParrentRetailerName + "</td>");
                sb.Append("<td style='background-color: #B8DBFD;border: 1px solid #ccc'>" + item.RecivedDate + "</td>");
                sb.Append("<td style='background-color: #B8DBFD;border: 1px solid #ccc'>" + item.BenifitRecived + "</td>");
                sb.Append("<td style='background-color: #B8DBFD;border: 1px solid #ccc'>" + item.sharingtype + "</td>");
                sb.Append("<td style='background-color: #B8DBFD;border: 1px solid #ccc'>" + item.sharingvalue + "</td>");
                sb.Append("<td style='background-color: #B8DBFD;border: 1px solid #ccc'>" + item.PreParrentRetailerBalance + "</td>");
                sb.Append("<td style='background-color: #B8DBFD;border: 1px solid #ccc'>" + item.PostParrentRetailerBalance + "</td>");
                sb.Append("</tr>");
            }

            ViewBag.testing = sb.ToString();
            //RefferalListViewModel vmodel=new RefferalListViewModel
            //{

            //}
            // db.tblRefferalRetailerIncomes
            return Json(sb.ToString(), JsonRequestBehavior.AllowGet);
        }

