        public JsonResult InsertRefferalsetting(string reftype, decimal minlimit, int noofday, string sharingtype, decimal sharingvalue, string catetype, string ddlReferalcode)
        {
            if (reftype == "Purchases Basis")
            {
                catetype = null;
            }
            var typs = db.tblRefferalsettings.Where(x => x.ReferalType == reftype).Any();
            if (typs == false)
            {
                var result = new tblRefferalsetting();
                result.ReferalType = reftype;
                result.minimiumimit = minlimit;
                result.expnoofday = noofday;
                result.SharingType = sharingtype;
                result.SharingValue = sharingvalue;
                result.category = catetype;
                result.status = false;
                result.dates = DateTime.Today;
                result.purchasetype = ddlReferalcode;
                db.tblRefferalsettings.Add(result);
                var countval = db.SaveChanges();
                if (countval > 0)
                {
                    return Json("Success", JsonRequestBehavior.AllowGet);

                }
            }
            else
            {
                return Json(reftype + " Already Exist", JsonRequestBehavior.AllowGet);
            }
            return Json("Something Wrong", JsonRequestBehavior.AllowGet);
        }

        public JsonResult CHKSTATSETREFFEREDONTIME()
        {
            var result = db.tblRefferalsettings.Where(x => x.status == true).FirstOrDefault();
            if (result != null)
            {
                string reftype = result.ReferalType;   // db.tblRefferalsettings.Where(x => x.status == true).FirstOrDefault().ReferalType;
                return Json(reftype, JsonRequestBehavior.AllowGet);
            }
            return Json("", JsonRequestBehavior.AllowGet);
        }

        public JsonResult CHKSTATSETREFFERED(string name, bool status)
        {
            var result = db.tblRefferalsettings.ToList();
            result.ForEach(x => x.status = false);
            db.SaveChanges();
            var res = db.tblRefferalsettings.Where(x => x.ReferalType == name).Any();
            if (res == true)
            {
                var findreferalid = db.tblRefferalsettings.FirstOrDefault(x => x.ReferalType == name).refferalID;
                tblRefferalsetting model = db.tblRefferalsettings.Where(x => x.refferalID == findreferalid).FirstOrDefault();
                model.status = true;
                db.SaveChanges();
                return Json("Success", JsonRequestBehavior.AllowGet);
            }
            else
            {
                return Json("Erroe", JsonRequestBehavior.AllowGet);
            }
        }



        public JsonResult InsertRefferalsettingEditdata(string reftype, decimal minlimit, int noofday, string sharingtype, decimal sharingvalue, string catetype, int totalcount)
        {
            if (totalcount <= 12 && totalcount > 0)
            {
                if (reftype == "Purchases Basis")
                {
                    catetype = null;
                }

                var referid = db.tblRefferalsettings.Where(x => x.ReferalType == reftype).FirstOrDefault().refferalID;
                var findmodel = db.tblRefferalsettings.Where(x => x.refferalID == referid).FirstOrDefault();
                //  var result = new tblRefferalsetting();

                findmodel.minimiumimit = minlimit;
                findmodel.expnoofday = noofday;
                findmodel.SharingType = sharingtype;
                findmodel.SharingValue = sharingvalue;
                findmodel.category = catetype;
                findmodel.benifitrepeat = totalcount == 0 ? 1 : totalcount;



                var countval = db.SaveChanges();
                if (countval > 0)
                {
                    return Json("Success", JsonRequestBehavior.AllowGet);

                }
            }

            return Json("Something Wrong", JsonRequestBehavior.AllowGet);
        }
        public JsonResult DeleteReferedCode(string type)
        {

            var res = db.tblRefferalsettings.Where(x => x.ReferalType == type).Any();
            if (res == true)
            {
                int findreferalid = db.tblRefferalsettings.FirstOrDefault(x => x.ReferalType == type).refferalID;
                tblRefferalsetting model = db.tblRefferalsettings.Where(x => x.refferalID == findreferalid).FirstOrDefault();
                db.tblRefferalsettings.Remove(model);
                int count = db.SaveChanges();
                if (count > 0)
                {
                    return Json(type, JsonRequestBehavior.AllowGet);
                }
                return Json("Erroe", JsonRequestBehavior.AllowGet);
            }
            else
            {
                return Json("Erroe", JsonRequestBehavior.AllowGet);
            }
        }

        public JsonResult GetRefferalSetting()
        {
            var purchaseBasic = db.tblRefferalsettings.Where(x => x.ReferalType == "Purchases Basis").FirstOrDefault();
            var BusnewwBasic = db.tblRefferalsettings.Where(x => x.ReferalType == "business Basis").FirstOrDefault();
            return Json(new { purchaseBasic = purchaseBasic, BusnewwBasic = BusnewwBasic }, JsonRequestBehavior.AllowGet);
        }

        //sales report
        [HttpGet]
        public ActionResult total_daily_income()
        {
            string txt_to_date1 = DateTime.Now.ToString();
            var frm_date = Convert.ToDateTime(txt_to_date1).ToShortDateString();
            var to_date = Convert.ToDateTime(txt_to_date1).AddDays(1).ToString();
            Vastwebmulti.Areas.ADMIN.Models.salesincome viewModel = new Vastwebmulti.Areas.ADMIN.Models.salesincome();
            viewModel.sales = db.main_rch_total(Convert.ToDateTime(frm_date), Convert.ToDateTime(to_date)).ToList();
            return View(viewModel);
        }
        [HttpPost]
        public ActionResult total_daily_income(string txt_frm_date, string txt_to_date)
        {
            ViewBag.chk = "post";
            DateTime frm = Convert.ToDateTime(txt_frm_date);
            DateTime to = Convert.ToDateTime(txt_to_date);

            txt_frm_date = frm.ToString("dd-MM-yyyy");
            txt_to_date = to.ToString("dd-MM-yyyy");


            string[] formats = new[] { "MM/dd/yyyy", "dd-MMM-yyyy",
                            "yyyy-MM-dd", "dd-MM-yyyy", "dd MMM yyyy" };
            DateTime dt = !string.IsNullOrWhiteSpace(txt_frm_date) ? DateTime.ParseExact(txt_frm_date, formats, CultureInfo.InvariantCulture, DateTimeStyles.None) : DateTime.Now;
            DateTime dt1 = !string.IsNullOrWhiteSpace(txt_to_date) ? DateTime.ParseExact(txt_to_date, formats, CultureInfo.InvariantCulture, DateTimeStyles.None) : DateTime.Now;
            DateTime frm_date = Convert.ToDateTime(dt).Date;
            DateTime to_date = Convert.ToDateTime(dt1).Date.AddDays(1);

            Vastwebmulti.Areas.ADMIN.Models.salesincome viewModel = new Vastwebmulti.Areas.ADMIN.Models.salesincome();
            viewModel.sales = db.main_rch_total(Convert.ToDateTime(frm_date), Convert.ToDateTime(to_date)).ToList();
            return View(viewModel);
        }

        [HttpGet]
        public JsonResult GetRetailerByDealer(string dealerId)
        {
            // DealerId के हिसाब से retailers निकालो
            var retailers = db.select_retailer_for_ddl(dealerId.ToString())
                  .Select(r => new
