        [HttpGet]
        public JsonResult GetServiceListByRetailer(string retailerId)
        {
            // RetailerId से summary record लो
            var summary = db.GetRetailerTxnSummary(null, null, retailerId, null, null).FirstOrDefault();

            // अगर data नहीं मिला
            if (summary == null)
            {
                return Json(new List<object>(), JsonRequestBehavior.AllowGet);
            }

            // Services list बनाओ (same जैसे Retailer list में किया था)
            var services = new List<object>
             {
                 new { Value = "IMPS",     Text = "IMPS",     UserDiff = summary.Imps_UserDiff },
                 new { Value = "Recharge", Text = "Recharge", UserDiff = summary.Recharge_UserDiff },
                 new { Value = "AEPS",     Text = "AEPS",     UserDiff = summary.Aeps_UserDiff },
                 new { Value = "MicroATM", Text = "MicroATM", UserDiff = summary.MicroAtm_UserDiff }
             };

            return Json(services, JsonRequestBehavior.AllowGet);
        }



        //User wise Operator comm report

        public ActionResult User_wise_operator_comm()
        {
            string txt_frm_date = DateTime.Now.ToString();
            string txt_to_date = DateTime.Now.ToString();
            string frm_date = Convert.ToDateTime(txt_frm_date).Date.ToString("yyyy-MM-dd");
            string to_date = Convert.ToDateTime(txt_to_date).AddDays(1).ToString("yyyy-MM-dd");

            // show master id 
            var stands = db.Superstokist_details.ToList();
            IEnumerable<SelectListItem> selectList = from s in stands
                                                     select new SelectListItem
                                                     {
                                                         Value = s.SSId,
                                                         Text = s.FarmName.ToString()
                                                     };
            ViewBag.allmaster = new SelectList(selectList, "Value", "Text");

            // show whitelabel
            var totalwhitelabel = db.WhiteLabel_userList.ToList();
            IEnumerable<SelectListItem> selectList1 = from s in totalwhitelabel
                                                      select new SelectListItem
                                                      {
                                                          Value = s.WhiteLabelID,
                                                          Text = s.FrmName.ToString()
                                                      };
            ViewBag.allwhitelabel = new SelectList(selectList1, "Value", "Text");

            // show dealer
            ViewBag.alldealer = new SelectList(db.select_Dealer_for_ddl(), "Dealerid", "FarmName", null).ToList();

            // Retailer 
            ViewBag.allretailer = new SelectList(db.select_retailer_for_ddl("Admin"), "RetailerId", "Frm_Name", null).ToList();

            // api users 
            ViewBag.apiid = new SelectList(db.select_apiusers_for_ddl("Admin"), "apiid", "username", null);

            // ---- Existing Admin level commission report ----
            var ch = db.User_wise_comm_report("Admin", "ALL", 50, Convert.ToDateTime(frm_date), Convert.ToDateTime(to_date)).ToList();
            ViewData["totalrch"] = ch.Where(a => a.optnm != "Money" && a.optnm != "Pancard" && a.optnm != "Aeps").Sum(a => a.total);
            ViewData["totalmoney"] = ch.Where(a => a.optnm == "Money").Sum(a => a.total);
            ViewData["totalpancard"] = ch.Where(a => a.optnm == "Pancard").Sum(a => a.total);
            ViewData["totalaesps"] = ch.Where(a => a.optnm == "Aeps").Sum(a => a.total);
            ViewData["remincome"] = ch.Sum(x => x.remincome);

            // ---- Dealer Income Calculation (GetRetailerTxnSummary se) ----
            var dealers = db.select_Dealer_for_ddl().ToList();
            var dealerIncomeList = new List<dynamic>();

            foreach (var dealer in dealers)
            {
                decimal dealerTotal = 0;

                var retailers = db.select_retailer_for_ddl(dealer.DealerId).ToList();
                foreach (var retailer in retailers)
                {
                    var summary = db.GetRetailerTxnSummary(null, dealer.DealerId, retailer.RetailerId, null, null).FirstOrDefault();
                    if (summary != null)
                    {
                        dealerTotal += (summary.Recharge_UserDiff
                                     + summary.Imps_UserDiff
                                     + summary.Aeps_UserDiff
                                     + summary.MicroAtm_UserDiff);
                    }
                }

                dealerIncomeList.Add(new
                {
                    DealerId = dealer.DealerId,
                    DealerName = dealer.FarmName,
                    TotalIncome = dealerTotal
                });
            }

            // ViewBag me Dealer Income set
            ViewBag.DealerIncome = dealerIncomeList.ToDictionary(d => d.DealerId, d => new { d.DealerName, d.TotalIncome });

            return View(ch);
        }



