        [HttpPost]
        public ActionResult User_wise_operator_comm(DateTime txt_frm_date, DateTime txt_to_date, string ddlusers, string allmaster, string alldealer, string allretailer, string allwhitelabel, string ddl_top, string allapiuser)
        {
            var userid = "";

            ViewBag.chk = "post";
            // show master id 
            var stands = db.Superstokist_details.ToList();
            IEnumerable<SelectListItem> selectList = from s in stands
                                                     select new SelectListItem
                                                     {
                                                         Value = s.SSId,
                                                         Text = s.Email + "--" + s.SuperstokistName.ToString()
                                                     };
            ViewBag.allmaster = new SelectList(selectList, "Value", "Text");
            //show whitelabel
            var totalwhitelabel = db.WhiteLabel_userList.ToList();
            IEnumerable<SelectListItem> selectList1 = from s in totalwhitelabel
                                                      select new SelectListItem
                                                      {
                                                          Value = s.WhiteLabelID,
                                                          Text = s.EmailId + "--" + s.Name.ToString()
                                                      };
            ViewBag.allwhitelabel = new SelectList(selectList1, "Value", "Text");
            //show dealer
            ViewBag.alldealer = new SelectList(db.select_Dealer_for_ddl(), "Dealerid", "FarmName", null).ToList();
            //Retailer 
            ViewBag.allretailer = new SelectList(db.select_retailer_for_ddl("Admin"), "RetailerId", "Frm_Name", null).ToList();
            //api users 
            ViewBag.apiid = new SelectList(db.select_apiusers_for_ddl("Admin"), "apiid", "username", null);


            ddl_top = "1000000";


            int ddltop = Convert.ToInt32(ddl_top);
            if (ddlusers == "Master" && allmaster != "")
            {
                userid = allmaster;

            }
            else if (ddlusers == "Master")
            {
                userid = "ALL";
            }
            if (ddlusers == "Dealer" && alldealer != "")
            {
                userid = alldealer;
            }
            else if (ddlusers == "Dealer")
            {
                userid = "ALL";
            }
            if (ddlusers == "Retailer" && allretailer != "")
            {
                userid = allretailer;
            }
            else if (ddlusers == "Retailer")
            {
                userid = "ALL";
            }
            if (ddlusers == "Whitelabel" && allwhitelabel != "")
            {
                userid = allwhitelabel;
            }
            else if (ddlusers == "Whitelabel")
            {
                userid = "ALL";
            }
            if (ddlusers == "APIID" && allapiuser != "")
            {
                userid = allapiuser;
            }
            else if (ddlusers == "APIID")
            {
                userid = "ALL";
            }

            if (ddlusers == "Admin")
            {
                userid = "ALL";
            }
            txt_to_date = txt_to_date.AddDays(1);
            //show whitelabel
            var ch = db.User_wise_comm_report(ddlusers, userid, ddltop, txt_frm_date, txt_to_date).ToList();
            ViewData["totalrch"] = ch.Where(a => a.optnm != "Money" && a.optnm != "Pancard" && a.optnm != "Aeps").Sum(a => a.total);
            ViewData["totalmoney"] = ch.Where(a => a.optnm == "Money").Sum(a => a.total);
            ViewData["totalpancard"] = ch.Where(a => a.optnm == "Pancard").Sum(a => a.total);
            ViewData["totalaesps"] = ch.Where(a => a.optnm == "Aeps").Sum(a => a.total);
            ViewData["remincome"] = ch.Sum(x => x.remincome);

            // ---- Dealer Income Calculation (GetRetailerTxnSummary se) ----
            var dealers = db.select_Dealer_for_ddl().ToList();
            var dealerIncomeList = new List<dynamic>();

            foreach (var dealer in dealers)
            {
                decimal dealerTotal = 0;

                var retailers = db.select_retailer_for_ddl(dealer.DealerId).ToList();
                foreach (var retailer in retailers)
                {
                    var summary = db.GetRetailerTxnSummary(
                        null,
                        dealer.DealerId,
                        retailer.RetailerId,
                        txt_frm_date,
                        txt_to_date
                    ).FirstOrDefault();

                    if (summary != null)
                    {
                        dealerTotal += summary.Recharge_DealerDiff
                                      + summary.Imps_DealerDiff
                                      + summary.Aeps_DealerDiff
                                      + summary.MicroAtm_DealerDiff;

                        // ✅ अब RetailerName जो DB में है वही use करो
                        dealerIncomeList.Add(new
                        {
                            DealerId = dealer.DealerId,
                            DealerName = dealer.FarmName,
                            RetailerName = retailer.RetailerName,  // DB column के अनुसार
                            TotalIncome = dealerTotal
                        });
                    }
                }
            }

            // ViewBag dictionary
            ViewBag.DealerIncome = dealerIncomeList.ToDictionary(
                d => d.RetailerName,
                d => d.TotalIncome
            );


            return View(ch);
        }


