        public ActionResult ExcelUserWiseOperatorCommreport(DateTime txt_frm_date, DateTime txt_to_date, string ddlusers, string allmaster, string alldealer, string allretailer, string allwhitelabel, string ddl_top, string allapiuser)
        {
            var userid = "";

            var stands = db.Superstokist_details.ToList();
            IEnumerable<SelectListItem> selectList = from s in stands
                                                     select new SelectListItem
                                                     {
                                                         Value = s.SSId,
                                                         Text = s.Email + "--" + s.SuperstokistName.ToString()
                                                     };

            var totalwhitelabel = db.WhiteLabel_userList.ToList();
            IEnumerable<SelectListItem> selectList1 = from s in totalwhitelabel
                                                      select new SelectListItem
                                                      {
                                                          Value = s.WhiteLabelID,
                                                          Text = s.EmailId + "--" + s.Name.ToString()
                                                      };


            ddl_top = "1000000";


            int ddltop = Convert.ToInt32(ddl_top);
            if (ddlusers == "Master" && allmaster != "")
            {
                userid = allmaster;
            }
            else if (ddlusers == "Master")
            {
                userid = "ALL";
            }
            if (ddlusers == "Dealer" && alldealer != "")
            {
                userid = alldealer;
            }
            else if (ddlusers == "Dealer")
            {
                userid = "ALL";
            }
            if (ddlusers == "Retailer" && allretailer != "")
            {
                userid = allretailer;
            }
            else if (ddlusers == "Retailer")
            {
                userid = "ALL";
            }
            if (ddlusers == "Whitelabel" && allwhitelabel != "")
            {
                userid = allwhitelabel;
            }
            else if (ddlusers == "Whitelabel")
            {
                userid = "ALL";
            }
            if (ddlusers == "APIID" && allapiuser != "")
            {
                userid = allapiuser;
            }
            else if (ddlusers == "APIID")
            {
                userid = "ALL";
            }

            if (ddlusers == "Admin")
            {
                userid = "ALL";
            }
            txt_to_date = txt_to_date.AddDays(1);
            //show whitelabel
            var ch = db.User_wise_comm_report(ddlusers, userid, ddltop, txt_frm_date, txt_to_date).ToList();


            DataTable dt = new DataTable();
            dt.Columns.Add("Email Id", typeof(string));
            dt.Columns.Add("Name", typeof(string));
            dt.Columns.Add("Firm Name", typeof(string));
            dt.Columns.Add("Operator Name", typeof(string));
            dt.Columns.Add("Income", typeof(string));
            dt.Columns.Add("Total Success", typeof(string));

            if (ch.Count > 0)
            {
                foreach (var item in ch)
                {
                    dt.Rows.Add(item.Email, item.RetailerName, item.Frm_Name, item.optnm, item.remincome, item.total);
                }
            }
            else
            {
                dt.Rows.Add("", "", "", "", "", "");
            }


            var grid = new GridView();
            grid.DataSource = dt;
            grid.DataBind();
            Response.ClearContent();
            Response.Buffer = true;
            Response.AddHeader("content-disposition", "attachment; filename=UserWiseOperatorCommReport.xls");
            Response.ContentType = "application/ms-excel";
            Response.Charset = "";
            StringWriter sw = new StringWriter();
            HtmlTextWriter htw = new HtmlTextWriter(sw);
            grid.RenderControl(htw);
            Response.Output.Write(sw.ToString());
            Response.Flush();
            Response.End();

            return View();
        }

        [HttpPost]
        public ActionResult insert_purchage(string txtport, string txtoptname, decimal purcharge, string tttt)
        {
            try
            {
                var imei = (from hh in db.PortManagers where hh.PortNo == txtport select hh).Single().Lapuno.ToString();
                string[] words = tttt.Split('-');
                string month = words[0].ToString();
                string date = words[1].ToString();
                string year = words[2].ToString();
                string dtfrm = year + "-" + month + "-" + date;
                DateTime dd = Convert.ToDateTime(dtfrm);
                int count = (from gg in db.purcharge_bal where gg.portno == txtport where gg.imeino == imei where gg.gdate == dd select gg).Count();
                if (count == 0)
                {
                    purcharge_bal objCourse = new purcharge_bal();
                    objCourse.portno = txtport;
                    objCourse.simname = txtoptname;
                    objCourse.purcharge = purcharge;
                    objCourse.gdate = dd;
                    objCourse.imeino = imei;
                    db.purcharge_bal.Add(objCourse);
                    db.SaveChanges();
                }
                else
                {
                    purcharge_bal objCourse = (from p in db.purcharge_bal
                                               where p.portno == txtport
                                               where p.imeino == imei
                                               where p.gdate == dd
                                               select p).Single();
                    objCourse.purcharge = purcharge;
                    db.SaveChanges();
                }
                return RedirectToAction("Total_Report");
            }
            catch
            {
                return RedirectToAction("Total_Report");
            }
        }
