        //Admin Income
        //Admin Income
        public ActionResult Admin_Income()
        {
            string txt_to_date1 = DateTime.Now.ToString();
            var frm_date = Convert.ToDateTime(txt_to_date1).ToShortDateString();
            var to_date = Convert.ToDateTime(txt_to_date1).AddDays(1).ToShortDateString();
            var apinm = (from jj in db.api_name select jj).OrderBy(a => a.apiname).ToList();
            ViewBag.apinm = new SelectList(apinm, "apiname", "apiname");
            var portno = (from jj in db.PortManagers select jj).ToList();
            ViewBag.portno = new SelectList(portno, "PortNo", "PortNo");
            var optnm = (from jj in db.Operator_Code select new { optnm = jj.operator_Name }).ToList();
            ViewBag.optnm = new SelectList(optnm.Distinct(), "optnm", "optnm");
            var ch = db.admin_income(Convert.ToDateTime(frm_date), Convert.ToDateTime(to_date), "All", "All", "All", "All").ToList();
            var ch1 = db.select_opt_show(Convert.ToDateTime(frm_date), Convert.ToDateTime(to_date)).ToList();
            var roffer = ch1.Sum(m => m.total);
            var adminincome = ch.Select(x => x.admin_income).Sum();
            adminincome = adminincome + roffer;
            ViewData["totalrch"] = ch.Where(a => a.type != "Money" && a.type != "Pancard" && a.type != "Aeps").Sum(a => a.total);
            ViewData["totalmoney"] = ch.Where(a => a.type == "Money").Sum(a => a.total);
            ViewData["totalpancard"] = ch.Where(a => a.type == "Pancard").Sum(a => a.total);
            ViewData["totalaesps"] = ch.Where(a => a.type == "Aeps").Sum(a => a.total);
            ViewData["wlincome"] = ch.Where(a => a.UserRole == "Whitelabel").Sum(a => a.whitelabelincome);
            ViewData["remincome"] = ch.Where(a => a.UserRole == "Retailer").Sum(a => a.remincome);
            ViewData["dlmincome"] = ch.Where(a => a.UserRole == "Retailer").Sum(a => a.dlmincome);
            ViewData["masterincome"] = ch.Where(a => a.UserRole == "Retailer").Sum(a => a.masterincome);
            ViewData["apiincome"] = ch.Select(x => x.apiincome).Sum();
            ViewData["purcharge"] = ch.Select(x => x.purchase).Sum();
            ViewData["roffer"] = roffer;
            var purchase = ViewData["purcharge"];
            var remincome = ViewData["remincome"];
            var dlmincome = ViewData["dlmincome"];
            var masterincome = ViewData["masterincome"];
            var apiincome = ViewData["apiincome"];
            var wlincome = ViewData["wlincome"];
            decimal totaladmininc = Convert.ToDecimal(purchase) - (Convert.ToDecimal(remincome) + Convert.ToDecimal(dlmincome) + Convert.ToDecimal(masterincome) + Convert.ToDecimal(apiincome) + Convert.ToDecimal(wlincome));
            //ViewData["adminincome"] = ch.Select(x => x.admin_income).Sum();
            ViewData["adminincome"] = totaladmininc;
            return View(ch);
        }
