        public ActionResult HoldAndLeanAmountReport()
        {
            var fromdate = DateTime.Now.Date;
            var todate = fromdate.AddDays(1);
            ViewBag.allretailer = new SelectList(db.select_retailer_for_ddl("Admin"), "RetailerId", "Frm_Name", null);

            var results = (
    from s in db.HoldBalanceReports.Where(x => x.insertdate >= fromdate && x.insertdate < todate)

    join t in db.Retailer_Details
        on s.userid equals t.RetailerId.ToString()

    select new HoldleanHIstrory
    {
        Name = t.RetailerName,
        Firmname = t.Frm_Name,

        InsertDate = s.insertdate,
        Amount = s.Amount,
        RemainPre = s.remainpre,
        RemainPost = s.Remainpost,
        Type = s.Type,
        RequestId = s.Requestid,
        Description = s.Description,
        HoldRemainPre = s.holdremainpre,
        HoldRemainPost = s.holdremainpost,
        Status = s.Status
    }
).OrderByDescending(aa => aa.InsertDate).ToList();
            var total = db.HoldRemainbalances.Sum(aa => aa.Remainbal);
            ViewBag.total = total;

            return View(results);
        }
