        public ActionResult ExcellGenerateForAdminLedger(string txt_frm_date, string ddlusers, string allmaster, string alldealer, string allretailer, string allwhitelabel, string allapiuser)
        {
            try
            {
                string txtfrm = DateTime.Now.Date.ToString();
                string frm_date = Convert.ToDateTime(txt_frm_date).Date.ToString();
                string to_date = Convert.ToDateTime(txt_frm_date).AddDays(1).ToString();
                var userid = User.Identity.GetUserId();
                var role = ""; var name = ""; var firmname = ""; var number = "";
                if (ddlusers == "Master" && allmaster != "")
                {
                    userid = allmaster;
                    role = "Master";
                    var chk = db.Superstokist_details.Where(aa => aa.SSId == userid).SingleOrDefault();
                    name = chk.SuperstokistName;
                    firmname = chk.FarmName;
                    number = chk.Mobile;
                }
                if (ddlusers == "Dealer" && alldealer != "")
                {
                    role = "Dealer";
                    userid = alldealer;
                    var chk = db.Dealer_Details.Where(aa => aa.DealerId == userid).SingleOrDefault();
                    name = chk.DealerName;
                    firmname = chk.FarmName;
                    number = chk.Mobile;
                }
                if (ddlusers == "Retailer" && allretailer != "")
                {
                    role = "Retailer";
                    userid = allretailer;
                    var chk = db.Retailer_Details.Where(aa => aa.RetailerId == userid).SingleOrDefault();
                    name = chk.RetailerName;
                    firmname = chk.Frm_Name;
                    number = chk.Mobile;

                }
                if (ddlusers == "Whitelabel" && allwhitelabel != "")
                {
                    role = "Whitelabel";
                    userid = allwhitelabel;
                    var chk = db.WhiteLabel_userList.Where(aa => aa.WhiteLabelID == userid).SingleOrDefault();
                    name = chk.Name;
                    firmname = chk.FrmName;
                    number = chk.Mobile;

                }
                if (ddlusers == "API" && allapiuser != "")
                {
                    role = "API";
                    userid = allapiuser;
                    var chk = db.api_user_details.Where(aa => aa.apiid == userid).SingleOrDefault();
                    name = chk.username;
                    firmname = chk.farmname;
                    number = chk.mobile;

                }
                if (ddlusers == "Admin")
                {
                    role = "Admin";
                    userid = "Admin";
                    name = "No Data Found";
                    firmname = "No Data Found";
                    number = "No Data Found";
                }

                DataTable dt = new DataTable("Grid");



                if (ddlusers == "Whitelabel")
                {
                    dt.Columns.AddRange(new DataColumn[12] {
                   new DataColumn("role"),
                   new DataColumn("Name"),
                    new DataColumn("Firm Name"),
                    new DataColumn("Reg Number"),
                    new DataColumn("Request Id"),
                    new DataColumn("Particular Details"),
                    new DataColumn("Amount"),
                    new DataColumn("Credit"),
                    new DataColumn("Debit"),
                    new DataColumn("WhitelabelPre"),
                    new DataColumn("WhitelabelPost"),
                    new DataColumn("Date & Time") });


                }

                else
                {
                    dt.Columns.AddRange(new DataColumn[11] {
                                            new DataColumn("role"),
                                            new DataColumn("Name"),
                                            new DataColumn("Firm Name"),
                                            new DataColumn("Reg Number"),
                                            new DataColumn("Request Id"),
                                            new DataColumn("Particular Details"),
                                            new DataColumn("Amount"),
                                            new DataColumn("Credit"),
                                            new DataColumn("Debit"),
                                            new DataColumn("Balance"),
                                            new DataColumn("Date & Time") });
                }



                var listall = db.Retailer_Cr_Dr_Report(ddlusers, userid, Convert.ToDateTime(frm_date), Convert.ToDateTime(to_date)).OrderByDescending(x => x.Date).ToList();

                if (ddlusers == "Whitelabel")
                {
                    foreach (var item in listall)
                    {

                        dt.Rows.Add(role, name, firmname, number, item.RequestId, item.Particulars, item.Amount, item.credit, item.debit, item.Balance, item.UserActualRemainAmount, item.Date);


                    }
                }
                else
                {

                    foreach (var item in listall)
                    {

                        dt.Rows.Add(role, name, firmname, number, item.RequestId, item.Particulars, item.Amount, item.credit, item.debit, item.Balance, item.Date);


                    }

                }




                using (XLWorkbook wb = new XLWorkbook())
                {

                    wb.Worksheets.Add(dt);

                    using (MemoryStream stream = new MemoryStream())
                    {
                        wb.SaveAs(stream);
                        return File(stream.ToArray(), "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet", "Ledgerlist.xlsx");
                    }
                }
            }
            catch (Exception ex)
            {
                return RedirectToAction("AdminLedger");
            }


        }

        public ActionResult PrintAdminLedgerPartialViewToPdf(string txt_frm_date, string ddlusers, string allmaster, string alldealer, string allretailer, string allwhitelabel, string allapiuser)
        {
            string txtfrm = DateTime.Now.Date.ToString();
            string frm_date = Convert.ToDateTime(txt_frm_date).Date.ToString();
            string to_date = Convert.ToDateTime(txt_frm_date).AddDays(1).ToString();
            var userid = User.Identity.GetUserId();
            var role = ""; var name = ""; var firmname = ""; var number = "";
            if (ddlusers == "Master" && allmaster != "")
            {
                userid = allmaster;
                role = "Master";
                var chk = db.Superstokist_details.Where(aa => aa.SSId == userid).SingleOrDefault();
                name = chk.SuperstokistName;
                firmname = chk.FarmName;
                number = chk.Mobile;
            }
            if (ddlusers == "Dealer" && alldealer != "")
            {
                role = "Dealer";
                userid = alldealer;
                var chk = db.Dealer_Details.Where(aa => aa.DealerId == userid).SingleOrDefault();
                name = chk.DealerName;
                firmname = chk.FarmName;
                number = chk.Mobile;
            }
            if (ddlusers == "Retailer" && allretailer != "")
            {
                role = "Retailer";
                userid = allretailer;
                var chk = db.Retailer_Details.Where(aa => aa.RetailerId == userid).SingleOrDefault();
                name = chk.RetailerName;
                firmname = chk.Frm_Name;
                number = chk.Mobile;

            }
            if (ddlusers == "Whitelabel" && allwhitelabel != "")
            {
                role = "Whitelabel";
                userid = allwhitelabel;
                var chk = db.WhiteLabel_userList.Where(aa => aa.WhiteLabelID == userid).SingleOrDefault();
                name = chk.Name;
                firmname = chk.FrmName;
                number = chk.Mobile;

            }
            if (ddlusers == "API" && allapiuser != "")
            {
                role = "API";
                userid = allapiuser;
                var chk = db.api_user_details.Where(aa => aa.apiid == userid).SingleOrDefault();
                name = chk.username;
                firmname = chk.farmname;
                number = chk.mobile;

            }
            if (ddlusers == "Admin")
            {
                role = "Admin";
                userid = "Admin";
                name = "No Data Found";
                firmname = "No Data Found";
                number = "No Data Found";
            }

            ViewBag.role = role;
            ViewBag.name = name;
            ViewBag.firmname = firmname;
            ViewBag.number = number;


            var ledger = db.Retailer_Cr_Dr_Report(ddlusers, userid, Convert.ToDateTime(frm_date), Convert.ToDateTime(to_date)).ToList();


            var report = new PartialViewAsPdf("_PDFAdminLagerlist", ledger);
            return report;

        }




