            dataTbl.Columns.Add("Charge", typeof(string));
            dataTbl.Columns.Add("From Acc No", typeof(string));
            dataTbl.Columns.Add("UtrNo/SlipNo", typeof(string));
            dataTbl.Columns.Add("Comment", typeof(string));
