        //[HttpPost]

        [HttpPost]
        public ActionResult process_sender_cyber(string sender_number)
        {
            try
            {
                var ch = "";
                moneytransfer_cyberplate cb = new moneytransfer_cyberplate();
                //ssl.CERTNo = "6804FEEE6755D0FEDB0F534FBF4A673C2E14EF14";
                ch = cb.customer_verify(sender_number);
                if (ch == "ERRORCHECK")
                {
                    var results = "{'message':'Error Please Try After Some Time!!!','status':'failure'}";
                    var jss = new JavaScriptSerializer();
                    var dict = jss.Deserialize<dynamic>(results);
                    return Json(dict, JsonRequestBehavior.AllowGet);
                }
                else
                {
                    int start1 = ch.IndexOf("ERROR=") + 6;
                    int end1 = ch.IndexOf("\r\n", start1);
                    string result = ch.Substring(start1, end1 - start1);
                    var results = "";
                    if (result == "0")
                    {
                        int start = ch.IndexOf("ADDINFO=") + 8;
                        int end = ch.IndexOf("AUTHCODE=NA", start);
                        results = ch.Substring(start, end - start);
                    }
                    else if (result == "23")
                    {
                        int start = ch.IndexOf("ERRMSG=") + 7;
                        int end = ch.IndexOf("\r\n", start);
                        var mss = ch.Substring(start, end - start);
                        if (mss == "CARD IS NOT CREATED BY THIS MOBILE NO.")
                        {
                            results = "{'CardExists':'N','status':'Success'}";
                        }
                        else
                        {
                            results = "{'message':'" + mss + "','status':'failure'}";
                        }
                    }
                    var jss = new JavaScriptSerializer();
                    var dict = jss.Deserialize<dynamic>(results);
                    return Json(dict, JsonRequestBehavior.AllowGet);
                }
            }
            catch (Exception ex)
            {
                var msg = ex.Message.ToString();
                var results = "{'message':'" + msg + "','status':'failure'}";
                var jss = new JavaScriptSerializer();
                var dict = jss.Deserialize<dynamic>(results);
                return Json(dict, JsonRequestBehavior.AllowGet);
            }
        }

        public ActionResult GeneratePDF(string Idno)
        {
            return new Rotativa.ActionAsPdf("PDF", new { Idno = Idno });
        }
        public ActionResult PDF(string Idno)
        {
            var user = User.Identity.GetUserId();
            var ch = db.pdf_creator(Idno).ToList();
            var retailerid = ch.First().rch_from;
            var gg = (from hh in db.Retailer_Details where hh.RetailerId == retailerid select hh).ToList();
            ViewData["retailername"] = gg.Single().RetailerName;
            ViewData["frmname"] = gg.Single().Frm_Name;
            ViewData["retailermobile"] = gg.Single().Mobile;
            ViewData["Total"] = ch.Sum(s => s.amount);
            var ddtt = ch.First().trans_time;
            ViewData["retailerdate"] = ddtt;
            ViewData["invoiceno"] = Idno.ToUpper();
            ViewData["date"] = System.DateTime.Now;
            return View(ch);
        }
        [HttpGet]

        public ActionResult Recharge_Report()
        {

            string txt_frm_date = DateTime.Now.ToString();
            string txt_to_date = DateTime.Now.ToString();
            string frm_date = Convert.ToDateTime(txt_frm_date).Date.ToString("yyyy-MM-dd");
            string to_date = Convert.ToDateTime(txt_to_date).AddDays(1).ToString("yyyy-MM-dd");
            var stands = db.Superstokist_details.ToList();
            IEnumerable<SelectListItem> selectList = from s in stands
                                                     select new SelectListItem
                                                     {
                                                         Value = s.SSId,
                                                         Text = s.FarmName.ToString()
                                                     };
            ViewBag.allmaster = new SelectList(selectList, "Value", "Text");
            ViewBag.alldealer = new SelectList(db.select_Dealer_for_ddl(), "Dealerid", "FarmName", null);
            ViewBag.allretailer = new SelectList(db.select_retailer_for_ddl("Admin"), "RetailerId", "Frm_Name", null);
            ViewBag.API = new SelectList(db.API_all_apiid(), "apiid", "apiuser");
            ViewBag.whitelabel = new SelectList(db.Whitelabel_all_whitelabelid(), "WhiteLabelID", "FrmName").ToList();
            var operator_value = db.Operator_Code.Distinct().ToList();
            ViewBag.Operator = new SelectList(operator_value, "new_opt_code", "operator_Name");
            //toltal count amount success and pending and failed
            var Liverechargecount = db.Recharge_Report_live(Convert.ToDateTime(frm_date), Convert.ToDateTime(to_date), "Admin", "ALL", "ALL", "ALL", "ALL", 25).ToList();
            var totalsuccesscount = Liverechargecount.Where(a => a.rstatus.ToUpper() == "SUCCESS").Sum(a => a.amount);
            var totalfailed = Liverechargecount.Where(a => a.rstatus.ToUpper() == "FAILED").Sum(a => a.amount);
            var totalpending = Liverechargecount.Where(a => a.rstatus.ToUpper().Contains("REQ")).Sum(a => a.amount);

            ViewData["Totals"] = totalsuccesscount;
            ViewData["Totalf"] = totalfailed;
            ViewData["Totalp"] = totalpending;

            //ViewData["TotalAPI_INC"] = API_Inc;
            //end
            Vastwebmulti.Areas.ADMIN.Models.recharge_report viewModel = new Vastwebmulti.Areas.ADMIN.Models.recharge_report();
            viewModel.rechargereport = db.Recharge_Report_live(Convert.ToDateTime(frm_date), Convert.ToDateTime(to_date), "Admin", "ALL", "ALL", "ALL", "ALL", 50).ToList();

            return View(viewModel);
        }
