        public virtual ActionResult ExcelRechargereport_Dispute(string ddl_status, string txt_frm_date, string txt_to_date)
        {
            DataTable dt2 = new DataTable();
            dt2.Columns.Add("Status", typeof(string));
            dt2.Columns.Add("User Firm", typeof(string));
            dt2.Columns.Add("Rch No.", typeof(string));
            dt2.Columns.Add("Amount", typeof(string));
            dt2.Columns.Add("Operator", typeof(string));
            dt2.Columns.Add("Port No", typeof(string));
            dt2.Columns.Add("Port Nm", typeof(string));
            dt2.Columns.Add("Rch Time", typeof(string));
            dt2.Columns.Add("Disp Time", typeof(string));
            dt2.Columns.Add("Dispute Reason", typeof(string));
            dt2.Columns.Add("Transition ID", typeof(string));
            dt2.Columns.Add("Response", typeof(string));

            DateTime frm = DateTime.ParseExact(txt_frm_date, "MM/dd/yyyy", System.Globalization.CultureInfo.InvariantCulture);
            DateTime to = DateTime.ParseExact(txt_to_date, "MM/dd/yyyy", System.Globalization.CultureInfo.InvariantCulture);
            to = to.AddDays(1);
            string frm_date = frm.ToString("yyyy-MM-dd");
            string to_date = to.ToString("yyyy-MM-dd");
            var respo = db.all_dispute_list(1, 1000000, ddl_status, frm_date, to_date).ToList();
            if (respo.Count > 0)
            {
                foreach (var item in respo)
                {
                    dt2.Rows.Add(item.sts, item.rch_from, item.rch_number, item.rch_amount, item.opt, item.portno, item.portnm, item.rch_time,
            item.dis_time, item.dispute_region, item.opt_id, item.comment);
                }
            }
            else
            {
                dt2.Rows.Add("", "", "", "", "", "", "", "", "", "", "", "");
            }


            var grid = new GridView();
            grid.DataSource = dt2;
            grid.DataBind();
            Response.ClearContent();
            Response.Buffer = true;
            Response.AddHeader("content-disposition", "attachment; filename=Report.xls");
            Response.ContentType = "application/ms-excel";
            Response.Charset = "";
            StringWriter sw = new StringWriter();
            HtmlTextWriter htw = new HtmlTextWriter(sw);
            grid.RenderControl(htw);
            Response.Output.Write(sw.ToString());
            Response.Flush();
            Response.End();
            return View();
        }


        public ActionResult diputerejected(string idno, string txtregion)
        {
            try
            {
                int idn = Convert.ToInt32(idno);

                // Sabhi matching records fetch karo
                var disputes = db.dispute_list.Where(a => a.rch_id == idn.ToString()).ToList();

                if (disputes.Count == 0)
                {
                    TempData["error"] = "No dispute entry found with this ID.";
                    return RedirectToAction("Dispute_list");
                }

                // Pehle record se email nikal lo
                var userid = disputes.FirstOrDefault().rch_from;
                var EmailId = db.Users.Where(a => a.UserId == userid).Select(a => a.Email).FirstOrDefault();

                // Sabhi disputes ko update karo (agar delete chahte ho to `db.dispute_list.RemoveRange(disputes);` use karein)
                foreach (var dispute in disputes)
                {
                    dispute.sts = "Rejected";
                    dispute.comment = txtregion;
                }

                db.SaveChanges();

                // Push notification bhejo
                SendPushNotification(EmailId, Url.Action("Dispute_list", "Home"),
                    "Your Dispute is Clear By Admin and Dispute Message is that " + txtregion + " .", "Dispute Clear..");

                TempData["success"] = "Dispute Rejected Successfully.";
                return RedirectToAction("Dispute_list");
            }
            catch (Exception ex)
            {
                TempData["error"] = ex.Message;
                return RedirectToAction("Dispute_list");
            }
        }

        public ActionResult Complaint(string type, string userid)
        {
            MarkComplaintChatSeen(userid);

            Vastwebmulti.Areas.ADMIN.Models.ChattingModel viewmodel = new Vastwebmulti.Areas.ADMIN.Models.ChattingModel();
            if (type == null)
            {
                viewmodel.Chatuser = db.chat_user().ToList();
                viewmodel.Complainreq = db.proc_Complaint_request("", "All").ToList();
            }
            else
            {
                viewmodel.Chatuser = db.chat_user().ToList();
                viewmodel.Complainreq = db.proc_Complaint_request(userid, "").ToList();
            }

            if (!string.IsNullOrWhiteSpace(userid) && viewmodel.Chatuser != null)
            {
                foreach (var user in viewmodel.Chatuser)
                {
                    if (user.Userid == userid)
                    {
                        user.count = 0;
                    }
                }
            }
            return View(viewmodel);
        }

        private void MarkComplaintChatSeen(string userid)
        {
            if (string.IsNullOrWhiteSpace(userid))
            {
                return;
            }

            var openChats = db.complaint_request.Where(c => c.userid == userid && c.sts == "Open").ToList();
            if (openChats.Count == 0)
            {
                return;
            }

            foreach (var row in openChats)
            {
                row.sts = row.resdate != null ? "Close" : "Read";
            }
            db.SaveChanges();
        }

        [HttpPost]
        public ActionResult Complaint_Reply_Insert(string userid, string message)
        {
            var retailer = db.Users.Where(p => p.UserId == userid).SingleOrDefault();
            var admin = db.Admin_details.FirstOrDefault();

            complaint_request objCourse = new complaint_request();
            objCourse.subject = "Chatting Reply";
            objCourse.complant = message;
            objCourse.complaintid = Guid.NewGuid().ToString().Substring(0, 18).ToUpper();
            objCourse.userid = userid;
            objCourse.sts = "Open";
            objCourse.rdate = System.DateTime.Now;
            db.complaint_request.Add(objCourse);
            db.SaveChanges();

            // 🔹 Retailer ko SMS bhejna
            if (retailer != null)
            {
                smssend.sms_init(
                    "Y",                 // sms_status
                    "Y",                 // whatsapp_status
                    "CHATSUPPORT",       // template type
                    retailer.PhoneNumber,     // Retailer ka mobile
                    admin.email,         // param[0] = Admin Email
                    message              // param[1] = Chat message
                );
            }

            return RedirectToAction("Complaint", new { userid = userid });
        }


        public ActionResult Complaint_edit(string type, string useridd, string id, string response)
        {
            // Update complaint with response
            var complaint = db.complaint_request.Where(c => c.idno.ToString() == id).FirstOrDefault();
            if (complaint != null)
            {
                complaint.response = response;
                complaint.resdate = DateTime.Now;
                complaint.sts = "Close";
                db.SaveChanges();
            }

            MarkComplaintChatSeen(useridd);

            // Retailer details
            var retailer = db.Users.Where(u => u.UserId == useridd).FirstOrDefault();
            var admin = db.Admin_details.FirstOrDefault();

            // 🔹 SMS bhejna Retailer ko
            if (retailer != null && admin != null)
            {
                smssend.sms_init(
                    "Y",                 // sms_status
                    "Y",                 // whatsapp_status
                    "CHATSUPPORT",       // template type
                    retailer.PhoneNumber,     // retailer mobile
                    "Admin",             // param[0] = Admin
                    response             // param[1] = message
                );
            }

            return RedirectToAction("Complaint", new { type = type, userid = useridd });
        }
