        public ActionResult Operator_report_new(string prtname, string type, string ddlusers, string allmaster1, string alldealer, string allretailer, string Whitelabel, string API, string ddl_status, string Operator, string opt12)
        {
            bool? sts = false;

            var actiond = db.billfailedotps.FirstOrDefault();
            if (actiond != null)
                sts = actiond.status;

            ViewBag.checkfailedstatus = sts;

            try
            {
                ViewBag.ReportType = "TODAY";
                ViewBag.type = type ?? "live";

                var portname = "ALL";
                if (prtname != null)
                {
                    var port = db.PortManagers.Where(aa => aa.PortNm == prtname).Select(x => x.PortNo).FirstOrDefault();
                    if (port != null)
                        portname = port;
                }

                var today = DateTime.Now;
                string frm_date = today.Date.ToString("yyyy-MM-dd");
                string to_date = today.AddDays(1).ToString("yyyy-MM-dd");

                var query1 = db.SRS_code_all("").ToList();
                var operator_value = db.port_list().ToList();
                var operator_value1 = db.Opt_codes_new().ToList();

                ViewBag.Lapuno = new SelectList(operator_value, "PortNo", "PortNo", portname);
                ViewBag.Operatornew = new SelectList(operator_value1, "new_opt_code", "operator_Name");

                var viewModel = new Vastwebmulti.Areas.ADMIN.Models.Multiview
                {
                    CountryListModel = new SelectList(query1, "mars", "mars", 0),
                    srspending = db.SRS_pending_count_ALL(),
                    srspending1 = db.SRS_pending_count_ALL()
                };

                var stands = db.Superstokist_details.Select(s => new SelectListItem { Value = s.SSId, Text = s.FarmName + " - " + s.Mobile }).ToList();

                ViewBag.allmaster = new SelectList(stands, "Value", "Text");

                ViewBag.alldealer = new SelectList(db.select_Dealer_for_ddl().ToList(), "Dealerid", "DealerName");
                ViewBag.allretailer = new SelectList(db.select_retailer_for_ddl("Admin").ToList(), "RetailerId", "Frm_Name");
                ViewBag.API = new SelectList(db.API_all_apiid().ToList(), "apiid", "farmname");
                ViewBag.whitelabel = new SelectList(db.Whitelabel_all_whitelabelid().ToList(), "WhiteLabelID", "FrmName");

                return View(viewModel);
            }
            catch (Exception)
            {
                return View();
            }
        }


