        public ActionResult Excel_Rch_Failed_success_Reports(DateTime txt_frm_date, DateTime txt_to_date)
        {
            var result = db.Proc_Recharge_info_Failed_TO_Success_Reports(txt_frm_date, txt_to_date.AddDays(1), "").ToList();
            DataTable datatabl1 = new DataTable();
            datatabl1.Columns.Add("User Information", typeof(string));
            datatabl1.Columns.Add("Recharge Request Time", typeof(string));
            datatabl1.Columns.Add("Operator Name", typeof(string));
            datatabl1.Columns.Add("Consumer No", typeof(string));
            datatabl1.Columns.Add("Port / API", typeof(string));
            datatabl1.Columns.Add("Request Time", typeof(string));
            datatabl1.Columns.Add("Operator ID", typeof(string));
            datatabl1.Columns.Add("Response Time", typeof(string));
            datatabl1.Columns.Add("Modify Time", typeof(string));
            datatabl1.Columns.Add("Modify Status", typeof(string));

            if (result.Count > 0)
            {
                foreach (var item in result)
                {
                    datatabl1.Rows.Add(item.usertype + " " + item.frmname, item.Rch_time, item.operator_Name, item.Mobile,
                        item.portno, item.Rch_time, item.OPt_id, item.Resp_time, item.Modify_time, item.modifystaus + " " + item.rchidno);
                }
            }
            else
            {
                datatabl1.Rows.Add("", "", "", "", "", "", "", "", "", "");
            }

            var grid = new GridView();
            grid.DataSource = datatabl1;
            grid.DataBind();
            Response.ClearContent();
            Response.Buffer = true;
            Response.AddHeader("content-disposition", "attachment; filename=Rch_Failed_Success_Report.xls");
            Response.ContentType = "application/ms-excel";
            Response.Charset = "";
            StringWriter sw = new StringWriter();
            HtmlTextWriter htw = new HtmlTextWriter(sw);
            grid.RenderControl(htw);
            Response.Output.Write(sw.ToString());
            Response.Flush();
            Response.End();
            return View();
        }

