        public void faildotp1()
        {
            var dbs = db.billfailedotps.Where(s => s.status == true).ToList();
            if (dbs.Count == 1)
            {
                string userid = User.Identity.GetUserId();
                Random ran = new Random();
                var otprem1 = ran.Next(1111, 9999);
                var AdminDetails = db.Admin_details.SingleOrDefault();
                TempData["OTPValue"] = otprem1;
                TempData["otpnot"] = "OTP NOT MATCHED";
                try
                {
                    var smsapi = db.apisms.Where(x => x.sts == "Y").ToList();
                    var adminmobile = db.Admin_details.SingleOrDefault().mobile;
                    var smsapionsts = smsapi.Where(s => s.api_type == "whatsapp").SingleOrDefault();
                    if (smsapionsts != null)
                    {
                        var apiurls = smsapionsts.smsapi;
                        string text = "Failed recharge otp is " + otprem1;
                        text = string.Format(text, "1230");

                        var apinamechange = apiurls.Replace("tttt", adminmobile).Replace("mmmm", text);

                        var client = new RestClient(apinamechange);
                        var request = new RestRequest(Method.GET);

                        VastBazaartoken Responsetoken = new VastBazaartoken();
                        var whatsts = db.Email_show_passcode.SingleOrDefault();
                        if (apinamechange.ToUpper().Contains("API.VASTBAZAAR.COM/API/WEB/WHATSAPPMSG") && whatsts.whatsappapists == true)
                        {
                            var token = Responsetoken.gettoken();
                            request.AddHeader("authorization", "bearer " + token);
                            request.AddHeader("content-type", "application/json");
                        }
                        var task = Task.Run(() =>
                        {
                            return client.Execute(request).Content;
                        });
                        bool isCompletedSuccessfully = task.Wait(TimeSpan.FromSeconds(10000));
                        var resp = "";
                        if (isCompletedSuccessfully == true)
                        {
                            resp = task.Result;
                        }

                        sms_api_entry sms = new sms_api_entry();
                        sms.apiname = apinamechange;
                        sms.msg = text;
                        sms.m_date = System.DateTime.Now;
                        sms.response = resp;
                        sms.messagefor = userid;
                        db.sms_api_entry.Add(sms);
                        db.SaveChanges();
                    }
                }
                catch { }

                try
                {

                    smssend.SendEmailAll(AdminDetails.email, "Failed recharge otp is " + otprem1, "Failed recharge otp", AdminDetails.email);
                }
                catch { }
                var ds = db.billfailedotps.Where(s => s.id != null).ToList();

                if (ds.Count == 1)
                {
                    var dws = db.billfailedotps.Where(s => s.id != null).SingleOrDefault();
                    dws.otp = Convert.ToString(otprem1);
                    dws.status = true;
                    db.SaveChanges();
                }
                else
                {
                    billfailedotp d1 = new billfailedotp();
                    d1.status = true;
                    d1.otp = Convert.ToString(otprem1);
                    db.billfailedotps.Add(d1);
                    db.SaveChanges();
                }
            }
        }
