        //Manual success money transfer
        public ActionResult Moneysucess(string trans_id, string bank_trans_id, string recivername, string currentstatus, string ddl_refund, string securitypass)
        {
            try
            {
                // ================= SECURITY PIN CHECK =================
                var chktranss = db.admin_new_pass.SingleOrDefault();
                DateTime currenttime = DateTime.Now;

                DateTime lastchangedpassdtr = Convert.ToDateTime(chktranss.lastupdatesec);
                lastchangedpassdtr = lastchangedpassdtr.AddDays(Convert.ToInt32(chktranss.secexpdays));

                var defaultht = Decrypt(chktranss.securitypass);

                if (defaultht == "1111" || lastchangedpassdtr <= currenttime)
                {
                    return Json(new
                    {
                        Status = false,
                        Message = "Your security pin is expired or have to be changed!! Please set new security pin"
                    });
                }

                var password = Encrypt(securitypass);
                var tranpass = db.admin_new_pass.Count(x => x.securitypass == password);

                if (tranpass <= 0)
                {
                    return Json(new { Status = false, Message = "Your Security Password is Wrong!" });
                }
                // ======================================================

                var RetailerEmail = "";
                var AdminEmail = db.Admin_details.Single().email;
                var comm = db.IMPS_transtion_detsils.Where(p => p.trans_id == trans_id).SingleOrDefault();

                if (comm != null)
                {
                    var retailerid = comm.rch_from;
                    var bankname = comm.bank_nm;
                    var transamount = comm.amount;
                    var bank_account = comm.accountno;
                    var RetailerMobile = "";

                    var userroleid = db.UserRoles.Single(x => x.UserId == retailerid).RoleId;
                    var userrole = db.Roles.Single(x => x.RoleId == userroleid).Name;

                    if (userrole == "Retailer")
                    {
                        var r = db.Retailer_Details.Single(x => x.RetailerId == retailerid);
                        RetailerEmail = r.Email;
                        RetailerMobile = r.Mobile;
                    }
                    else if (userrole == "Whitelabelretailer")
                    {
                        var r = db.Whitelabel_Retailer_Details.Single(x => x.RetailerId == retailerid);
                        RetailerEmail = r.Email;
                        RetailerMobile = r.Mobile;
                    }
                    else if (userrole == "API")
                    {
                        var r = db.api_user_details.Single(x => x.apiid == retailerid);
                        RetailerEmail = r.emailid;
                        RetailerMobile = r.mobile;
                    }

                    var statusAdmin = db.PushNotificationStatus.Single(x => x.UserRole == "Admin").Status;
                    var statusRetailer = db.PushNotificationStatus.Single(x => x.UserRole == "Retailer").Status;

                    var smsSetting = db.SMSSendAlls.Single(x => x.ServiceName == "dmtfailtosucconline");
                    var emailStatus = db.EmailSendAlls
                                        .Single(x => x.ServiceName == "dmtfailtosucconline1")
                                        .Status;

                    // ================= STATUS LOGIC =================
                    if (currentstatus.ToUpper() == "FAILED")
                    {
                        db.Money_transfer_failed_to_success(trans_id);
                    }
                    else
                    {
                        db.Money_transfer_update_new_new(
                            trans_id,
                            "SUCCESS",
                            bank_trans_id,
                            recivername,
                            ddl_refund,
                            "",
                            0,
                            0
                        );
                    }
                    // =================================================

                    // ================= NOTIFICATIONS =================
                    if (statusAdmin == "Y")
                    {
                        SendPushNotification(
                            AdminEmail,
                            Url.Action("Money_transfer_Report", "Home"),
                            $"Money Transfer in Bank {bankname} Account {bank_account} RefId {bank_trans_id} Amount {transamount}   SUCCESS {ddl_refund}.",
                            "Money Transfer Success"
                        );
                    }

                    if (statusRetailer == "Y")
                    {
                        SendPushNotification(
                            RetailerEmail,
                            Url.Action("Money_Transfer_Report", "Home"),
                            $"Money Transfer in Bank {bankname} Account {bank_account} RefId {bank_trans_id} Amount {transamount}  SUCCESS {ddl_refund}.",
                            "Money Transfer Success"
                        );
                    }

                    if (userrole == "Retailer")
                    {
                        smssend.sms_init(
                            smsSetting.Status,
                            smsSetting.Whatsapp_Status,
                            "MONEYTRANSFERMANUALMONEYSUCCESS",
                            RetailerMobile,
                            bankname,
                            bank_account,
                            bank_trans_id,
                            transamount,
                            ddl_refund
                        );

                        if (emailStatus == "Y")
                        {
                            smssend.SendEmailAll(
                                RetailerEmail,
                                $"Money Transfer SUCCESS | Bank:{bankname} Acc:{bank_account} Ref:{bank_trans_id} Amount:{transamount} Reason:{ddl_refund} ",
                                "Money Transfer",
                                AdminEmail
                            );
                        }

                        notify.sendmessage(
                            RetailerEmail,
                            $"Money Transfer SUCCESS | Bank:{bankname} Acc:{bank_account} Ref:{bank_trans_id} Amount:{transamount} Reason:{ddl_refund} "
                        );
                    }
                    else if (userrole == "API")
                    {
                        var api_call_back = db.Recharge_Update_Url.SingleOrDefault(x => x.UserId == retailerid);
                        if (api_call_back != null)
                        {
                            var apiremain = db.api_remain_amount
                                              .Single(x => x.apiid == retailerid)
                                              .balance
                                              .ToString();

                            var urls = api_call_back.responseurl
                                .Replace("rrr", trans_id)
                                .Replace("sss", "Success")
                                .Replace("ooo", bank_trans_id)
                                .Replace("bbb", apiremain);

                            try
                            {
                                var client = new RestClient(urls);
                                ServicePointManager.SecurityProtocol = SecurityProtocolType.Tls12;
                                client.Execute(new RestRequest(Method.GET));
                            }
                            catch { }
                        }
                    }

                    return Json(new { Status = true, Message = "Successfully" });
                }

                return Json(new { Status = false, Message = "Transaction not found" });
            }
            catch (Exception ex)
            {
                return Json(new { Status = false, Message = ex.Message });
            }
        }


