        public IRestResponse tokencheck()
        {
            var apidetails = db.Money_API_URLS.Where(aa => aa.API_Name == "VASTWEB").SingleOrDefault();
            var token = apidetails == null ? "" : apidetails.Token;
            var apiid = apidetails == null ? "" : apidetails.API_ID;
            var apiidpwd = apidetails == null ? "" : apidetails.Api_pwd;
            var client = new RestClient("http://api.vastbazaar.com/token");
            var request = new RestRequest(Method.POST);
            request.AddHeader("iptoken", token);
            request.AddHeader("content-type", "application/x-www-form-urlencoded");
            request.AddParameter("application/x-www-form-urlencoded", "UserName=" + apiid + "&Password=" + apiidpwd + "&grant_type=password", ParameterType.RequestBody);
            IRestResponse response = client.Execute(request);
            return response;
        }

        private static Random random = new Random();
        public string RandomString(int length)
        {
            const string chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";
            return new string(Enumerable.Repeat(chars, length)
              .Select(s => s[random.Next(s.Length)]).ToArray());
        }

        public ActionResult ResendMasterEmail(string email)
        {
            var adminemail = db.Admin_details.SingleOrDefault().email;
            var data = db.ResendConfirmMails.Where(aa => aa.Email == email).SingleOrDefault();
            if (data != null)
            {
                var callbackurl = data.CallBackUrl;
                var pass = data.Password;
                string body = new CommonUtil().PopulateBodyDealer("", "Confirm your account", "", "" + callbackurl + "", email, pass);
                new CommonUtil().Insertsendmail(email, "Confirm your account", body, callbackurl);
                new CommonUtil().Rsendmailadmin(adminemail, "Confirm your account", body, callbackurl);
                TempData["ResendMAil"] = "Confirmation Mail Is Successfully Resend .";
            }
            else
            {
                TempData["ResendMAil"] = "Confirmation Mail Not Resend .";
                return RedirectToAction("Master_list");
            }
            return RedirectToAction("Master_list");
        }
