                if (chk != null)
                {
                    db.delete_Master(ssiddelete);

                    //for logout from all devices web
                    UserManager.UpdateSecurityStamp(ssiddelete);

                    ViewBag.state = new SelectList(db.Select_State_Details(), "State_Id", "State_Name").ToList();
