        public async Task<ActionResult> BulkMasterCreate()
        {
            List<string> errorlistitem = new List<string>();
            StringBuilder addtbl = new StringBuilder();
            addtbl.Append("<table>");
            addtbl.Append("<tr>");
            addtbl.Append("<th>Email ID/Phone No</th><th>Action</th>");
            addtbl.Append("<tr>");
            if (Request.Files["FileUpload1"].ContentLength > 0)
            {
                string extension = System.IO.Path.GetExtension(Request.Files["FileUpload1"].FileName).ToLower();
                string query = null;
                string connString = "";
                string[] validFileTypes = { ".xls", ".xlsx", ".csv" };

                string path1 = string.Format("{0}/{1}", Server.MapPath("~/Content/Uploads"), Request.Files["FileUpload1"].FileName);
                if (!Directory.Exists(path1))
                {
                    Directory.CreateDirectory(Server.MapPath("~/Content/Uploads"));
                }
                if (validFileTypes.Contains(extension))
                {
                    if (System.IO.File.Exists(path1))
                    {
                        System.IO.File.Delete(path1);
                    }
                    Request.Files["FileUpload1"].SaveAs(path1);

                    errorlistitem = null;
                    if (extension == ".csv")
                    {
                        DataTable dt = Utility.ConvertCSVtoDataTable(path1);
                        var appDbContext = HttpContext.GetOwinContext().Get<ApplicationDbContext>();
                        for (int i = 0; i <= dt.Rows.Count - 1; i++)
                        {
                            var name = dt.Rows[i][0].ToString();
                            var firmname = dt.Rows[i][1].ToString();
