        public JsonResult Deletedealer(string DealerId, int OTP)
        {
            try
            {
                var retailerdetails = db.Dealer_Details.Where(a => a.DealerId == DealerId).SingleOrDefault();
                DeleteUserHistory user = new DeleteUserHistory();
                LedgerReport ledger = new LedgerReport();
                var chk = db.deleteuserotps.Any(a => a.otp == OTP);
                if (chk == true)
                {
                    if (DealerId != null && DealerId != "")
                    {
                        var dealer1 = db.Retailer_Details.Where(pp => pp.DealerId == DealerId && pp.ISDeleteuser == false).ToList();
                        if (dealer1.Count > 0)
                        {
                            return Json("FailedDealer", JsonRequestBehavior.AllowGet);
                        }
                        else
                        {

                            var DealerRemain = db.Remain_dealer_balance.Where(pp => pp.DealerID == DealerId).Single().Remainamount;
                            var adminremain = db.Remain_Admin_balance.Single().RemainAmount;
                            decimal Totalvalue = Convert.ToDecimal(adminremain) + Convert.ToDecimal(DealerRemain);
                            var admin = db.Remain_Admin_balance.Single();
                            admin.RemainAmount = Totalvalue;
                            db.SaveChanges();
                            db.delete_Dealer(DealerId);
                            db.deleteOTP();

                            user.ContectNo = retailerdetails.Mobile;
                            user.DeleteDate = DateTime.Now;
                            user.Email = retailerdetails.Email;
                            user.FarmName = retailerdetails.FarmName;
                            user.JoiningDate = retailerdetails.JoinDate;
                            user.Name = retailerdetails.DealerName;
                            user.RecoveryAmount = DealerRemain;
                            user.Role = "Dealer";
                            db.DeleteUserHistories.Add(user);
                            db.SaveChanges();

                            ledger.UserId = retailerdetails.DealerId;
                            ledger.Role = "Dealer";
                            ledger.Particulars = "Dealer Id Delete By Admin";
                            ledger.UserRemainAmount = DealerRemain;
                            ledger.Date = Convert.ToDateTime(DateTime.Now.ToString());
                            ledger.Amount = DealerRemain;
                            ledger.Credit = 0;
                            ledger.Debit = DealerRemain;
                            db.LedgerReports.Add(ledger);
                            db.SaveChanges();

                            ledger.UserId = "Admin";
                            ledger.Role = "Admin";
                            ledger.Particulars = "Dealer Id Delete By Admin";
                            ledger.UserRemainAmount = Totalvalue;
                            ledger.Date = Convert.ToDateTime(DateTime.Now.ToString());
                            ledger.Amount = DealerRemain;
                            ledger.Credit = DealerRemain;
                            ledger.Debit = 0;
                            db.LedgerReports.Add(ledger);
                            db.SaveChanges();

                            return Json("Success", JsonRequestBehavior.AllowGet);
                        }
                    }
                    else
                    {
                        return Json("Failed", JsonRequestBehavior.AllowGet);
                    }
                }
                else
                {
                    return Json("OTPWrong", JsonRequestBehavior.AllowGet);
                }
            }
            catch
            {
                return Json("Failed", JsonRequestBehavior.AllowGet);
            }

        }
