        public JsonResult Delete_API(string APIId, int OTP)
        {
            try
            {
                var retailerdetails = db.api_user_details.Where(a => a.apiid == APIId).SingleOrDefault();
                DeleteUserHistory user = new DeleteUserHistory();
                LedgerReport ledger = new LedgerReport();
                var chk = db.deleteuserotps.Any(a => a.otp == OTP);
                if (chk == true)
                {
                    if (APIId != null && APIId != "")
                    {
                        decimal apiRemain = (decimal)db.api_remain_amount.Where(pp => pp.apiid == APIId).Single().balance;
                        decimal adminremain = (decimal)db.Remain_Admin_balance.Single().RemainAmount;
                        decimal Totalvalue = adminremain + apiRemain;
                        var admin = db.Remain_Admin_balance.Single();
                        admin.RemainAmount = Totalvalue;
                        db.SaveChanges();
                        db.delete_Api(APIId);
                        db.deleteOTP();

                        user.ContectNo = retailerdetails.mobile;
                        user.DeleteDate = DateTime.Now;
                        user.Email = retailerdetails.emailid;
                        user.FarmName = retailerdetails.farmname;
                        user.JoiningDate = retailerdetails.joindate;
                        user.Name = retailerdetails.username;
                        user.RecoveryAmount = apiRemain;
                        user.Role = "API";
                        db.DeleteUserHistories.Add(user);
                        db.SaveChanges();

                        ledger.UserId = retailerdetails.apiid;
                        ledger.Role = "API";
                        ledger.Particulars = "API Id Delete By Admin";
                        ledger.UserRemainAmount = apiRemain;
                        ledger.Date = Convert.ToDateTime(DateTime.Now.ToString());
                        ledger.Amount = apiRemain;
                        ledger.Credit = 0;
                        ledger.Debit = apiRemain;
                        db.LedgerReports.Add(ledger);
                        db.SaveChanges();

                        ledger.UserId = "Admin";
                        ledger.Role = "Admin";
                        ledger.Particulars = "API Id Delete By Admin";
                        ledger.UserRemainAmount = Totalvalue;
                        ledger.Date = Convert.ToDateTime(DateTime.Now.ToString());
                        ledger.Amount = apiRemain;
                        ledger.Credit = apiRemain;
                        ledger.Debit = 0;
                        db.LedgerReports.Add(ledger);
                        db.SaveChanges();

                        return Json("Success", JsonRequestBehavior.AllowGet);
                    }
                    else
                    {
                        return Json("Failed", JsonRequestBehavior.AllowGet);
                    }
                }
                else
                {
                    return Json("OTPWrong", JsonRequestBehavior.AllowGet);
                }
            }
            catch
            {
                return Json("Failed", JsonRequestBehavior.AllowGet);
            }
        }
        //end

