        [HttpPost]
        public async Task<ActionResult> Insert_vendor(Vandorlist vendor)
        {
            string msg = "";
            var appDbContext = HttpContext.GetOwinContext().Get<ApplicationDbContext>();
            using (var transaction = appDbContext.Database.BeginTransaction())
            {
                try
                {
                    if (vendor.State > 0 && vendor.District > 0)
                    {
                        var chkmobile = db.Users.Where(a => a.PhoneNumber == vendor.Mb).Any();
                        if (chkmobile == true)
                        {
                            msg = "This Mobile Number Already Exists.";
                            return Json(new { msg = msg, type = "Error" }, JsonRequestBehavior.AllowGet);
                            // TempData["mobileno"] = "This Mobile Number Already Exists.";
                            // return RedirectToAction("VendorList");
                        }

                        var check = db.Vendor_details.Where(es => es.mobile == vendor.Mb).Any();
                        if (check == false)
                        {
                            ViewBag.state = new SelectList(db.Select_State_Details(), "State_Id", "State_Name").ToList();
                            var user = new ApplicationUser { UserName = vendor.Email, Email = vendor.Email, PhoneNumber = vendor.Mb };
                            //Generate Random Password

                            bool includeLowercase = false;
                            bool includeUppercase = false;
                            bool includeNumeric = true;
                            bool includeSpecial = false;
                            bool includeSpaces = false;
                            int lengthOfPassword = 8;

                            string pass = PasswordGenerator.GeneratePassword(includeLowercase, includeUppercase, includeNumeric, includeSpecial, includeSpaces, lengthOfPassword);

                            while (!PasswordGenerator.PasswordIsValid(includeLowercase, includeUppercase, includeNumeric, includeSpecial, includeSpaces, pass))
                            {
                                pass = PasswordGenerator.GeneratePassword(includeLowercase, includeUppercase, includeNumeric, includeSpecial, includeSpaces, lengthOfPassword);
                            }
                            var Password = pass;

                            var result = await UserManager.CreateAsync(user, Password);
                            if (result.Succeeded)
                            {
                                System.Data.Entity.Core.Objects.ObjectParameter output = new
                                System.Data.Entity.Core.Objects.ObjectParameter("Output", typeof(string));
                                var res = db.Insert_Vendor(user.Id, vendor.Name, vendor.FarmName, vendor.State, vendor.District, vendor.Address, vendor.Pincode, vendor.Email, vendor.Mb, vendor.aadharnumber, vendor.pancard, vendor.gstnumber, "ADMIN", output).SingleOrDefault().msg;



                                var AdminMailId = db.Admin_details.Single().email;
                                var statusAdmin = db.PushNotificationStatus.Where(a => a.UserRole == "Admin").SingleOrDefault().Status;
                                var statusSendSmsVendor = db.SMSSendAlls.Where(a => a.ServiceName == "VendorCreate").SingleOrDefault();
                                var statusSendEmailVendor = db.EmailSendAlls.Where(a => a.ServiceName == "VendorCreate1").SingleOrDefault().Status;
                                if (res.ToString() == "Register SuccessFully.")
                                {
                                    string passsss = HttpUtility.UrlEncode(Password);
                                    transaction.Commit();

                                    // Send an email with this link
                                    string code = await UserManager.GenerateEmailConfirmationTokenAsync(user.Id);
                                    var callbackUrl = Url.Action("ConfirmEmailAdmin", "Account", new { userId = user.Id, code = code }, protocol: Request.Url.Scheme);
                                    callbackUrl = callbackUrl.Replace("/ADMIN", "");
                                    string body = new CommonUtil().PopulateBodyDealer("", "Confirm your account", "", "" + callbackUrl + "", vendor.Email, Password);
                                    string Welcomebody = new CommonUtil().PopulateBodyWelcome("", "Confirm your account", "", "" + callbackUrl + "", vendor.Email, Password);
                                    new CommonUtil().Insertsendmail(vendor.Email, "Confirm your account", body, callbackUrl);
                                    new CommonUtil().InsertsendmailWelcome(vendor.Email, "Confirm your account", Welcomebody, callbackUrl);
                                    var adminemail = db.Admin_details.SingleOrDefault().email;
                                    new CommonUtil().Rsendmailadmin(adminemail, "Confirm your account", body, callbackUrl);

                                    ResendConfirmMail resend = new ResendConfirmMail();
                                    resend.CallBackUrl = callbackUrl;
                                    resend.Email = vendor.Email;
                                    resend.Password = Password;
                                    resend.Pin = "";
                                    db.ResendConfirmMails.Add(resend);
                                    db.SaveChanges();

                                    //if (statusSendSmsVendor == "Y")
                                    //{
                                    //    string msgssss = "";
                                    //    string tempid = "";
                                    //    string urlss = "";

                                    //    var smsapionsts = db.apisms.Where(x => x.sts == "Y").SingleOrDefault();
                                    //    var smsstypes = db.Sending_SMS_Templates.Where(x => x.SMS_TYPE == "ADMIN_CREATE_NEW_USERS" && x.SMSAPIID == smsapionsts.id).SingleOrDefault();
                                    //    if (smsstypes != null)
                                    //    {
                                    //        msgssss = string.Format(smsstypes.Templates, vendor.Mb, passsss);
                                    //        tempid = smsstypes.Templateid;
                                    //        urlss = smsapionsts.smsapi;

                                    //        smssend.sendsmsallnew(vendor.Mb, msgssss, urlss, tempid);
                                    //    }



                                    //    // smssend.sendsmsall(vendor.Mb, "Dear Partner ! Welcome Your user Id " + vendor.Mb + " and Password " + passsss + ". Thanks For Your Business . ", "User Create");
                                    //}

                                    smssend.sms_init(statusSendSmsVendor.Status, statusSendSmsVendor.Whatsapp_Status, "ADMIN_CREATE_NEW_USERS", vendor.Mb, vendor.Mb + " ", passsss);

                                    if (statusSendEmailVendor == "Y")
                                    {
                                        smssend.SendEmailAll(vendor.Email, "Dear Partner ! Welcome Your user Id " + vendor.Mb + " and Password " + passsss + ". Thanks For Your Business . ", "User Create", AdminMailId);
                                    }
                                    if (statusAdmin == "Y")
                                    {
                                        SendPushNotification(AdminMailId, Url.Action("VendorList", "Home"), "The New Vendor Id " + vendor.Email + " is Created Successfully.", "Vendor ID Create.");
                                    }
                                    msg = res;
                                    return Json(new { msg = msg, type = "Success" }, JsonRequestBehavior.AllowGet);
                                    //  TempData["msgrem"] = res;
                                    //return RedirectToAction("VendorList");
                                }

                            }
                            else
                            {
                                transaction.Rollback();
                                msg = "User Not Created. Please Create After Some Time.";
                                return Json(new { msg = msg, type = "Error" }, JsonRequestBehavior.AllowGet);
                                //TempData["msgrem"] = "User Not Created. Please Create After Some Time.";
                                // return RedirectToAction("VendorList");
                            }
                        }
                        else
                        {
                            msg = "This Mobile Number Already Exists.";
                            return Json(new { msg = msg, type = "Error" }, JsonRequestBehavior.AllowGet);
                            // TempData["mobileno"] = "This Mobile Number Already Exists.";
                            // return RedirectToAction("VendorList");
                        }

                    }
                    else
                    {
                        msg = "Please select District";
                        return Json(new { msg = msg, type = "Error" }, JsonRequestBehavior.AllowGet);
                        //  TempData["Error"] = "Please select District";
                        //  return RedirectToAction("VendorList");
                    }
                }

                catch (Exception ex)
                {
                    transaction.UnderlyingTransaction.Connection.Open();
                    transaction.Rollback();
                    msg = "User Not Created. Please Create After Some Time.";
                    return Json(new { msg = msg, type = "Error" }, JsonRequestBehavior.AllowGet);
                    //  TempData["Error"] = "User Not Created. Please Create After Some Time.";
                    // return View("VendorList");
                }
            }
            msg = "User Not Created. Please Create After Some Time.";
            return Json(new { msg = msg, type = "Error" }, JsonRequestBehavior.AllowGet);
        }

