        [HttpPost]
        public ActionResult EditVendor_list(Vandorlist vendor)
        {
            try
            {
                var ccc = db.Vendor_details.Where(p => p.userid == vendor.userid).SingleOrDefault();
                var mobileno = ccc.mobile;
                var emailid = ccc.emailid;
                var userid = ccc.userid;
                if (vendor.State1 != 0 && vendor.District1 != 0)
                {
                    if (mobileno != vendor.Mb1)
                    {
                        var usermobileno = db.Users.Where(a => a.PhoneNumber == vendor.Mb1).Any();
                        if (usermobileno == true)
                        {
                            TempData["Error"] = "This Mobile Number Alerady Use To Another User.Please Enter Another Mobile No.";
                            return RedirectToAction("Master_list");
                        }
                        else
                        {
                            int pin = new Random().Next(1000, 10000);
                            MobileOtp motp = new MobileOtp();
                            motp.Date = DateTime.Now;
                            motp.Userid = userid;
                            motp.Type = "Vendor";
                            motp.mobileno = vendor.Mb1;
                            motp.Otp = pin.ToString();
                            db.MobileOtps.Add(motp);
                            db.SaveChanges();

                            try
                            {
                                var ToCC = db.Admin_details.FirstOrDefault().email;
                                CommUtilEmail emailsend = new CommUtilEmail();
                                emailsend.EmailLimitChk(emailid, ToCC, "Mobile Number Change OTP", "Your OTP Is  " + pin, "No CallBackUrl");
                            }
                            catch { }
                            TempData["email"] = "Otp Send in User Mail-Id Successfully.Please Check Mail Id and Enter OTP.";
                            return RedirectToAction("InsertOTP");
                        }
                    }
                    else
                    {
                        Vendor_details obj = (from p in db.Vendor_details
                                              where p.userid == vendor.userid
                                              select p).SingleOrDefault();
                        obj.Name = vendor.Name1;
                        obj.Firmname = vendor.FarmName1;
                        obj.state = vendor.State1;
                        obj.district = vendor.District1;
                        obj.address = vendor.Address1;
                        obj.pin = vendor.Pincode1.ToString();
                        obj.gstnumber = vendor.gstnumber1.ToString();
                        obj.aadharnumber = vendor.aadharnumber1.ToString();
                        obj.pancardnumber = vendor.pancard1.ToString();
                        db.SaveChanges();
                        TempData["edit"] = "Update Successfully.";
                        return RedirectToAction("VendorList");
                    }
                }
                else
                {
                    TempData["Error"] = "Please select District";
                    return RedirectToAction("VendorList");
                }
            }
            catch
            {
                return RedirectToAction("VendorList");
            }
        }

