        //Edit Distributor 
        [HttpPost]
        public ActionResult Editdealer(string txtdealerid, string txtdealername, string txtfrmname, string State1, string District1, string txtAddress, string txtmobileedit, string slabedit, string txtcommedit, int txtpincode, string txtemail, string txtpancard1, string txtadharcard1, string txtgst1, string txtcapping1)
        {
            try
            {


                var ccc = db.Dealer_Details.Where(p => p.Email == txtemail).SingleOrDefault();
                var mobileno = ccc.Mobile;
                var emailid = ccc.Email;
                var userid = ccc.DealerId;
                if (mobileno != txtmobileedit)
                {
                    var usermobileno = db.Users.Where(a => a.PhoneNumber == txtmobileedit).Any();
                    if (usermobileno == true)
                    {
                        TempData["alerdymobile"] = "This Mobile Number Alerady Use To Another User.Please Enter Another Mobile No.";
                        return RedirectToAction("DistibutorList");
                    }
                    else
                    {
                        int pin = new Random().Next(1000, 10000);
                        MobileOtp motp = new MobileOtp();
                        motp.Date = DateTime.Now;
                        motp.Userid = userid;
                        motp.Type = "Dealer";
                        motp.mobileno = txtmobileedit;
                        motp.Otp = pin.ToString();
                        db.MobileOtps.Add(motp);
                        db.SaveChanges();

                        try
                        {
                            var ToCC = db.Admin_details.FirstOrDefault().email;
                            CommUtilEmail emailsend = new CommUtilEmail();
                            emailsend.EmailLimitChk(emailid, ToCC, "Mobile Number Change OTP", "Your OTP Is  " + pin, "No CallBackUrl");
                        }
                        catch { }
                        TempData["email"] = "Otp Send in User Mail-Id Successfully.Please Check Mail Id and Enter OTP.";
                        return RedirectToAction("InsertOTP");
                    }
                }
                else
                {
                    if (District1 != "Select District" && District1 != null && District1 != "0")
                    {
                        db.Update_Dealer(txtdealerid, txtdealername, txtfrmname, State1, District1, txtAddress, txtmobileedit, slabedit, txtpincode, txtemail, txtpancard1, txtadharcard1, txtgst1);
                        TempData["edit"] = "Update Successfully..";
                        return RedirectToAction("DistibutorList");
                    }
                    else
                    {
                        return RedirectToAction("DistibutorList");
                    }
                }
            }

            catch
            {
                return RedirectToAction("DistibutorList");
            }
        }


