        // Insert OTP Distributor
        public ActionResult Insert_OTP(string USER)
        {
            var id = TempData["ID"];
            if (id != null)
            {
                ViewData["ID"] = id.ToString();
                ViewData["Role"] = TempData["Role"];
                return View();
            }
            else
            {
                if (USER == "API")
                {
                    return RedirectToAction("Api_user");
                }
                else if (USER == "RETAILER")
                {
                    return RedirectToAction("Retailerlist");
                }
                else if (USER == "DEALER")
                {
                    return RedirectToAction("DistibutorList");
                }
                else
                {
                    return RedirectToAction("Rch_details");
                }

            }
        }

        //Delete Confrimed  for users
        [HttpPost]
        public ActionResult Delete_Confirm(string txtcode, string id, string Role)
        {
            string msg = string.Empty;
            var otp = db.Delete_OTP_ALLUsers.Where(aa => aa.userid == id).OrderByDescending(aa => aa.idno).FirstOrDefault().otp;
            //Delete_OTP_ALLUsers objCourse = (from p in db.Delete_OTP_ALLUsers
            //                                 where p.userid == id
            //                                  select p).SingleOrDefault();
            //db.Delete_OTP_ALLUsers.Remove(objCourse);
            //db.SaveChanges();
            var deleteOrderDetails = from details in db.Delete_OTP_ALLUsers where details.userid == id select details;

            foreach (var detail in deleteOrderDetails)
            {
                db.Delete_OTP_ALLUsers.Remove(detail);
            }

            if (otp == txtcode)
            {
                System.Data.Entity.Core.Objects.ObjectParameter output = new
                  System.Data.Entity.Core.Objects.ObjectParameter("Response", typeof(string));
                var i = db.delete_Api(id);
                if (i > 0)
                {
                    msg = "success";
                }
                TempData["wrong"] = msg;
            }
            else
            {
                TempData["wrong"] = "OTP Not Match! Please try again.";
            }
            if (Role == "API")
            {
                return RedirectToAction("Api_user");
            }
            else if (Role == "RCH")
            {
                return RedirectToAction("Rch_details");
            }
            else
            {
                return RedirectToAction("DistibutorList");
            }
        }

