        [HttpPost]
        public ActionResult Manual_FormName(string Name, HttpPostedFileBase ManualformFile)
        {
            TempData["cueerntdtabeopen"] = "opencurrent";
            var image = db.Formservices.Where(a => a.servicename == Name).FirstOrDefault();
            if (image == null)
            {
                if (ManualformFile != null && !string.IsNullOrEmpty(Name))
                {
                    try
                    {
                        WebImage photo = new WebImage(ManualformFile.InputStream);
                        if (photo != null)
                        {
                            photo.Resize(50, 50, false, true);
                            if (photo.Height <= 50)
                            {
                                if (photo.ImageFormat == "png" || photo.ImageFormat == "PNG")
                                {
                                    string _FileNames = Path.GetFileName(ManualformFile.FileName);
                                    var _path = Path.Combine(Server.MapPath("~/TempraryImages"), _FileNames);
                                    photo.Save(_path);
                                    byte[] imageArray = System.IO.File.ReadAllBytes(_path);

                                    FileInfo file = new FileInfo(_path);
                                    if (file.Exists)
                                    {
                                        file.Delete();
                                    }

                                    var base64ImageRepresentation = Convert.ToBase64String(imageArray);
                                    Formservice model = new Formservice();
                                    model.servicename = Name;
                                    model.images = base64ImageRepresentation;
                                    db.Formservices.Add(model);
                                    db.SaveChanges();
                                }
                                else
                                {
                                    TempData["Errormsgtype"] = "PNGIMG";
                                    return RedirectToAction("More_Option");
                                }

                            }
                            else
                            {
                                TempData["Errormsgtype"] = "IMGSIZE";
                                return RedirectToAction("More_Option");
                            }

                        }
                    }
                    catch (Exception ex)
                    { }
                }


            }
            else
            {
                image.servicename = Name;

                db.SaveChanges();
            }
            return RedirectToAction("More_Option");
        }

