                                item.Demouser = false;
                            }
                            db.SaveChanges();
                        }

                        chkretailer.Demouser = true;
                        db.SaveChanges();

                        var servid = db.passcodesettings.Where(x => x.userid == chkretailer.RetailerId).SingleOrDefault();
