                            catch { }
                        }

                        var chkdemo = db.Demo_User_Chk.SingleOrDefault();
                        if (chkdemo == null)
                        {
                            Demo_User_Chk dm = new Demo_User_Chk();
                            dm.userid = chkretailer.RetailerId;
                            dm.date = DateTime.Now;
                            db.Demo_User_Chk.Add(dm);
