                                var client = new RestClient(apinamechange);
                                var request = new RestRequest(Method.GET);

                                VastBazaartoken Responsetoken = new VastBazaartoken();
                                var whatsts = db.Email_show_passcode.SingleOrDefault();
                                if (apinamechange.ToUpper().Contains("API.VASTBAZAAR.COM/API/WEB/WHATSAPPMSG") && whatsts.whatsappapists == true)
                                {
                                    var token = Responsetoken.gettoken();
                                    request.AddHeader("authorization", "bearer " + token);
                                    request.AddHeader("content-type", "application/json");
                                }
                                var task = Task.Run(() =>
                                {
                                    return client.Execute(request).Content;
                                });
                                bool isCompletedSuccessfully = task.Wait(TimeSpan.FromSeconds(10000));
                                var resp = "";
                                if (isCompletedSuccessfully == true)
                                {
                                    resp = task.Result;
                                }

                                sms_api_entry sms = new sms_api_entry();
                                sms.apiname = apinamechange;
                                sms.msg = text;
                                sms.m_date = System.DateTime.Now;
                                sms.response = resp;
                                sms.messagefor = userid;
                                db.sms_api_entry.Add(sms);
                                db.SaveChanges();
                            }
                        }
                    }
                    catch
                    { }
                    try
                    {
                        var txtMsgBody = "Delete Retailer MPOSID OTP " + otp;
                        smssend.SendEmailAll(admindetails.email, txtMsgBody, "Delete User MPOSID", db.Admin_details.SingleOrDefault().Companyname);
                    }
                    catch
                    {
                    }

                    msg = "success";
                }

            }

            return Json(msg);
        }

        private string generatenum()
        {
            //Generate Random no.of 4 Digit between range 0 to 9999
            Random _rdm = new Random();
            var otp = _rdm.Next(0, 9999).ToString("0000");
            return otp;
        }

        public ActionResult DeleteRetailer(string RetailerId)
        {
            var check = db.Retailer_Details.Where(aa => aa.RetailerId == RetailerId && aa.ISDeleteuser == false).SingleOrDefault();
            string userid = User.Identity.GetUserId();
            var msg = "";
            string chkstats = "OK";
            var ekycstschk = db.ekycChecks.Where(x => x.userid == RetailerId).SingleOrDefault();
            if (ekycstschk != null)
            {
                if (ekycstschk.isvalid == true)
                {
                    chkstats = "NOTOK";
                }
            }
            if (chkstats == "OK")
            {
                if (check != null)
                {
                    var statusSendSmsuserdelete = db.SMSSendAlls.Where(a => a.ServiceName == "DeleteUserOTP").SingleOrDefault();
                    var statusSendEmailuserdelete = db.EmailSendAlls.Where(a => a.ServiceName == "DeleteUserOTP1").SingleOrDefault().Status;

                    var otp = generatenum();
                    if (statusSendSmsuserdelete.Status == "Y" || statusSendEmailuserdelete == "Y")
                    {
                        MobileOtp mobile = new MobileOtp();
                        mobile.Date = DateTime.Now;
                        mobile.mobileno = check.Mobile;
                        mobile.Otp = otp;
                        mobile.Type = "RetailerDelete";
                        mobile.Userid = userid;
                        db.MobileOtps.Add(mobile);
                        db.SaveChanges();
                    }
                    var txtMsgBody = "Retailer Delete OTP " + otp;
                    var admindetails = db.Admin_details.SingleOrDefault();

                    try
                    {
                        smssend.sms_init(statusSendSmsuserdelete.Status, statusSendSmsuserdelete.Whatsapp_Status, "RetailerDelete", admindetails.mobile, otp);


                        if (statusSendEmailuserdelete == "Y")
                        {
                            smssend.SendEmailAll(admindetails.email, txtMsgBody, "User Delete", db.Admin_details.SingleOrDefault().Companyname);
                        }

                    }
                    catch (System.Net.WebException E)
                    {
                    }

                    msg = "success";

                    return Json(msg, JsonRequestBehavior.AllowGet);

                }
                else
                {

                    msg = "Failed";

                    return Json(msg, JsonRequestBehavior.AllowGet);
                }
            }
            else
            {
                msg = "Failed Due to Ekyc Exists";

                return Json(msg, JsonRequestBehavior.AllowGet);
            }
        }

