                        Retailerdetail.aadharcardPath = null;
                        Retailerdetail.BackSideAadharcardphoto = null;
                    }
                    else if (hdval == "MPOSID")
                    {

                        Retailerdetail.PartnerID = null;
                    }

                    var res = db.SaveChanges();
