                        viewmodel.Service_BlockUserwiseclslist = from tbl in db.Show_Service_name
                                                                 join tbl1 in db.Service_BlockUserwise
                                                                 on tbl.idno equals tbl1.Show_Service_name_id
                                                                 select new Service_BlockUserwisecls
                                                                 {
                                                                     idno = tbl.idno,
