                                                            TempData["mobileno"] = ch;
                                                            //  return RedirectToAction("DistibutorList");
                                                        }
                                                    }
                                                    else
                                                    {
                                                        // TempData["emailconfrim"] = "Your Email id is Allready Exist.";
                                                        //  return RedirectToAction("DistibutorList");
                                                        TempData["errorexist"] = "Your Email ID Allready Exist";

                                                        addtbl.Append("<tr>");
                                                        addtbl.Append($"<td>{email}</td><td> Your Email ID Allready Exist</td>");
                                                        addtbl.Append("<tr>");
                                                    }
                                                }
                                                else
                                                {
                                                    TempData["errorexist"] = "Dealer Email ID Does NOt Exist";

                                                    addtbl.Append("<tr>");
                                                    addtbl.Append($"<td>{dealeremail}</td><td> Dealer Email ID Does NOt Exist.</td>");
                                                    addtbl.Append("<tr>");
                                                }

                                            }
                                            else
                                            {
                                                TempData["errorexist"] = "Your Mobile No  is Allready Exist.";

                                                addtbl.Append("<tr>");
                                                addtbl.Append($"<td>{phone}</td><td> Your Mobile No is Allready Exist.</td>");
                                                addtbl.Append("<tr>");
                                            }

                                        }
                                        catch
                                        {
                                            transaction.UnderlyingTransaction.Connection.Open();
                                            transaction.Rollback();
                                            TempData["Error"] = "User Not Created. Please Create After Some Time.";
                                            // return RedirectToAction("DistibutorList");
                                        }
                                    }
                                }
                            }

                        }
                    }
                }
                else
                {
                    ViewBag.Error = "Please Upload Files in .xls, .xlsx or .csv format";
                }
            }
            addtbl.Append("</table>");
            //  TempData["mobileno"] = errorlistitem;
            TempData["errortable"] = addtbl.ToString();

            return RedirectToAction("Retailerlist");
        }


