        public void vastbazzarretailer(pininsert model)
        {
            try
            {
                var tokenapi = Responsetoken.gettoken();

                var client = new RestClient("http://api.vastbazaar.com/api/Update/Pin");
                var request = new RestRequest(Method.POST);
                request.AddHeader("Authorization", "Bearer " + tokenapi);
                request.AddHeader("Content-Type", "application/json");
                var tbody = new
                {
                    model.Mobile,
                    model.RetailerName,
                    model.Pincode,
                    model.Email,
                    model.Address,
                    model.State_name,
                    model.Dist_Desc,
                    model.Frm_Name,
                    model.DealerName,
                    model.dlmpin,
                    model.dlmfirm,
                    model.dlmmobile,
                    model.dlmstate,
                    model.dealerdistrict,
                    model.dlmemail,
                    model.mstername,
                    model.msterfirmname,
                    model.mstermobile,
                    model.msteremail,
                    model.mstrpin,
                    model.msterstatename,
                    model.msterdistictname,
                    model.isseleep
                };
                var infodata = JsonConvert.SerializeObject(tbody);
                request.AddParameter("application/json", infodata, ParameterType.RequestBody);
                IRestResponse response = client.Execute(request);
            }
            catch { }
        }

        public class pininsert
        {
            public string Mobile { get; set; }
            public string RetailerName { get; set; }
            public string Pincode { get; set; }
            public string Email { get; set; }
            public string Address { get; set; }
            public string State_name { get; set; }
            public string Dist_Desc { get; set; }
            public string Frm_Name { get; set; }
            public string DealerName { get; set; }
            public string dlmpin { get; set; }
            public string dlmfirm { get; set; }
            public string dlmmobile { get; set; }
            public string dlmstate { get; set; }
            public string dealerdistrict { get; set; }
            public string dlmemail { get; set; }
            public string mstername { get; set; }
            public string msterfirmname { get; set; }
            public string mstermobile { get; set; }
            public string msteremail { get; set; }
            public string mstrpin { get; set; }
            public string msterstatename { get; set; }
            public string msterdistictname { get; set; }
            public bool isseleep { get; set; }
        }


        public ActionResult Emailconfrimation(string id)
        {
            var sts = (from pp in db.Users where pp.UserId == id select pp).Single().EmailConfirmed;
            if (sts == false)
            {
                sts = true;
            }
            User obj = (from dd in db.Users
                        where dd.UserId == id
                        select dd).SingleOrDefault();
            obj.EmailConfirmed = sts;
            db.SaveChanges();
            TempData["msgrem"] = "Email Confirmation Update Successfully.";
            return RedirectToAction("Retailerlist");
        }

        //Generate Referral code
        [HttpPost]
        public ActionResult Genratereferralcode(string Retailerid)
        {

            Random rand = new Random();
            long referralcode = (long)(rand.NextDouble() * 9000000000) + 1000000000;
            Retailer_Details obj = (from dd in db.Retailer_Details
                                    where dd.RetailerId == Retailerid
                                    select dd).SingleOrDefault();
            obj.referralcode = referralcode.ToString();
            db.SaveChanges();
            var info = (from pp in db.Retailer_Details where pp.RetailerId == Retailerid select pp).FirstOrDefault();
            new CommonUtil().SendReferralcodemail(info.RetailerName, info.Email, referralcode);
            TempData["msgrem"] = "Referral Code Send Successfully.";
            return RedirectToAction("Retailerlist");


        }

