        public ActionResult ShowAllstateWisedateBYID(string users, string filterby, string empids)
        {
            List<EmployeeAdvancePermissionViewmodel> vmodellis = new List<EmployeeAdvancePermissionViewmodel>();
            EmployeeAdvancePermissionViewmodellist vmodel = new EmployeeAdvancePermissionViewmodellist();

            vmodel.Employeeid = empids;
            vmodel.usertype = users;
            vmodel.permissiontype = filterby;
            var statewiseop = db.State_user_Wise_permission.Where(x => x.Employeeid == vmodel.Employeeid).ToList();
            //vmodel.ServicelistALL = db.tbl_permission_Services.Where(x => x.Employee_ID == EId).ToList();
            //vmodel.EmployeeIDforpart = EId;
            if (filterby == "Statewise")
            {

                if (users == "master")
                {

                    var allmaster = (from tbl in db.Superstokist_details
                                     join tbl1 in db.State_Desc on tbl.State equals tbl1.State_id
                                     select new
                                     {
                                         stateid = tbl1.State_id,
                                         statename = tbl1.State_name

                                     }).Distinct().ToList();

                    foreach (var item in allmaster)
                    {
                        EmployeeAdvancePermissionViewmodel vmodeldataonebyone = new EmployeeAdvancePermissionViewmodel();

                        var mastersaccess = statewiseop.Where(x => x.stateid == item.stateid && x.permissiontype == "Statewise" && x.usertype == users).Distinct().FirstOrDefault();
                        if (mastersaccess != null)
                        {
                            vmodeldataonebyone.isaccess = true;
                        }
                        else
                        {
                            vmodeldataonebyone.isaccess = false;
                        }

                        vmodeldataonebyone.stateid = item.stateid;
                        vmodeldataonebyone.user_statename = item.statename;
                        vmodellis.Add(vmodeldataonebyone);

                    }
                    vmodel.statewiselist = vmodellis;

                }
                else if (users == "dealer")
                {

                    var allmaster = (from tbl in db.Dealer_Details
                                     join tbl1 in db.State_Desc on tbl.State equals tbl1.State_id
                                     select new
                                     {
                                         stateid = tbl1.State_id,
                                         statename = tbl1.State_name

                                     }).Distinct().ToList();

                    foreach (var item in allmaster)
                    {
                        EmployeeAdvancePermissionViewmodel vmodeldataonebyone = new EmployeeAdvancePermissionViewmodel();

                        var mastersaccess = statewiseop.Where(x => x.stateid == item.stateid && x.permissiontype == "Statewise" && x.usertype == users).Distinct().FirstOrDefault();
                        if (mastersaccess != null)
                        {
                            vmodeldataonebyone.isaccess = true;
                        }
                        else
                        {
                            vmodeldataonebyone.isaccess = false;
                        }


                        vmodeldataonebyone.stateid = item.stateid;
                        vmodeldataonebyone.user_statename = item.statename;
                        vmodellis.Add(vmodeldataonebyone);
                    }
                    vmodel.statewiselist = vmodellis;

                }


                // return Json(allmaster, JsonRequestBehavior.AllowGet);

            }
            else
            {
                if (users == "master")
                {
                    var allmaster = (from tbl in db.Superstokist_details

                                     select new
                                     {
                                         userid = tbl.SSId,
                                         username = tbl.SuperstokistName

                                     }).ToList();

                    foreach (var item in allmaster)
                    {

                        EmployeeAdvancePermissionViewmodel vmodeldataonebyone = new EmployeeAdvancePermissionViewmodel();

                        var mastersaccess = statewiseop.Where(x => x.userID == item.userid).FirstOrDefault();
                        if (mastersaccess != null)
                        {
                            vmodeldataonebyone.isaccess = true;
                        }
                        else
                        {
                            vmodeldataonebyone.isaccess = false;
                        }
                        vmodeldataonebyone.userID = item.userid;
                        vmodeldataonebyone.user_statename = item.username;
                        vmodellis.Add(vmodeldataonebyone);
                    }
                    vmodel.userwiselist = vmodellis;

                }
                else if (users == "dealer")
                {
                    var allmaster = (from tbl in db.Dealer_Details

                                     select new
                                     {
                                         userid = tbl.DealerId,
                                         username = tbl.DealerName

                                     }).Distinct().ToList();

                    foreach (var item in allmaster)
                    {
                        EmployeeAdvancePermissionViewmodel vmodeldataonebyone = new EmployeeAdvancePermissionViewmodel();

