        [HttpPost]
        public ActionResult AddpermisionForServices(EmployeePermissionViewmodel vm, bool?[] isRead, int?[] ser_id, bool?[] iswrite, FormCollection frm)
        {
            var readvalue = Convert.ToString(frm["isRead"]);
            var EmployeeIDs = Convert.ToString(frm["EmployeeIDforpart"]);
            var result = db.tbl_permission_Services.Where(x => x.Employee_ID == EmployeeIDs).ToList();
            result.ForEach(x => x.isRead = false);
            result.ForEach(x => x.iswrite = false);
            db.SaveChanges();
            if (readvalue != null)
            {
                readvalue = readvalue.Replace("Read_", "");
                var groupname1 = readvalue.Split(',');


                foreach (var item in groupname1)
                {
                    var res = db.tbl_permission_Services.Where(x => x.Servicename == item && x.Employee_ID == EmployeeIDs).SingleOrDefault();
                    res.isRead = true;

                }
                db.SaveChanges();

            }
            var writevalue = Convert.ToString(frm["iswrite"]);

            if (writevalue != null)
            {
                writevalue = writevalue.Replace("write_", "");
                var groupname2 = writevalue.Split(',');

                foreach (var item in groupname2)
                {
                    var res = db.tbl_permission_Services.Where(x => x.Servicename == item && x.Employee_ID == EmployeeIDs).SingleOrDefault();
                    res.iswrite = true;

                }
                db.SaveChanges();
            }


            return RedirectToAction("ShowEmployeeWithPermission");
        }


