        public ActionResult Excel_new_Employee()
        {
            GeltALLEmployee geltALLEmployee = new GeltALLEmployee();

            geltALLEmployee.Emplist = db.Select_all_employee();

            DataTable dataTbl = new DataTable();

            dataTbl.Columns.Add("Current Status", typeof(string));
            dataTbl.Columns.Add("Employee Name", typeof(string));
            dataTbl.Columns.Add("Address", typeof(string));
            dataTbl.Columns.Add("Pincode", typeof(string));
            dataTbl.Columns.Add("Mobile No", typeof(string));
            dataTbl.Columns.Add("Joining Date", typeof(string));
            dataTbl.Columns.Add("Date of Birth", typeof(string));
            dataTbl.Columns.Add("EmailId", typeof(string));
            dataTbl.Columns.Add("Aadhar No", typeof(string));
            dataTbl.Columns.Add("PAN No", typeof(string));
            dataTbl.Columns.Add("Email V/F", typeof(string));

            foreach (var item in geltALLEmployee.Emplist)
            {
                dataTbl.Rows.Add(item.Status == true ? "Active" : "Deactive", item.Employee_name, item.Address, item.Pincode, item.Mobile, item.JoinDate, item.DOB, item.E_mail, item.AadharCard, item.PanCard, item.EmailConfirmed == true ? "Done" : "Due");
            }
            var grid = new GridView();
            grid.DataSource = dataTbl;
            grid.DataBind();
            Response.ClearContent();
            Response.Buffer = true;
            Response.AddHeader("content-disposition", "attachment; filename=New_Employee.xls");
            Response.ContentType = "application/ms-excel";
            Response.Charset = "";
            StringWriter sw = new StringWriter();
            HtmlTextWriter htw = new HtmlTextWriter(sw);
            grid.RenderControl(htw);
            Response.Output.Write(sw.ToString());
            Response.Flush();
            Response.End();
            return PartialView("_Get_ALL_Employeelist", geltALLEmployee);
        }
        [HttpPost]
        public async Task<ActionResult> Register_new_Employee(string Employee_name, string E_mail, string Mobile, string PanCard, string State1, string District1, string Address, string Pincode, string AadharCard)
        {
            var appDbContext = HttpContext.GetOwinContext().Get<ApplicationDbContext>();
            using (var transaction = appDbContext.Database.BeginTransaction())
            {
                try
                {
                    using (VastwebmultiEntities db = new VastwebmultiEntities())
                    {

                        var chkmobile = db.Users.Where(a => a.PhoneNumber == Mobile).Any();
                        if (chkmobile == true)
                        {
                            TempData["mobileno"] = "This Mobile Number Already Exists.";
                            return RedirectToAction("new_Employee");
                        }
                        var check = db.tbl_Admin_Employee.Where(es => es.Mobile == Mobile).Any();
                        if (check == false)
                        {
                            bool includeLowercase = false;
                            bool includeUppercase = false;
                            bool includeNumeric = true;
                            bool includeSpecial = false;
                            bool includeSpaces = false;
                            int lengthOfPassword = 8;

                            string pass = PasswordGenerator.GeneratePassword(includeLowercase, includeUppercase, includeNumeric, includeSpecial, includeSpaces, lengthOfPassword);

                            while (!PasswordGenerator.PasswordIsValid(includeLowercase, includeUppercase, includeNumeric, includeSpecial, includeSpaces, pass))
                            {
                                pass = PasswordGenerator.GeneratePassword(includeLowercase, includeUppercase, includeNumeric, includeSpecial, includeSpaces, lengthOfPassword);
                            }

                            var Password = pass;

                            var user = new ApplicationUser { UserName = E_mail, Email = E_mail, PhoneNumber = Mobile };
                            var result = await UserManager.CreateAsync(user, Password);
                            if (result.Succeeded)
                            {
                                System.Data.Entity.Core.Objects.ObjectParameter output = new
                                    System.Data.Entity.Core.Objects.ObjectParameter("output", typeof(string));
                                //   System.Data.Entity.Core.Objects.ObjectParameter("output", typeof(string));
                                var JoinDate = DateTime.Now;
                                var DOB = DateTime.Now;
                                var ch = db.Insert_new_Employee(user.Id, Employee_name, Address, Convert.ToInt32(Pincode), Mobile, JoinDate, DOB, E_mail, AadharCard, PanCard, Convert.ToInt32(State1), Convert.ToInt32(District1), "", false, output).Single().msg;

                                if (ch == "Register SuccessFully.")
                                {
                                    if (transaction.UnderlyingTransaction.Connection != null)
                                    {
                                        transaction.Commit();
                                    }
                                }
                                else
                                {
                                    if (transaction.UnderlyingTransaction.Connection != null)
                                    {
                                        transaction.Rollback();
                                    }
                                    else
                                    {
                                        transaction.UnderlyingTransaction.Connection.Open();
                                        transaction.Rollback();
                                    }
                                    TempData["mobileno"] = ch;
                                    return RedirectToAction("new_Employee");
                                }

                                string code = await UserManager.GenerateEmailConfirmationTokenAsync(user.Id);
                                var callbackUrl = Url.Action("ConfirmEmailAdmin", "Account", new { userId = user.Id, code = code }, protocol: Request.Url.Scheme);
                                callbackUrl = callbackUrl.Replace("/ADMIN", "");
                                string body = new CommonUtil().PopulateBodyDealer("", "Confirm your account", "", "" + callbackUrl + "", E_mail, Password);
                                string Welcomebody = new CommonUtil().PopulateBodyWelcomeforEmployee("", "", E_mail, Password);
                                new CommonUtil().Insertsendmail(E_mail, "Confirm your account", body, callbackUrl);
                                new CommonUtil().InsertsendmailWelcome(E_mail, "Confirm your account", Welcomebody, callbackUrl);

                                var adminemail = db.Admin_details.SingleOrDefault().email;
                                new CommonUtil().Rsendmailadmin(adminemail, "Confirm your account", body, callbackUrl);
                                var statusDealer = db.PushNotificationStatus.Where(a => a.UserRole == "Distributor").SingleOrDefault().Status;
                                var statusSendSmsDealerToRetailerCreate = db.SMSSendAlls.Where(a => a.ServiceName == "RetailerCreateDLM").SingleOrDefault();
                                var statusSendMailDealerToRetailerCreate = db.EmailSendAlls.Where(a => a.ServiceName == "RetailerCreateDLM1").SingleOrDefault().Status;

                                if (ch.ToString() == "Register SuccessFully.")
                                {
                                    string passsss = HttpUtility.UrlEncode(Password);
                                    //if (statusSendSmsDealerToRetailerCreate == "Y")
                                    //{
                                    //    string msgssss = "";
                                    //    string tempid = "";
                                    //    string urlss = "";

                                    //    var smsapionsts = db.apisms.Where(x => x.sts == "Y").SingleOrDefault();
                                    //    var smsstypes = db.Sending_SMS_Templates.Where(x => x.SMS_TYPE == "NEWEMPLOYEECREATES" && x.SMSAPIID == smsapionsts.id).SingleOrDefault();
                                    //    if (smsstypes != null)
                                    //    {
                                    //        msgssss = string.Format(smsstypes.Templates, vmodel.Mobile, passsss);
                                    //        tempid = smsstypes.Templateid;
                                    //        urlss = smsapionsts.smsapi;

                                    //        smssend.sendsmsallnew(vmodel.Mobile, msgssss, urlss, tempid);
                                    //    }

                                    //    //  smssend.sendsmsall(vmodel.Mobile, "Dear Employee ! Welcome Your user Id " + vmodel.Mobile + " and Password " + passsss + ". Thanks For Your Business . ", "User Create");
                                    //}

                                    smssend.sms_init(statusSendSmsDealerToRetailerCreate.Status, statusSendSmsDealerToRetailerCreate.Whatsapp_Status, "NEWEMPLOYEECREATES", Mobile, Mobile + " ", passsss);

                                    if (statusSendMailDealerToRetailerCreate == "Y")
                                    {
                                        smssend.SendEmailAll(E_mail, "Dear Employee ! Welcome Your user Id " + Mobile + " and Password " + passsss + ". Thanks For Your Business . ", "User Create", adminemail);
                                    }

                                    TempData["msgrem"] = ch;
                                    return RedirectToAction("new_Employee");
                                }
                                else
                                {
                                    transaction.Rollback();
                                    TempData["mobileno"] = ch;
                                    return RedirectToAction("new_Employee");
                                }

                            }


                        }
                    }
                }
                catch (Exception ex)
                {
                    transaction.Rollback();
                    return RedirectToAction("new_Employee");
                }
            }
            TempData["error"] = "Incorrect Details Found! Please try again";
            return RedirectToAction("new_Employee");
        }



