                                            Whitelabel_Trans_HighSecu_Pass wsp = new Whitelabel_Trans_HighSecu_Pass();
                                            wsp.WhitelabelId = user.Id;
                                            wsp.securitypass = securityPass;
                                            wsp.transpass = transactionPass;
                                            db.Whitelabel_Trans_HighSecu_Pass.Add(wsp);
                                            db.SaveChanges();

                                            transaction.Commit();

                                            // Send an email with this link
                                            string code = await UserManager.GenerateEmailConfirmationTokenAsync(user.Id);
                                            var callbackUrl = Url.Action("ConfirmEmail", "Account", new { userId = user.Id, code = code }, protocol: "http://" + white.websitename);
                                            callbackUrl = callbackUrl.Replace("..//" + adminwebname + "/ADMIN", "");
                                            string body = new CommonUtil().PopulateBodyDealer("", "Confirm your account", "", "" + callbackUrl + "", white.Email, Password);
                                            string Welcomebody = new CommonUtil().PopulateBodyWelcome("", "Confirm your account", "", "" + callbackUrl + "", white.Email, Password);
                                            new CommonUtil().Insertsendmail(white.Email, "Confirm your account", body, callbackUrl);
                                            new CommonUtil().InsertsendmailWelcome(white.Email, "Confirm your account", Welcomebody, callbackUrl);
                                            var adminemail = db.Admin_details.SingleOrDefault().email;
                                            new CommonUtil().Rsendmailadmin(adminemail, "Confirm your account", body, callbackUrl);

                                            ResendConfirmMail resend = new ResendConfirmMail();
                                            resend.CallBackUrl = callbackUrl;
                                            resend.Email = white.Email;
                                            resend.Password = Password;
                                            resend.Pin = "";
                                            db.ResendConfirmMails.Add(resend);
                                            db.SaveChanges();

                                            //if (statusSendSmsWhite == "Y")
                                            //{

