                                            //    string tempid = "";
                                            //    string urlss = "";

                                            //    var smsapionsts = db.apisms.Where(x => x.sts == "Y").SingleOrDefault();
                                            //    var smsstypes = db.Sending_SMS_Templates.Where(x => x.SMS_TYPE == "ADMIN_CREATE_NEW_USERS" && x.SMSAPIID == smsapionsts.id).SingleOrDefault();
                                            //    if (smsstypes != null)
