                                            //        msgssss = string.Format(smsstypes.Templates, white.Mb, Password);
                                            //        tempid = smsstypes.Templateid;
                                            //        urlss = smsapionsts.smsapi;

                                            //        smssend.sendsmsallnew(white.Mb, msgssss, urlss, tempid);
                                            //    }


