        public ActionResult WhitelabelIDSearch(string userid)
        {
            var ch = (from tbl in db.WhiteLabel_userList
                      join tbl1 in db.whitelabel_virtual_remain on tbl.WhiteLabelID equals tbl1.whitelabelid
                      where tbl.WhiteLabelID == userid
                      select new
                      {
                          tbl.WhiteLabelID,
                          tbl.Name,
                          tbl.Mobile,
                          tbl.FrmName,
                          tbl.Address,
                          tbl.state,
                          tbl.aadharnumber,
                          tbl.PanCardnumber,
                          tbl.GstNumber,
                          tbl1.ParmanentValue
                      }).ToList();
            return Json(ch.ToArray(), JsonRequestBehavior.AllowGet);
        }

        public ActionResult EditWhite_label(string userid, string Name1, string FarmName1, int State1, int District1, string Address1, string adharcard1, string Mb1, string pancard1, string gst1, decimal Virtualvalue1)
        {
            try
            {
                var ccc = db.WhiteLabel_userList.Where(p => p.WhiteLabelID == userid).SingleOrDefault();
                var mobileno = ccc.Mobile;
                var emailid = ccc.EmailId;
                var userid1 = ccc.WhiteLabelID;
                if (mobileno != Mb1)
                {
                    var usermobileno = db.Users.Where(a => a.PhoneNumber == Mb1).Any();
                    if (usermobileno == true)
                    {
                        TempData["alerdymobile"] = "This Mobile Number Alerady Use To Another User.Please Enter Another Mobile No.";
                        return RedirectToAction("Master_list");
                    }
                    else
                    {
                        int pin = new Random().Next(1000, 10000);
                        MobileOtp motp = new MobileOtp();
                        motp.Date = DateTime.Now;
                        motp.Userid = userid1;
                        motp.Type = "Whitelabel";
                        motp.mobileno = Mb1;
                        motp.Otp = pin.ToString();
                        db.MobileOtps.Add(motp);
                        db.SaveChanges();

                        try
                        {
                            var ToCC = db.Admin_details.FirstOrDefault().email;
                            CommUtilEmail emailsend = new CommUtilEmail();
                            emailsend.EmailLimitChk(emailid, ToCC, "Mobile Number Change OTP", "Your OTP Is  " + pin, "No CallBackUrl");
                        }
                        catch { }
                        TempData["email"] = "Otp Send in User Mail-Id Successfully.Please Check Mail Id and Enter OTP.";
                        return RedirectToAction("InsertOTP");
                    }
                }
                else
                {
                    if (State1 != 0 && District1 != 0)
                    {
                        db.Update_Whitelabel_user(userid, Name1, FarmName1, State1, District1, Address1, string.IsNullOrWhiteSpace(pancard1) ? "" : pancard1, adharcard1, string.IsNullOrWhiteSpace(gst1) ? "" : gst1, Virtualvalue1);
                        TempData["edit"] = "Update Successfully..";
                        return RedirectToAction("WhiteLabelUser");
                    }
                    else
                    {
                        TempData["Virtualvalue"] = "Please select District";
                        return RedirectToAction("WhiteLabelUser");
                    }
                }
            }
            catch (Exception ex)
            {
                return RedirectToAction("WhiteLabelUser");
            }
        }
