        public ActionResult Excel_WhiteLabelUser()
        {
            ViewBag.state = new SelectList(db.Select_State_Details(), "State_Id", "State_Name").ToList();
            ViewData["msg"] = TempData["msgshow"];
            Whitelabel_user white = new Whitelabel_user();
            white.White_labelUser = db.WhiteLabel_Select_Details().ToList();

            DataTable dataTbl = new DataTable();
            dataTbl.Columns.Add("White label Firm", typeof(string));
            dataTbl.Columns.Add("White label Name", typeof(string));
            dataTbl.Columns.Add("Mobile No", typeof(string));
            dataTbl.Columns.Add("PAN No", typeof(string));
            dataTbl.Columns.Add("KYC", typeof(string));
            dataTbl.Columns.Add("Email V/F", typeof(string));
            dataTbl.Columns.Add("Robotic Api", typeof(string));

            foreach (var item in white.White_labelUser)
            {
                dataTbl.Rows.Add(item.FrmName, item.Name, item.Mobile, item.PanCardnumber,
                    item.PSAStatus == "Y" && item.AadhaarStatus == "Y" ? "Done" : "Due", item.EmailConfirmed == true ? "Done" : "Due", item.Allow_RoboticsApi == "Y" ? "ON" : "OFF");
            }
            var grid = new GridView();
            grid.DataSource = dataTbl;
            grid.DataBind();
            Response.ClearContent();
            Response.Buffer = true;
            Response.AddHeader("content-disposition", "attachment; filename=WhiteLabel_User.xls");
            Response.ContentType = "application/ms-excel";
            Response.Charset = "";
            StringWriter sw = new StringWriter();
            HtmlTextWriter htw = new HtmlTextWriter(sw);
            grid.RenderControl(htw);
            Response.Output.Write(sw.ToString());
            Response.Flush();
            Response.End();
            return View();
        }

