        [HttpPost]
        [AllowAnonymous]
        [ValidateAntiForgeryToken]
        public async Task<ActionResult> Insert_api_user(string txtapinm, string txtfrimname, int State1, int District1, string Mobile1, string Address1, string email1, string txtpancard, string txtadharcard, string txtgst, string txtcapping)
        {
            var appDbContext = HttpContext.GetOwinContext().Get<ApplicationDbContext>();
            string msg = "";
            using (var transaction = appDbContext.Database.BeginTransaction())
            {
                try
                {
                    var Password = "";
                    var ConfirmPassword = "";
                    if (State1 != 0 && District1 != 0)
                    {
                        var chkmobile = db.Users.Where(a => a.PhoneNumber == Mobile1).Any();
                        if (chkmobile == true)
                        {
                            msg = "This Mobile Number Already Exists.";
                            return Json(new { msg = msg, type = "error" }, JsonRequestBehavior.AllowGet);
                            // TempData["mobileno"] = "This Mobile Number Already Exists.";
                            // return RedirectToAction("Api_user");
                        }
                        var check = db.api_user_details.Where(es => es.mobile == Mobile1).Any();
                        if (check == false)
                        {
                            ViewBag.state = new SelectList(db.Select_State_Details(), "State_Id", "State_Name").ToList();
                            //var results = (from p in db.API_Slab where p.Slab_Name != "Default" group p.Slab_Name by p.Slab_Name into g select new { SlabName = g.Key });
                            //ViewBag.slabname = new SelectList(results, "SlabName", "SlabName");
                            var user = new ApplicationUser { UserName = email1, Email = email1, PhoneNumber = Mobile1 };
                            //Generate Random Password
                            bool includeLowercase = false;
                            bool includeUppercase = false;
                            bool includeNumeric = true;
                            bool includeSpecial = false;
                            bool includeSpaces = false;
                            int lengthOfPassword = 8;

                            string pass = PasswordGenerator.GeneratePassword(includeLowercase, includeUppercase, includeNumeric, includeSpecial, includeSpaces, lengthOfPassword);

                            while (!PasswordGenerator.PasswordIsValid(includeLowercase, includeUppercase, includeNumeric, includeSpecial, includeSpaces, pass))
                            {
                                pass = PasswordGenerator.GeneratePassword(includeLowercase, includeUppercase, includeNumeric, includeSpecial, includeSpaces, lengthOfPassword);
                            }
                            Password = pass;
                            ConfirmPassword = pass.ToString();
                            var result = await UserManager.CreateAsync(user, Password);
                            if (result.Succeeded)
                            {
                                System.Data.Entity.Core.Objects.ObjectParameter output = new
                                System.Data.Entity.Core.Objects.ObjectParameter("Output", typeof(string));
                                var ch = db.Insert_Api_user(user.Id, txtapinm, txtfrimname, Mobile1, State1, District1, Address1, email1, "", string.IsNullOrWhiteSpace(txtpancard) ? "" : txtpancard, txtadharcard, string.IsNullOrWhiteSpace(txtgst) ? "" : txtgst, Convert.ToInt32(txtcapping), output).Single().msg;


                                var AdminMailId = db.Admin_details.Single().email;
                                var statusAdmin = db.PushNotificationStatus.Where(a => a.UserRole == "Admin").SingleOrDefault().Status;
                                var statusSendSmsAPI = db.SMSSendAlls.Where(a => a.ServiceName == "APICreate").SingleOrDefault();
                                var statusSendMailAPI = db.EmailSendAlls.Where(a => a.ServiceName == "APICreate1").SingleOrDefault().Status;
                                if (ch.ToString() == "Register SuccessFully.")
                                {
                                    string passsss = HttpUtility.UrlEncode(Password);
                                    transaction.Commit();

                                    // Send an email with this link
                                    string code = await UserManager.GenerateEmailConfirmationTokenAsync(user.Id);
                                    var callbackUrl = Url.Action("ConfirmEmailAdmin", "Account", new { userId = user.Id, code = code }, protocol: Request.Url.Scheme);
                                    callbackUrl = callbackUrl.Replace("/ADMIN", "");
                                    string body = new CommonUtil().PopulateBodyDealer("", "Confirm your account", "", "" + callbackUrl + "", email1, Password);
                                    string Welcomebody = new CommonUtil().PopulateBodyWelcome("", "Confirm your account", "", "" + callbackUrl + "", email1, Password);
                                    new CommonUtil().Insertsendmail(email1, "Confirm your account", body, callbackUrl);
                                    new CommonUtil().InsertsendmailWelcome(email1, "Confirm your account", Welcomebody, callbackUrl);
                                    var adminemail = db.Admin_details.SingleOrDefault().email;
                                    new CommonUtil().Rsendmailadmin(adminemail, "Confirm your account", body, callbackUrl);

                                    ResendConfirmMail resend = new ResendConfirmMail();
                                    resend.CallBackUrl = callbackUrl;
                                    resend.Email = email1;
                                    resend.Password = Password;
                                    resend.Pin = "";
                                    db.ResendConfirmMails.Add(resend);
                                    db.SaveChanges();

                                    //if (statusSendSmsAPI == "Y")
                                    //{

                                    //    string msgssss = "";
                                    //    string tempid = "";
                                    //    string urlss = "";

                                    //    var smsapionsts = db.apisms.Where(x => x.sts == "Y").SingleOrDefault();
                                    //    var smsstypes = db.Sending_SMS_Templates.Where(x => x.SMS_TYPE == "ADMIN_CREATE_NEW_USERS" && x.SMSAPIID == smsapionsts.id).SingleOrDefault();
                                    //    if (smsstypes != null)
                                    //    {
                                    //        msgssss = string.Format(smsstypes.Templates, Mobile1, passsss);
                                    //        tempid = smsstypes.Templateid;
                                    //        urlss = smsapionsts.smsapi;

                                    //        smssend.sendsmsallnew(Mobile1, msgssss, urlss, tempid);
                                    //    }

                                    //    //  smssend.sendsmsall(Mobile1, "Dear Partner ! Welcome Your user Id " + Mobile1 + " and Password " + passsss + ". Thanks For Your Business . ", "User Create");
                                    //}

                                    smssend.sms_init(statusSendSmsAPI.Status, statusSendSmsAPI.Whatsapp_Status, "ADMIN_CREATE_NEW_USERS", Mobile1, Mobile1 + " ", passsss);

                                    if (statusSendMailAPI == "Y")
                                    {
                                        smssend.SendEmailAll(email1, "Dear Partner ! Welcome Your user Id " + Mobile1 + " and Password " + passsss + ". Thanks For Your Business . ", "User Create", AdminMailId);
                                    }

                                    if (statusAdmin == "Y")
                                    {
                                        SendPushNotification(AdminMailId, Url.Action("Api_user", "Home"), "The New API User Id " + email1 + " is Created Successfully.", "API User Create.");
                                    }
                                    //  TempData["msgrem"] = ch;
                                    //  return RedirectToAction("Api_user");
                                    msg = "This Mobile Number Already Exists.";
                                    return Json(new { msg = ch, type = "Success" }, JsonRequestBehavior.AllowGet);
                                }
                                else
                                {
                                    transaction.Rollback();
                                    //TempData["mobileno"] = ch;
                                    //  return RedirectToAction("Api_user");
                                    msg = ch;
                                    return Json(new { msg = ch, type = "error" }, JsonRequestBehavior.AllowGet);
                                }

                            }
                            else
                            {
                                msg = "Your Email id is Allready Exist."; ;
                                return Json(new { msg = msg, type = "error" }, JsonRequestBehavior.AllowGet);
                                //TempData["emailconfrim"] = "Your Email id is Allready Exist.";
                                // return RedirectToAction("Api_user");
                            }
                        }
                        else
                        {
                            //  TempData["mobileno"] = "This Mobile Number Already Exists.";
                            //  return RedirectToAction("Api_user");
                            msg = "This Mobile Number Already Exists.";
                            return Json(new { msg = msg, type = "error" }, JsonRequestBehavior.AllowGet);
                        }
                    }
                    else
                    {
                        msg = "Failed";
                        return Json(new { msg = msg, type = "error" }, JsonRequestBehavior.AllowGet);
                        // return RedirectToAction("Api_user");
                    }
                }
                catch
                {
                    transaction.UnderlyingTransaction.Connection.Open();
                    transaction.Rollback();
                    msg = "User Not Created. Please Create After Some Time.";
                    return Json(new { msg = msg, type = "error" }, JsonRequestBehavior.AllowGet);
                    // TempData["Error"] = "User Not Created. Please Create After Some Time.";
                    // return RedirectToAction("Api_user");
                }
            }
        }
