        //Edit API USERS
        [HttpPost]
        public ActionResult Edit_Api_user(string txtapiid, string txtapiname, string txtfrmname, int State, int District, string ddlSlab, string txtemail, string txtmobilenew, string txtpancard1, string txtadharcard1, string txtgst1, int txtcapping1, string txtaddress)
        {
            var ccc = db.api_user_details.Where(p => p.apiid == txtapiid).SingleOrDefault();
            var mobileno = ccc.mobile;
            var emailid = ccc.emailid;
            var userid = ccc.apiid;
            if (mobileno != txtmobilenew)
            {
                var usermobileno = db.Users.Where(a => a.PhoneNumber == txtmobilenew).Any();
                if (usermobileno == true)
                {
                    TempData["alerdymobile"] = "This Mobile Number Alerady Use To Another User.Please Enter Another Mobile No.";
                    return RedirectToAction("Api_user");
                }
                else
                {
                    int pin = new Random().Next(1000, 10000);
                    MobileOtp motp = new MobileOtp();
                    motp.Date = DateTime.Now;
                    motp.Userid = userid;
                    motp.Type = "Api";
