        //Edit RCH Details
        [HttpPost]
        public ActionResult Editrch(string txtrchid, string txtemail, string txtname, string txtfrimname, string txtmobil, int State, int District, string Address, int Pincode)
        {
            try
            {
                var ccc = db.RCH_Details.Where(p => p.RCHId == txtrchid).SingleOrDefault();
                var mobileno = ccc.Mobile;
                var emailid = ccc.Email;
                var userid = ccc.RCHId;
                if (mobileno != txtmobil)
                {
                    var usermobileno = db.Users.Where(a => a.PhoneNumber == txtmobil).Any();
                    if (usermobileno == true)
                    {
                        TempData["mobileno"] = "This Mobile Number Alerady Use To Another User.Please Enter Another Mobile No.";
                        return RedirectToAction("Rch_details");
                    }
                    else
                    {
                        int pin = new Random().Next(1000, 10000);
                        MobileOtp motp = new MobileOtp();
                        motp.Date = DateTime.Now;
                        motp.Userid = userid;
                        motp.Type = "RchUser";
                        motp.mobileno = txtmobil;
                        motp.Otp = pin.ToString();
                        db.MobileOtps.Add(motp);
                        db.SaveChanges();

                        try
                        {
                            var ToCC = db.Admin_details.FirstOrDefault().email;
                            CommUtilEmail emailsend = new CommUtilEmail();
                            emailsend.EmailLimitChk(emailid, ToCC, "Mobile Number Change OTP", "Your OTP Is  " + pin, "No CallBackUrl");
                        }
                        catch { }
                        TempData["email"] = "Otp Send in User Mail-Id Successfully.Please Check Mail Id and Enter OTP.";
                        return RedirectToAction("InsertOTP");
                    }
                }

                else
                {
                    if (State != 0 && District != 0)
                    {
                        RCH_Details obj = (from p in db.RCH_Details
                                           where p.RCHId == txtrchid
                                           select p).SingleOrDefault();
                        obj.RCHName = txtname;
                        obj.Email = txtemail;
                        obj.FarmName = txtfrimname;
                        obj.Mobile = txtmobil;
                        obj.State = State.ToString();
                        obj.District = District.ToString();
                        obj.Address = Address;
                        obj.Pincode = Pincode;
                        db.SaveChanges();
                        TempData["edit"] = "Update Successfully.";
                        return RedirectToAction("Rch_details");
                    }
                    else
                    {
                        TempData["mobileno"] = "Please select District";
                        return RedirectToAction("Rch_details");
                    }
                }
            }
            catch
            {
                return RedirectToAction("Rch_details");
            }
        }

