                fileName = "Master.xlsx";
            }
            else if (Userid == "Distributor")
            {
                directoryPath = "~/Doc/Distributor.xlsx";
                fileName = "Distributor.xlsx";
            }
            else if (Userid == "Retailer")
            {
                directoryPath = "~/Doc/Retailer.xlsx";
                fileName = "Retailer.xlsx";
            }
            else if (Userid == "API")
