        //Check bal singnal
        [HttpGet]
        public ActionResult checksignal(string port, string type)
        {
            if (type == "Signal")
            {
                db.srs_Chk_signal(port, type, "");
            }
            else
            {
                var simno = (from ff in db.PortManagers where ff.PortNo == port select ff).Single().Lapuno;
                var code = (from ff in db.LapuDetails where ff.SimNo == simno select ff).FirstOrDefault().Code;
                db.srs_Chk_signal(port, type, code);
            }
            return RedirectToAction("PortReport");
        }
