        //Port Login
        public JsonResult portlogin(string Id)
        {
            var message = "";
            var port = db.PortManagers.Where(aa => aa.PortNo == Id);
            var lapuno = port.Single().Lapuno;
            var servicenm = port.Single().Sname;
            var lapu = db.LapuDetails.Where(aa => aa.SimNo == lapuno);
            var opt = lapu.Take(1).SingleOrDefault().Code;
            var userid = lapu.Take(1).SingleOrDefault().pin;
            var password = lapu.Take(1).SingleOrDefault().method;
            var imeino = lapu.Take(1).SingleOrDefault().imeino;
            var mobile = ""; var amount = ""; var rch_id = ""; var rch_type = ""; var splchk = "";
            rch_id = Guid.NewGuid().ToString().Substring(1, 12);
            var url = "https://www.vastwebindia.com/Automation.aspx?optnm=" + opt + "&userid=" + userid + "&password=" + password + "&imeino=" + imeino + "&rchno=" + mobile + "&amt=" + amount + "&servicenm=" + servicenm + "&websitenm=paynowrecharge.in&rch_id=" + rch_id + "&rch_type=" + rch_type + "&splchk=" + splchk + "&islogin=True&otp=''&otpsts=''";
            HttpWebRequest WebRequestObject = (HttpWebRequest)HttpWebRequest.Create(url);
            WebRequestObject.Timeout = (System.Int32)TimeSpan.FromSeconds(25).TotalMilliseconds;
            try
            {

                WebResponse Response = WebRequestObject.GetResponse();
                Stream WebStream = Response.GetResponseStream();

                StreamReader Reader = new StreamReader(WebStream);
                string webcontent = Reader.ReadToEnd();
            }
            catch (System.Net.WebException ex)
            { }
            message = mesg(122);
            return Json(message, JsonRequestBehavior.AllowGet);
        }
