        int count = 0;
        public string mesg(int time)
        {

            var msg = db.docomomsg().FirstOrDefault();
            var message = msg != null ? msg.statusmessage : "";
            if (count > time)
            {
                return "timeout";

            }
            else if (!string.IsNullOrEmpty(message))
            {
                return message;

            }
            else
            {

                count++;
                Thread.Sleep(1000);
                return mesg(time);

            }

        }

