        public JsonResult FillOperatorType(string name)
        {
            string othername = "";
            if (name == "PrePaid")
            {

                var operators = db.Operator_Code.ToList();
                IEnumerable<SelectListItem> selectoptlist = from p in operators
                                                            where p.Operator_type == name || p.Operator_type == "DTH"
                                                            select new SelectListItem
                                                            {
                                                                Value = p.Operator_id.ToString(),
                                                                Text = p.operator_Name
                                                            };
                ViewBag.Operatorsname = new SelectList(selectoptlist, "Value", "Text");
                return Json(ViewBag.Operatorsname, JsonRequestBehavior.AllowGet);
            }
            if (name == "PostPaid" || name == "Electricity" || name == "PostPaid" || name == "Landline" || name == "Broadband" || name == "Water" || name == "Gas")
            {

                var operators = db.Operator_Code.ToList();
                IEnumerable<SelectListItem> selectoptlist = from p in operators
                                                            where name == p.Operator_type
                                                            select new SelectListItem
                                                            {
                                                                Value = p.Operator_id.ToString(),
                                                                Text = p.operator_Name
                                                            };
                ViewBag.Operatorsname = new SelectList(selectoptlist, "Value", "Text");
                return Json(ViewBag.Operatorsname, JsonRequestBehavior.AllowGet);
            }
            if (name == "PAN" || name == "DMT" || name == "UPI" || name == "AEPS" || name == "MPOS" || name == "INDO NEPAL" || name == "PrePared Card" || name == "DigitalVoucher" || name == "Insurance" || name == "Loan" || name == "Money")
            {

                var operators = db.Operator_Code.ToList();
                IEnumerable<SelectListItem> selectoptlist = from p in operators
                                                            where name == p.Operator_type
                                                            select new SelectListItem
                                                            {
                                                                Value = p.Operator_id.ToString(),
                                                                Text = p.operator_Name
                                                            };
                ViewBag.Operatorsname = new SelectList(selectoptlist, "Value", "Text");
                return Json(ViewBag.Operatorsname, JsonRequestBehavior.AllowGet);
            }
            if (name == "DTH-Booking")
            {

                var operators = db.Operator_Code.ToList();
                IEnumerable<SelectListItem> selectoptlist = from p in operators
                                                            where name == p.Operator_type
                                                            select new SelectListItem
                                                            {
                                                                Value = p.Operator_id.ToString(),
                                                                Text = p.operator_Name
                                                            };
                ViewBag.Operatorsname = new SelectList(selectoptlist, "Value", "Text");
                return Json(ViewBag.Operatorsname, JsonRequestBehavior.AllowGet);
            }

            return Json(ViewBag.Operatorsname, JsonRequestBehavior.AllowGet);

        }
