                db.Configuration.AutoDetectChangesEnabled = false;
                // if (service123 == "PostPaid" || service123 == "Landline" || service123 == "Broadband" || service123 == "Water" || service123 == "Gas" || service123 == "Money" || service123 == "Electricity" || service123 == "Bus" || service123 == "Flight")
