                {
                    //var result = db.retailer_operator_code.Where(x => x.RetailerId == rem && x.Operator_id == operatornameid).FirstOrDefault();//(from tbl in db.retailer_operator_code where tbl.RetailerId == rem && tbl.Operator_id == operatornameid).FirstOrDefault();
