        public ActionResult BlockUserList(string opid, string retid, string serid, string categoryname)
        {
            opid = opid == "Select Operator" ? null : opid;
            retid = retid == "Select Retailer" ? null : retid;
            serid = serid == "Select Service" ? null : serid;
            categoryname = categoryname == "Select Category" ? null : categoryname;
            ViewBag.retailer1 = new SelectList(db.select_retailer_for_all(), "RetailerId", "RetailerName", null);
            List<CategoryService> myLevels = Enum.GetValues(typeof(CategoryService)).Cast<CategoryService>().ToList();
            // ViewBag.RequiredCategory = new SelectList(myLevels);

            var itemTypesList = new List<SelectListItem>();
            itemTypesList.AddRange(Enum.GetValues(typeof(CategoryService)).Cast<CategoryService>().Select(
                        (item, index) => new SelectListItem
                        {
                            Text = item.ToString(),
                            Value = item.ToString()

                        }).ToList());
            ViewBag.RequiredCategory = itemTypesList;



            IEnumerable<block_operator_list_Result> mylist;// = new IEnumerable<block_operator_list_Result>();
            // var mylist = db.block_operator_list();
            mylist = db.block_operator_list();
            if (categoryname == "PrePaid")
            {
                if (!string.IsNullOrEmpty(retid) && string.IsNullOrEmpty(categoryname))
                {
                    mylist = mylist.Where(x => x.RetailerId == retid);//db.block_operator_list().Where(z => z.RetailerId == retid); //mylist.Where(aa => aa.RetailerId == retid).ToList();
                }
                else if (string.IsNullOrEmpty(retid) && !string.IsNullOrEmpty(categoryname))
                {
                    mylist = mylist.Where(aa => aa.Operator_type == "PrePaid" || aa.Operator_type == "DTH").ToList();
                }
                else if (!string.IsNullOrEmpty(retid) && !string.IsNullOrEmpty(categoryname))
                {
                    mylist = mylist.Where(aa => aa.RetailerId == retid && (aa.Operator_type == "PrePaid" || aa.Operator_type == "DTH")).ToList();
                }
            }

            //else if (!string.IsNullOrEmpty(categoryname) && categoryname != "PrePaid")
            //{

            //        myList = myList.Where(aa => aa.Operator_type == categoryname).ToList();

            //}
            else
            {

                if (!string.IsNullOrEmpty(retid) && string.IsNullOrEmpty(opid) && string.IsNullOrEmpty(serid))
                {
                    mylist = mylist.Where(aa => aa.RetailerId == retid).ToList();
                }
                else if (string.IsNullOrEmpty(retid) && !string.IsNullOrEmpty(opid) && string.IsNullOrEmpty(serid))
                {
                    mylist = mylist.Where(aa => aa.Operator_id == opid).ToList();
                }
                else if (string.IsNullOrEmpty(retid) && string.IsNullOrEmpty(opid) && !string.IsNullOrEmpty(serid))
                {
                    mylist = mylist.Where(aa => aa.Operator_type.ToUpper() == serid.ToUpper()).ToList();
                }
                else if (!string.IsNullOrEmpty(retid) && !string.IsNullOrEmpty(opid) && string.IsNullOrEmpty(serid))
                {
                    mylist = mylist.Where(aa => aa.RetailerId == retid && aa.Operator_id == opid).ToList();
                }
                else if (string.IsNullOrEmpty(retid) && !string.IsNullOrEmpty(opid) && !string.IsNullOrEmpty(serid))
                {
                    mylist = mylist.Where(aa => aa.Operator_id == opid && aa.Operator_type.ToUpper() == serid.ToUpper()).ToList();
                }
                else if (!string.IsNullOrEmpty(retid) && string.IsNullOrEmpty(opid) && !string.IsNullOrEmpty(serid))
                {

                    mylist = mylist.Where(aa => aa.RetailerId == retid && aa.Operator_type.ToUpper() == serid.ToUpper()).ToList();
                }
                //else if (!string.IsNullOrEmpty(retid) && !string.IsNullOrEmpty(opid) && !string.IsNullOrEmpty(serid))
                //{

                //    myList = myList.Where(aa => aa.RetailerId == retid && aa. && aa.Operator_type == serid).ToList();
                //}
            }
            var result = new { retailer = ViewBag.retailer1, category = ViewBag.RequiredCategory, list = mylist };
            return new JsonResult()
            {
                ContentEncoding = Encoding.Default,
                ContentType = "application/json",
                Data = result,

                JsonRequestBehavior = JsonRequestBehavior.AllowGet,
                MaxJsonLength = int.MaxValue
            };



        }
