        public ActionResult BlockWhitelabel(string Whitelabellist, string WhitelabelOperator, string WhiteLabelCategory, string WhitelabelService)
        {
            int status = 0;
            if (WhiteLabelCategory == "PrePaid" || WhitelabelService == "Utility")
            {
                //var result = db.whitelabel_operator_code.Where(x => x.nuserid == Whitelabellist && x.optid == WhitelabelOperator).FirstOrDefault();//(from tbl in db.retailer_operator_code where tbl.RetailerId == rem && tbl.Operator_id == operatornameid).FirstOrDefault();
                //if (result != null)
                //{
                //    result.status = false;
                //    db.Entry(result).State = EntityState.Modified;


                //}

                if (WhitelabelOperator == "")
                {

                    var myList = (from a in db.whitelabel_operator_code
                                  join c in db.Operator_Code on a.optid equals c.Operator_id.ToString()
                                  where (c.Operator_type == WhiteLabelCategory || c.Operator_type == "DTH") && a.whitelabelid == Whitelabellist
                                  select a).ToList();
                    // var result = db.dlm_opt_code.Where(x => x.dlmid == Distributorlist && x.optid == DOperator).FirstOrDefault();//(from tbl in db.retailer_operator_code where tbl.RetailerId == rem && tbl.Operator_id == operatornameid).FirstOrDefault();
                    if (myList != null)
                    {
                        // result.status = false;
                        // db.Entry(result).State = EntityState.Modified;

                        myList.ForEach(x => x.status = false);

                    }



                }
                else if (WhitelabelOperator != "")
                {

                    var result = db.whitelabel_operator_code.Where(x => x.whitelabelid == Whitelabellist && x.optid == WhitelabelOperator).FirstOrDefault();//(from tbl in db.retailer_operator_code where tbl.RetailerId == rem && tbl.Operator_id == operatornameid).FirstOrDefault();
                    if (result != null)
                    {
                        result.status = false;
                        db.Entry(result).State = EntityState.Modified;



                    }
                }






            }

            else if (WhitelabelService == "PostPaid" || WhitelabelService == "Electricity" || WhitelabelService == "Gas" || WhitelabelService == "Broadband" || WhitelabelService == "Landline" || WhitelabelService == "Insurance" || WhitelabelService == "Loan" || WhitelabelService == "DTH-Booking")
            {

                var myList = (from a in db.whitelabel_operator_code
                              join c in db.Operator_Code on a.optid equals c.Operator_id.ToString()
                              where c.Operator_type == WhitelabelService && a.whitelabelid == Whitelabellist
                              select a).ToList();
                myList.ForEach(x => x.status = false);

                //  db.Entry(myList).State = EntityState.Modified;



            }


            else
            {
                if (WhitelabelService == "PAN")
                {
                    var result = db.WhiteLabel_userList.Where(x => x.WhiteLabelID == Whitelabellist).FirstOrDefault();//(from tbl in db.retailer_operator_code where tbl.RetailerId == rem && tbl.Operator_id == operatornameid).FirstOrDefault();
                    if (result != null)
                    {
                        result.pancardsts = "N";
                        db.Entry(result).State = EntityState.Modified;

                    }
                }
                else if (WhitelabelService == "DMT")
                {
                    var result = db.WhiteLabel_userList.Where(x => x.WhiteLabelID == Whitelabellist).FirstOrDefault();//(from tbl in db.retailer_operator_code where tbl.RetailerId == rem && tbl.Operator_id == operatornameid).FirstOrDefault();
                    if (result != null)
                    {
                        result.moneysts = false;
                        db.Entry(result).State = EntityState.Modified;

                    }
                }
