        public JsonResult BlockAmountStatusUpdate(int id, string optnm, string status)
        {
            var list = db.AmountBlockunblocks.FirstOrDefault(x => x.idno == id);
            if (list != null)
            {
                status = status == "Y" ? "N" : "Y";
                list.status = status;
                db.Entry(list).State = EntityState.Modified;
            }
            db.SaveChanges();
            var result = db.AmountBlockunblocks.Where(x => x.OperatorName == optnm).ToList();
            return Json(result, JsonRequestBehavior.AllowGet);
        }

