        public JsonResult AddAmountBlock(decimal? amount, string name, string User)
        {
            if (User == "")
            {
                User = null;
            }
            AmountBlockunblock tbl = new AmountBlockunblock();
            tbl.Amount = amount.Value;
            tbl.OperatorName = name;
            tbl.status = "Y";
            tbl.User = User;
            db.AmountBlockunblocks.Add(tbl);
            //var list = db.AmountBlockunblocks.FirstOrDefault(x => x.idno == id);
            //if (list != null)
            //{
            //    status = status == "Y" ? "N" : "Y";
            //    list.status = status;
            //    db.Entry(list).State = EntityState.Modified;
            //}
            db.SaveChanges();
            var result = db.AmountBlockunblocks.Where(x => x.OperatorName == name).ToList();
            return Json(result, JsonRequestBehavior.AllowGet);
        }

