        public ActionResult BlockAllOperatorList(DateTime? blockdate, string Category, int? Operatoename, string opertype)
        {
            OperatorIndexViewModel vmodel = new OperatorIndexViewModel();
            if (!string.IsNullOrEmpty(Category) && Operatoename != null)
            {
                var list = db.Operator_Code.Where(a => a.Operator_type == Category && a.Operator_id == Operatoename.Value).ToList();
                if (list.Count > 0)
                {
                    list.ToList().ForEach(u =>
                    {
                        u.status = "N";
                        u.blocktime = blockdate;
                    });
                    // list.ForEach(z => z.status = "N");


                }
                db.SaveChanges();
                // vmodel.opcodelist = db.Operator_Code.Where(a => a.Operator_type == Category && a.Operator_id == Operatoename.Value).ToList();
                //   return PartialView("_PrePaidDTHService", vmodel);

                var resulttable = db.Operator_Code.ToList();
                if (opertype == "Postpaid")
                {

