        [HttpPost]
        public ActionResult check(string[] array, string date, string type)
        {
            foreach (var item in array)
            {
                if (item == "on")
                {
                    db.update_opt_date("All", type, date);
                }
                else
                {
                    db.update_opt_date(item, type, date);
                }
            }
            return Json("", JsonRequestBehavior.AllowGet);
        }
        public ActionResult inset_New_Operator(string ddloperatortype, string txtoperatorname, string txtoperatorCode)
        {
            if (txtoperatorname != "" && txtoperatorCode != "")
            {
                db.insert_new_Operator(txtoperatorname, ddloperatortype, txtoperatorCode);
                TempData["success"] = "Operator Code insert Successfully.";
                return RedirectToAction("OperatorIndex");
            }
            else
            {
                TempData["success"] = "Operator Code Not Inserted.Please Try again !";
                return RedirectToAction("OperatorIndex");
            }
        }

        [HttpPost]
        public ActionResult Search_OperatorIndex(string operatorname, string operatortype)
        {
            var optname = "";
            var opttype = "";
            if (operatorname != "")
            {
                optname = operatorname;
                var opt = db.Operator_Code.Where(a => a.operator_Name == optname).OrderBy(a => a.Operator_type).ToList();
                ViewBag.show = opt;
            }
            if (operatortype != "")
            {

                opttype = operatortype;
                var opt = db.Operator_Code.Where(a => a.Operator_type == opttype).OrderBy(a => a.Operator_type).ToList();
                ViewBag.show = opt;

            }
            if (operatortype != "" && operatorname != "")
            {
                optname = operatorname;
                opttype = operatortype;
                var opt = db.Operator_Code.Where(a => a.operator_Name == optname && a.Operator_type == opttype).OrderBy(a => a.Operator_type).ToList();
                ViewBag.show = opt;
            }
            if (operatortype == "" && operatorname == "")
            {
                optname = operatorname;
                opttype = operatortype;
                var opt = db.Operator_Code.OrderBy(a => a.Operator_type).ToList();
                ViewBag.show = opt;
            }
            TempData["show"] = ViewBag.show;
            return RedirectToAction("OperatorIndex");
        }
