        [HttpPost]
        public ActionResult TDSSettingSave(string[] optCode)
        {
            foreach (var item in optCode)
            {
                var groupname1 = item.Split(',');
                var type = groupname1[0].ToString();
                var emailid = groupname1[1].ToString();
                var Status = groupname1[2].ToString();

                if (type == "DMT")
                {
                    TDSController obj = (from pp in db.TDSControllers
                                         where pp.Email == emailid
                                         select pp).SingleOrDefault();
                    obj.DMT = Status;
                    db.SaveChanges();
                }
                else if (type == "AEPS")
                {
                    TDSController obj = (from pp in db.TDSControllers
                                         where pp.Email == emailid
                                         select pp).SingleOrDefault();
                    obj.AEPS = Status;
                    db.SaveChanges();
                }
                else if (type == "MPoss")
                {
                    TDSController obj = (from pp in db.TDSControllers
                                         where pp.Email == emailid
                                         select pp).SingleOrDefault();
                    obj.MPoss = Status;
                    db.SaveChanges();
                }
                else if (type == "Flight")
                {
                    TDSController obj = (from pp in db.TDSControllers
                                         where pp.Email == emailid
                                         select pp).SingleOrDefault();
                    obj.Flight = Status;
                    db.SaveChanges();
                }
                else if (type == "Postpaid")
                {
                    TDSController obj = (from pp in db.TDSControllers
                                         where pp.Email == emailid
                                         select pp).SingleOrDefault();
                    obj.Postpaid = Status;
                    db.SaveChanges();
                }
                else if (type == "Pancard")
                {
                    TDSController obj = (from pp in db.TDSControllers
                                         where pp.Email == emailid
                                         select pp).SingleOrDefault();
                    obj.Pancard = Status;
                    db.SaveChanges();
                }
