        [HttpPost]
        public ActionResult checkpassword(string txtcode, string type)
        {
            var chktranss = db.admin_new_pass.SingleOrDefault();
            DateTime currenttime = DateTime.Now;
            DateTime lastchangedpassdtr = Convert.ToDateTime(chktranss.lastupdatesec);
            lastchangedpassdtr = lastchangedpassdtr.AddDays(Convert.ToInt32(chktranss.secexpdays));
            var defaultht = Decrypt(chktranss.securitypass);
            if (defaultht == "1111" || (lastchangedpassdtr <= currenttime))
            {
                TempData["error"] = "Your security pin is expired or have to be changed!! Please set new security pin";
                return RedirectToAction("ChangeSecurityPassword");
            }

            var txtcdoe1 = Encrypt(txtcode.ToString());
            var tranpass = (from paa in db.admin_new_pass where paa.securitypass == txtcdoe1 select paa).Count();
            if (tranpass > 0)
            {
                TempData["chk"] = "ok";
                if (type == "slabmaster")
                {
                    return RedirectToAction("Slab_Master_Distributer");
                }
                else if (type == "slabdealer")
                {
                    return RedirectToAction("Slab_distibutor");
                }
                else if (type == "slabretailer")
                {
                    return RedirectToAction("Slab_retailer");
                }
                else if (type == "changecode")
                {
                    return RedirectToAction("ChangeOperatorcode");
                }
                else
                {
                    return RedirectToAction("Slab_API");
                }
            }
            else
            {
                ViewData["MSG"] = "Hi Security Password Wrong.";
                return View();
            }
        }

