        public ActionResult apisearch(string apicd)
        {
            var chk = db.SRS_API.ToList();
            if (apicd != "ALL")
            {
                chk = db.SRS_API.Where(s => s.opt_code == apicd).ToList();
            }
            List<apilisst> ds = new List<apilisst>();

            foreach (var i in chk)
            {
                apilisst d1 = new apilisst();
                d1.apiname = i.apiname;
                ds.Add(d1);
            }
            var datass = ds.ToList();
            return Json(new { datas = datass }, 0);
        }
        public ActionResult ShowNillPostReports(string operatorstypevalue, string listAllOp)
        {
            NillPortalViewmodel viewModel = new NillPortalViewmodel();
            listAllOp = listAllOp == "select operator" ? "" : listAllOp;
            operatorstypevalue = operatorstypevalue == "ALL OPERATORS TYPE" ? "" : operatorstypevalue;
            viewModel.NillCOmopcodeamountlist = db.select_nill_com().ToList();
            if (!string.IsNullOrEmpty(operatorstypevalue) && string.IsNullOrEmpty(listAllOp))
            {
                viewModel.NillCOmopcodeamountlist = viewModel.NillCOmopcodeamountlist.Where(x => x.Operator_type == operatorstypevalue);
            }
            else if (string.IsNullOrEmpty(operatorstypevalue) && !string.IsNullOrEmpty(listAllOp))
            {
                viewModel.NillCOmopcodeamountlist = viewModel.NillCOmopcodeamountlist.Where(x => x.opt == listAllOp);
            }
            else if (!string.IsNullOrEmpty(operatorstypevalue) && !string.IsNullOrEmpty(listAllOp))
            {
                viewModel.NillCOmopcodeamountlist = viewModel.NillCOmopcodeamountlist.Where(x => x.Operator_type == operatorstypevalue && x.opt == listAllOp);
            }
            return PartialView("_NILLPORTALLAMOUNTShow", viewModel);
        }
        public ActionResult ShowALLNillPortalAMount(string opnamelistbyid, decimal? textminiamount, decimal? textmaxamount)
        {
            bool exists = (from users in db.Nill_Com
                           where users.opt == opnamelistbyid && users.min < textminiamount && users.max > textmaxamount
                           select users).Any();
