        public ActionResult AddRechargeSpecial(string ddlType, string ddlusertype, string ddluserList, string dlmMP, string ddlPT, string ByAMountopttype, string ByAmountOperator, int? txtByamount, int? txtmaxByamount)
        {
            if (ByAmountOperator != "ALL")
            {
                var count = (from gg in db.recharge_switch_special where gg.rch_from == ddlusertype where gg.users == ddluserList where gg.opt == ByAmountOperator where gg.amount <= txtByamount.Value && gg.maxamount >= txtByamount.Value where gg.rch_to == ddlType select gg).Count();
                if (count == 0)
                {
                    if (ddlType == "Machine")
                    {
                        ddlPT = dlmMP;
                    }
                    else
                    {
                        ddlPT = ddlPT;
                    }
                    if (ddlPT == "")
                    {
                        ddlPT = "ALL";
                    }
                    if (string.IsNullOrEmpty(ddluserList))
                    {
                        ddluserList = "All";
                    }
                    else
                    {
                        ddluserList = ddluserList;
                    }
                    recharge_switch_special objOTP = new recharge_switch_special();
                    objOTP.rch_from = ddlusertype;
                    objOTP.rch_to = ddlType;
                    objOTP.opt = ByAmountOperator;
                    objOTP.amount = txtByamount.Value;
                    objOTP.maxamount = txtmaxByamount.Value;
                    objOTP.portno = ddlPT;
                    objOTP.sts = "N";
                    objOTP.users = ddluserList;
                    db.recharge_switch_special.Add(objOTP);
                    db.SaveChanges();

                }
            }
            else
            {
                var type = db.Operator_Code.Where(x => x.Operator_type == ByAMountopttype).ToList();

                foreach (var i in type)
                {
                    var count = (from gg in db.recharge_switch_special where gg.rch_from == ddlusertype where gg.users == ddluserList where gg.opt == i.new_opt_code where gg.amount <= txtByamount.Value && gg.maxamount >= txtByamount.Value where gg.rch_to == ddlType select gg).Count();
                    if (count == 0)
                    {
                        if (ddlType == "Machine")
                        {
                            ddlPT = dlmMP;
                        }
                        else
                        {
                            ddlPT = ddlPT;
                        }
                        if (ddlPT == "")
                        {
                            ddlPT = "ALL";
                        }
                        if (string.IsNullOrEmpty(ddluserList))
                        {
                            ddluserList = "All";
                        }
                        else
                        {
                            ddluserList = ddluserList;
                        }
                        recharge_switch_special objOTP = new recharge_switch_special();
                        objOTP.rch_from = ddlusertype;
                        objOTP.rch_to = ddlType;
                        objOTP.opt = i.new_opt_code;
                        objOTP.amount = txtByamount.Value;
                        objOTP.maxamount = txtmaxByamount.Value;
                        objOTP.portno = ddlPT;
                        objOTP.sts = "N";
                        objOTP.users = ddluserList;
                        db.recharge_switch_special.Add(objOTP);
                        db.SaveChanges();

                    }
                }



            }

            NillPortalViewmodel vmodel = new NillPortalViewmodel();
            vmodel.ShowREchargelist = db.show_recharge_switch_special("ALL", "ALL", "ALL").ToList();

            return PartialView("_specialamount", vmodel);
        }

        public ActionResult RCHSPLSearch(string usertype, string SwitchTypes)
        {
            NillPortalViewmodel vmodel = new NillPortalViewmodel();
            vmodel.ShowREchargelist = db.show_recharge_switch_special("ALL", "ALL", "ALL").ToList();
            if (!string.IsNullOrEmpty(usertype))
            {


                if (usertype == "API" || usertype == "Retailer")
                {
                    vmodel.ShowREchargelist = vmodel.ShowREchargelist.Where(x => x.users == SwitchTypes).ToList();
                }
                else if (usertype == "GetWaywise")
                {
                    vmodel.ShowREchargelist = vmodel.ShowREchargelist.Where(x => x.rch_from == SwitchTypes).ToList();

                }
                else
                {
                    if (!string.IsNullOrEmpty(SwitchTypes))
                    {
                        vmodel.ShowREchargelist = vmodel.ShowREchargelist.Where(x => x.opt == SwitchTypes).ToList();
                    }

                }
            }

            return PartialView("_specialamount", vmodel);
        }

