        //Recharge Spical Block And Unblock
        public ActionResult rch_spl(int id)
        {
            var entry = db.recharge_switch_special.Single(s => s.idno == id);
            entry.sts = entry.sts == "N" ? "Y" : "N";

            var check = db.recharge_switch_special.Where(s => s.idno != id && s.rch_from == entry.rch_from && s.opt == entry.opt && s.sts == "Y" && s.portno == entry.portno).FirstOrDefault();
            if (check != null)
            {
                if ((check.amount >= entry.amount && check.amount <= entry.maxamount) || (entry.amount >= check.amount && entry.maxamount <= check.amount))
                {
                    if (check.users != "All" && entry.users != "All" && check.users != entry.users)
                    {
                        db.SaveChanges();
                    }
                }
                else
                {
                    db.SaveChanges();
                }
            }
            else
            {
                db.SaveChanges();
            }

            if (entry.sts == "N")
            {
                db.SaveChanges();
            }

            //recharge_switch_special objCourse = (from p in db.recharge_switch_special
            //                                     where p.idno == id
            //                                     select p).SingleOrDefault();
            //objCourse.sts = sts;
            //db.SaveChanges();
            if (Request.IsAjaxRequest())
            {
                NillPortalViewmodel vmodel = new NillPortalViewmodel();
                vmodel.ShowREchargelist = db.show_recharge_switch_special("ALL", "ALL", "ALL").ToList();

                return PartialView("_specialamount", vmodel);
            }
            return RedirectToAction("Recharge_special");
        }
