        public ActionResult Searchrechargeswitch(string usertype, string SwitchTypes)
        {
            NillPortalViewmodel vmodel = new NillPortalViewmodel();
            vmodel.ShowOPSwitchList = db.show_recharge_switch("ALL", "ALL", "ALL").ToList();
            if (!string.IsNullOrEmpty(usertype))
            {


                if (usertype == "API" || usertype == "Retailer")
                {
                    if (string.IsNullOrEmpty(SwitchTypes))
                    {
                        vmodel.ShowOPSwitchList = vmodel.ShowOPSwitchList.Where(x => x.Recharge_from == usertype).ToList();

                    }
                    else
                    {
                        vmodel.ShowOPSwitchList = vmodel.ShowOPSwitchList.Where(x => x.users == SwitchTypes).ToList();

                    }
                }
                else if (usertype == "GetWaywise")
                {
                    if (string.IsNullOrEmpty(SwitchTypes))
                    {
                        vmodel.ShowOPSwitchList = vmodel.ShowOPSwitchList.Where(x => x.Type == "API" || x.Type == "Machine").ToList();

                    }
                    else
                    {
                        vmodel.ShowOPSwitchList = vmodel.ShowOPSwitchList.Where(x => x.Type == SwitchTypes).ToList();


                    }

                }
                else
                {
                    if (!string.IsNullOrEmpty(SwitchTypes))
                    {
                        vmodel.ShowOPSwitchList = vmodel.ShowOPSwitchList.Where(x => x.opt == SwitchTypes).ToList();
                    }

                }
            }

            return PartialView("_Recharge_switch", vmodel);
        }


