        [HttpPost]
        public ActionResult Dealer_switch(string dlmid, string masterid)
        {
            ViewBag.dlmid = new SelectList(db.select_Dealer_for_ddl(), "Dealerid", "DealerName", null);
            ViewBag.masterid = new SelectList(db.select_Master_Dealer_for_ddl(), "SSId", "MasterDealerName", null);
            var oldssid = (db.Dealer_Details.Where(aa => aa.DealerId == dlmid).Single().SSId);
            //var slab = "";
            //var chkslab = db.Slab_name.Where(a => a.createdby == masterid).Any();
            //if (chkslab == false)
            //{
            //    TempData["slabname"] = "This Master Not Assign Any Slab";
            //    return RedirectToAction("Dealer_switch", "Home");
            //}
            //else
            //{
            //    slab = (from pp in db.Slab_name where pp.createdby == masterid select pp.SlabName).First();
            //}
            if (oldssid.ToLower() != masterid.ToLower())
            {
                using (VastwebmultiEntities newdb = new VastwebmultiEntities())
                {
                    Dealer_Details objCourse = (from p in newdb.Dealer_Details
                                                where p.DealerId == dlmid
                                                select p).Single();
                    objCourse.SSId = masterid;
                    //objCourse.slab_name = slab;
                    newdb.SaveChanges();
                }
                TempData["success"] = "Distributor Transfer SuccessFully.";
            }
            else
            {
                TempData["error"] = "Distributor Already Under This Master.";
            }

            return View();
        }
        //Assign Operator RCH id
        public ActionResult Assign_Opt()
        {
            var stands = db.RCH_Details.ToList();
            IEnumerable<SelectListItem> selectList = from s in stands
                                                     select new SelectListItem
                                                     {
                                                         Value = s.RCHId,
                                                         Text = s.Email + "--" + s.RCHName.ToString()
                                                     };
            ViewBag.rchid = new SelectList(selectList, "Value", "Text");
            ViewBag.rchid1 = new SelectList(selectList, "Value", "Text");
            ViewBag.rchid2 = new SelectList(selectList, "Value", "Text");
            ViewBag.rchid3 = new SelectList(selectList, "Value", "Text");

            var retailer = db.Retailer_Details.Where(aa => aa.ISDeleteuser == false).ToList();
            IEnumerable<SelectListItem> selectListRetailer = from s in retailer
                                                             select new SelectListItem
                                                             {
                                                                 Value = s.RetailerId,
                                                                 Text = s.Email + "--" + s.RetailerName.ToString()
                                                             };
            ViewBag.retailerid = new SelectList(selectListRetailer, "Value", "Text");
            ViewBag.retailerid1 = new SelectList(selectListRetailer, "Value", "Text");
            ViewBag.retailerid2 = new SelectList(selectListRetailer, "Value", "Text");
            ViewBag.retailerid3 = new SelectList(selectListRetailer, "Value", "Text");


            var opt = (from ff in db.Operator_Code select ff);
            ViewBag.opt = new SelectList(opt, "new_opt_code", "operator_Name");
            ViewBag.opt2 = new SelectList(opt, "new_opt_code", "operator_Name");
            ViewBag.opt3 = new SelectList(opt, "new_opt_code", "operator_Name");
            RchModel rch = new RchModel();
            rch.show_all = db.Select_manual_opt("ALL");
            var innerJoin = from e in db.Operator_Code
                            join d in db.Rch_purchase on e.new_opt_code equals d.Opt
                            join r in db.RCH_Details on d.Rch_id equals r.RCHId

                            select new GoodVM
                            {
                                id = d.idno,
                                Rch_id = d.Rch_id,
                                Email = r.Email,
                                Opt = e.operator_Name,
                                Optcode = d.Opt,
                                comm = d.comm


                            };
            rch.Rch_purcharge = (innerJoin.ToList());
            return View(rch);
        }
        [HttpPost]
        public ActionResult Assign_Opt(string rchid1, string but)
        {
            if (rchid1 == "")
            {
                rchid1 = "ALL";
            }
            var stands = db.RCH_Details.ToList();
            IEnumerable<SelectListItem> selectList = from s in stands
                                                     select new SelectListItem
                                                     {
                                                         Value = s.RCHId,
                                                         Text = s.RCHId + "--" + s.RCHName.ToString()
                                                     };
            ViewBag.rchid = new SelectList(selectList, "Value", "Text");
            ViewBag.rchid1 = new SelectList(selectList, "Value", "Text");
            ViewBag.rchid2 = new SelectList(selectList, "Value", "Text");
            ViewBag.rchid3 = new SelectList(selectList, "Value", "Text");

            var retailer = db.Retailer_Details.Where(aa => aa.ISDeleteuser == false).ToList();
            IEnumerable<SelectListItem> selectListRetailer = from s in retailer
                                                             select new SelectListItem
                                                             {
                                                                 Value = s.RetailerId,
                                                                 Text = s.Email + "--" + s.RetailerName.ToString()
                                                             };
            ViewBag.rchid = new SelectList(selectListRetailer, "Value", "Text");
            ViewBag.rchid1 = new SelectList(selectListRetailer, "Value", "Text");
            ViewBag.rchid2 = new SelectList(selectListRetailer, "Value", "Text");
            ViewBag.rchid3 = new SelectList(selectListRetailer, "Value", "Text");

            var opt = (from ff in db.Operator_Code select ff);
            ViewBag.opt = new SelectList(opt, "new_opt_code", "operator_Name");
            ViewBag.opt2 = new SelectList(opt, "new_opt_code", "operator_Name");
            ViewBag.opt3 = new SelectList(opt, "new_opt_code", "operator_Name");
            if (but == "All Block")
            {
                if (rchid1 == "A")
                {
                    db.Manual_opt_sts.ToList().ForEach(x =>
                    {
                        x.status = "N";
                    });
                    db.SaveChanges();
                }
                else
                {
                    db.Manual_opt_sts.Where(x => x.respID == rchid1).ToList().ForEach(x =>
                    {
                        x.status = "N";
                    });
                    db.SaveChanges();
                }
            }
            else if (but == "All Unblock Block")
            {
                if (rchid1 == "A")
                {
                    db.Manual_opt_sts.Where(x => x.respID == rchid1).ToList().ForEach(x =>
                    {
                        x.status = "Y";
                    });
                    db.SaveChanges();
                }
                else
                {
                    db.Manual_opt_sts.Where(x => x.respID == rchid1).ToList().ForEach(x =>
                    {
                        x.status = "Y";
                    });
                    db.SaveChanges();
                }
            }
            RchModel rch = new RchModel();
            rch.show_all = db.Select_manual_opt("A");
            var innerJoin = from e in db.Operator_Code
                            join d in db.Rch_purchase on e.new_opt_code equals d.Opt
                            select new GoodVM
                            {
                                id = d.idno,
                                Rch_id = d.Rch_id,
                                Opt = e.operator_Name,
                                Optcode = d.Opt,
                                comm = d.comm
                            };
            rch.Rch_purcharge = (innerJoin.ToList());
            return View(rch);

        }
