        //Add Rch  Purchase 
        [HttpPost]
        public ActionResult Insert_rch_purcharge(string rchid2, string opt2, decimal Comm)
        {
            if (db.Rch_purchase.Any(o => o.Rch_id == rchid2 && o.Opt == opt2) == false)
            {
                // Match!
                Rch_purchase rch = new Rch_purchase();
                rch.Opt = opt2;
                rch.Rch_id = rchid2;
                rch.comm = Comm;
                db.Rch_purchase.Add(rch);
                db.SaveChanges();
                TempData["success"] = "Add Purchase Successfully.";
                return RedirectToAction("Assign_Opt");
            }
            else
            {
                TempData["error"] = "Add Purchase Allready Exist";
                return RedirectToAction("Assign_Opt");
            }

        }

