        public ActionResult Insert_ExtraCommision(string extracommopnamelistbyid, decimal textextracommminiamount, decimal extracommtextmaxamount, decimal extracommtextCommision)
        {
            var chkexist = db.Range_wise_extra_commission.Where(x => x.opratoridid == extracommopnamelistbyid).Any();
            if (chkexist == false)
            {
                Range_wise_extra_commission rangecomm = new Range_wise_extra_commission();
                rangecomm.opratoridid = extracommopnamelistbyid;
                rangecomm.minamount = textextracommminiamount;
                rangecomm.maxamnt = extracommtextmaxamount;
                rangecomm.Com_in_per = extracommtextCommision;
                rangecomm.statuss = false;
                db.Range_wise_extra_commission.Add(rangecomm);
                db.SaveChanges();

            }
            NillPortalViewmodel vmodel = new NillPortalViewmodel();
            vmodel.rangewisecomm_report = db.range_wise_comm_Report("ALL");
            return PartialView("_ExtraCommision_report", vmodel);
        }
