        private void UserInformationlist(string userwise, ref List<Common_status_master_dlm_cls> listview)
        {
            if (userwise == "master")
            {


                var userssmaster = (from tbl in db.Superstokist_details
                                    join tbl1 in db.Commision_status_master_dlm on tbl.SSId equals tbl1.userid
                                    where tbl1.Roles == "master"
                                    select new
                                    {
                                        tbl1,
                                        FarmName = tbl.FarmName,
                                        Name = tbl.SuperstokistName,
                                        Mobile = tbl.Mobile,
                                        userid = tbl.SSId,

                                    });


                foreach (var item in userssmaster)
                {
                    Common_status_master_dlm_cls model = new Common_status_master_dlm_cls();
                    model.Frmname = item.FarmName;
                    model.Name = item.Name;
                    model.mobile = item.Mobile;
                    model.Userid = item.userid;
                    model.Comm_Status = item.tbl1.Current_status;
                    model.Role = item.tbl1.Roles;
                    model.updatetime = item.tbl1.updtime.Value;
                    model.idno = item.tbl1.idno;
                    listview.Add(model);
                }

            }
            else if (userwise == "dealer")
            {


                // var  userssmaster = db.Dealer_Details.ToList();


                var userssmaster = (from tbl in db.Dealer_Details
                                    join tbl1 in db.Commision_status_master_dlm on tbl.DealerId equals tbl1.userid
                                    where tbl1.Roles == "dealer"
                                    select new
                                    {
                                        tbl1,
                                        FarmName = tbl.FarmName,
                                        Name = tbl.DealerName,
                                        Mobile = tbl.Mobile,
                                        userid = tbl.SSId,

                                    });



                foreach (var item in userssmaster)
                {
                    Common_status_master_dlm_cls model = new Common_status_master_dlm_cls();
                    model.Frmname = item.FarmName;
                    model.Name = item.Name;
                    model.mobile = item.Mobile;
                    model.Userid = item.userid;
                    model.Comm_Status = item.tbl1.Current_status;
                    model.Role = item.tbl1.Roles;
                    model.updatetime = item.tbl1.updtime.Value;
                    model.idno = item.tbl1.idno;
                    listview.Add(model);
                }

            }
        }

