        public ActionResult Desktop_popupimage()
        {
            try
            {
                string url = Request.Url.AbsoluteUri;
                var imageurl = (from hh in db.message_popup select hh.imageurl).FirstOrDefault() ?? "";
                var headercontent = (from hh in db.message_popup select hh.Heardercontent).FirstOrDefault() ?? "";
                var sts = (from hh in db.message_popup select hh.sts).FirstOrDefault() ?? "N";
                if (sts == "Y")
                {
                    sts = "OPEN";
                }
                else
                {
                    sts = "CLOSE";
                }
                ViewData["but"] = sts;
                ViewBag.ImageURL = imageurl;
                ViewBag.headercontent = headercontent;
                return View();
            }
            catch
            {
                return View();
            }
        }
        [HttpPost]
        public ActionResult Desktop_popupimage(HttpPostedFileBase file, string headercontent)
        {
            try
            {
                WebImage photo = null;
                var newFileName = "";
                var imagePath = "";
                var imageThumbPath = "";


                if (Request.HttpMethod == "POST")
                {
                    photo = WebImage.GetImageFromRequest();
                    if (photo != null)
                    {
                        newFileName = Guid.NewGuid().ToString() + "_" +
                            Path.GetFileName(photo.FileName);
                        newFileName = Regex.Replace(newFileName, "[^a-zA-Z0-9_.]+", "", RegexOptions.Compiled);
                        imagePath = @"\Desktoppopupimg\" + newFileName;
                        //photo.Save(@"~\" + imagePath);

                        imageThumbPath = @"\Desktoppopupimg\" + newFileName;

                        photo.Resize(1267, 532, false, true);


                        //preventEnlarge: true);

                        photo.Save(@"~\" + imageThumbPath);
                        db.insert_msg_popup(imageThumbPath, headercontent);
                        ViewBag.ImageURL = imageThumbPath;
                    }
                }

                TempData["add"] = "Uploaded successfully.";
            }
            catch
            {
                ViewBag.Message = "Error while uploading the files.";
                return View();
            }
            return View();
        }

        //Update Desktop poppup
        public ActionResult Update_desktopsts(string sts)
        {
            try
            {
                var hj = (db.message_popup.Where(a => a.sts == sts)).Single().sts;
                if (hj == "Y")
                {
                    hj = "N";
                }
                else
                {
                    hj = "Y";
                }
                message_popup objCourse = (from p in db.message_popup select p).SingleOrDefault();
