        public ActionResult Delete_desktopsts()
        {
            var chk = db.message_popup.SingleOrDefault();
            if (chk != null)
            {
                string path = Server.MapPath("~/" + chk.imageurl);
                if (System.IO.File.Exists(path))
                {
                    System.IO.File.Delete(path);
                }
                db.message_popup.Remove(chk);
                db.SaveChanges();
            }
            return RedirectToAction("Notification");
        }
