        [HttpPost]
        public ActionResult Api_Operator(string apinm, string txtidno, string txtapinm, string txtoptnm, string txtapiopt, string txtpurcharge, string purchasetype, string[] myCategories)
        {
            if (!string.IsNullOrWhiteSpace(txtidno))
            {
                db.SRS_update_api(Convert.ToInt32(txtidno), txtapinm, "", "", txtapiopt, Convert.ToDecimal(txtpurcharge), 0, 0, purchasetype);
            }
            if (apinm == "")
            {
                apinm = "Y";
            }

            //var ch = db.select_api_info(apinm);
            var query = (from o in db.api_name select o).Distinct().OrderBy(x => x.apiname);
            ViewBag.apinm = new SelectList(query, "apiname", "apiname", null);
            TempData["edit"] = "Update Successfully.";

            IEnumerable<SelectListItem> ldidList = db.Operator_Code.Select(c => new SelectListItem
            {
                Value = c.Operator_type,
                Text = c.Operator_type
            }).Distinct();
            ViewBag.OptCategories = ldidList.Where(a => a.Text == "Broadband" || a.Text == "Electricity" || a.Text == "Gas" || a.Text == "Insurance" || a.Text == "Landline" || a.Text == "Loan" || a.Text == "LPG Gas" || a.Text == "Fastag" || a.Text == "Water"
              || a.Text == "PrePaid" || a.Text == "DTH" || a.Text == "PostPaid" || a.Text == "Bus" || a.Text == "CMSFINO" || a.Text == "DigitalVoucher" || a.Text == "DTH-Booking" || a.Text == "Flight" || a.Text == "Hotel" || a.Text == "Money" || a.Text == "PAN");
            List<select_api_info_Test_Result> firstlist = new List<select_api_info_Test_Result>();
            if ((myCategories != null) && (apinm != null || apinm != ""))
            {
                dynamic ch = (object)null;

                foreach (var item in myCategories)
                {
                    ch = db.select_api_info_Test(apinm, item).ToList();
                    firstlist.AddRange(ch);
                }
            }
            else
            {
                var ch1 = db.select_api_info_Test(apinm, "").ToList();
                firstlist.AddRange(ch1);
            }
            var chList = firstlist.DistinctBy(a => a.opt_code).ToList();
            return View(chList);
        }
        [HttpGet]
        public ActionResult Api_Status(string id, string apinm)
        {
            var value = apinm;
            if (apinm == null)
            {
                value = "Y";
            }
            else
            {
                value = apinm;
                if (id != null)
                {
                    int idno = Convert.ToInt32(id);
                    //db.srs_api_blo_unblok(idno);
                    var status = db.SRS_API.Where(x => x.id == idno).SingleOrDefault();
                    if (status != null)
                    {
                        if (status.status == "Y")
                        {
                            status.status = "N";
                            db.SaveChanges();
                        }
                        else
                        {
                            status.status = "Y";
                            db.SaveChanges();
                        }
                    }
                }
            }
            TempData["apinm"] = value;
            return RedirectToAction("Api_Operator");
        }
