        public ActionResult Remllist(string dealerid)
        {

            var chk1 = db.Retailer_Details.Where(s => s.DealerId == dealerid).ToList();
            var chk2 = db.rang_of_imps_transaction_dealer.Where(s => s.Dealer_id == dealerid).ToList();
            var chk3 = db.Dealer_Details.Where(s => s.DealerId == dealerid).ToList();
            string[] set = new string[chk1.Count()];
            string[] set1 = new string[chk1.Count()];
            string[] set2 = new string[chk1.Count()];

            for (int i = 0; i < chk1.Count(); i++)
            {
                set[i] = chk1[i].Frm_Name;
                set1[i] = chk1[i].Email;
                set2[i] = chk1[i].RetailerId;
            }
            var responseData = new
            {
                Frm_Names = set,
                Emails = set1,
                retailerids = set2,
                dealedetails = chk2,
                dealerEMail = chk3[0].Email,
                dealerFarm = chk3[0].FarmName
            };

            return Json(responseData, JsonRequestBehavior.AllowGet);


        }
