        public ActionResult savedataodrangewish(string Uid, int? insmin, int? insmax, int Razmin, int Razmax, string Role)
        {
            var message = "";
            try
            {
                bool? instantpayallow = db.Serviceallows.Where(aa => aa.ServiceName == "InstantPayPayOut").SingleOrDefault().Sts;
                bool? razorpayallow = db.Serviceallows.Where(aa => aa.ServiceName == "RazorpayUPI").SingleOrDefault().Sts;
                if (Role == "Retailer")
                {
                    var chk3 = db.rang_of_imps_transaction_retailer.Where(s => s.retailer_id == Uid).ToList();
                    chk3[0].vastbazzar_min = 0;
                    chk3[0].vastbazzar_max = 0;
                    if (instantpayallow == true)
                    {
                        chk3[0].instatntpay_min = insmin;
                        chk3[0].instatntpay_max = insmax;
                    }
                    if (razorpayallow == true)
                    {
                        chk3[0].Razorpay_min = Razmin;
                        chk3[0].razorpay_max = Razmax;
                    }
                    db.SaveChanges();
                    message = "Done";
                }
                else if (Role == "ALL")
                {
                    var chk4 = db.rang_of_imps_transaction_ALL_retailer.ToList();
                    chk4[0].vastbazzar_min = 0;
                    chk4[0].vastbazzar_max = 0;
                    if (instantpayallow == true)
                    {
                        chk4[0].instatntpay_min = insmin;
                        chk4[0].instatntpay_max = insmax;
                    }
                    if (razorpayallow == true)
                    {
                        chk4[0].Razorpay_min = Razmin;
                        chk4[0].razorpay_max = Razmax;
                    }
                    db.SaveChanges();

                    var chk6 = db.rang_of_imps_transaction_retailer.ToList();

                    foreach (var i in chk6)
                    {
                        var chk8 = db.rang_of_imps_transaction_retailer.Where(s => s.retailer_id == i.retailer_id).FirstOrDefault();
                        chk8.vastbazzar_min = 0;
                        chk8.vastbazzar_max = 0;
                        if (instantpayallow == true)
                        {
                            chk8.instatntpay_min = insmin;
                            chk8.instatntpay_max = insmax;
                        }
                        if (razorpayallow == true)
                        {
                            chk8.Razorpay_min = Razmin;
                            chk8.razorpay_max = Razmax;
                        }
                        db.SaveChanges();

                    }
                    message = "Done";
                }
                else
                {
                    message = "No";
                }

            }
            catch
            {
                message = "No";

            }

            return Json(message, JsonRequestBehavior.AllowGet);


        }

        [HttpPost]
        public ActionResult Add_MoneyApiUrls(string txtapiname, string apiid, string pwd, string tkn, string tkn1, string tkn2, string tokenpriority)
        {
            Money_API_URLS obj = new Money_API_URLS();

            money_api_status d2 = new money_api_status();
            if (!string.IsNullOrEmpty(txtapiname))
            {
                bool exists = db.Money_API_URLS.Any(t => t.API_Name == txtapiname);
                if (exists == false)
                {
                    using (VastwebmultiEntities db = new VastwebmultiEntities())
                    {
                        //insert into money_Api_URL Table
                        obj.API_Name = txtapiname;
                        obj.API_ID = apiid;
                        obj.Api_pwd = pwd;
                        obj.Token = tkn;
                        obj.token1 = tkn1;
                        obj.token2 = tkn2;
                        obj.tokenpriority = tokenpriority;
                        obj.Status = "Y";
                        db.Money_API_URLS.Add(obj);
                        db.SaveChanges();

                        string[] catag = { "DMT", "PAYOUT", "ACCOUNT VERIFY" };

                        for (int i = 0; i <3; i++)
                        {
                            d2.api_name = txtapiname;
                            d2.catagory = catag[i];
                            d2.status = false;
                            db.money_api_status.Add(d2);
                            db.SaveChanges();
                        }




                        TempData["edit"] = "Insert Successfully.";
                        var ch = db.show_ALL_DMT_info(txtapiname).ToList();
                        return RedirectToAction("MoneyApiUrls");
                    }
                }
                else
                {
                    TempData["error"] = "Api Name Allready Exits.";
                    return RedirectToAction("MoneyApiUrls");
                }

            }
            else
            {
                TempData["error"] = "Please Select API Name";
                return RedirectToAction("MoneyApiUrls");
            }
            return RedirectToAction("MoneyApiUrls");

        }

