        [HttpPost]
        public ActionResult insert_cyber(string sdcode, string apcode, string opcode, string password, string cert, string dealercode, HttpPostedFileBase file)
        {
            if (file != null)
                try
                {
                    var supportedTypes = new[] { "pfx" };
                    var fileExt = System.IO.Path.GetExtension(file.FileName).Substring(1);
                    if (!supportedTypes.Contains(fileExt))
                    {
                        TempData["file"] = "File Extension Is InValid - Only Upload pfx File";
                    }
                    else
                    {
                        string path = Path.Combine(Server.MapPath("~/CERT/"),
                    Path.GetFileName(file.FileName));
                        string pathchk = Path.Combine(Server.MapPath("~/CERT/"));
                        string[] filePaths = Directory.GetFiles(pathchk);
                        foreach (string filePath in filePaths)
                            System.IO.File.Delete(filePath);

                        file.SaveAs(path);
                        int count = (db.cyberplate_info.Select(aa => aa.keypath)).Count();
                        if (count == 0)
                        {
                            cyberplate_info objCourse = new cyberplate_info();
                            objCourse.apcode = apcode;
                            objCourse.opcode = opcode;
                            objCourse.sdcode = sdcode;
                            objCourse.password = password;
                            objCourse.certcode = cert;
                            objCourse.dealercode = dealercode;
                            objCourse.keypath = file.FileName;

                            db.cyberplate_info.Add(objCourse);
                            db.SaveChanges();
                            TempData["add"] = "File Upload successfully";
                        }
                        else
                        {
                            TempData["allready"] = "Only One File Upload";
                        }

                    }

                }
                catch (Exception ex)
                {

                }
            return RedirectToAction("cyberplate_details");
        }

        public ActionResult Edit_cyber(string txtsdcode, int txtid, string txtapcode, string txtopcode, string txtcertcode, string txtpasswordcode, string txtdcode, HttpPostedFileBase file)
        {
            string keypath = "";
            if (file != null)
            {
                var supportedTypes = new[] { "pfx" };
                var fileExt = System.IO.Path.GetExtension(file.FileName).Substring(1);
                if (!supportedTypes.Contains(fileExt))
                {
                    TempData["file"] = "File Extension Is InValid - Only Upload pfx File";
                }
                else
                {
                    string path = Path.Combine(Server.MapPath("~/CERT/"),
                    Path.GetFileName(file.FileName));
                    string pathchk = Path.Combine(Server.MapPath("~/CERT/"));
                    string[] filePaths = Directory.GetFiles(pathchk);
                    foreach (string filePath in filePaths)
                        System.IO.File.Delete(filePath);
                    file.SaveAs(path);
                    keypath = file.FileName;
                    Vastwebmulti.Models.cyberplate_info objCourse = (from p in db.cyberplate_info
                                                                     where p.idnno == txtid
                                                                     select p).SingleOrDefault();
                    objCourse.apcode = txtapcode;
                    objCourse.opcode = txtopcode;
                    objCourse.sdcode = txtsdcode;
                    objCourse.certcode = txtcertcode;
                    objCourse.password = txtpasswordcode;
                    objCourse.dealercode = txtdcode;
                    objCourse.keypath = keypath;
                    db.SaveChanges();
                    TempData["add"] = "Edit Upload SuccessFully.";
                }
            }
            else
            {
                keypath = (db.cyberplate_info.Where(aa => aa.idnno == txtid)).SingleOrDefault().keypath;
                Vastwebmulti.Models.cyberplate_info objCourse = (from p in db.cyberplate_info
                                                                 where p.idnno == txtid
                                                                 select p).SingleOrDefault();
                objCourse.apcode = txtapcode;
                objCourse.opcode = txtopcode;
                objCourse.sdcode = txtsdcode;
                objCourse.certcode = txtcertcode;
                objCourse.password = txtpasswordcode;
                objCourse.dealercode = txtdcode;
                objCourse.keypath = keypath;
                db.SaveChanges();
                TempData["add"] = "Edit Upload SuccessFully.";
            }
            return RedirectToAction("cyberplate_details");
        }

