        public object Delete_Recharge_Api(int id)
        {
            JObject obj = new JObject();
            try
            {
                var api = db.RechargeapiInfoes.Single(s => s.id == id);

                var all_api = db.api_name.Where(s => s.apiname == api.apiname).SingleOrDefault();
                db.RechargeapiInfoes.Remove(api);
                db.SaveChanges();

                if (all_api != null)
                {
                    db.delete_apinm(all_api.idno);
                }

                obj.Add("status", true);
            }
            catch (Exception ex)
            {
                obj.Add("status", false);
                obj.Add("message", ex.Message);
            }

            return obj;
        }

