        public ActionResult ApiResponseInsert(int apiinfo, string restype, string addKeyRequestid, string addKeyStatus,
    string addKeyOptID, string addKeymsg, string KeyRemainBal, string ValStatusSucess, string ValStatusFailed,
    string ValStatusPending, string sapratewith, string Keyerror, string KeyerrorMessage, string valerror,
    string valerrorMessage, string uniqueid, string otp)
        {
            var userid = User.Identity.GetUserId();
            var otp_matched = db.MobileOtps.Any(s => s.Userid == userid && s.Type == "RechargeApiInsert" && s.Otp == otp && s.mobileno == uniqueid);
            if (otp_matched)
            {
                var chk = db.rechargeapiresponses.Where(aa => aa.id == apiinfo).SingleOrDefault();
                if (chk == null)
                {
                    rechargeapirespons rch = new rechargeapirespons();
                    rch.id = apiinfo;
                    rch.Keyerror = Keyerror;
                    rch.KeyerrorMessage = KeyerrorMessage;
                    rch.KeyMsg = addKeymsg;
                    rch.KeyOptID = addKeyOptID;
                    rch.KeyRemainBal = KeyRemainBal;
                    rch.KeyRequestid = addKeyRequestid;
                    rch.KeyStatus = addKeyStatus;
                    rch.Resptype = restype;
                    rch.sapratewith = sapratewith;
                    rch.valerror = valerror;
                    rch.valerrorMessage = valerrorMessage;
                    rch.ValStatusFailed = ValStatusFailed;
                    rch.ValStatusPending = ValStatusPending;
                    rch.ValStatusSucess = ValStatusSucess;
                    rch.ip_address = GetComputer_InternetIP();
                    rch.update_time = DateTime.Now.ToString();
