        }

        public object ApiResponseInsert_SendOtp(string type)
        {
            JObject obj = new JObject();

            try
            {
                string uniqueid = DateTime.Parse(DateTime.Now.ToString()).ToString("yyMMddHHmmss") + RandomString(4);
                var userid = User.Identity.GetUserId();

                bool includeLowercase = false;
                bool includeUppercase = false;
                bool includeNumeric = true;
                bool includeSpecial = false;
                bool includeSpaces = false;
                int lengthOfPassword = 4;

                string pingen = PasswordGenerator.GeneratePassword(includeLowercase, includeUppercase, includeNumeric, includeSpecial, includeSpaces, lengthOfPassword);

                while (!PasswordGenerator.PasswordIsValid(includeLowercase, includeUppercase, includeNumeric, includeSpecial, includeSpaces, pingen))
                {
                    pingen = PasswordGenerator.GeneratePassword(includeLowercase, includeUppercase, includeNumeric, includeSpecial, includeSpaces, lengthOfPassword);
                }

                MobileOtp mo = new MobileOtp();
                mo.Userid = userid;
                mo.Type = type;
                mo.Otp = pingen;
                mo.Date = DateTime.Now;
                mo.mobileno = uniqueid;
                db.MobileOtps.Add(mo);
                db.SaveChanges();


                var admin = db.Admin_details.Single();
                var email = admin.email;
                var AdminMailId = admin.email1;

                smssend.SendEmailAll(email, "Recharge Api Otp is  " + pingen, "Recharge Api Insert", AdminMailId);

                obj.Add("status", true);
                obj.Add("uniqueid", uniqueid);
                obj.Add("message", "Otp sent successfully");

            }
            catch (Exception ex)
            {
                obj.Add("status", false);
                obj.Add("message", ex.Message);
            }

            return obj;
        }

