        //GET : SMS API Details
        public ActionResult SMSAPI()
        {

            string strtemp = Convert.ToString(TempData["data"]);
            if (string.IsNullOrEmpty(strtemp))
            {
                TempData["actiontype"] = "SMSAPI";
                return PartialView("Trans_highsecurity_Setting");
            }


            SMSViewModel vmodel = new SMSViewModel();

            using (VastwebmultiEntities db = new VastwebmultiEntities())
            {
                var userid = User.Identity.GetUserId();
                vmodel.apismslist_all = (from cust in db.apisms
                                         where (cust.userfor == userid)
                                         select new apismslist1
                                         {
                                             id = cust.id,
                                             smsapi = cust.smsapi,
                                             sts = cust.sts,
                                             smsremainapi = cust.smsremainapi,
                                             api_type = cust.api_type
                                         }).ToList();
                vmodel.SMS_PriorityList = db.SMS_Priority.ToList();
                string txt_frm_date = DateTime.Now.ToString();
                string txt_to_date = DateTime.Now.ToString();
                DateTime frm_date = Convert.ToDateTime(txt_frm_date).Date;
                DateTime to_date = Convert.ToDateTime(txt_to_date).Date.AddDays(1);
                vmodel.srs_show_sent_message_Result_List = db.srs_show_sent_message(frm_date, to_date, "NA").ToList();

                vmodel.sms_api_entryList = db.sms_api_entry.Where(aa => aa.m_date >= frm_date && aa.m_date <= to_date).OrderByDescending(aa => aa.idno).ToList();

                var smstemps = db.apisms.ToList();
                List<SelectListItem> listofitem = new List<SelectListItem>();
                foreach (var items in db.apisms.ToList())
                {
                    //var apiname = items.smsapi;
                    var apiname = items.smsapi.Substring(0, items.smsapi.IndexOf("?"));
                    listofitem.Add(new SelectListItem { Text = apiname.ToString(), Value = items.id.ToString() });

                }
                ViewBag.spsmsmmmsdsd = listofitem;

            }
