        public ActionResult SMSAPISTSetting(int id)
        {
            var sms_api = db.apisms.Where(s => s.id == id).Single();
            if (sms_api.sts == "Y")
            {
                sms_api.sts = "N";
            }
            else
            {
                bool isalreadyon = db.apisms.Any(s => s.id != id && s.api_type == sms_api.api_type && s.sts == "Y");
                if (isalreadyon == false) sms_api.sts = "Y";
            }
            db.SaveChanges();

            var userid = User.Identity.GetUserId();

            SMSViewModel ch = new SMSViewModel();
            ch.apismslist_all = (from cust in db.apisms
