            try
            {
                var userid = User.Identity.GetUserId();
                int i = 1;

                if (!string.IsNullOrEmpty(Userform1))
                {

                    if (Userform1 == "Master")
                    {
                        var usermobiles = db.Superstokist_details.ToList();
                        foreach (var item in usermobiles)
                        {
                            if (i % 5 == 0)
                            {
                                Thread.Sleep(1500);
                            }
                            i++;
                            smssend.sms_init("Y", "Y", "ManualSMS", item.Mobile, txtMsgBody);
                        }
