                        {
                            if (i % 5 == 0)
                            {
                                Thread.Sleep(1500);
                            }
                            i++;
                            smssend.sms_init("Y", "Y", "ManualSMS", item.Mobile, txtMsgBody);
                        }
                    }
                    else if (Userform1 == "API")
                    {
                        var usermobiles = db.api_user_details.ToList();
                        foreach (var item in usermobiles)
                        {
                            if (i % 5 == 0)
                            {
                                Thread.Sleep(1500);
                            }
                            i++;
                            smssend.sms_init("Y", "Y", "ManualSMS", item.mobile, txtMsgBody);
                        }
                    }
                    else if (Userform1 == "Whitelabel")
                    {
                        var usermobiles = db.WhiteLabel_userList.ToList();
                        foreach (var item in usermobiles)
                        {
                            if (i % 5 == 0)
                            {
                                Thread.Sleep(1500);
                            }
                            i++;
                            smssend.sms_init("Y", "Y", "ManualSMS", item.Mobile, txtMsgBody);
                        }
                    }
                }
                else
                {
                    smssend.sms_init("Y", "Y", "ManualSMS", txtmobileNo, txtMsgBody);
                }
            }
            catch
            {
                //  return RedirectToAction("Send_SMS");
