        [HttpPost]
        public ActionResult Send_Notification(string Userform1, string txtUserid, string txtMsgBody)
        {
            try
            {
                var statusRetailer = db.PushNotificationStatus.Where(a => a.UserRole == "Retailer").SingleOrDefault().Status;
                var statusMaster = db.PushNotificationStatus.Where(a => a.UserRole == "Master").SingleOrDefault().Status;
                var statusDealer = db.PushNotificationStatus.Where(a => a.UserRole == "Distributor").SingleOrDefault().Status;
                var statusApi = db.PushNotificationStatus.Where(a => a.UserRole == "ApiUser").SingleOrDefault().Status;
                string s = "";
                if (!string.IsNullOrEmpty(Userform1))
                {
                    if (Userform1 == "Indivisual")
                    {
                        var Userid = db.Users.Where(a => a.Email == txtUserid).SingleOrDefault().UserId;
                        if (Userid == null || Userid == "")
                        {
                            return RedirectToAction("Notification");
                        }
                        else
                        {
                            //notify.sendmessage(Userid, txtMsgBody);
                            var RoleId = db.UserRoles.Where(a => a.UserId == Userid).SingleOrDefault().RoleId;
                            var Role = db.Roles.Where(a => a.RoleId == RoleId).SingleOrDefault().Name;
                            if (Role == "Retailer")
                            {
                                notify.sendmessage(txtUserid, txtMsgBody);
                                if (statusRetailer == "Y")
