        [HttpPost]
        public ActionResult HolidayAdd(string date, string desc, string holydayimages)
        {
            CultureInfo culture = new CultureInfo("en-US");
            DateTime tempDate = Convert.ToDateTime(date, culture);


            var chk = db.tbl_Holiday.Where(aa => aa.HolidayDate == tempDate).SingleOrDefault();
            if (chk == null)
            {
                var request = HttpContext.Request;
                var baseUrl = $"{request.Url.Scheme}://{request.Url.Authority}{request.ApplicationPath.TrimEnd('/')}/";
                tbl_Holiday tbl = new tbl_Holiday();
                tbl.HolidayDate = tempDate;
                tbl.HolidayName = desc;
                tbl.isAepsBlocked = false;
                tbl.isMposBlocked = false;
                tbl.images = baseUrl+holydayimages;
                db.tbl_Holiday.Add(tbl);
                db.SaveChanges();
            }

            return Json("", JsonRequestBehavior.AllowGet);
        }
        public ActionResult Deleteholiday(DateTime date)
        {
            var chk = db.tbl_Holiday.Where(aa => aa.HolidayDate == date).SingleOrDefault();
            db.tbl_Holiday.Remove(chk);
            db.SaveChanges();
            return Json("", JsonRequestBehavior.AllowGet);
        }
        public ActionResult Updateholiday(string type, DateTime date)
        {
            bool updateaeps = true; bool updatempos = true;
            var chk = db.tbl_Holiday.Where(aa => aa.HolidayDate == date).SingleOrDefault();
            bool aepssts = chk.isAepsBlocked;
            bool mpossts = chk.isMposBlocked;
            if (type == "AEPS")
            {
                if (aepssts == true)
                {
                    updateaeps = false;
                }
                chk.isAepsBlocked = updateaeps;
                db.SaveChanges();
            }
            else
            {
                if (mpossts == true)
                {
                    updatempos = false;
                }
                chk.isMposBlocked = updatempos;
                db.SaveChanges();
            }
            return Json("", JsonRequestBehavior.AllowGet);
        }


