        //pancard Verifiy Status
        public ActionResult Pancardsts(string Retailerid, string status)
        {
            try
            {
                switch (status)
                {

                    case "Verify":
                        var chk = db.Retailer_Details.Any(a => a.RetailerId == Retailerid && a.pancardPath != null && a.aadharcardPath != null);
                        if (chk == true)
                        {
                            Retailer_Details obj = (from p in db.Retailer_Details
                                                    where p.RetailerId == Retailerid
                                                    select p).SingleOrDefault();
                            obj.PSAStatus = "Y";
                            db.SaveChanges();
                            TempData["success"] = "Profile Kyc Verify Successfully";
                            return RedirectToAction("ProfileKYC");
                        }
                        else
                        {
                            TempData["error"] = "Please Complete Profile Kyc Information";
                            return RedirectToAction("ProfileKYC");
                        }
                    case "Rejected":

                        Retailer_Details obj1 = (from p in db.Retailer_Details
                                                 where p.RetailerId == Retailerid
                                                 select p).SingleOrDefault();
                        obj1.pancardPath = null;
                        obj1.PSAStatus = "P";
                        db.SaveChanges();
                        TempData["error"] = "Pancard Card Kyc Document Rejected Successfully";
                        return RedirectToAction("ProfileKYC");

                    default:
                        return RedirectToAction("ProfileKYC");
                }
            }
            catch
            {

            }
            return RedirectToAction("ProfileKYC");

        }

