        public List<fino_Report_paging_Result> getFinoReport(DateTime? from = null, DateTime? to = null, string userid = "", string status = "", string number = "", int pageNumber = 1, int rowPerPage = 100000)
        {
            if (String.IsNullOrWhiteSpace(userid)) userid = "";
            if (status != "" && status.ToUpper() != "SUCCESS" && status.ToUpper() != "FAILED" && status.ToUpper() != "PENDING")
            {
                status = "";
            }
            if (String.IsNullOrWhiteSpace(number)) number = "";

            if (from == null || to == null)
            {
                from = DateTime.Now.AddDays(-1);
                to = DateTime.Now.AddDays(1);
            }
            else
            {
                to = DateTime.Parse(to.ToString()).AddDays(1);
            }

            return db.fino_Report_paging("Admin", userid, status, number, pageNumber, rowPerPage, from, to).ToList();
        }

