        public ActionResult updateotpsetting()
        {
            var sts = db.Email_show_passcode.SingleOrDefault();
            if (sts.forgetotp == true)
            {
                sts.forgetotp = false;

            }
            else
            {
                sts.forgetotp = true;
            }
            db.SaveChanges();
            TempData["data"] = "11";
            return RedirectToAction("WebLogin");
        }
        public ActionResult WebLogin()
        {
            var sts = db.Email_show_passcode.SingleOrDefault();


            if (sts.forgetotp == true)
            {
                Session["yes"] = "ON";
            }
            else
            {
                Session["yes"] = "OFF";
            }

            string strtemp = Convert.ToString(TempData["data"]);
            if (string.IsNullOrEmpty(strtemp))
            {
                TempData["actiontype"] = "WebLogin";
                return PartialView("Trans_highsecurity_Setting");
            }
            DateTime txt_frm_date = DateTime.Now.Date;
            DateTime txt_to_date = DateTime.Now;
            var Login_details = (db.Login_info.Where(aa => aa.CurrentLoginTime >= txt_frm_date && aa.CurrentLoginTime <= txt_to_date && aa.LoginFrom == "Web").Take(100).OrderByDescending(aa => aa.Idno)).ToList();
            ViewBag.setting = db.security_settings.ToList();
            BlockUserViewModel vmoel = new BlockUserViewModel();
            vmoel.userslist = db.Users.Where(a => a.LockoutEndDateUtc >= txt_frm_date && a.LockoutEndDateUtc <= txt_to_date).ToList();
            vmoel.WLoginHistory = db.login_history("Admin", "", "", txt_frm_date, txt_to_date).ToList();
            vmoel.Apploginhistory = db.Failed_login_history("Admin", "", "", txt_frm_date, txt_to_date).ToList();
            return View(vmoel);
        }
        [HttpPost]
        public ActionResult WebLoginFilter(DateTime? txtAPP_frm_date, DateTime? txt_APPto_date, string ddlRoleName, string ddlfirmname, string ddlType)
        {
            var sts = db.Email_show_passcode.SingleOrDefault();


            if (sts.forgetotp == true)
            {
                Session["yes"] = "ON";
            }
            else
            {
                Session["yes"] = "OFF";
            }


            DateTime txt_APPto_date1 = txt_APPto_date.Value.AddDays(1);
            BlockUserViewModel vmoel = new BlockUserViewModel();
            vmoel.WLoginHistory = db.login_history(ddlRoleName, ddlfirmname, ddlType, txtAPP_frm_date, txt_APPto_date1).ToList();
            return PartialView("_WebLoginHistory", vmoel);
        }
        public ActionResult APPLoginFilter(DateTime? txt_APPfrm_date, string ddlAppRoleName, string ddlAppfirmname, string ddlType1)
        {
            BlockUserViewModel vmode = new BlockUserViewModel();
            DateTime to_date = Convert.ToDateTime(txt_APPfrm_date).Date.AddDays(1);
            vmode.Apploginhistory = db.Failed_login_history(ddlAppRoleName, ddlAppfirmname, ddlType1, txt_APPfrm_date, to_date).ToList();
            return PartialView("_Apploginhistory", vmode);
        }

