        [HttpPost]
        public JsonResult ChangeSignupKYCSetting(string type)
        {
            try
            {
                var validTypes = new[] { "ZERO", "DIGITAL", "PHYSICAL", "DIGITAL_PHYSICAL" };

                if (string.IsNullOrEmpty(type) || !validTypes.Contains(type))
                {
                    return Json(new { Status = false, Message = "Invalid KYC Type." });
                }

                var allTypes = db.SignupKYCSettings.ToList();
                var selected = allTypes.FirstOrDefault(x => x.KYCType == type);

                if (selected == null)
                {
                    return Json(new { Status = false, Message = "KYC Type not found in setting." });
                }

                foreach (var item in allTypes)
                {
                    item.IsActive = (item.KYCType == type);
                }

                db.SaveChanges();

                return Json(new
                {
                    Status = true,
                    Message = selected.DisplayName + " Set As Active KYC Type.",
                    type = selected.KYCType,
                    DisplayName = selected.DisplayName
                });
            }
            catch (Exception ex)
            {
                return Json(new { Status = false, Message = ex.Message });
            }
        }

        public JsonResult Insert_IPaddressdata(string txtIPADDRESS, string txthighsecuritypwd, string btnnamekonsa)
        {
            var userid = User.Identity.GetUserId();
            var chktranss = db.admin_new_pass.SingleOrDefault();
            DateTime currenttime = DateTime.Now;
            DateTime lastchangedpassdtr = Convert.ToDateTime(chktranss.lastupdatesec);
            lastchangedpassdtr = lastchangedpassdtr.AddDays(Convert.ToInt32(chktranss.secexpdays));
            var defaultht = Decrypt(chktranss.securitypass);
            if (defaultht == "1111" || (lastchangedpassdtr <= currenttime))
            {
                return Json(new { status = "Failed", msg = "Your security pin is expired or have to be changed!! Please set new security pin" }, JsonRequestBehavior.AllowGet);
            }
            JObject response = new JObject();
            if (btnnamekonsa == "Confirm")
            {
                var password = Encrypt(txthighsecuritypwd);
                var tranpass = (from paa in db.admin_new_pass where paa.securitypass == password select paa).Count();
                if (tranpass > 0)
                {
                    var ipexist = db.ipadreesvalidates.Where(x => x.ipaddress == txtIPADDRESS).FirstOrDefault();
                    if (ipexist == null)
                    {
                        var count3ip = db.ipadreesvalidates.Count();
                        if (count3ip <= 3)
                        {
                            ipadreesvalidate tblss = new ipadreesvalidate();
                            tblss.ipaddress = txtIPADDRESS;
                            tblss.ipstatus = "Y";
                            db.ipadreesvalidates.Add(tblss);
                            db.SaveChanges();
                            //for logout from all devices web
                            UserManager.UpdateSecurityStamp(userid);

                            return Json(new { status = "Suceess", msg = "IP Set Successfully,Please refresh and login with same IP" }, JsonRequestBehavior.AllowGet);

                        }
                        else
                        {
                            return Json(new { status = "Failed", msg = "You can't set more than 4 IP" }, JsonRequestBehavior.AllowGet);
                        }
                    }

                }
                else
                {
                    return Json(new { status = "Failed", msg = "Wrong Security Password" }, JsonRequestBehavior.AllowGet);
                }
            }
            return Json(new { status = "Failed", msg = "Already Set" }, JsonRequestBehavior.AllowGet);
        }


