        public JsonResult IPaddressDelete(int ID, string highsecpass)
        {
            var chktranss = db.admin_new_pass.SingleOrDefault();
            DateTime currenttime = DateTime.Now;
            DateTime lastchangedpassdtr = Convert.ToDateTime(chktranss.lastupdatesec);
            lastchangedpassdtr = lastchangedpassdtr.AddDays(Convert.ToInt32(chktranss.secexpdays));
            var defaultht = Decrypt(chktranss.securitypass);
            if (defaultht == "1111" || (lastchangedpassdtr <= currenttime))
            {
                return Json(new { status = false, msg = "Your security pin is expired or have to be changed!! Please set new security pin" }, JsonRequestBehavior.AllowGet);
            }
            var password = Encrypt(highsecpass);
            var tranpass = (from paa in db.admin_new_pass where paa.securitypass == password select paa).Count();
            if (tranpass > 0)
            {
                var result = db.ipadreesvalidates.Find(ID);
                db.ipadreesvalidates.Remove(result);
                db.SaveChanges();
            }
            else
            {
                return Json(new { status = false, msg = "Wrong Security Password" }, JsonRequestBehavior.AllowGet);
            }
            return Json(new { status = true, msg = "IP Deleted Successfully" }, JsonRequestBehavior.AllowGet);
        }

