        public ActionResult Web_Login_PDF_History(DateTime? txt_frm_date, DateTime txt_APPto_date, string ddlRoleName, string ddlfirmname, string ddlType)
        {
            DateTime txt_APPto_date1 = txt_APPto_date.AddDays(1);
            BlockUserViewModel vmoel = new BlockUserViewModel();
            vmoel.Fromdatesearch = txt_frm_date.Value;
            vmoel.Todatesearch = txt_APPto_date1;
            vmoel.LoginSearchUserRole = ddlRoleName;
            vmoel.LoginType = ddlType;
            try
            {
                var retailerinform = db.Users.Where(x => x.Email == ddlfirmname).FirstOrDefault();
                if (retailerinform != null)
                {
                    vmoel.RegisteredMobile = retailerinform.PhoneNumber;
                    vmoel.searchEmailID = retailerinform.Email;
                    var reminformdata = db.Retailer_Details.Where(x => x.Email == ddlfirmname).SingleOrDefault();
                    if (reminformdata == null)
                    {
                        var dlminfo = db.Dealer_Details.Where(x => x.Email == ddlfirmname).SingleOrDefault();

                        if (dlminfo == null)
                        {
                            var masterinform = db.Superstokist_details.Where(x => x.Email == ddlfirmname).SingleOrDefault();
                            if (masterinform == null)
                            {
                                vmoel.searchfrmname = "";
                            }
                            else
                            {
                                vmoel.searchfrmname = masterinform.FarmName;
                            }
                        }
                        else
                        {
                            vmoel.searchfrmname = dlminfo.FarmName;
                        }
                    }
                    else
                    {
                        vmoel.searchfrmname = reminformdata.Frm_Name;
                    }

                    vmoel.CompanyURL = db.Admin_details.FirstOrDefault().WebsiteUrl;
                }
                else
                {
                    vmoel.RegisteredMobile = "";
                    vmoel.searchEmailID = "";
                    vmoel.searchfrmname = "";
                    vmoel.CompanyURL = "";
                }
            }
            catch (Exception ex)
            {
                vmoel.RegisteredMobile = "";
                vmoel.searchEmailID = "";
                vmoel.searchfrmname = "";
                vmoel.CompanyURL = "";
            }


            //  DateTime to_date = Convert.ToDateTime(txt_frm_date.Value).Date.AddDays(1);

            vmoel.WLoginHistory = db.login_history(ddlRoleName, ddlfirmname, ddlType, txt_frm_date, txt_APPto_date1).ToList();


            return new Rotativa.ViewAsPdf(vmoel);
            // return View(vmoel);
        }


        public ActionResult AttemptBlockFilter(DateTime? txt_Attemptfrm_date, string ddlAttemptRoleName, string ddlAttemptfirmname)
        {
            BlockUserViewModel vmode = new BlockUserViewModel();
            // DateTime frm_date = DateTime.Now.Date;
            DateTime to_date = Convert.ToDateTime(txt_Attemptfrm_date.Value).Date.AddDays(1);
            vmode.userslist = db.Users.Where(a => a.LockoutEndDateUtc >= txt_Attemptfrm_date.Value && a.LockoutEndDateUtc <= to_date).ToList();
            if (!string.IsNullOrEmpty(ddlAttemptRoleName))
            {
                if (!string.IsNullOrEmpty(ddlAttemptfirmname))
                {
                    vmode.userslist = vmode.userslist.Where(a => a.Email == ddlAttemptfirmname).ToList();
                }
                else
                {
                    if (ddlAttemptRoleName == "master")
                    {
                        var allusers = db.Superstokist_details.Select(x => x.SSId).ToList();
                        vmode.userslist = vmode.userslist.Where(x => allusers.Contains(x.UserId));
                    }
                    else if (ddlAttemptRoleName == "Dealer")
                    {
                        var allusers = db.Dealer_Details.Select(x => x.DealerId).ToList();
                        vmode.userslist = vmode.userslist.Where(x => allusers.Contains(x.UserId));
                    }
                    else if (ddlAttemptRoleName == "Retailer")
                    {
                        var allusers = db.Retailer_Details.Select(x => x.RetailerId).ToList();
                        vmode.userslist = vmode.userslist.Where(x => allusers.Contains(x.UserId));
                    }
                    else if (ddlAttemptRoleName == "Whitelabel")
                    {
                        var allusers = db.WhiteLabel_userList.Select(x => x.WhiteLabelID).ToList();
                        vmode.userslist = vmode.userslist.Where(x => allusers.Contains(x.UserId));
                    }
                    else if (ddlAttemptRoleName == "API")
                    {
                        var allusers = db.api_user_details.Select(x => x.apiid).ToList();
                        vmode.userslist = vmode.userslist.Where(x => allusers.Contains(x.UserId));
                    }
                }
            }
            else
            {
                vmode.userslist = db.Users.Where(a => a.LockoutEndDateUtc >= txt_Attemptfrm_date.Value && a.LockoutEndDateUtc <= to_date).ToList();
            }
            return PartialView("_AttemptBlockHistory", vmode);

        }




