        public ActionResult CallingLoginInformationOnlyCITY(string roles, string userid)
        {
            var getemailid = db.Users.Where(x => x.UserId == userid).FirstOrDefault().Email;

            var result = db.Login_info
            .Where(a => a.City != null && a.City != "" && a.UserId.ToUpper() == getemailid.ToUpper())//if you have any condition
            .Select(x => x.City.Trim()).Distinct().ToList();

            var havecityname = db.Manage_rem_Location_by_Admin.Where(x => x.userid == userid).Select(x => x.nameofcity.Trim()).ToList();


            return Json(new { cityname = result, remids = userid, havecityname = havecityname }, JsonRequestBehavior.AllowGet);
        }

        public ActionResult managelocationSaveEDITCITY(string hdidsss, string hdremuserid)
        {
            string[] splitstr = hdidsss.Split(',');
            var userdata = db.Users.Where(x => x.UserId == hdremuserid).SingleOrDefault().UserId;
            if (userdata != null)
            {
                var result = db.Manage_rem_Location_by_Admin.Where(x => x.userid == hdremuserid).ToList();
                if (result.Count() <= 3)
                {
                    if (result.Count > 0)
                    {
                        db.Manage_rem_Location_by_Admin.RemoveRange(result);
                        db.SaveChanges();
                    }
                    if (hdidsss.Count() > 0)
                    {
                        foreach (var item in splitstr)
                        {

                            Manage_rem_Location_by_Admin tbls = new Manage_rem_Location_by_Admin();

                            tbls.userid = userdata;
                            tbls.nameofcity = item.Trim();
                            db.Manage_rem_Location_by_Admin.Add(tbls);

                        }
                        db.SaveChanges();
                    }
                    return Json("Success", JsonRequestBehavior.AllowGet);
                }
            }
            return Json("Failed", JsonRequestBehavior.AllowGet);
        }

        public ActionResult ChangeSecuritySetting()
        {
            var result = db.security_settings.SingleOrDefault();
            bool? ravi = true;
            string labelsecurity = "Low";
            if (result.highsecurity == true)
            {
                ravi = false;
                labelsecurity = "High";

            }
            result.highsecurity = ravi;

            var stat = db.SaveChanges();
            var useremail = db.Admin_details.SingleOrDefault().email;
            smssend.SendEmailAll(useremail, "Your Security is " + labelsecurity, "Security Lavel", useremail);

            ViewBag.setting = db.security_settings.ToList();
            return PartialView("_SecurityStatus", ViewBag.setting);


