        public ActionResult Generate_Excel_Setting_SMS_TEMPLATE()
        {
            var result = GET_ALL_Template_list().OrderByDescending(x => x.idno);

            DataTable dataTbl = new DataTable();
            dataTbl.Columns.Add("SMS FOR", typeof(string));
            dataTbl.Columns.Add("Template", typeof(string));
            dataTbl.Columns.Add("Template ID", typeof(string));
            dataTbl.Columns.Add("SMS API", typeof(string));


            foreach (var item in result)
            {
                dataTbl.Rows.Add(item.SMS_TYPE, item.Templates, item.Templateid, item.SMSAPI);
            }

            var grid = new GridView();
            grid.DataSource = dataTbl;
            grid.DataBind();
            Response.ClearContent();
            Response.Buffer = true;
            Response.AddHeader("content-disposition", "attachment; filename=SMS_Template_Report.xls");
            Response.ContentType = "application/ms-excel";
            Response.Charset = "";
            StringWriter sw = new StringWriter();
            HtmlTextWriter htw = new HtmlTextWriter(sw);
            grid.RenderControl(htw);
            Response.Output.Write(sw.ToString());
            Response.Flush();
            Response.End();

            return View();


        }


        public ActionResult Save_SMS_Templates(int? ddlAPIfill, string idst, string txttemplate_id, string txttemplateformate)
        {

            var result = db.apisms.Where(x => x.id == ddlAPIfill.Value).SingleOrDefault();
            if (result != null)
            {
                var updtetbl = db.Sending_SMS_Templates.Where(x => x.SMSAPIID == result.id && x.SMS_TYPE == idst && x.Templateid == txttemplate_id).FirstOrDefault();
                if (updtetbl == null)
                {
                    Sending_SMS_Templates modeltbl = new Sending_SMS_Templates();
                    modeltbl.SMSAPIID = Convert.ToInt32(ddlAPIfill);
                    modeltbl.SMS_TYPE = idst;
                    modeltbl.Templateid = txttemplate_id;
                    modeltbl.Templates = txttemplateformate;
                    modeltbl.uplaodby = "manual";
                    modeltbl.templatedate = DateTime.Now;

                    db.Sending_SMS_Templates.Add(modeltbl);
                    db.SaveChanges();
                    //below table did not use anywhere. it is only for save templates..
                    var temprarytblnotuse = db.Send_sms_templist.Where(x => x.smstype == idst).FirstOrDefault();
                    if (temprarytblnotuse == null)
                    {
                        Send_sms_templist tbltemp = new Send_sms_templist();
                        tbltemp.smstype = idst;
                        tbltemp.templates = txttemplateformate;
                        db.Send_sms_templist.Add(tbltemp);
                        db.SaveChanges();
                    }
                    else
                    {
                        temprarytblnotuse.templates = txttemplateformate;
                        db.SaveChanges();
                    }

                    //END
                }
                else
                {
                    //  return Json("NOTOK", JsonRequestBehavior.AllowGet);
                }
            }

            List<Sending_SMS_TemplatesViewmodel> vmodel = new List<Sending_SMS_TemplatesViewmodel>();

            var resultssss = GET_ALL_Template_list().OrderByDescending(x => x.idno);
            return PartialView("_SMS_TEMPLATE_Reports", resultssss);
            // return Json("OK", JsonRequestBehavior.AllowGet);
        }

        public IEnumerable<Sending_SMS_TemplatesViewmodel> GET_ALL_Template_list()
        {
            List<Sending_SMS_TemplatesViewmodel> vmodel = new List<Sending_SMS_TemplatesViewmodel>();
            var smstemplateslist = (from a in db.Sending_SMS_Templates
                                    join b in db.apisms on a.SMSAPIID equals b.id

                                    select new Sending_SMS_TemplatesViewmodel
                                    {
                                        SMSAPID = a.SMSAPIID.Value,
                                        Templateid = a.Templateid,
                                        SMS_TYPE = a.SMS_TYPE,
                                        SMSAPI = b.smsapi,
                                        idno = a.idno,
                                        Templates = a.Templates,
                                        UploadBy = a.uplaodby


                                    });

            if (smstemplateslist != null)
            {
                vmodel = new List<Sending_SMS_TemplatesViewmodel>();
                foreach (var i in smstemplateslist)
                {
                    Sending_SMS_TemplatesViewmodel con = new Sending_SMS_TemplatesViewmodel();
                    con.SMSAPI = i.SMSAPI;
                    con.SMSAPID = i.SMSAPID;
                    con.Templateid = i.Templateid;
                    con.Templates = i.Templates;
                    con.SMS_TYPE = i.SMS_TYPE;
                    con.UploadBy = i.UploadBy;
                    con.idno = i.idno;
                    vmodel.Add(con);
                    // all.Add(con);
                }
            }
            return vmodel;
            //  return Json(new { IsSuccess = true, Message = "Details fetched successfully..", Data = emp }, JsonRequestBehavior.AllowGet);
            // return Json(new { Data=vmodel}, JsonRequestBehavior.AllowGet);
        }


        public ActionResult DeleteTemplatebyid(int id)
        {
            var tablefordelete = db.Sending_SMS_Templates.Find(id);
            db.Sending_SMS_Templates.Remove(tablefordelete);
            db.SaveChanges();
            var resultssss = GET_ALL_Template_list();
            return PartialView("_SMS_TEMPLATE_Reports", resultssss);
        }

