        [HttpPost]
        public ActionResult Trans_highsecurity_Setting(string txtcode)
        {
            TempData["showmassage"] = null;
            ViewData["MSG1"] = TempData["error"];
            ViewData["MSG1success"] = TempData["success"];
            TempData.Remove("error");
            TempData.Remove("success");

            var chksec = db.admin_new_pass.SingleOrDefault();
            DateTime currenttime = DateTime.Now;
            DateTime lastchangedpassdss = Convert.ToDateTime(chksec.lastupdatesec);
            lastchangedpassdss = lastchangedpassdss.AddDays(Convert.ToInt32(chksec.secexpdays));
            var defaulths = Decrypt(chksec.securitypass);
            if (defaulths == "1111" || (lastchangedpassdss <= currenttime))
            {
                TempData["error"] = "Your security pin is expired or have to be changed!! Please set new security pin";
                return RedirectToAction("Trans_highsecurity_Setting");
            }
            var typesss = Convert.ToString(TempData.Peek("actiontype"));
            var userid = User.Identity.GetUserId();
            var password = Encrypt(txtcode);

            TempData.Keep("data");
            var tranpass = (from paa in db.admin_new_pass where paa.securitypass == password select paa).Count();
            if (tranpass > 0)
            {
                if (typesss == "Email")
                {
                    TempData["data"] = txtcode;
                    return RedirectToAction("Email_Security");
                }
                if (typesss == "WebLogin")
                {
                    TempData["data"] = txtcode;
                    return RedirectToAction("WebLogin");
                }
                if (typesss == "SMSAPI")
                {
                    TempData["data"] = txtcode;
                    return RedirectToAction("SMSAPI");
                }
                if (typesss == "AutoFundtransferStatus")
                {
                    TempData["data"] = txtcode;
                    return RedirectToAction("AutoFundtransferStatus");
                }

            }
            else
            {
                TempData.Remove("data");
                ViewData["MSG"] = "Security Password is Wrong.";
                return View();
            }
            return View();
        }
