            try
            {
                if (idno > 0)
                {
                    var userid = User.Identity.GetUserId();
                    var ch = db.priorityEmails.Single(a => a.idno == idno);
                    ch.Email = EmailID;
                    ch.Password = Paswrd;
                    ch.Smpthost = SMTPHost;
                    ch.Port = Port;
                    ch.Userid = userid;
                    db.Entry(ch).State = EntityState.Modified;
                    res = db.SaveChanges();
                }
                return Json(new { status = "Success", Message = "Email Updated Successfully." });
            }
            catch
            {
                return Json(new { status = "Failed", Message = "Something Went Wrong !!!" });
            }
        }
        public ActionResult Email_enablessl(int id)
        {
            try
            {
                int res = 0;
                var status = db.priorityEmails.Where(p => p.idno == id).SingleOrDefault().Enablessl;
                if (status == "false")
                {
                    priorityEmail obj = (from tbl in db.priorityEmails
                                         where tbl.idno == id
                                         select tbl).SingleOrDefault();
                    obj.Enablessl = "true";
                    res = db.SaveChanges();
                    return Json(new { status = "Success", Message = "SSL True" });
                }
                else
                {
                    priorityEmail obj = (from tbl in db.priorityEmails
                                         where tbl.idno == id
                                         select tbl).SingleOrDefault();
                    obj.Enablessl = "false";
                    res = db.SaveChanges();
                    return Json(new { status = "Success", Message = "SSL False" });
                }
            }
            catch
            {
                return Json(new { status = "Failed", Message = "Something Went Wrong !!!" });
            }
        }

        [HttpPost]
        public JsonResult SendEmail(SendMail SM)
        {
            try
            {

                if (!string.IsNullOrEmpty(SM.Userform1))
                {
                    if (SM.Userform1 == "Master")
                    {
                        var useremail = db.Superstokist_details.ToList();
                        foreach (var item in useremail)
                        {
                            SM.txtEmail = item.Email;
                            var ToCC = db.Admin_details.FirstOrDefault().email;
                            CommUtilEmail emailsend = new CommUtilEmail();
                            emailsend.EmailLimitChk(SM.txtEmail, ToCC, SM.txtSubject, SM.txtMsgBody, "No CallBackUrl");
                        }
                    }
                    else if (SM.Userform1 == "Dealer")
                    {
                        var smsapilist = (from ff in db.apisms where ff.sts == "Y" select ff).FirstOrDefault();
                        if (smsapilist != null)
                        {
                            var usermobiles = db.Dealer_Details.ToList();
