        [HttpPost]
        public ActionResult UpdateCC(string CCmail)
        {
            try
            {
                if (!string.IsNullOrEmpty(CCmail))
                {
                    string emailRegex = @"^([a-zA-Z0-9_\-\.]+)@((\[[0-9]{1,3}" +
                                        @"\.[0-9]{1,3}\.[0-9]{1,3}\.)|(([a-zA-Z0-9\-]+\" +
                                           @".)+))([a-zA-Z]{2,4}|[0-9]{1,3})(\]?)$";
                    Regex re = new Regex(emailRegex);
                    if (!re.IsMatch(CCmail))
                    {
                        return Json("Email format is not correct.", JsonRequestBehavior.AllowGet);
                    }
                    else
                    {
                        Admin_details adm = (from tbl in db.Admin_details select tbl).FirstOrDefault();
                        adm.email2 = CCmail;
                        db.SaveChanges();
                        return Json("Success", JsonRequestBehavior.AllowGet);
                    }
                }
                else
                {
                    return Json("Failed", JsonRequestBehavior.AllowGet);
                }
            }
            catch { return Json("Failed", JsonRequestBehavior.AllowGet); }
        }

