        [HttpPost]
        public ActionResult SMSSettingSave(string[] ch, string MsgType, string[] whats_code = null)
        {
            var responseMsg = "";
            try
            {
                if (MsgType == "Message's")
                {
                    for (int i = 0; i < ch.Length; i++)
                    {
                        var groupname1 = ch[i].Split(',');
                        var whats_status = whats_code[i].Split(',')[1];
                        var Status = groupname1[1].ToString();
                        var name = groupname1[0].ToString();
                        SMSSendAll obj = (from pp in db.SMSSendAlls
                                          where pp.ServiceName == name
                                          select pp).SingleOrDefault();
                        obj.Status = Status;
                        obj.Whatsapp_Status = whats_status;
                        db.SaveChanges();
                    }
                    responseMsg = "SMS Setting Change Successfully !";
                }
                else if (MsgType == "Email's")
                {
                    foreach (var item in ch)
                    {
                        var groupname1 = item.Split(',');

                        var Status = groupname1[1].ToString();
                        var name = groupname1[0].ToString();
                        EmailSendAll obj = (from pp in db.EmailSendAlls
                                            where pp.ServiceName == name
                                            select pp).SingleOrDefault();
                        obj.Status = Status;
                        db.SaveChanges();
                    }
                    responseMsg = "Mail Setting Change Successfully !";
                }

                return Json(new { status = "Success", Message = responseMsg });
            }
            catch
            {
                return Json(new { status = "Failed", Message = "Something Went Wrong !!!" });
            }
        }
