        [HttpPost]
        public ActionResult Retailer_Reset_IMPSPin(string RetailerId, string oTP, string oTP1, string oTP2, string oTP3)
        {
            try
            {
                string OTp1 = oTP + oTP1 + oTP2 + oTP3;
                if (oTP == null && oTP1 == null && oTP2 == null && oTP3 == null)
                {
                    OTp1 = null;
                }
                var chk1 = db.Users.Where(s => s.UserId == RetailerId).SingleOrDefault();

                if (chk1.forgetpin == OTp1 || OTp1 == null)
                {

                    var chk = db.Retailer_Details.Where(aa => aa.ISDeleteuser == false).Any(a => a.RetailerId == RetailerId);

                    if (chk == true)
                    {

                        int pin = new Random().Next(100000, 999999);
                        var msg = Encrypt(pin.ToString());
                        var id = (from tbl in db.Retailer_Details
                                  where tbl.RetailerId == RetailerId
                                  select tbl).SingleOrDefault();
                        id.PIN = msg;
                        db.SaveChanges();
                        var emailid = db.Retailer_Details.Single(p => p.RetailerId == RetailerId).Email;
                        try
                        {
                            var ToCC = db.Admin_details.FirstOrDefault().email;
                            CommUtilEmail emailsend = new CommUtilEmail();
                            emailsend.EmailLimitChk(emailid, ToCC, "Transaction Pin", "Your Transaction Pin Is  " + pin, "No CallBackUrl");
                        }
                        catch { }
                        chk1.forgetpin = null;
                        db.SaveChanges();
                        return Json(new { status = "Success", Message = "Retailer Transaction Pin Send Successfully in Mail Id . Please Check Your Mail Id." }, JsonRequestBehavior.AllowGet);

                    }
                    else
                    {
                        return Json(new { status = "Failed", Message = "Retailer Email Not Verify.Please Enter Your Corrent Registered Email." }, JsonRequestBehavior.AllowGet);
                    }
                    chk1.forgetpin = null;
                    db.SaveChanges();
                }
                else
                {
                    if (OTp1 == "")
                    {
                        return Json(new { status = "Failed", Message = "Please Enter Otp" }, JsonRequestBehavior.AllowGet);

                    }
                    else
                    {
                        return Json(new { status = "Failed", Message = "Wrong Otp Please try Again" }, JsonRequestBehavior.AllowGet);

                    }
                }
            }
            catch { return Json(new { status = "Failed", Message = "Something Went Wrong!!!" }, JsonRequestBehavior.AllowGet); }
        }
