            }
            else
            {
                var show = (db.PaidServicesPaymentHistories.Where(aa => aa.UserId == allretailer && aa.PurchaseDate >= frm_date && aa.PurchaseDate <= to_date).OrderByDescending(aa => aa.Idno)).ToList();
                return View(show);
            }

        }

