        public ActionResult Admin_to_Retailler()
        {
            var msg = TempData["result"];
            ViewData["output"] = msg;
            var userid = User.Identity.GetUserId();
            ViewBag.RetailerId = new SelectList(db.select_retailer_for_ddl("Admin"), "RetailerId", "Frm_Name", null).ToList();
            ViewBag.RetailerId1 = new SelectList(db.select_retailer_for_ddl("Admin"), "RetailerId", "Frm_Name", null).ToList();
            string txt_frm_date = DateTime.Now.ToString();
            string txt_to_date = DateTime.Now.ToString();
            string frm_date = Convert.ToDateTime(txt_frm_date).Date.ToString("yyyy-MM-dd");
            string to_date = Convert.ToDateTime(txt_to_date).AddDays(1).ToString("yyyy-MM-dd");
            var ch = db.select_dlm_rem(userid, Convert.ToDateTime(frm_date), Convert.ToDateTime(to_date), "ALL", 1, 1500).ToList();
            return View(ch);
        }

        [HttpPost]
        public ActionResult Admin_to_Retailler(string txt_frm_date, string txt_to_date, string RetailerId1)
        {

            var userid = User.Identity.GetUserId();
            ViewBag.chk = "post";
            DateTime frm = Convert.ToDateTime(txt_frm_date);
            DateTime to = Convert.ToDateTime(txt_to_date);
            txt_frm_date = frm.ToString("dd-MM-yyyy");
            txt_to_date = to.ToString("dd-MM-yyyy");
            string[] formats = new[] { "MM/dd/yyyy", "dd-MMM-yyyy",
                            "yyyy-MM-dd", "dd-MM-yyyy", "dd MMM yyyy" };
            DateTime dt = !string.IsNullOrWhiteSpace(txt_frm_date) ? DateTime.ParseExact(txt_frm_date, formats, CultureInfo.InvariantCulture, DateTimeStyles.None) : DateTime.Now;
            DateTime dt1 = !string.IsNullOrWhiteSpace(txt_to_date) ? DateTime.ParseExact(txt_to_date, formats, CultureInfo.InvariantCulture, DateTimeStyles.None) : DateTime.Now;
            DateTime frm_date = Convert.ToDateTime(dt).Date;
            DateTime to_date = Convert.ToDateTime(dt1).Date.AddDays(1);
            if (RetailerId1 == "")
            {
                RetailerId1 = "ALL";
            }
            ViewBag.RetailerId = new SelectList(db.select_retailer_for_ddl("Admin"), "RetailerId", "Frm_Name", null).ToList();
            ViewBag.RetailerId1 = new SelectList(db.select_retailer_for_ddl("Admin"), "RetailerId", "Frm_Name", null).ToList();
            var ch = db.select_dlm_rem(userid, Convert.ToDateTime(frm_date), Convert.ToDateTime(to_date), RetailerId1, 1, 15000).ToList();
            return View(ch);
        }

        //check Retailer Old Credit Balance
        //Credit Balance Check
        public ActionResult R_Creditchk(string retailerid)
        {
            string userid = User.Identity.GetUserId();
            var ch = db.Dealer_To_Retailer_Balance.Where(aa => aa.RetailerId == retailerid && aa.DealerId == userid).OrderByDescending(aa => aa.id).FirstOrDefault()?.cr;
            ch = ch ?? 0;
            decimal rembal;
            decimal? remposbal;
            if (string.IsNullOrEmpty(retailerid))
            {
                rembal = 0;
                remposbal = 0;
            }
            else
            {
                rembal = (decimal)db.Remain_reteller_balance.Where(x => x.RetellerId == retailerid).SingleOrDefault().Remainamount;

                remposbal = db.Pos_remain.Where(s => s.userid == retailerid).SingleOrDefault().Remain;
            }
            db.Configuration.ProxyCreationEnabled = false;
            Retailer_Details reinfo = db.Retailer_Details.Where(x => x.RetailerId == retailerid).FirstOrDefault();
            return Json(new { currntcr = ch, rembal = rembal, reinfo = reinfo, rempos = remposbal }, JsonRequestBehavior.AllowGet);


        }

