        //master purchase order
        public ActionResult updatepurchage_master(int id, string type, string txtcomment, string txthighsec)
        {
            try
            {
                var chktranss = db.admin_new_pass.SingleOrDefault();
                DateTime currenttime = DateTime.Now;
                DateTime lastchangedpassdtr = Convert.ToDateTime(chktranss.lastupdatetrans);
                lastchangedpassdtr = lastchangedpassdtr.AddDays(Convert.ToInt32(chktranss.transexpdays));
                var defaultht = Decrypt(chktranss.transpass);
                if (defaultht == "1111" || (lastchangedpassdtr <= currenttime))
                {
                    TempData["error"] = "Your transaction pin is expired or have to be changed!! Please set new transaction pin";
                    return RedirectToAction("ChangeSecurityPassword");
                }
                var password = Encrypt(txthighsec);
                var tranpass = (from paa in db.admin_new_pass where paa.transpass == password select paa).Count();
                if (tranpass > 0)
                {
                    if (type == "APP")
                    {
                        type = "Approved";
                    }
                    else
                    {
                        type = "rejected";
                    }
                    var statusSendSmsRetailerfundtransfer = db.SMSSendAlls.Where(a => a.ServiceName == "AdmintoREMfundtrans").SingleOrDefault();
                    var statusSendEmailRetailerfundtransfer = db.EmailSendAlls.Where(a => a.ServiceName == "AdmintoREMfundtrans1").SingleOrDefault().Status;

                    var masterpurdetails = db.master_purchase.Where(x => x.idno == id).FirstOrDefault();
                    var masterinfo = db.Superstokist_details.Where(x => x.SSId == masterpurdetails.masterid).FirstOrDefault();
                    var adminemail = db.Admin_details.FirstOrDefault().Companyname;
                    var sts = db.master_purchase.Where(a => a.idno == id).Single().sts.ToUpper();
                    if (sts == "PENDING")
                    {
                        System.Data.Entity.Core.Objects.ObjectParameter output = new
                        System.Data.Entity.Core.Objects.ObjectParameter("Output", typeof(string));
                        var ch = db.update_master_purchage(Convert.ToInt32(id), type, 0, txtcomment, output).Single().msg;
                        if (ch == "Balance Transfer SuccessFully.")
                        {
                            TempData["successorder"] = ch;

                            try
                            {
                                var diff1 = (db.admin_to_super_balance.Where(aa => aa.SuperStokistID == masterpurdetails.masterid && aa.balance_from == masterpurdetails.frm).OrderByDescending(aa => aa.ID).Select(aa => aa.cr).FirstOrDefault());
                                diff1 = diff1 ?? 0;
                                var remainmaster = db.Remain_superstokist_balance.Where(p => p.SuperStokistID == masterpurdetails.masterid).Single().Remainamount;

                                smssend.sms_init(statusSendSmsRetailerfundtransfer.Status, statusSendSmsRetailerfundtransfer.Whatsapp_Status, "PURCHASEORDERRECEIVED", masterinfo.Mobile, masterpurdetails.finalAmount, adminemail, remainmaster, diff1);

                                if (statusSendEmailRetailerfundtransfer == "Y")
                                {
                                    smssend.SendEmailAll(masterinfo.Email, "Recived Rs." + masterpurdetails.finalAmount + " From " + adminemail + ".New Balance Rs. " + remainmaster + ".Your O/s Credit is " + diff1 + ",", "Purchase Order", db.Admin_details.SingleOrDefault().Companyname, 1000);
                                }
                            }
                            catch (Exception)
                            { }

                        }
                        else if (ch == "Purchase Order Rejected.")
                        {
                            TempData["failedorder"] = ch;
                            try
                            {
                                smssend.sms_init(statusSendSmsRetailerfundtransfer.Status, statusSendSmsRetailerfundtransfer.Whatsapp_Status, "REJECTPURCHASEORDER", masterinfo.Mobile, masterpurdetails.finalAmount, adminemail, txtcomment);

                                if (statusSendEmailRetailerfundtransfer == "Y")
                                {
                                    smssend.SendEmailAll(masterinfo.Email, "Purchase Order Of Rs " + masterpurdetails.finalAmount + " From " + adminemail + " Is REJECTED Due To " + txtcomment + " .", "Reject Purchase Order", db.Admin_details.SingleOrDefault().Companyname, 1000);
                                }
                            }
                            catch (Exception ex)
                            { }
                        }
                        else
                        {
                            TempData["failedorder"] = ch;
                        }

                    }
                }
                else
                {
                    TempData["failedorder"] = "Transection Password Was Wrong.";
                }

            }
            catch (Exception e)
            { }
            return RedirectToAction("ShowPurchase_master");
        }

