                    {
                        type = "rejected";
                    }
                    var statusSendSmsRetailerfundtransfer = db.SMSSendAlls.Where(a => a.ServiceName == "AdmintoREMfundtrans").SingleOrDefault();
                    var statusSendEmailRetailerfundtransfer = db.EmailSendAlls.Where(a => a.ServiceName == "AdmintoREMfundtrans1").SingleOrDefault().Status;
                    var rempurdetails = db.rem_purchage.Where(x => x.idno == id).FirstOrDefault();
                    var reminfo = db.Retailer_Details.Where(x => x.RetailerId == rempurdetails.remid).FirstOrDefault();
                    var adminemail = db.Admin_details.FirstOrDefault().Companyname;

                    var sts = db.rem_purchage.Where(a => a.idno == id).Single().sts.ToUpper();
                    if (sts == "PENDING")
                    {
                        System.Data.Entity.Core.Objects.ObjectParameter output = new
                 System.Data.Entity.Core.Objects.ObjectParameter("Output", typeof(string));
                        var ch = db.update_rem_purchage(Convert.ToInt32(id), type, 0, txtcomment, output).Single().msg;
                        try
                        {
