        public ActionResult updatepurchage_Api(int id, string type, string txtcomment, string txthighsec)
        {
            try
            {
                var chktranss = db.admin_new_pass.SingleOrDefault();
                DateTime currenttime = DateTime.Now;
                DateTime lastchangedpassdtr = Convert.ToDateTime(chktranss.lastupdatetrans);
                lastchangedpassdtr = lastchangedpassdtr.AddDays(Convert.ToInt32(chktranss.transexpdays));
                var defaultht = Decrypt(chktranss.transpass);
                if (defaultht == "1111" || (lastchangedpassdtr <= currenttime))
                {
                    TempData["error"] = "Your transaction pin is expired or have to be changed!! Please set new transaction pin";
                    return RedirectToAction("ChangeSecurityPassword");
                }
                var password = Encrypt(txthighsec);
                var tranpass = (from paa in db.admin_new_pass where paa.transpass == password select paa).Count();
                if (tranpass > 0)
                {
                    if (type == "APP")
                    {
                        type = "Approved";
                    }
                    else
                    {
                        type = "rejected";
                    }
                    var statusSendSmsRetailerfundtransfer = db.SMSSendAlls.Where(a => a.ServiceName == "AdmintoREMfundtrans").SingleOrDefault();
                    var statusSendEmailRetailerfundtransfer = db.EmailSendAlls.Where(a => a.ServiceName == "AdmintoREMfundtrans1").SingleOrDefault().Status;
                    var apipurdetails = db.api_purchase.Where(x => x.idno == id).FirstOrDefault();
                    var reminfo = db.api_user_details.Where(x => x.apiid == apipurdetails.apiid).FirstOrDefault();
                    var adminemail = db.Admin_details.FirstOrDefault().Companyname;

                    var sts = db.api_purchase.Where(a => a.idno == id).Single().sts.ToUpper();
                    if (sts == "PENDING")
                    {
                        System.Data.Entity.Core.Objects.ObjectParameter output = new
                 System.Data.Entity.Core.Objects.ObjectParameter("Output", typeof(string));
                        var ch = db.update_api_purchage(Convert.ToInt32(id), type, 0, txtcomment, output).Single().msg;
                        try
                        {
                            var retailerdetails = db.api_user_details.Where(aa => aa.apiid == apipurdetails.apiid).SingleOrDefault();
                            var remdetails = db.api_remain_amount.Where(aa => aa.apiid == apipurdetails.apiid).SingleOrDefault();

                            var admininfo = db.Admin_details.SingleOrDefault();
                            Backupinfo back = new Backupinfo();

                            var model = new Backupinfo.Addinfo
                            {
                                Websitename = admininfo.WebsiteUrl,
                                RetailerID = apipurdetails.apiid,
                                Email = retailerdetails.emailid,
                                Mobile = retailerdetails.mobile,
                                Details = "Fund Recived From Admin ",
                                RemainBalance = (decimal)remdetails.balance,
                                Usertype = "API"
                            };
                            back.Fundtransfer(model);


                        }
                        catch { }
                        if (ch == "Balance Transfer Successfully.")
                        {

                            TempData["successorder"] = ch;

                            try
                            {
                                var diff1 = (db.API_Balance_transfer.Where(aa => aa.apiid == apipurdetails.apiid && aa.groupname == apipurdetails.frm).OrderByDescending(aa => aa.id).Select(aa => aa.cr).FirstOrDefault());
                                diff1 = diff1 ?? 0;
                                var remainapi = db.api_remain_amount.Where(p => p.apiid == apipurdetails.apiid).Single().balance;

                                smssend.sms_init(statusSendSmsRetailerfundtransfer.Status, statusSendSmsRetailerfundtransfer.Whatsapp_Status, "PURCHASEORDERRECEIVED", reminfo.mobile, apipurdetails.finalAmount, adminemail, remainapi, diff1);

                                if (statusSendEmailRetailerfundtransfer == "Y")
                                {
                                    smssend.SendEmailAll(reminfo.emailid, "Recived Rs." + apipurdetails.finalAmount + " From " + adminemail + ".New Balance Rs. " + remainapi + ".Your O/s Credit is " + diff1 + ",", "Purchase Order", db.Admin_details.SingleOrDefault().Companyname, 1000);
                                }
                            }
                            catch (Exception) { }
                        }
                        else if (ch == "Purchase Order Rejected.")
                        {
                            TempData["failedorder"] = ch;
                            try
                            {
                                smssend.sms_init(statusSendSmsRetailerfundtransfer.Status, statusSendSmsRetailerfundtransfer.Whatsapp_Status, "REJECTPURCHASEORDER", reminfo.mobile, apipurdetails.finalAmount, adminemail, txtcomment);

                                if (statusSendEmailRetailerfundtransfer == "Y")
                                {
                                    smssend.SendEmailAll(reminfo.emailid, "Purchase Order Of Rs " + apipurdetails.finalAmount + " From " + adminemail + " Is REJECTED Due To " + txtcomment + " .", "Reject Purchase Order", db.Admin_details.SingleOrDefault().Companyname, 1000);
                                }

                            }
                            catch (Exception ex)
                            { }
                        }

                        else
                        {
                            TempData["failedorder"] = ch;
                        }
                    }
                }
                else
                {
                    TempData["failedorder"] = "Transection Password Was Wrong";
                }

            }
            catch (Exception ex)
            { }
            return RedirectToAction("Api_showpurchase");
        }

