        public ActionResult UnblockWallet()
        {
            var chk = db.Wallet_unload_sts.SingleOrDefault();
            bool? sts1 = false;
            if (chk != null)
            {
                sts1 = chk.sts;
                if (sts1 == false)
                {
                    chk.sts = true;
                }
                else
                {
                    chk.sts = false;
                }
                db.SaveChanges();
            }
            else
            {
                Wallet_unload_sts sts = new Wallet_unload_sts();
                sts.sts = true;
                sts.type = "Retailer";
                db.Wallet_unload_sts.Add(sts);
                db.SaveChanges();
            }
            return Json("", JsonRequestBehavior.AllowGet);
        }
