        public ActionResult _WalletToBankSlabList(string Role, string RetailerId)
        {
            CashDepositeAndBank_Info_VM CashBank = new CashDepositeAndBank_Info_VM();



            ViewBag.RetailerId2 = new SelectList(db.select_retailer_for_ddl("Admin"), "RetailerId", "Frm_Name", null).ToList();
            if (RetailerId != null)
            {

                CashBank.WulChargeList = db.WalletToBankAmountTransferCharges.Where(aa => aa.userid == RetailerId).OrderBy(a => a.AmtFromTatkal).ToList();
            }
            else if (RetailerId == "All")
            {
                CashBank.WulChargeList = db.WalletToBankAmountTransferCharges.Where(aa => aa.userid == "All").OrderBy(a => a.AmtFromTatkal).ToList();
            }

            else if (Role == "Retailer")
            {
                CashBank.WulChargeList = db.WalletToBankAmountTransferCharges.Where(aa => aa.UserRole == "All").OrderBy(a => a.AmtFromTatkal).ToList();
            }
            else if (Role == "WhiteLabel")
            {
                CashBank.WulChargeList = db.WalletToBankAmountTransferCharges.Where(aa => aa.UserRole == "WhiteLabel").OrderBy(a => a.AmtFromTatkal).ToList();
            }
            else if (Role == "Seller")
            {
                CashBank.WulChargeList = db.WalletToBankAmountTransferCharges.Where(aa => aa.UserRole == "Seller").OrderBy(a => a.AmtFromTatkal).ToList();
            }
            return PartialView("_WalletToBankSlabList", CashBank);
        }
        [HttpPost]
        public ActionResult AddWalletToBankSlab(decimal amtFromTatkal, decimal amtToTatkal, decimal IMPSFee, decimal NEFTFee, string RetailerId, string Role)
        {
            if (RetailerId == "" || RetailerId == null)
            {
                RetailerId = "ALL";
            }
            System.Data.Entity.Core.Objects.ObjectParameter output = new
                   System.Data.Entity.Core.Objects.ObjectParameter("Output", typeof(string));

            var chk = db.retailer_unload_charge(amtFromTatkal, amtToTatkal, IMPSFee, NEFTFee, RetailerId, Role, output).SingleOrDefault().msg;

            CashDepositeAndBank_Info_VM CashBank = new CashDepositeAndBank_Info_VM();

            if (Role == "Retailer")
            {
                CashBank.WulChargeList = db.WalletToBankAmountTransferCharges.Where(aa => aa.UserRole == "Retailer").ToList();


            }

            else if (Role == "WhiteLabel")
            {
                CashBank.WulChargeList = db.WalletToBankAmountTransferCharges.Where(aa => aa.UserRole == "WhiteLabel").ToList();
            }
            else if (Role == "Seller")
            {
                CashBank.WulChargeList = db.WalletToBankAmountTransferCharges.Where(aa => aa.UserRole == "Seller").ToList();
            }
            CashBank.msg = chk;
            return PartialView("_WalletToBankSlabList", CashBank);
        }


