        public ActionResult AddCatagory(string catName, int? parentCatId)
        {
            try
            {
                if (!string.IsNullOrWhiteSpace(catName))
                {
                    using (VastwebmultiEntities db = new VastwebmultiEntities())
                    {
                        if (parentCatId != null && parentCatId > 0)
                        {
                            var entry = db.SubCatagories.SingleOrDefault(a =>
                                a.SubCatName.ToLower() == catName.ToLower());
                            if (entry != null)
                            {
                                entry.CreatedOn = DateTime.Now;
                                entry.IsDeleted = false;
                                db.SaveChanges();
                            }
                            else
                            {
                                entry = new SubCatagory();
                                entry.CatID = parentCatId;
                                entry.CreatedOn = DateTime.Now;
                                entry.IsActive = false;
                                entry.SubCatName = catName;
                                db.SubCatagories.Add(entry);
                                db.SaveChanges();
                            }

                        }
                        else
                        {
                            var entry = db.Catagories.SingleOrDefault(a => a.CatName.ToLower() == catName.ToLower());
                            if (entry != null)
                            {
                                entry.IsDeleted = false;
                                entry.CreatedOn = DateTime.Now;
                                db.SaveChanges();
                            }
                            else
                            {
                                entry = new Catagory();
                                entry.CatName = catName;
                                entry.CreatedOn = DateTime.Now;
                                entry.IsActive = false;
                                db.Catagories.Add(entry);
                                db.SaveChanges();
                            }

                        }
                    }
                }

                return RedirectToAction("CatagoryList");
            }
            catch (Exception ex)
            {
                throw;
            }
        }
        public ActionResult EditCatagory(string catName1, string catagory, int? CatId = 0)
        {
            try
            {
                if (!string.IsNullOrWhiteSpace(catName1))
                {
                    using (VastwebmultiEntities db = new VastwebmultiEntities())
                    {
                        if (CatId != null && CatId > 0 && catagory == "SubCat")
                        {
                            var entry = db.SubCatagories.SingleOrDefault(a => a.SubCatID == CatId);
                            entry.SubCatName = catName1;
                            db.SaveChanges();
                        }
                        else if (CatId != null && CatId > 0 && catagory == "catagory")
                        {
                            var entry = db.Catagories.SingleOrDefault(a => a.CatID == CatId);
                            entry.CatName = catName1;
                            db.SaveChanges();
                        }
                    }
                }

                return RedirectToAction("CatagoryList");
            }
            catch (Exception ex)
            {
                throw;
            }
        }
        public ActionResult RemoveCat(string catagory, int? CatId = 0)
        {
            try
            {
                if (CatId != null)
                {
                    using (VastwebmultiEntities db = new VastwebmultiEntities())
                    {
                        if (CatId > 0 && catagory == "SubCat")
                        {
                            var entry = db.SubCatagories.SingleOrDefault(a => a.SubCatID == CatId);
                            entry.IsDeleted = true;
                            db.SaveChanges();
                        }
                        else if (CatId > 0 && catagory == "catagory")
                        {
                            using (TransactionScope transactionScope = new TransactionScope())
                            {

                                try
                                {
                                    var subentry = db.SubCatagories.Where(a => a.CatID == CatId).ToList();
                                    subentry.ForEach(a => a.IsDeleted = true);
                                    db.SaveChanges();
                                    var entry = db.Catagories.SingleOrDefault(a => a.CatID == CatId);
                                    entry.IsDeleted = true;
                                    db.SaveChanges();
                                    transactionScope.Complete();

                                    transactionScope.Dispose();
                                }
                                catch (TransactionException ex)
                                {
                                    transactionScope.Dispose();
                                }

                            }
                        }
                    }
                }
                return RedirectToAction("CatagoryList");
            }
            catch (Exception ex)
            {
                throw;
            }
        }
