        [HttpPost]
        public ActionResult ApproveProduct(int ProductID, decimal MDComm, decimal DEComm, decimal REMComm, decimal WLComm)
        {
            try
            {
                if (ProductID >= 0 && MDComm >= 0 && DEComm >= 0 && REMComm >= 0 && WLComm >= 0)
                {
                    using (VastwebmultiEntities db = new VastwebmultiEntities())
                    {
                        var entry = db.Products.SingleOrDefault(a => a.ProductID == ProductID);
                        entry.IsApproved = 1;
                        entry.IsActive = true;
                        db.SaveChanges();
                        var PV_Entry = db.ProductVendors.SingleOrDefault(a => a.ProductID == ProductID);
                        PV_Entry.MDComm = MDComm;
                        PV_Entry.DEComm = DEComm;
                        PV_Entry.RemComm = REMComm;
                        PV_Entry.WhiteLabelComm = WLComm;
                        db.SaveChanges();
                        TempData["approved"] = "Order Approved Successfully";
                    }
                }
            }
            catch (Exception ex)
            {
                return RedirectToAction("Products");
            }
            return RedirectToAction("Products");
        }

        public ActionResult RejectProduct(int ProductID)
        {
            try
            {
                if (ProductID > 0)
                {
                    using (VastwebmultiEntities db = new VastwebmultiEntities())
                    {
                        var entry = db.Products.SingleOrDefault(a => a.ProductID == ProductID);
                        entry.IsApproved = 2;
                        db.SaveChanges();
                        TempData["Rejected"] = "Order Rejected Successfully";
                    }
                }
            }
            catch (Exception e)
            {
                throw;
            }
            return RedirectToAction("Products");
        }

