        [HttpPost]
        public ActionResult EditFeeController(string txtFCId, string FeeCollectorName1, string FirmName1, string State1, string District1, string Address1, int Pincode1, decimal CommissionAdmin1, decimal CommissionMD1, decimal CommissionDLM1, decimal CommissionREM1, decimal CommissionWL1, string pancard1, string adharcard1, string gst1, string SchoolName1, string Website1, string Mb1)
        {
            try
            {
                var ccc = db.FeeCollector_details.Where(p => p.FCId == txtFCId).SingleOrDefault();
                var mobileno = ccc.Mobile;
                var emailid = ccc.Email;
                var userid = ccc.FCId;
                if (mobileno != Mb1)
                {
                    var usermobileno = db.Users.Where(a => a.PhoneNumber == Mb1).Any();
                    if (usermobileno == true)
                    {
                        TempData["alerdymobile"] = "This Mobile Number Alerady Use To Another User.Please Enter Another Mobile No.";
                        return RedirectToAction("Master_list");
                    }
                    else
                    {
                        int pin = new Random().Next(1000, 10000);
                        MobileOtp motp = new MobileOtp();
                        motp.Date = DateTime.Now;
                        motp.Userid = userid;
                        motp.Type = "FeeCollector";
                        motp.mobileno = Mb1;
                        motp.Otp = pin.ToString();
                        db.MobileOtps.Add(motp);
                        db.SaveChanges();

                        try
                        {
                            var ToCC = db.Admin_details.FirstOrDefault().email;
                            CommUtilEmail emailsend = new CommUtilEmail();
                            emailsend.EmailLimitChk(emailid, ToCC, "Mobile Number Change Otp", "Your OTP Is  " + pin, "No CallBackUrl");
                        }
                        catch { }
                        TempData["email"] = "Otp Send in User Mail-Id Successfully.Please Check Mail Id and Enter OTP.";
                        return RedirectToAction("InsertOTP");
                    }
                }
                else
                {
                    FeeCollector_details objCourse = (from p in db.FeeCollector_details
                                                      where p.FCId == txtFCId
                                                      select p).SingleOrDefault();
                    objCourse.Address = Address1;
                    objCourse.District = Convert.ToInt32(District1);
                    objCourse.FCName = FeeCollectorName1;
                    objCourse.FirmName = FirmName1;
                    objCourse.Pincode = Pincode1;
                    objCourse.CommissionAdmin = CommissionAdmin1 < 1 ? objCourse.CommissionAdmin : CommissionAdmin1;
                    objCourse.CommissionMD = CommissionMD1 < 1 ? objCourse.CommissionMD : CommissionMD1;
                    objCourse.CommissionDLM = CommissionDLM1 < 1 ? objCourse.CommissionDLM : CommissionDLM1;
                    objCourse.CommissionREM = CommissionREM1 < 1 ? objCourse.CommissionREM : CommissionREM1;
                    objCourse.CommissionWL = CommissionWL1 < 1 ? objCourse.CommissionWL : CommissionWL1;
                    objCourse.pancard = string.IsNullOrWhiteSpace(pancard1) ? objCourse.pancard : pancard1;
                    objCourse.adharcard = string.IsNullOrWhiteSpace(adharcard1) ? objCourse.adharcard : adharcard1; ;
                    objCourse.gst = string.IsNullOrWhiteSpace(gst1) ? objCourse.gst : gst1;
                    objCourse.State = Convert.ToInt32(State1);
                    objCourse.SchoolName = SchoolName1;
                    objCourse.Website = Website1;
                    db.SaveChanges();

                    TempData["edit"] = "Data Edit Successfully..";
                    return RedirectToAction("FC");
                }
            }
            catch
            {
                return RedirectToAction("FC");
            }
        }
        [HttpGet]
        public ActionResult FeeCollection()
        {
            var userid = User.Identity.GetUserId();
            string txt_frm_date = DateTime.Now.ToString();
            string txt_to_date = DateTime.Now.ToString();
            string frm_date = Convert.ToDateTime(txt_frm_date).Date.ToString("yyyy-MM-dd");
            string to_date = Convert.ToDateTime(txt_to_date).AddDays(1).ToString("yyyy-MM-dd");
            FeeCollector.Models.FeeDepositModel model = new FeeCollector.Models.FeeDepositModel();
            model.lstFeedeposit = db.proc_getFeedepositDetails(null, null, Convert.ToDateTime(frm_date), Convert.ToDateTime(to_date)).ToList();
            return View(model);
        }
        [HttpPost]
        public ActionResult FeeCollection(string stdRollNO, string txt_frm_date, string txt_to_date)
        {

            var userid = User.Identity.GetUserId();
            ViewBag.chk = "post";

            DateTime frm = Convert.ToDateTime(txt_frm_date);
            DateTime to = Convert.ToDateTime(txt_to_date);
            txt_frm_date = frm.ToString("dd-MM-yyyy");
            txt_to_date = to.ToString("dd-MM-yyyy");
            string[] formats = new[] { "MM/dd/yyyy", "dd-MMM-yyyy",
                            "yyyy-MM-dd", "dd-MM-yyyy", "dd MMM yyyy" };
            DateTime dt = !string.IsNullOrWhiteSpace(txt_frm_date) ? DateTime.ParseExact(txt_frm_date, formats, CultureInfo.InvariantCulture, DateTimeStyles.None) : DateTime.Now;
            DateTime dt1 = !string.IsNullOrWhiteSpace(txt_to_date) ? DateTime.ParseExact(txt_to_date, formats, CultureInfo.InvariantCulture, DateTimeStyles.None) : DateTime.Now;
            DateTime frm_date = Convert.ToDateTime(dt).Date;
            DateTime to_date = Convert.ToDateTime(dt1).Date.AddDays(1);
            FeeCollector.Models.FeeDepositModel model = new FeeCollector.Models.FeeDepositModel();
            model.lstFeedeposit = db.proc_getFeedepositDetails(stdRollNO, null, Convert.ToDateTime(frm_date), Convert.ToDateTime(to_date)).ToList();
            return View(model);
        }
