        public ActionResult Delete_slabName(int id, string slabfor, string slabname)
        {

            if (slabfor == "API")
            {
                var apiresult = db.api_user_details.Where(p => p.SlabName == slabname).ToList();
                if (apiresult.Count > 0)
                {
                    TempData["api"] = "This slab is Already Assign To API User..";
                }
                else
                {
                    var msg = db.Delete_slab(slabfor, slabname, "Admin");
                    TempData["successmsg"] = "Slab Deteted Successfully..";
                }
            }
            else if (slabfor == "Master")
            {
                var masterresult = db.Superstokist_details.Where(p => p.slab_name == slabname).ToList();
                if (masterresult.Count > 0)
                {
                    TempData["api"] = "This slab is Already Assign To Master User..";
                }
                else
                {
                    var msg = db.Delete_slab(slabfor, slabname, "Admin");
                    TempData["successmsg"] = "Slab Deteted Successfully..";
                }
            }
            else if (slabfor == "White")
            {
                var whiteresult = db.WhiteLabel_userList.Where(p => p.SlabName == slabname).ToList();
                if (whiteresult.Count > 0)
                {
                    TempData["api"] = "This slab is Already Assign To Whitelabel User..";
                }
                else
                {
                    var msg = db.Delete_slab(slabfor, slabname, "Admin");
                    TempData["successmsg"] = "Slab Deteted Successfully..";
                }
            }

            return RedirectToAction("generateSlab");
        }
