        public ActionResult Flight_Commission()
        {
            Show_Flight_Commission ch = new Show_Flight_Commission();
            ch.Flight = (from tbl in db.Flight_Commission_admin
                         select new Flight
                         {
                             idno = tbl.idno,
                             RetailerCommission = tbl.RetailerCommission,
                             DealerCommission = tbl.DealerCommission,
                             MasterCommission = (decimal)tbl.MDCommission,
                             WhitelabelCommission = tbl.WhitelabelCommission,
                         }).ToList();
            return View(ch);
        }
        public ActionResult EditFlightCommission(Show_Flight_Commission show, string ID, string retailercommission)
        {
            if (retailercommission != "")
            {
                if (ID == "Flight")
                {
                    foreach (var jj in show.Flight)
                    {
                        var idno = jj.idno;
                        decimal retailercomm = Convert.ToDecimal(retailercommission);
                        var dealercomm = jj.DealerCommission;
                        var mdcomm = jj.MasterCommission;
                        var whitecomm = jj.WhitelabelCommission;
                        var totaldealerandmdcomm = dealercomm + mdcomm;
                        if (retailercomm >= totaldealerandmdcomm)
                        {
                            Flight_Commission_admin objCourse = (from p in db.Flight_Commission_admin where p.idno == idno select p).Single();
                            objCourse.RetailerCommission = retailercomm;
                            objCourse.DealerCommission = dealercomm;
                            objCourse.MDCommission = mdcomm;
                            objCourse.WhitelabelCommission = whitecomm;
                            db.SaveChanges();
                            TempData["flight"] = "Flight Commission Update Successfully.";
                        }
                        else
                        {
                            TempData["flight"] = "Retailer Commission Must Be Greater Then Dealer and Master Commission";
                        }
                    }
                }
            }
            else
            {
                TempData["flight"] = "Please Select Retailer Commission";
            }
            return RedirectToAction("Flight_Commission");
        }
