        public ActionResult Default_slab(string ddltype, string ddluser)
        {
            ShowAllDefaultSlabCharge ch = new ShowAllDefaultSlabCharge();
            ch.DefaultPrepaid = (from tbl in db.default_prepaid_comm
                                 join p in db.Operator_Code on tbl.optid equals p.Operator_id.ToString()
                                 where tbl.createdfor == ddluser && tbl.createdby == "Admin"
                                 select new DefaultPrepaid
                                 {
                                     idno = tbl.idno,
                                     commission = tbl.comm,
                                     OperatorName = p.operator_Name
                                 }).ToList();
            ch.DefaultPostpaid = (from tbl in db.default_postpaid_comm
                                  join tbl1 in db.Operator_Code on tbl.optid equals tbl1.Operator_id.ToString()
                                  where tbl.createdfor == ddluser && tbl.createdby == "Admin"
                                  select new DefaultPostpaid
                                  {
                                      idno = tbl.idno,
                                      commission1 = tbl.comm1,
                                      commission2 = tbl.comm2,
                                      commission3 = tbl.comm3,
                                      OperatorName = tbl1.operator_Name
                                  }).ToList();

            ch.DefaultIMPS = (from tbl in db.default_dmt_comm
                              where tbl.createdfor == ddluser && tbl.createdby == "Admin"
                              select new DefaultIMPS
                              {
                                  idno = tbl.idno,
