        public ActionResult EditDefaultSlabCharge(ShowAllDefaultSlabCharge show, string ID, string userid)
        {
            var ddltype = "";
            if (ID == "Prepaid")
            {
                foreach (var jj in show.DefaultPrepaid)
                {
                    ddltype = "Prepaid";
                    var idno = jj.idno;
                    var comm = jj.commission;
                    default_prepaid_comm objCourse = (from p in db.default_prepaid_comm where p.idno == idno select p).Single();
                    objCourse.comm = comm;
                    db.SaveChanges();
                }
            }
            else if (ID == "Postpaid")
            {
                foreach (var jj in show.DefaultPostpaid)
                {
                    ddltype = show.DefaultPostpaid[0].ddltype;
                    var idno = jj.idno;
                    var comm1 = jj.commission1;
                    var comm2 = jj.commission2;
                    var comm3 = jj.commission3;
                    default_postpaid_comm obj = (from p in db.default_postpaid_comm where p.idno == idno select p).Single();
                    obj.comm1 = comm1;
                    obj.comm2 = comm2;
                    obj.comm3 = comm3;
                    db.SaveChanges();
                }
            }
            else if (ID == "IMPS")
            {
                foreach (var jj in show.DefaultIMPS)
                {
                    ddltype = show.DefaultIMPS[0].ddltype;
                    var idno = jj.idno;
                    var comm = jj.commission;
                    default_dmt_comm imps = (from p in db.default_dmt_comm where p.idno == idno select p).Single();
                    imps.value = comm;
                    db.SaveChanges();
                }
            }
            return RedirectToAction("Default_slab", new { ddltype = ID, ddluser = userid });
        }
