        [HttpPost]
        public ActionResult Update_FlightSlab(List<Slab_Flight> model, string ddlUserId, string role)
        {
            //master User
            if (!string.IsNullOrWhiteSpace(role))
            {
                if (!string.IsNullOrWhiteSpace(ddlUserId))
                {
                    foreach (var item in model)
                    {
                        var entry = db.Slab_Flight.FirstOrDefault(a => a.idno == item.idno && a.UserId != "Default" && a.Role == role);
                        entry.IsDomestic = item.IsDomestic;
                        entry.marginPercentage = item.marginPercentage;
                        entry.gst = item.gst;
                        entry.tds = item.tds;
                        db.SaveChanges();
                    }
                }
                else
                {
                    model = model.Where(a => a.UserId == "Default").ToList();
                    foreach (var item in model)
                    {
                        var entry = db.Slab_Flight.Where(a => a.Role == role && a.IsDomestic == item.IsDomestic && a.UserId != "Default").ToList();
                        entry.ForEach(a => { a.marginPercentage = item.marginPercentage; });
                        db.SaveChanges();
                    }
                }
            }
            return RedirectToAction("Flight_Slab");
        }
