        #region BUS

        public ActionResult BUS_Slab()
        {
            var data = TempData.Peek("data");
            if (data == "" || data == null)
            {
                return RedirectToAction("tran_passslabsetting");
            }
            else
            {
                var entries = db.Slab_Bus.Where(a => a.UserId == "Default").ToList();
                BusSlabModel model = new BusSlabModel();
                model.common = entries;
                ViewBag.UserId = new List<SelectListItem>() { new SelectListItem { Text = "No data", Value = "No Data" } };
                return View(model);
            }
        }
        [HttpPost]
        public ActionResult _common_bus_slab(BusSlabModel model)
        {
            foreach (var item in model.common)
            {
                var entry = db.Slab_Bus.FirstOrDefault(a => a.idno == item.idno);
                entry.marginPercentage = item.marginPercentage;
                entry.gst = item.gst;
                entry.tds = item.tds;
                db.SaveChanges();
            }
            var entries = db.Slab_Bus.Where(a => a.UserId == "Default").ToList();
            model.common = entries;
            return PartialView(model);
        }

