        [HttpPost]
        public ActionResult Update_BUS_Slab(BusSlabModel model, string ddlUserId, string role)
        {

            //master User
            if (role == "Master")
            {
                if (ddlUserId != "")
                {
                    foreach (var item in model.Materuser)
                    {
                        var entry = db.Slab_Bus.Single(a => a.UserId == ddlUserId);
                        entry.marginPercentage = item.marginPercentage;
                        entry.retailerMarkup = item.retailerMarkup;
                        entry.gst = item.gst;
                        entry.tds = item.tds;
                        db.SaveChanges();
                    }
                }
                else
                {
                    foreach (var item in model.UpdateMaster)
                    {
                        db.Update_BUS_All_userSlab("Master", item.marginPercentage, item.retailerMarkup, item.gst, item.tds);
                    }

                }
            }
            //Dealer User
            if (role == "Dealer")
            {
                if (ddlUserId != "")
                {
                    foreach (var item in model.Dealeruser)
                    {
                        var entry = db.Slab_Bus.Single(a => a.UserId == ddlUserId);
                        entry.marginPercentage = item.marginPercentage;
                        entry.retailerMarkup = item.retailerMarkup;
                        entry.gst = item.gst;
                        entry.tds = item.tds;
                        db.SaveChanges();
                    }
                }
                else
                {
                    foreach (var item in model.UpdateDealer)
                    {
                        db.Update_BUS_All_userSlab("Dealer", item.marginPercentage, item.retailerMarkup, item.gst, item.tds);
                    }
                }
            }
            //end dealer user

            //Retailer User
            if (role == "Retailer")
            {
                if (ddlUserId != "")
                {
                    foreach (var item in model.Retaileruser)
                    {
                        var entry = db.Slab_Bus.Single(a => a.UserId == ddlUserId);
                        entry.marginPercentage = item.marginPercentage;
                        entry.retailerMarkup = item.retailerMarkup;
                        entry.gst = item.gst;
                        entry.tds = item.tds;
                        db.SaveChanges();
                    }
                }
                else
                {
                    foreach (var item in model.UpdateRetailer)
                    {
                        db.Update_BUS_All_userSlab("Retailer", item.marginPercentage, item.retailerMarkup, item.gst, item.tds);
                    }
                }
            }
            //end Retailer user
            //Whitelabel User
            if (role == "Whitelabel")
            {
                if (ddlUserId != "")
                {
                    foreach (var item in model.Whitelabeluser)
                    {
                        var entry = db.Slab_Bus.Single(a => a.UserId == ddlUserId);
                        entry.marginPercentage = item.marginPercentage;
                        entry.retailerMarkup = item.retailerMarkup;
                        entry.gst = item.gst;
                        entry.tds = item.tds;
                        db.SaveChanges();
                    }
                }
                else
                {
                    foreach (var item in model.UpdateWhitelabel)
                    {
                        db.Update_BUS_All_userSlab("Whitelabel", item.marginPercentage, item.retailerMarkup, item.gst, item.tds);

                    }
                }
            }
            //end API user
            return RedirectToAction("BUS_Slab");
        }

