        [HttpPost]
        public PartialViewResult _UserIRCTCSlab(string role, string userid, IRCTCSlabModel model2, string ddlUserId, string Button, string ddlUserIdrem, string dlmid)
        {
            List<SelectListItem> Provinces = new List<SelectListItem>();
            if (ddlUserId == null)
            {
                IRCTCSlabModel model = new IRCTCSlabModel();
                //List<imps_master_comm> masteruser = null;
                //Master User
                if (role == "Master")
                {
                    if (string.IsNullOrWhiteSpace(userid))
                    {
                        model.Materuser =
                     (from m in db.IRCTC_master_Common_comm
                      join u in db.Users on m.userid equals u.UserId
                      where m.userid == userid
                      select new MasterIRCTCComm
                      {
                          idno = m.idno,
                          userid = m.userid,
