        [HttpPost]
        public ActionResult _UpdateIRCTCSlab(IRCTCSlabModel model, string ddlUserId, string role)
        {
            //master User
            if (role == "Master")
            {
                if (ddlUserId != "")
                {
                    foreach (var item in model.Materuser)
                    {
                        var entry = db.IRCTC_master_Common_comm.Single(a => a.userid == ddlUserId);
                        //entry.tokenvalueDigital = item.tokenvalueDigital;
                        //entry.tokenvaluePhysical = item.tokenvaluePhysical;
                        entry.Commtoken = item.commtokenval;

                        db.SaveChanges();
                    }
                }
                else
                {
                    foreach (var item in model.UpdateMaster)
                    {
                        db.Update_IRCTC_All_userSlab("Master", item.tokenvalue, item.commmastertokenval);
                    }


                }
            }
            //Dealer User
            if (role == "Dealer")
            {
                if (ddlUserId != "")
                {
                    foreach (var item in model.Dealeruser)
                    {
                        var entry = db.IRCTC_distributor_Common_comm.Single(a => a.userid == ddlUserId);
                        //entry.tokenvalueDigital = item.tokenvalueDigital;
                        //entry.commDigital = item.commDigital;
                        entry.Commtoken = item.commdlmtokenval;

                        db.SaveChanges();
                    }
                }
                else
                {
                    foreach (var item in model.UpdateDealer)
                    {
                        db.Update_IRCTC_All_userSlab("Dealer", item.tokenvalue, item.commdlmtokenval);
                    }


                }
            }
            //end dealer user

            //Retailer User
            if (role == "Retailer")
            {
                if (ddlUserId != "")
                {
                    foreach (var item in model.Retaileruser)
                    {
                        var entry = db.IRCTC_retailer_Common_comm.Single(a => a.userid == ddlUserId);
                        entry.tokenval = item.tokenvalue;
                        entry.Commtoken = item.RenewalToken;

                        db.SaveChanges();
                    }
                }
                else
                {
                    foreach (var item in model.UpdateRetailer)
                    {
                        db.Update_IRCTC_dlm_rem_userSlab(ddlUserId, item.tokenvalue, item.RenewalToken);
                    }


                }
            }
            //end Retailer user

            //API User
            if (role == "API")
            {
                if (ddlUserId != "")
                {
                    foreach (var item in model.APIuser)
                    {
                        var entry = db.IRCTC_api_Common_comm.Single(a => a.userid == ddlUserId);
                        entry.tokenval = item.tokenvalue;
                        entry.Commtoken = item.commapiTokenval;
                        db.SaveChanges();
                    }
                }
                else
                {
                    foreach (var item in model.UpdateAPI)
                    {
                        db.Update_IRCTC_All_userSlab("API", item.tokenvalue, item.commapitokenval);
                    }


                }
            }
            //end API user

            //Whitelabel User
            if (role == "Whitelabel")
            {
                if (ddlUserId != "")
                {
                    foreach (var item in model.Whitelabeluser)
                    {
                        var entry = db.IRCTC_whitelabel_Common_comm.Single(a => a.userid == ddlUserId);
                        entry.tokenval = item.tokenvalue;
                        entry.Commtoken = item.commwhitelabeltokenval;

                        db.SaveChanges();
                    }
                }
                else
                {
                    foreach (var item in model.UpdateWhitelabel)
                    {
                        db.Update_IRCTC_All_userSlab("Whitelabel", item.tokenvalue, item.commWhitelabeltokenval);
                    }


                }
            }
            //end API user
            return RedirectToAction("IRCTC_Slab_setting");
        }

        [HttpPost]
        public ActionResult _Common_IRCTC(IRCTCSlabModel model)
        {
            foreach (var item in model.common)
            {
                var entry = db.IRCTC_COMMON_SLAB.Find(item.idno);  // db.Pancard_Common_comm.Find(item.idno);
                entry.tokenvalue = item.tokenvalue;
                entry.mdtokencomm = item.mdtokencomm;
                entry.dlmtokencomm = item.dlmtokencomm;
                entry.retailertoken = item.retailertoken;
                entry.apitoken = item.apitoken;
                entry.Whitelabeltoken = item.Whitelabeltoken;
                entry.dlmremtokenvalue = item.dlmremtokenvalue;
                db.SaveChanges();
            }
            return PartialView(model);
        }




