        public ActionResult microatmspendingTosuccess(string secuirtypass, string filed1, string rrn, string created_at, string transaction_type, decimal amount, string card_payment_type, string card_usage_type, string network)
        {



            var chktranss = db.admin_new_pass.SingleOrDefault();
            DateTime currenttime = DateTime.Now;
            DateTime lastchangedpassdtr = Convert.ToDateTime(chktranss.lastupdatesec);
            lastchangedpassdtr = lastchangedpassdtr.AddDays(Convert.ToInt32(chktranss.secexpdays));
            var defaultht = Decrypt(chktranss.securitypass);
            if (defaultht == "1111" || (lastchangedpassdtr <= currenttime))
            {
                return Json(new { Status = false, Message = "Your security pin is expired or have to be changed!! Please set new security pin" });
            }

            var result = db.MicroAtm_Trans_info.Where(x => x.Requestid == filed1 && x.amount == amount && x.status.ToUpper() == "PENDING").SingleOrDefault();
            if (result != null)
            {
                //  string transaction_id = result.SingleOrDefault();

                var password = Encrypt(secuirtypass);
                var tranpass = (from paa in db.admin_new_pass where paa.securitypass == password select paa).Count();
                if (tranpass > 0)
                {
                    string mtmrrn = rrn;
                    string mtmstatus = "Success";
                    DateTime mtmcreated_at = Convert.ToDateTime(created_at);
                    string mtmtransaction_type = transaction_type;

                    //string mtmpayment_method = payment_method;
                    decimal mtmamount = result.amount.Value;
                    string mtmcard_payment_type = card_payment_type == "" ? null : card_payment_type;
                    string mtmcard_usage_type = card_usage_type;
                    string mtmnetwork = network;
                    string mtmfiled1 = filed1;



                    System.Data.Entity.Core.Objects.ObjectParameter output = new
                      System.Data.Entity.Core.Objects.ObjectParameter("Output", typeof(string));
                    db.updatemicroatm(mtmfiled1, "", mtmrrn, mtmstatus, mtmcreated_at, "", mtmtransaction_type, "", "card", mtmamount, mtmcard_payment_type, mtmcard_usage_type, "", "", "", mtmnetwork, "", output);
                    try
                    {
                        var retailerdetails = db.Retailer_Details.Where(aa => aa.RetailerId == result.retailerid).SingleOrDefault();
                        var dealerdetails = db.Dealer_Details.Where(aa => aa.DealerId == retailerdetails.DealerId).SingleOrDefault();
                        var masterdetails = db.Superstokist_details.Where(aa => aa.SSId == dealerdetails.SSId).SingleOrDefault();

                        var remdetails = db.Remain_reteller_balance.Where(aa => aa.RetellerId == result.retailerid).SingleOrDefault();
                        var dlmdetails = db.Remain_dealer_balance.Where(aa => aa.DealerID == retailerdetails.DealerId).SingleOrDefault();
                        var Masterdetails = db.Remain_superstokist_balance.Where(aa => aa.SuperStokistID == dealerdetails.SSId).SingleOrDefault();

                        var admininfo = db.Admin_details.SingleOrDefault();
                        Backupinfo back = new Backupinfo();

                        var model = new Backupinfo.Addinfo
                        {

                            Websitename = admininfo.WebsiteUrl,
                            RetailerID = result.retailerid,
                            Email = retailerdetails.Email,
                            Mobile = retailerdetails.Mobile,
                            Details = "MicroATM Success",
                            RemainBalance = (decimal)remdetails.Remainamount,
                            Usertype = "Retailer"
                        };
                        back.Microatm(model);

                        var model1 = new Backupinfo.Addinfo
                        {
                            Websitename = admininfo.WebsiteUrl,
                            RetailerID = dealerdetails.DealerId,
                            Email = dealerdetails.Email,
                            Mobile = dealerdetails.Mobile,
                            Details = "MicroATM Success",
                            RemainBalance = Convert.ToDecimal(dlmdetails.Remainamount),
                            Usertype = "Dealer"
                        };
                        back.Microatm(model1);

                        var model2 = new Backupinfo.Addinfo
                        {
                            Websitename = admininfo.WebsiteUrl,
                            RetailerID = masterdetails.SSId,
                            Email = masterdetails.Email,
                            Mobile = masterdetails.Mobile,
                            Details = "MicroATM Success",
                            RemainBalance = Convert.ToDecimal(Masterdetails.Remainamount),
                            Usertype = "Master"
                        };
                        back.Microatm(model2);
                    }
                    catch { }
                    return Json(new { Status = true, Message = "done" });
                }
                else
                {
                    return Json(new { Status = false, Message = "Your Security Password is Wrong!" });
                }

            }

            return Json(new { Status = false, Message = "Something Went Wrong" });
        }

        public ActionResult microatmspendingToFailed(string secuirtypass, string filed1, decimal amount)
        {
            var result = db.MicroAtm_Trans_info.Where(x => x.Requestid == filed1 && x.amount == amount && x.status.ToUpper() == "PENDING").SingleOrDefault();
            if (result != null)
            {
                result.status = "failed";
                db.SaveChanges();
                return Json(new { Status = true, Message = "" });
            }
            return Json(new { Status = false, Message = "Something Went Wrong" });
        }


