        public ActionResult Excel_DeleteUserReport()
        {
            DeleteUser model = new DeleteUser();
            model.Deleteuserall = db.DeleteUserHistories.ToList();

            DataTable dataTbl = new DataTable();
            dataTbl.Columns.Add("Sr", typeof(string));
            dataTbl.Columns.Add("User Role", typeof(string));
            dataTbl.Columns.Add("Firm Name", typeof(string));
            dataTbl.Columns.Add("User Name", typeof(string));
            dataTbl.Columns.Add("Contact No", typeof(string));
            dataTbl.Columns.Add("Register Email", typeof(string));
            dataTbl.Columns.Add("Joining Date", typeof(string));
            dataTbl.Columns.Add("Deleted Date", typeof(string));
            dataTbl.Columns.Add("Recovery Amt", typeof(string));

            var i = 0;
            foreach (var item in model.Deleteuserall)
            {
                i++;
                dataTbl.Rows.Add(i, item.Role, item.FarmName, item.Name, item.ContectNo, item.Email, item.JoiningDate, item.DeleteDate, item.RecoveryAmount);
            }
            var grid = new GridView();
            grid.DataSource = dataTbl;
            grid.DataBind();
            Response.ClearContent();
            Response.Buffer = true;
            Response.AddHeader("content-disposition", "attachment; filename=Deleted_User_Report.xls");
            Response.ContentType = "application/ms-excel";
            Response.Charset = "";
            StringWriter sw = new StringWriter();
            HtmlTextWriter htw = new HtmlTextWriter(sw);
            grid.RenderControl(htw);
            Response.Output.Write(sw.ToString());
            Response.Flush();
            Response.End();
            return View();
        }

