        public ActionResult UpdateCashGst(string type)
        {
            if (type == "CashGSTAc")
            {
                var sts = db.mpos_gst_tds_status.Where(p => p.type_ == "Cash").SingleOrDefault().gststatus;
                if (sts == true)
                {
                    sts = false;
                }
                else
                {
                    sts = true;
                }
                mpos_gst_tds_status objCourse = (from p in db.mpos_gst_tds_status
                                                 where p.type_ == "Cash"
                                                 select p).SingleOrDefault();
                objCourse.gststatus = sts;
                db.SaveChanges();
            }
            else if (type == "CashTDSAc")
            {
                var sts = db.mpos_gst_tds_status.Where(p => p.type_ == "Cash").SingleOrDefault().tdsstaus;
                if (sts == true)
                {
                    sts = false;
                }
                else
                {
                    sts = true;
                }
                mpos_gst_tds_status objCourse = (from p in db.mpos_gst_tds_status
                                                 where p.type_ == "Cash"
                                                 select p).SingleOrDefault();
                objCourse.tdsstaus = sts;
                db.SaveChanges();
            }
            else if (type == "SaleGSTAc")
            {
                var sts = db.mpos_gst_tds_status.Where(p => p.type_ == "Sale").SingleOrDefault().gststatus;
                if (sts == true)
                {
                    sts = false;
                }
                else
                {
                    sts = true;
                }
                mpos_gst_tds_status objCourse = (from p in db.mpos_gst_tds_status
                                                 where p.type_ == "Sale"
                                                 select p).SingleOrDefault();
                objCourse.gststatus = sts;
                db.SaveChanges();
            }
            return RedirectToAction("M_Poss");
        }
