        #region MIcro_atm
        public ActionResult Micro_Atm()
        {
            ViewBag.microatmlimit = db.micro_atm_Purchase_MaxtransectionLimit.Single().maxvalues;

            var data = TempData.Peek("data");
            if (data == "" || data == null)
            {
                return RedirectToAction("tran_passslabsetting");
            }
            else
            {
                MicroAtmSlabModel model = new MicroAtmSlabModel();
                var commonSlab = db.Common_Microatm_comm.ToList();

                model.common = commonSlab;

                model.UserId = new List<SelectListItem>() { new SelectListItem { Text = "No data", Value = "No Data" } };

                var mpossstatus = db.mpos_gst_tds_status.SingleOrDefault(aa => aa.type_ == "Cash");
                ViewBag.Cashgststatus = mpossstatus.gststatus;
                ViewBag.Cashtdsstatus = mpossstatus.tdsstaus;
                var mpossstatus1 = db.mpos_gst_tds_status.SingleOrDefault(aa => aa.type_ == "Sale");
                ViewBag.Salegststatus = mpossstatus1.gststatus;
                ViewBag.Saletdsstatus = mpossstatus1.tdsstaus;

                return View(model);
            }
        }
        [HttpPost]
        public ActionResult _Common_Microatm(MicroAtmSlabModel model)
        {
            foreach (var item in model.common)
            {
                var entry = db.Common_Microatm_comm.Find(item.idno);
                entry.Charge = item.Charge;
                db.SaveChanges();
            }
            var commonSlab = db.Common_Microatm_comm.ToList();
            model.common = commonSlab;
            return PartialView(model);

        }
