        public ActionResult Money_Transfer_Slab()
        {
            var data = TempData.Peek("data");
            if (data == "" || data == null)
            {
                return RedirectToAction("tran_passslabsetting");
            }
            else
            {
                var commslab = db.imps_common_comm.Where(a => a.usertype != "Purchase").ToList();
                DMTSlabModel model = new DMTSlabModel();
                model.common = commslab;
                model.UserId = new List<SelectListItem>() { new SelectListItem { Text = "No data", Value = "No Data" } };
                return View(model);
            }
