        [HttpPost]
        public ActionResult Update_DMTSlab(DMTSlabModel model, string ddlUserId, string role)
        {
            //master User
            if (role == "Master")
            {
                if (ddlUserId != "")
                {
                    foreach (var item in model.Materuser)
                    {
                        var entry = db.imps_master_comm.Single(a => a.userid == ddlUserId);
                        entry.verify_comm = item.verify_comm;
                        entry.comm_1000 = item.comm_1000;
                        entry.comm_2000 = item.comm_2000;
                        entry.comm_3000 = item.comm_3000;
                        entry.comm_4000 = item.comm_4000;
                        entry.comm_5000 = item.comm_5000;
                        entry.gst = item.gst;
                        db.SaveChanges();
                    }
                }
                else
                {
                    foreach (var item in model.UpdateMaster)
                    {
                        db.Update_DMT_All_userSlab("Master", item.verify_comm, item.comm_1000, item.comm_2000, item.comm_3000, item.comm_4000, item.comm_5000, item.gst);
                    }

                }
            }
            //Dealer User
            if (role == "Dealer")
            {
                if (ddlUserId != "")
                {
                    foreach (var item in model.Dealeruser)
                    {
                        var entry = db.imps_dealer_comm.Single(a => a.userid == ddlUserId);
                        entry.verify_comm = item.verify_comm;
