                else
                {
                    foreach (var item in model.UpdateDealer)
                    {
                        db.Update_DMT_All_userSlab("Dealer", item.verify_comm, item.comm_1000, item.comm_2000, item.comm_3000, item.comm_4000, item.comm_5000, item.gst);
