        [HttpPost]
        public ActionResult _Common_Wallet_transfer(WalletTransfer model)
        {
            try
            {
                db.Configuration.AutoDetectChangesEnabled = false;
                foreach (var item in model.common)
                {
                    var entry = db.wallet_imps_common_comm.Find(item.idno);
                    entry.verify_comm = item.verify_comm;
                    entry.comm_1000 = item.comm_1000;
                    entry.comm_2000 = item.comm_2000;
                    entry.comm_3000 = item.comm_3000;
                    entry.comm_4000 = item.comm_4000;
                    entry.comm_5000 = item.comm_5000;
                    entry.comm_6000 = item.comm_6000;
                    entry.comm_7000 = item.comm_7000;
                    entry.comm_8000 = item.comm_8000;
                    entry.comm_9000 = item.comm_9000;
                    entry.comm_10000 = item.comm_10000;

                    entry.comm_11000 = item.comm_11000;
                    entry.comm_12000 = item.comm_12000;
                    entry.comm_13000 = item.comm_13000;
                    entry.comm_14000 = item.comm_14000;
                    entry.comm_15000 = item.comm_15000;
