        public object Dmt_status_check()
        {
            DateTime fiveMinutesAgo = DateTime.Now.AddMinutes(-5);
            var allPending = db.IMPS_transtion_detsils.Where(s => s.Status.ToUpper() == "PENDING" && s.api_name=="VASTWEB" &&  s.trans_time<= fiveMinutesAgo).Select(s => s.trans_id).ToList();
            var allPending_old = db.IMPS_transtion_detsils_old.Where(s => s.Status.ToUpper() == "PENDING" && s.api_name == "VASTWEB" && s.trans_time <= fiveMinutesAgo).Select(s => s.trans_id).ToList();

            allPending.AddRange(allPending_old);

            var token = Responsetoken.gettoken();

            JArray arr = new JArray();

            foreach (string id in allPending)
            {
                JObject obj = new JObject();

                var client = new RestClient("http://api.vastbazaar.com/api/DMTPAYTM/statuschk_NEW?agentid=" + id);
                var request = new RestRequest(Method.POST);
                request.AddHeader("authorization", "bearer " + token);
                IRestResponse response = client.Execute(request);

                dynamic resp = JsonConvert.DeserializeObject(response.Content);
                dynamic json = resp.Content.ADDINFO;

                string status = (string)json.status;
                string message = (string)json.bankrrn;
                string name = (string)json.name;

                obj.Add("id", id);
                obj.Add("Status", status);
                obj.Add("message", message);
                obj.Add("name", name);

                arr.Add(obj);

                try
                {
                    if (status.ToUpper() == "SUCCESS")
                    {
                        if (db.IMPS_transtion_detsils.Any(s => s.trans_id == id))
                            db.Money_transfer_update_by_paytm(id, "SUCCESS", message, name, json.ToString(), "", 0, 0);
                        else
                            db.Money_transfer_update_by_paytm_old(id, "SUCCESS", message, name, json.ToString(), "", 0, 0);
                    }
                    else if (status.ToUpper() == "FAILED")
                    {
                        if (db.IMPS_transtion_detsils.Any(s => s.trans_id == id))
                            db.Money_transfer_update_by_paytm(id, "FAILED", message, name, json.ToString(), "", 0, 0);
                        else
                            db.Money_transfer_update_by_paytm_old(id, "FAILED", message, name, json.ToString(), "", 0, 0);
                    }
                }
                catch
                {

                }

            }

            if (allPending.Count() == 0)
            {
                return new { status = false };
            }
            else
            {
                return new { status = true, data = arr };
            }

        }

        public ActionResult Money_Transfer_Slab_DMT1()
        {
            var data = TempData.Peek("data");
            if (data == "" || data == null)
            {
                return RedirectToAction("tran_passslabsetting");
            }
            else
            {
                var perlimit = db.transtion_limit.SingleOrDefault().Perlimit;
                var permonth = db.transtion_limit.SingleOrDefault().Permonth;
                ViewBag.permonth = permonth;
                ViewBag.perlimit = perlimit;
                var commslab = db.paytm_imps_common_comm1.ToList();
                DMT2SlabModel1 model = new DMT2SlabModel1();
                model.common = commslab;
                model.UserId = new List<SelectListItem>() { new SelectListItem { Text = "No data", Value = "No Data" } };
                return View(model);
            }
        }
