        #region DMT TRANSFER SLAB
        public ActionResult dmtSlab()
        {
            var perlimit = db.transtion_limit.SingleOrDefault().Perlimit;
            var permonth = db.transtion_limit.SingleOrDefault().Permonth;
            ViewBag.permonth = permonth;
            ViewBag.perlimit = perlimit;
            var infochk = db.DMT_Ekyc_Charge.SingleOrDefault().Charge;
            ViewBag.Charge = infochk;
            var commslab = db.imps_common_comm_new.ToList();
            DMT2SlabModel model = new DMT2SlabModel();
            model.commonnew = commslab;
            model.UserId = new List<SelectListItem>() { new SelectListItem { Text = "No data", Value = "No Data" } };
            return View(model);
        }
        public ActionResult ChargeDMTEKYCinfo()
        {
            var infochk = db.DMT_Ekyc_Charge.SingleOrDefault().Charge;
            return Json(infochk, JsonRequestBehavior.AllowGet);
        }
        public ActionResult Update_Dlm_slab(decimal txtcharge)
        {
            var chkinfo = db.DMT_Ekyc_Charge.SingleOrDefault();
            chkinfo.Charge = txtcharge;
            db.SaveChanges();
            return RedirectToAction("dmtSlab");
        }
        public ActionResult fixchargeupdate()
        {
            try
            {
                var chk = db.Imps_Charge_type.ToList();

                if (chk.Count > 0)
                {
                    var chk1 = db.Imps_Charge_type.SingleOrDefault();
                    if (chk[0].fixedsts == false)
                    {
                        chk1.fixedsts = true;
                    }
                    else
                    {
                        chk1.fixedsts = false;
                    }
                    db.SaveChanges();
                }
                else
                {
                    Imps_Charge_type d1 = new Imps_Charge_type();
                    d1.fixedsts = false;
                    db.Imps_Charge_type.Add(d1);
                    db.SaveChanges();

                }

                chk = db.Imps_Charge_type.ToList();
                return Json(chk[0].fixedsts, JsonRequestBehavior.AllowGet);
            }
            catch
            {
                return Json(false, JsonRequestBehavior.AllowGet);
            }
        }
        [HttpPost]
        public ActionResult DMTdataSaves(string role, string userid, decimal? vc, decimal? c1, decimal? c2, decimal? c3, decimal? c4, decimal? c5)
        {
            try
            {
                if (!string.IsNullOrEmpty(role) && !string.IsNullOrEmpty(userid))
                {
                    if (role == "Master")
                    {
                        var ms = db.imps_master_comm_new.Where(s => s.userid == userid).SingleOrDefault();
                        ms.verify_comm = vc;
                        ms.comm_1000 = c1;
                        ms.comm_2000 = c2;
                        ms.comm_3000 = c3;
                        ms.comm_4000 = c4;
                        ms.comm_5000 = c5;
                        db.SaveChanges();

                    }
                    else if (role == "Dealer")
                    {
                        var ms = db.imps_dealer_comm_new.Where(s => s.userid == userid).SingleOrDefault();
                        ms.verify_comm = vc;
                        ms.comm_1000 = c1;
                        ms.comm_2000 = c2;
                        ms.comm_3000 = c3;
                        ms.comm_4000 = c4;
                        ms.comm_5000 = c5;
                        db.SaveChanges();

                    }
                    else if (role == "RDealer")
                    {
                        var ms = db.imps_dlm_rem_comm_new.Where(s => s.userid == userid).SingleOrDefault();
                        ms.verify_comm = vc;
                        ms.comm_1000 = c1;
                        ms.comm_2000 = c2;
                        ms.comm_3000 = c3;
                        ms.comm_4000 = c4;
                        ms.comm_5000 = c5;
                        db.SaveChanges();

                        var rems = db.Retailer_Details.Where(s => s.DealerId == userid && s.ISDeleteuser != true).ToList();



                        foreach (var j in rems)
                        {
                            var rs = db.imps_retailer_comm_new.Where(s => s.userid == j.RetailerId).ToList();
                            if (rs.Count == 0)
                            {
                                imps_retailer_comm_new d1 = new imps_retailer_comm_new();
                                d1.userid = j.RetailerId;
                                d1.verify_comm = vc;
                                d1.comm_1000 = c1;
                                d1.comm_2000 = c2;
                                d1.comm_3000 = c3;
                                d1.comm_4000 = c4;
                                d1.comm_5000 = c5;
                                d1.gst_sts = true;
                                d1.tds_sts = true;
                                db.imps_retailer_comm_new.Add(d1);
                                db.SaveChanges();
                            }

                        }

                        foreach (var i in rems)
                        {
                            var rs = db.imps_retailer_comm_new.Where(s => s.userid == i.RetailerId).ToList();
                            if (rs.Count == 1)
                            {
                                var rs1 = db.imps_retailer_comm_new.Where(s => s.userid == i.RetailerId).SingleOrDefault();
                                rs1.verify_comm = vc;
                                rs1.comm_1000 = c1;
                                rs1.comm_2000 = c2;
                                rs1.comm_3000 = c3;
                                rs1.comm_4000 = c4;
                                rs1.comm_5000 = c5;
                                db.SaveChanges();
                            }

                        }


                    }
                    else if (role == "API")
                    {
                        var rs1 = db.imps_api_comm_new.Where(s => s.userid == userid).SingleOrDefault();
                        rs1.verify_comm = vc;
                        rs1.comm_1000 = c1;
                        rs1.comm_2000 = c2;
                        rs1.comm_3000 = c3;
                        rs1.comm_4000 = c4;
                        rs1.comm_5000 = c5;
                        db.SaveChanges();
                    }
                    else if (role == "Whitelabel")
                    {
                        var rs1 = db.imps_whitelabel_comm_new.Where(s => s.userid == userid).SingleOrDefault();
                        rs1.verify_comm = vc;
                        rs1.comm_1000 = c1;
                        rs1.comm_2000 = c2;
                        rs1.comm_3000 = c3;
                        rs1.comm_4000 = c4;
                        rs1.comm_5000 = c5;
                        db.SaveChanges();
                    }
                    else if (role == "Retailer")
                    {
                        var rs1 = db.imps_retailer_comm_new.Where(s => s.userid == userid).SingleOrDefault();
                        rs1.verify_comm = vc;
                        rs1.comm_1000 = c1;
                        rs1.comm_2000 = c2;
                        rs1.comm_3000 = c3;
                        rs1.comm_4000 = c4;
                        rs1.comm_5000 = c5;
                        db.SaveChanges();
                    }
                    return Json("Success", JsonRequestBehavior.AllowGet);
                }
                else
                {
                    return Json("Something wrong", JsonRequestBehavior.AllowGet);
                }
            }
            catch
            {
                return Json("Failed", JsonRequestBehavior.AllowGet);
            }

        }
        [HttpPost]
        public ActionResult _Common_Money_transfer_new(DMT2SlabModel model)
        {
            try
            {
                db.Configuration.AutoDetectChangesEnabled = false;
                foreach (var item in model.commonnew)
                {
                    var entry = db.imps_common_comm_new.Find(item.idno);
                    entry.Verify_comm = item.Verify_comm == null ? 0 : item.Verify_comm;
                    entry.Comm_1000 = item.Comm_1000 == null ? 0 : item.Comm_1000;
                    entry.Comm_2000 = item.Comm_2000 == null ? 0 : item.Comm_2000;
                    entry.Comm_3000 = item.Comm_3000 == null ? 0 : item.Comm_3000;
                    entry.Comm_4000 = item.Comm_4000 == null ? 0 : item.Comm_4000;

                    entry.Comm_5000 = item.Comm_5000 == null ? 0 : item.Comm_5000;

                    db.ChangeTracker.DetectChanges();
                    db.SaveChanges();
                }
            }
            finally
            {
                db.Configuration.AutoDetectChangesEnabled = true;
            }


            return RedirectToAction("dmtSlab");
        }
