        public ActionResult UpdateLimit(decimal per = 0)
        {
            var limit = db.transtion_limit.SingleOrDefault();
            if (per == 50000)
            {
                limit.Permonth = per;
                db.SaveChanges();
            }
            else if (per == 200000)
            {
                limit.Permonth = per;
                db.SaveChanges();
            }
            else if (per == 500000)
            {
                limit.Permonth = per;
                db.SaveChanges();
            }
            return Json("okok", JsonRequestBehavior.AllowGet);
        }
        public ActionResult Pertansectonmoneytransfer(decimal per = 0)
        {
            var limit = db.transtion_limit.SingleOrDefault();
            if (per == 5000)
            {
                limit.Perlimit = 5000;
                db.SaveChanges();
                return Json("okok", JsonRequestBehavior.AllowGet);
            }
            if (per == 25000)
            {
                limit.Perlimit = 25000;
                db.SaveChanges();
                return Json("okok", JsonRequestBehavior.AllowGet);
            }
            if (per == 49750)
            {
                limit.Perlimit = 49750;
                db.SaveChanges();
                return Json("okok", JsonRequestBehavior.AllowGet);
            }
            if (per == 50000)
            {
                limit.Perlimit = 50000;
                db.SaveChanges();
                return Json("okok", JsonRequestBehavior.AllowGet);
            }
            return Json("", JsonRequestBehavior.AllowGet);
        }
