        public ActionResult Dmt_Purchase()
        {
            var show = db.DMTpurchases.ToList();
            ViewData["update"] = TempData["msg"];
            TempData.Remove("msg");
            return View(show);
        }
        [HttpPost]
        public ActionResult Dmt_Purchase_comm(int txtid, decimal commission)
        {
            DMTpurchase obj = (from pp in db.DMTpurchases
                               where pp.idno == txtid
                               select pp).FirstOrDefault();
            obj.comm = commission;
            db.SaveChanges();
            TempData["msg"] = "Update Successfully.";
            return RedirectToAction("Dmt_Purchase");
        }
