        public ActionResult UpdatePanCardLimit(int? per)
        {
            var result = db.PancardMinTokenlimits.Find(db.PancardMinTokenlimits.SingleOrDefault().id);
            if (result != null)
            {

                result.minmium = per;
                db.SaveChanges();
                return Json("okok", JsonRequestBehavior.AllowGet);
            }
            return Json("", JsonRequestBehavior.AllowGet);

        }

        public ActionResult Pancard_Slab_Setting()
        {
            var data = TempData.Peek("data");
            if (data == "" || data == null)
            {
                return RedirectToAction("tran_passslabsetting");
            }
            else
            {
                var commslab = db.Pancard_common_comm_new.ToList();
                PancardSlabModel model = new PancardSlabModel();
                model.common = commslab;
                ViewBag.pancardlimit = db.PancardMinTokenlimits.SingleOrDefault().minmium ?? 0;
                model.UserId = new List<SelectListItem>() { new SelectListItem { Text = "No data", Value = "No Data" } };
                return View(model);
            }
        }

