        [HttpPost]
        public ActionResult _Common_pancard(PancardSlabModel model)
        {
            foreach (var item in model.common)
            {
                var entry = db.Pancard_common_comm_new.Find(item.idno);
                entry.retailer_comm = item.retailer_comm;
                entry.dealer_comm = item.dealer_comm;
                entry.master_comm = item.master_comm;

                db.SaveChanges();
            }
            return PartialView(model);
        }
