        #region Prepaid and DTH Slab Setting
        public ActionResult Prepaid_Slab_setting()
        {
            var data = TempData.Peek("data");
            if (data == "" || data == null)
            {
                return RedirectToAction("tran_passslabsetting");
            }
            else
            {
                PrepaidSlab model = new PrepaidSlab();
                model.AmountRange = (from p in db.Recharge_Amount_range
                                     select new Recharge_Amount_range_info
                                     {
                                         idno = p.idno,
                                         maximum1 = p.maximum1,
                                         maximum2 = p.maximum2
                                     }).ToList();
                model.common =
               (from p in db.prepaid_common_comm
                join opt in db.Operator_Code on p.optcode equals opt.Operator_id.ToString()
                select new PrepaidCommon
                {
                    idno = p.idno,
                    optcode = p.optcode,
                    OperatorName = opt.operator_Name,
                    mastercomm = p.mastercomm,
                    mastercomm1 = p.mastercomm1,
                    mastercomm2 = p.mastercomm2,
                    dlmcomm = p.dlmcomm,
                    dlmcomm1 = p.dlmcomm1,
                    dlmcomm2 = p.dlmcomm2,
                    dlm_rem_comm = p.dlm_rem_comm,
                    dlm_rem_comm1 = p.dlm_rem_comm1,
                    dlm_rem_comm2 = p.dlm_rem_comm2,
                    retailercomm = p.retailercomm,
                    apicomm = p.apicomm,
                    apicomm1 = p.apicomm1,
                    apicomm2 = p.apicomm2,
                    whitelabelcomm = p.whitelabelcomm,
                    whitelabelcomm1 = p.whitelabelcomm1,
                    whitelabelcomm2 = p.whitelabelcomm2
                }).OrderBy(p => p.OperatorName).ToList();
                return View(model);
            }
        }
        [HttpPost]
        public ActionResult _prepaid_comm(PrepaidSlab model)
        {
            foreach (var item in model.common)
            {
                var entry = db.prepaid_common_comm.Find(item.idno);
                entry.mastercomm = item.mastercomm;
                entry.mastercomm1 = item.mastercomm1;
                entry.mastercomm2 = item.mastercomm2;
                entry.dlmcomm = item.dlmcomm;
                entry.dlmcomm1 = item.dlmcomm1;
                entry.dlmcomm2 = item.dlmcomm2;
                entry.dlm_rem_comm = item.dlm_rem_comm;
                entry.dlm_rem_comm1 = item.dlm_rem_comm1;
                entry.dlm_rem_comm2 = item.dlm_rem_comm2;
                entry.retailercomm = item.retailercomm;
                entry.apicomm = item.apicomm;
                entry.apicomm1 = item.apicomm1;
                entry.apicomm2 = item.apicomm2;
                entry.whitelabelcomm = item.whitelabelcomm;
                entry.whitelabelcomm1 = item.whitelabelcomm1;
                entry.whitelabelcomm2 = item.whitelabelcomm2;
                db.SaveChanges();
            }
            PrepaidSlab pmodel = new PrepaidSlab();
            pmodel.AmountRange = (from p in db.Recharge_Amount_range
                                  select new Recharge_Amount_range_info
                                  {
                                      idno = p.idno,
                                      maximum1 = p.maximum1,
                                      maximum2 = p.maximum2
                                  }).ToList();

            pmodel.common =
           (from p in db.prepaid_common_comm
            join opt in db.Operator_Code on p.optcode equals opt.Operator_id.ToString()
            select new PrepaidCommon
            {
                idno = p.idno,
                optcode = p.optcode,
                OperatorName = opt.operator_Name,
                mastercomm = p.mastercomm,
                mastercomm1 = p.mastercomm1,
                mastercomm2 = p.mastercomm2,
                dlmcomm = p.dlmcomm,
                dlmcomm1 = p.dlmcomm1,
                dlmcomm2 = p.dlmcomm2,
                dlm_rem_comm = p.dlm_rem_comm,
                dlm_rem_comm1 = p.dlm_rem_comm1,
                dlm_rem_comm2 = p.dlm_rem_comm2,
                retailercomm = p.retailercomm,
                apicomm = p.apicomm,
                apicomm1 = p.apicomm1,
                apicomm2 = p.apicomm2,
                whitelabelcomm = p.whitelabelcomm,
                whitelabelcomm1 = p.whitelabelcomm1,
                whitelabelcomm2 = p.whitelabelcomm2
            }).OrderBy(p => p.OperatorName).ToList();
            return PartialView(pmodel);
            // return RedirectToAction("Prepaid_Slab_setting");
        }
        [HttpPost]
        public PartialViewResult _UserPrepaidSlab(string role, string userid, string ddlUserIdrem, string dlmid, PrepaidSlab model2, string ddlUserId, string Button)
        {
            if (ddlUserId == null)
            {
                PrepaidSlab model1 = new PrepaidSlab();
                model1.AmountRange = (from p in db.Recharge_Amount_range
                                      select new Recharge_Amount_range_info
                                      {
                                          idno = p.idno,
                                          maximum1 = p.maximum1,
                                          maximum2 = p.maximum2
                                      }).ToList();
                //master user
                if (role == "Master")
                {
                    if (string.IsNullOrWhiteSpace(userid))
                    {
                        model1.Materuser =
                        (from m in db.prepaid_master_comm
                         join u in db.Users on m.userid equals u.UserId
                         join opt in db.Operator_Code on m.optcode equals opt.Operator_id.ToString()
                         where m.userid == userid
                         select new PrepaidMaster
                         {
                             idno = m.idno,
                             userid = m.userid,
                             optcode = m.optcode,
                             OperatorName = opt.operator_Name,
                             comm = m.comm,
                             comm1 = m.comm1,
                             comm2 = m.comm2,
                             Email = u.Email,
                             RolesName = "Master"
                         }).OrderBy(p => p.OperatorName).ToList();
                        List<SelectListItem> Provinces = new List<SelectListItem>();
                        var list = db.Superstokist_details.Select(a => new SelectListItem { Text = a.FarmName, Value = a.SSId, Selected = a.SSId == userid ? true : false }).ToList();
                        model1.UserId = list;
                        model1.RetailerId = Provinces;
                        model1.allow = false;
                        model1.Email = "";
                        model1.Name = "";
                        model1.Phone = "";
                    }
                    else
                    {
                        model1.Materuser =
                         (from m in db.prepaid_master_comm
                          join u in db.Users on m.userid equals u.UserId
                          join opt in db.Operator_Code on m.optcode equals opt.Operator_id.ToString()
                          where m.userid == userid
                          select new PrepaidMaster
                          {
                              idno = m.idno,
                              userid = m.userid,
                              optcode = m.optcode,
                              OperatorName = opt.operator_Name,
                              comm = m.comm,
                              comm1 = m.comm1,
                              comm2 = m.comm2,
                              Email = u.Email,
                              RolesName = "Master"
                          }).OrderBy(g => g.OperatorName).ToList();
                        var super = db.Superstokist_details.ToList();
                        var masterallow = db.Master_allow_commission.Where(aa => aa.masterid == userid).SingleOrDefault().allowcommision;
                        List<SelectListItem> Provinces = new List<SelectListItem>();
                        var list = super.Select(a => new SelectListItem { Text = a.FarmName, Value = a.SSId, Selected = a.SSId == userid ? true : false }).ToList();
                        model1.UserId = list;
                        model1.RetailerId = Provinces;
                        model1.Email = super.Where(aa => aa.SSId == userid).SingleOrDefault().Email;
                        model1.Name = super.Where(aa => aa.SSId == userid).SingleOrDefault().SuperstokistName;
                        model1.Phone = super.Where(aa => aa.SSId == userid).SingleOrDefault().Mobile;
                        model1.allow = masterallow;
                    }
                    model1.UpdateMaster =
                     (from com in db.prepaid_common_comm
                      join opt in db.Operator_Code on com.optcode equals opt.Operator_id.ToString()
                      select new UpdatePrepaidMaster
                      {
                          idno = com.idno,
                          OperatorName = opt.operator_Name,
                          comm = com.mastercomm,
                          comm1 = com.mastercomm1,
                          comm2 = com.mastercomm2,
                          optcode = com.optcode,
                      }).Distinct().OrderBy(a => a.OperatorName).ToList();
                }
                //end user
                //Dealer User
                if (role == "Dealer")
                {
                    if (string.IsNullOrWhiteSpace(userid))
                    {

                        model1.Dealeruser =
                     (from m in db.prepaid_dealer_comm
                      join u in db.Users on m.userid equals u.UserId
                      join opt in db.Operator_Code on m.optcode equals opt.Operator_id.ToString()
                      where m.userid == userid
                      select new PrepaidDealer
                      {
                          idno = m.idno,
                          userid = m.userid,
                          optcode = m.optcode,
                          OperatorName = opt.operator_Name,
                          comm = m.comm,
                          comm1 = m.comm1,
                          comm2 = m.comm2,
                          Email = u.Email,
                          RolesName = "Dealer"
                      }).OrderBy(p => p.OperatorName).ToList();
                        List<SelectListItem> Provinces = new List<SelectListItem>();
                        var list = db.Dealer_Details.Select(a => new SelectListItem { Text = a.FarmName, Value = a.DealerId, Selected = a.DealerId == userid ? true : false }).ToList();
                        model1.UserId = list;
                        model1.RetailerId = Provinces;
                        model1.Email = "";
                        model1.Name = "";
                        model1.Phone = "";


                    }
                    else
                    {
                        model1.Dealeruser =
                         (from m in db.prepaid_dealer_comm
                          join u in db.Users on m.userid equals u.UserId
                          join opt in db.Operator_Code on m.optcode equals opt.Operator_id.ToString()
                          where m.userid == userid
                          select new PrepaidDealer
