        #region Gift card Slab Setting
        public ActionResult Giftcard_Slab_setting()
        {
            var data = TempData.Peek("data");
            if (data == "" || data == null)
            {
                return RedirectToAction("tran_passslabsetting");
            }
            else
            {
                GiftcardSlab model = new GiftcardSlab();
                model.common =
               (from p in db.gift_common_comm
                join opt in db.Operator_Code on p.optcode equals opt.Operator_id.ToString()
                select new GiftcardCommon
                {
                    idno = p.idno,
                    optcode = p.optcode,
                    OperatorName = opt.operator_Name,
                    mastercomm = p.mastercomm,
                    dlmcomm = p.dealercomm,
                    retailercomm = p.retailercomm,
                    whitelabelcomm = p.whitelabelcomm

                }).ToList();
                return View(model);

            }
        }
        [HttpPost]
        public ActionResult _common_giftCard(GiftcardSlab model)
        {
            try
            {
                db.Configuration.AutoDetectChangesEnabled = false;
                foreach (var item in model.common)
                {
                    var entry = db.gift_common_comm.Find(item.idno);
                    entry.mastercomm = item.mastercomm;
                    entry.dealercomm = item.dlmcomm;
                    entry.retailercomm = item.retailercomm;
                    entry.whitelabelcomm = item.whitelabelcomm;
                    db.ChangeTracker.DetectChanges();
                    db.SaveChanges();
                }
            }
            finally
            {
                db.Configuration.AutoDetectChangesEnabled = true;
            }
            model.common =
           (from p in db.gift_common_comm
