                          join opt in db.Operator_Code on m.optcode equals opt.Operator_id.ToString()
                          where m.whitelabelid == userid
                          select new GiftcardWhitelabel
                          {
                              idno = m.idno,
                              userid = m.whitelabelid,
                              optcode = m.optcode,
                              OperatorName = opt.operator_Name,
                              comm = m.comm,
                              Email = u.Email,
                              RolesName = "Whitelabel"
                          }).OrderByDescending(g => g.idno).ToList();
                        var white = db.WhiteLabel_userList.ToList();
                        var list = white.Select(a => new SelectListItem { Text = a.FrmName, Value = a.WhiteLabelID, Selected = a.WhiteLabelID == userid ? true : false }).ToList();
                        model.UserId = list;
                        model.Email = white.Where(aa => aa.WhiteLabelID == userid).SingleOrDefault().EmailId;
                        model.Name = white.Where(aa => aa.WhiteLabelID == userid).SingleOrDefault().Name;
                        model.Phone = white.Where(aa => aa.WhiteLabelID == userid).SingleOrDefault().Mobile;
                    }
