                          optcode = com.optcode,


                      }).Distinct().OrderByDescending(a => a.idno).ToList();

                }
                return PartialView(model);
            }
        }

        [HttpPost]
        public ActionResult _UpdateGiftcardSlab(GiftcardSlab model, string ddlUserId, string role, string Retailerid)
        {
            if (role == "Master")
            {
                if (ddlUserId != "")
                {
                    foreach (var item in model.Materuser)
                    {
                        var entry = db.giftcard_master_comm.Single(a => a.masterid == ddlUserId && a.opt_code == item.optcode);
                        entry.comm = item.comm;
                        db.SaveChanges();
                    }
                }
                else
                {
                    foreach (var item in model.UpdateMaster)
                    {
                        db.update_All_Giftcard_comm("Master", item.optcode, item.comm, "");
                    }
                }
            }
            if (role == "Dealer")
            {
                if (ddlUserId != "")
                {
                    foreach (var item in model.Dealeruser)
                    {
                        var entry = db.giftcard_dealer_comm.Single(a => a.dealerid == ddlUserId && a.optcode == item.optcode);
                        entry.comm = item.comm;
                        db.SaveChanges();
                    }
                }
                else
                {
                    foreach (var item in model.UpdateDealer)
                    {
                        db.update_All_Giftcard_comm("Dealer", item.optcode, item.comm, "");
                    }
                }
            }
            if (role == "Retailer")
            {
                if (Retailerid != "")
                {
                    if (model.Retaileruser != null)
                    {
                        foreach (var item in model.Retaileruser)
                        {
                            var entry = db.giftcard_retailer_comm.Single(a => a.retailerid == Retailerid && a.optcode == item.optcode);
                            entry.comm = item.comm;
                            db.SaveChanges();
                        }
                    }
                }
                else
                {
                    foreach (var item in model.UpdateRetailer)
                    {
                        db.update_All_Giftcard_comm("Retailer", item.optcode, item.comm, ddlUserId);
                    }
                }
            }

            if (role == "Whitelabel")
            {
                if (ddlUserId != "")
                {
                    foreach (var item in model.Whitelabeluser)
                    {
                        var entry = db.giftcard_whitelabel_comm.Single(a => a.whitelabelid == ddlUserId && a.optcode == item.optcode);
                        entry.comm = item.comm;
                        db.SaveChanges();
                    }
                }
                else
                {
                    foreach (var item in model.UpdateWhitelabel)
                    {
                        db.update_All_Giftcard_comm("Whitelabel", item.optcode, item.comm, "");
                    }
                }
            }
            return RedirectToAction("Giftcard_Slab_setting");
        }
