        #region Security Slab Setting
        public ActionResult Security_Slab_setting()
        {
            var data = TempData.Peek("data");
            if (data == "" || data == null)
            {
                return RedirectToAction("tran_passslabsetting");
            }
            else
            {
                SecuritySlab model = new SecuritySlab();
                model.common =
               (from p in db.Security_common_comm
                select new SecurityCommon
                {
                    idno = p.idno,
                    optcode = "Norton",
                    OperatorName = "Norton",
                    mastercomm = p.mastercomm,
                    dlmcomm = p.dlmcomm,
                    dlm_rem_comm = p.dlm_rem_comm,
                    whitelabelcomm = p.whitelabelcomm,
                    purchase = p.purchase
                }).ToList();
                return View(model);
            }
        }
        [HttpPost]
        public ActionResult _Security_comm(SecuritySlab model)
        {
            foreach (var item in model.common)
            {
                var entry = db.Security_common_comm.Find(item.idno);
                entry.mastercomm = item.mastercomm;
                entry.dlmcomm = item.dlmcomm;
                entry.dlm_rem_comm = item.dlm_rem_comm;
                entry.whitelabelcomm = item.whitelabelcomm;
                entry.purchase = item.purchase;
                db.SaveChanges();
            }
            SecuritySlab pmodel = new SecuritySlab();
            pmodel.common =
           (from p in db.Security_common_comm
            select new SecurityCommon
            {
                idno = p.idno,
                optcode = "Norton",
                OperatorName = "Norton",
                mastercomm = p.mastercomm,
                dlmcomm = p.dlmcomm,
                dlm_rem_comm = p.dlm_rem_comm,
                whitelabelcomm = p.whitelabelcomm,
                purchase = p.purchase
            }).ToList();
            return PartialView(pmodel);
            // return RedirectToAction("Prepaid_Slab_setting");
        }
