        #region Whatsapp Slab Setting
        public ActionResult WhatsappCommon()
        {
            var data = TempData.Peek("data");
            if (data == "" || data == null)
            {
                return RedirectToAction("tran_passslabsetting");
            }
            else
            {
                var tokenapi = Responsetoken.gettoken();

                var client = new RestClient("http://api.vastbazaar.com/api/Web/otherservicepricelist");
                var request = new RestRequest(Method.POST);
                request.AddHeader("Authorization", "Bearer " + tokenapi);
                request.AddHeader("Content-Type", "application/json");
                var tbody = new
                {
                    servicenm = "WHATSAPP"
                };
                var infodata = JsonConvert.SerializeObject(tbody);
                request.AddParameter("application/json", infodata, ParameterType.RequestBody);
                IRestResponse response = client.Execute(request);
                var responsechk = response.Content;
                dynamic outp = JsonConvert.DeserializeObject(responsechk);

                var addinfo = outp.Content.ADDINFO.datalist;
                var duedatechk = outp.Content.ADDINFO.duedate;


                List<otherservices> Details1 = addinfo.ToObject<List<otherservices>>();
                var p1 = Details1.Where(aa => aa.servicenm == "WHATSAPP").SingleOrDefault().p1;
                var p2 = Details1.Where(aa => aa.servicenm == "WHATSAPP").SingleOrDefault().p2;
                var p3 = Details1.Where(aa => aa.servicenm == "WHATSAPP").SingleOrDefault().p3;
                var gst1 = (p1 * 18) / 100;
                var gst2 = (p2 * 18) / 100;
                var gst3 = (p3 * 18) / 100;

                p1 = p1 + gst1;
                p2 = p2 + gst2;
                p3 = p3 + gst3;

                var t1 = Details1.Where(aa => aa.servicenm == "WHATSAPP").SingleOrDefault().t1;
                var t2 = Details1.Where(aa => aa.servicenm == "WHATSAPP").SingleOrDefault().t2;
                var t3 = Details1.Where(aa => aa.servicenm == "WHATSAPP").SingleOrDefault().t3;

                whatsappslab model = new whatsappslab();
                model.common =
               (from p in db.Whatsapp_Common
                select new WhatsappCommon
                {
                    idno = p.idno,
                    P1 = p.P1,
                    P2 = p.P2,
                    P3 = p.P3,
                    T1 = t1,
                    T2 = t2,
                    T3 = t3,
                    PP1 = p1,
                    PP2 = p2,
                    PP3 = p3
                }).ToList();
                return View(model);
            }
        }
