        [HttpPost]
        public ActionResult _UpdateWaterSlab(Waterslab model, string ddlUserId, string role, string Retailerid)
        {
            if (role == "Master")
            {
                if (ddlUserId != "")
                {
                    foreach (var item in model.Materuser)
                    {
                        var entry = db.Water_master_comm.Single(a => a.userid == ddlUserId && a.optcode == item.optcode);
                        entry.comm = item.comm;
                        db.SaveChanges();
                    }
                }
                else
                {
                    foreach (var item in model.UpdateMaster)
                    {
                        db.update_All_Water_comm("Master", item.optcode, item.comm, "");
                    }
                }
            }
            if (role == "Dealer")
            {
                if (ddlUserId != "")
                {
                    foreach (var item in model.Dealeruser)
                    {
                        var entry = db.Water_dealer_comm.Single(a => a.userid == ddlUserId && a.optcode == item.optcode);
                        entry.comm = item.comm;
                        db.SaveChanges();
                    }
                }
                else
                {
                    foreach (var item in model.UpdateDealer)
                    {
                        db.update_All_Water_comm("Dealer", item.optcode, item.comm, "");
                    }
                }
            }
            if (role == "Retailer")
            {
                if (Retailerid != "")
                {
                    if (model.Retaileruser != null)
                    {
                        foreach (var item in model.Retaileruser)
                        {
                            var entry = db.Water_retailer_comm.Single(a => a.userid == Retailerid && a.optcode == item.optcode);
                            entry.comm = item.comm;
                            db.SaveChanges();
                        }
                    }
                }
                else
                {
                    foreach (var item in model.UpdateRetailer)
                    {
                        db.update_All_Water_comm("Retailer", item.optcode, item.comm, ddlUserId);
                    }
                }
            }
            if (role == "API")
            {
                if (ddlUserId != "")
                {
                    foreach (var item in model.APIuser)
                    {
                        var entry = db.Water_api_comm.Single(a => a.userid == ddlUserId && a.optcode == item.optcode);
                        entry.comm = item.comm;
                        db.SaveChanges();
                    }
                }
                else
                {
                    foreach (var item in model.UpdateAPI)
                    {
                        db.update_All_Water_comm("API", item.optcode, item.comm, "");
                    }
                }
            }
            if (role == "Whitelabel")
            {
                if (ddlUserId != "")
                {
                    foreach (var item in model.Whitelabeluser)
                    {
                        var entry = db.Water_whitelabel_comm.Single(a => a.userid == ddlUserId && a.optcode == item.optcode);
                        entry.comm = item.comm;
                        db.SaveChanges();
                    }
                }
                else
                {
                    foreach (var item in model.UpdateWhitelabel)
                    {
                        db.update_All_Water_comm("Whitelabel", item.optcode, item.comm, "");
                    }
                }
            }
            return RedirectToAction("Water_Slab_setting");
        }
        public ActionResult Watercharge()
        {
            var chkk = db.Utility_Charge_type.Where(aa => aa.rch_type == "Water").SingleOrDefault();
            if (chkk.Fixedrs == true)
            {
                chkk.Fixedrs = false;
            }
            else
            {
                chkk.Fixedrs = true;
            }
            db.SaveChanges();
            return RedirectToAction("Water_Slab_setting");
        }
