        [HttpGet]
        public ActionResult DthConnection_Slab_setting()
        {
            var data = TempData.Peek("data");
            if (data == "" || data == null)
            {
                return RedirectToAction("tran_passslabsetting");
            }
            else
            {
                DthConnSlab model = new DthConnSlab();
                model.common =
               (from p in db.DthConnection_common_comm
                join opt in db.Operator_Code on p.optcode equals opt.Operator_id.ToString()
                select new DthConnectionCommon
                {
                    idno = p.idno,
                    optcode = p.optcode,
                    OperatorName = opt.operator_Name,
                    mastercomm = p.mastercomm,
                    dlmcomm = p.dlmcomm,
                    retailercomm = p.retailercomm,
                    apicomm = p.apicomm,
                    whitelabelcomm = p.whitelabelcomm

                }).ToList();
                return View(model);
            }
        }
        [HttpPost]
        public ActionResult DthConnection_Slab_setting(DthConnSlab model)
        {
            foreach (var item in model.common)
            {
                var entry = db.DthConnection_common_comm.Find(item.idno);
                entry.mastercomm = item.mastercomm;
                entry.dlmcomm = item.dlmcomm;
                entry.retailercomm = item.retailercomm;
                entry.apicomm = item.apicomm;
                entry.whitelabelcomm = item.whitelabelcomm;
                db.SaveChanges();
            }
            return RedirectToAction("DthConnection_Slab_setting");
        }
