                {
                    if (model.Retaileruser != null)
                    {
                        foreach (var item in model.Retaileruser)
                        {
                            var entry = db.DthConnection_retailer_comm.Single(a => a.userid == Retailerid && a.optcode == item.optcode);
                            entry.comm = item.comm;
                            db.SaveChanges();
                        }
                    }
                }
                else
                {
                    foreach (var item in model.UpdateRetailer)
                    {
                        db.update_All_DthConnection_comm("Retailer", item.optcode, item.comm, ddlUserId);
                    }
                }
            }
            if (role == "API")
            {
                if (ddlUserId != "")
                {
                    foreach (var item in model.APIuser)
                    {
                        var entry = db.DthConnection_api_comm.Single(a => a.userid == ddlUserId && a.optcode == item.optcode);
                        entry.comm = item.comm;
                        db.SaveChanges();
                    }
                }
                else
                {
                    foreach (var item in model.UpdateAPI)
                    {
                        db.update_All_DthConnection_comm("API", item.optcode, item.comm, "");
                    }
                }
            }
            if (role == "Whitelabel")
            {
                if (ddlUserId != "")
                {
                    foreach (var item in model.Whitelabeluser)
                    {
                        var entry = db.DthConnection_whitelabel_comm.Single(a => a.userid == ddlUserId && a.optcode == item.optcode);
                        entry.comm = item.comm;
                        db.SaveChanges();
                    }
                }
                else
                {
                    foreach (var item in model.UpdateWhitelabel)
                    {
                        db.update_All_DthConnection_comm("Whitelabel", item.optcode, item.comm, "");
                    }
                }
            }
            return RedirectToAction("DthConnection_Slab_setting");
        }
        public ActionResult DTHConnectionReport()
        {
            string txt_frm_date = DateTime.Now.ToString();
            string txt_to_date = DateTime.Now.ToString();
            string frm_date = Convert.ToDateTime(txt_frm_date).Date.ToString("yyyy-MM-dd");
