        public ActionResult PostpaidUtility_Slab_setting()
        {
            var data = TempData.Peek("data");
            if (data == "" || data == null)
            {
                return RedirectToAction("tran_passslabsetting");
            }
            else
            {
                var commtime = db.utility_comm_bytiming.SingleOrDefault();
                if (commtime == null)
                {
                    utility_comm_bytiming per = new utility_comm_bytiming();
                    per.commper = 100;
                    per.commper1 = 100;
                    per.Date = DateTime.Now;
                    per.date1 = DateTime.Now;
                    per.Typefor = "Utilities";
                    db.utility_comm_bytiming.Add(per);
                    db.SaveChanges();
                }
                var comper = db.utility_comm_bytiming.Where(a => a.Typefor == "Utilities").SingleOrDefault();
                ViewBag.unload1 = comper.commper;
                ViewBag.unload2 = comper.commper1;
                var ent = Convert.ToDateTime(comper.Date);
                ViewBag.date123 = ent.ToShortDateString();
                var ent1 = Convert.ToDateTime(comper.date1);
                ViewBag.date321 = ent1.ToShortDateString();
                PostpaidUtilitySlab model = new PostpaidUtilitySlab();
                model.common =
               (from p in db.utility_common_comm
                join opt in db.Operator_Code on p.optcode equals opt.Operator_id.ToString()
                where opt.Operator_type == "Broadband"
                select new PostpaidCommon
                {
                    idno = p.idno,
                    optcode = p.optcode,
                    OperatorName = opt.operator_Name,
                    mastercomm = p.mastercomm,
                    dlmcomm = p.dlmcomm,
                    retailercomm = p.retailercomm,
                    dlm_rem_comm = p.dlm_rem_comm,
                    apicomm = p.apicomm,
                    whitelabelcomm = p.whitelabelcomm,
                    gst = p.gst,
                    surcharge = p.SurCharge,
                    opttype = opt.Operator_type
                }).OrderBy(aa => aa.opttype).ToList();
                var opttype = db.Operator_Code.Where(
                aa => aa.Operator_type == "Broadband" || aa.Operator_type == "Electricity"
                || aa.Operator_type == "Gas" || aa.Operator_type == "Insurance"
                || aa.Operator_type == "Landline" || aa.Operator_type == "Loan"
                || aa.Operator_type == "PostPaid" || aa.Operator_type == "Water" || aa.Operator_type == "LPG Gas" || aa.Operator_type == "Fastag").OrderBy(aa => aa.Operator_type).ToList();
                var list = opttype.Select(a => new SelectListItem { Text = a.Operator_type, Value = a.Operator_type });
                model.OPttype = list.GroupBy(x => x.Text).Select(x => x.First()).ToList();
                var info = (from p in db.Utility_extra_comm_Retailer
                            join opt in db.Operator_Code on p.optcode equals opt.Operator_id.ToString()
                            select new ExtraCommon
                            {
                                optcode = p.optcode,
                                move1 = p.move1,
                                move2 = p.move2,
                                move3 = p.move3,
                                move4 = p.move4,
                                move5 = p.move5,
                                operator_Name = opt.operator_Name,
                                Operator_type = opt.Operator_type
                            }).Where(aa => aa.Operator_type == "Broadband").ToList();
                model.Extra = info;
                var infoAPI = (from p in db.Utility_extra_comm_Api
                               join opt in db.Operator_Code on p.optcode equals opt.Operator_id.ToString()
                               select new ExtraCommonAPI
                               {
                                   optcode = p.optcode,
                                   move1 = p.move1,
                                   move2 = p.move2,
                                   move3 = p.move3,
                                   move4 = p.move4,
                                   move5 = p.move5,
                                   operator_Name = opt.operator_Name,
                                   Operator_type = opt.Operator_type
                               }).Where(aa => aa.Operator_type == "Broadband").ToList();
                model.ExtraAPI = infoAPI;
                ViewBag.comm = 50;

                return View(model);
            }
        }
