        [HttpPost]
        public PartialViewResult _UserPostpaidUtilitySlab(string role, string userid, string ddlUserIdrem, string dlmid, PostpaidUtilitySlab model2, string ddlUserId, string ddlVal1, string Button)
        {
            var ddlVal = ddlVal1;
            if (ddlVal == "" || ddlVal == null)
            {
                ddlVal = "Broadband";
            }
            if (ddlUserId == null)
            {
                PostpaidUtilitySlab model = new PostpaidUtilitySlab();
                if (role == "Master")
                {
                    if (string.IsNullOrWhiteSpace(userid))
                    {
                        model.Materuser =
                          (from m in db.utility_master_comm
                           join u in db.Users on m.userid equals u.UserId
                           join opt in db.Operator_Code on m.optcode equals opt.Operator_id.ToString()
                           where m.userid == userid && opt.Operator_type == ddlVal
                           select new PostpaidMaster
                           {
                               idno = m.idno,
                               userid = m.userid,
                               optcode = m.optcode,
                               gst = m.gst,
                               OperatorName = opt.operator_Name,
                               comm = m.comm,
                               Email = u.Email,
                               RolesName = "Master",
                               opttype = opt.Operator_type
                           }).OrderBy(aa => aa.opttype).ToList();
                        List<SelectListItem> Provinces = new List<SelectListItem>();
                        //  ddlVal = db.Operator_Code.Where(aa => aa.Operator_id == optid).SingleOrDefault().Operator_type;
                        var list = db.Superstokist_details.Select(a => new SelectListItem { Text = a.FarmName, Value = a.SSId, Selected = a.SSId == userid ? true : false }).ToList();
                        model.UserId = list;
                        model.RetailerId = Provinces;
                        model.Email = "";
                        model.Name = "";
                        model.Phone = "";
                        model.role = "Master";
                    }
                    else
                    {
                        model.Materuser =
                         (from m in db.utility_master_comm
                          join u in db.Users on m.userid equals u.UserId
                          join opt in db.Operator_Code on m.optcode equals opt.Operator_id.ToString()
                          where m.userid == userid && opt.Operator_type == ddlVal
                          select new PostpaidMaster
                          {
                              idno = m.idno,
                              userid = m.userid,
                              optcode = m.optcode,
                              gst = m.gst,
                              OperatorName = opt.operator_Name,
                              comm = m.comm,
                              Email = u.Email,
                              RolesName = "Master",
                              opttype = opt.Operator_type
                          }).OrderBy(aa => aa.opttype).ToList();
                        var super = db.Superstokist_details;
                        List<SelectListItem> Provinces = new List<SelectListItem>();
                        var list = super.Select(a => new SelectListItem { Text = a.FarmName, Value = a.SSId, Selected = a.SSId == userid ? true : false }).ToList();
                        model.UserId = list;
                        model.RetailerId = Provinces;
                        model.Email = super.Where(aa => aa.SSId == userid).SingleOrDefault().Email;
                        model.Name = super.Where(aa => aa.SSId == userid).SingleOrDefault().SuperstokistName;
                        model.Phone = super.Where(aa => aa.SSId == userid).SingleOrDefault().Mobile;
                        model.role = "Master";
                    }
                    model.UpdateMaster =
                     (from com in db.utility_common_comm
                      join opt in db.Operator_Code on com.optcode equals opt.Operator_id.ToString()
                      where opt.Operator_type == ddlVal
                      select new UpdatePostpaidMaster
                      {
                          idno = com.idno,
                          OperatorName = opt.operator_Name,
                          comm = com.mastercomm,
                          gst = com.gst,
                          optcode = com.optcode,
                          opttype = opt.Operator_type
