                        join opt in db.Operator_Code on m.optcode equals opt.Operator_id.ToString()
                        where m.userid == userid && opt.Operator_type == ddlVal
                        select new PostpaidWhitelabel
                        {
                            idno = m.idno,
                            userid = m.userid,
                            optcode = m.optcode,
                            gst = m.gst,
                            OperatorName = opt.operator_Name,
                            comm = m.comm,
                            Email = u.Email,
                            RolesName = "Whitelabel",
                            opttype = opt.Operator_type
                        }).OrderBy(aa => aa.opttype).ToList();
                        List<SelectListItem> Provinces = new List<SelectListItem>();
                        var list = db.WhiteLabel_userList.Select(a => new SelectListItem { Text = a.FrmName, Value = a.WhiteLabelID, Selected = a.WhiteLabelID == userid ? true : false }).ToList();
                        model.UserId = list;
                        model.RetailerId = Provinces;
                        model.Email = "";
                        model.Name = "";
                        model.Phone = "";
                        model.role = "Whitelabel";

                    }
                    else
                    {
                        model.Whitelabeluser =
                         (from m in db.utility_whitelabel_comm
                          join u in db.Users on m.userid equals u.UserId
                          join opt in db.Operator_Code on m.optcode equals opt.Operator_id.ToString()
                          where m.userid == userid && opt.Operator_type == ddlVal
                          select new PostpaidWhitelabel
                          {
                              idno = m.idno,
                              userid = m.userid,
                              optcode = m.optcode,
                              gst = m.gst,
                              OperatorName = opt.operator_Name,
                              comm = m.comm,
                              Email = u.Email,
                              RolesName = "Whitelabel",
                              opttype = opt.Operator_type
                          }).OrderBy(aa => aa.opttype).ToList();
                        var super = db.WhiteLabel_userList;
                        List<SelectListItem> Provinces = new List<SelectListItem>();
                        var list = super.Select(a => new SelectListItem { Text = a.FrmName, Value = a.WhiteLabelID, Selected = a.WhiteLabelID == userid ? true : false }).ToList();
                        model.UserId = list;
                        model.RetailerId = Provinces;
                        model.Email = super.Where(aa => aa.WhiteLabelID == userid).SingleOrDefault().EmailId;
                        model.Name = super.Where(aa => aa.WhiteLabelID == userid).SingleOrDefault().Name;
                        model.Phone = super.Where(aa => aa.WhiteLabelID == userid).SingleOrDefault().Mobile;
                        model.role = "Whitelabel";
                    }
                    model.UpdateWhitelabel =
                     (from com in db.utility_common_comm
                      join opt in db.Operator_Code on com.optcode equals opt.Operator_id.ToString()
                      where opt.Operator_type == ddlVal
                      select new UpdatePostpaidWhitelabel
                      {
                          idno = com.idno,
                          OperatorName = opt.operator_Name,
                          comm = com.whitelabelcomm,
                          gst = com.gst,
                          optcode = com.optcode,
                          opttype = opt.Operator_type
                      }).OrderBy(aa => aa.opttype).ToList();
                }
                var opttype = db.Operator_Code.Where(
aa => aa.Operator_type == "Broadband" || aa.Operator_type == "Electricity"
|| aa.Operator_type == "Gas" || aa.Operator_type == "Insurance"
|| aa.Operator_type == "Landline" || aa.Operator_type == "Loan"
|| aa.Operator_type == "PostPaid" || aa.Operator_type == "Water" || aa.Operator_type == "LPG Gas" || aa.Operator_type == "Fastag").OrderBy(aa => aa.Operator_type).ToList();
                var listopt = opttype.Select(a => new SelectListItem { Text = a.Operator_type, Value = a.Operator_type, Selected = a.Operator_type == ddlVal ? true : false });
                model.OPttype = listopt.GroupBy(x => x.Text).Select(x => x.First()).ToList();
                return PartialView(model);
            }
            //End User

        }
        [HttpPost]
        public ActionResult _UpdatePostpaidUtilitySlab(PostpaidUtilitySlab model, string ddlUserId, string role, string Retailerid)
        {
            if (role == "Master")
            {
                if (ddlUserId != "")
                {
                    try
                    {
                        db.Configuration.AutoDetectChangesEnabled = false;

                        foreach (var item in model.Materuser)
                        {
                            var entry = db.utility_master_comm.Single(a => a.userid == ddlUserId && a.optcode == item.optcode);
                            entry.comm = item.comm;
                            entry.gst = item.gst;
                            db.ChangeTracker.DetectChanges();
                            db.SaveChanges();
                        }
                    }
                    finally
                    {
                        db.Configuration.AutoDetectChangesEnabled = true;
                    }
                }
                else
                {
                    foreach (var item in model.UpdateMaster)
                    {
                        db.update_All_PostpaidandUtility_comm("Master", item.optcode, item.comm, item.gst, "", 0);
                    }
                }
            }
            if (role == "Dealer")
            {
                if (ddlUserId != "")
                {
                    try
                    {
                        db.Configuration.AutoDetectChangesEnabled = false;

                        foreach (var item in model.Dealeruser)
                        {
                            var entry = db.utility_dealer_comm.Single(a => a.userid == ddlUserId && a.optcode == item.optcode);
                            entry.comm = item.comm;
                            entry.gst = item.gst;
                            db.ChangeTracker.DetectChanges();
                            db.SaveChanges();
                        }
                    }
                    finally
                    {
                        db.Configuration.AutoDetectChangesEnabled = true;
                    }
                }
                else
                {
                    foreach (var item in model.UpdateDealer)
                    {
                        db.update_All_PostpaidandUtility_comm("Dealer", item.optcode, item.comm, item.gst, "", 0);
                    }
                }
            }
            if (role == "Retailer")
            {
                if (Retailerid != "")
                {
                    if (model.Retaileruser != null)
                    {
                        try
                        {
                            db.Configuration.AutoDetectChangesEnabled = false;

                            foreach (var item in model.Retaileruser)
                            {
                                var entry = db.utility_retailer_comm.Single(a => a.userid == Retailerid && a.optcode == item.optcode);
                                entry.comm = item.comm;
                                entry.gst = item.gst;
                                entry.SurCharge = item.surcharge;

                                db.ChangeTracker.DetectChanges();
                                db.SaveChanges();
                            }
                        }
                        finally
                        {
                            db.Configuration.AutoDetectChangesEnabled = true;
                        }
                    }
                }
                else
                {
                    foreach (var item in model.UpdateRetailer)
                    {
                        db.update_All_PostpaidandUtility_comm("Retailer", item.optcode, item.comm, item.gst, ddlUserId, item.surcharge);
                    }
                }
            }
            if (role == "API")
            {
                if (ddlUserId != "")
                {
                    try
                    {
                        db.Configuration.AutoDetectChangesEnabled = false;


                        foreach (var item in model.APIuser)
                        {
                            var entry = db.utility_api_comm.Single(a => a.userid == ddlUserId && a.optcode == item.optcode);
                            entry.comm = item.comm;
                            entry.gst = item.gst;
                            db.ChangeTracker.DetectChanges();
                            db.SaveChanges();
                        }
                    }
                    finally
                    {
                        db.Configuration.AutoDetectChangesEnabled = true;
                    }
                }
                else
                {
                    foreach (var item in model.UpdateAPI)
                    {
                        db.update_All_PostpaidandUtility_comm("API", item.optcode, item.comm, item.gst, "", 0);
                    }
                }
            }
            if (role == "Whitelabel")
            {
                if (ddlUserId != "")
                {
                    try
                    {
                        db.Configuration.AutoDetectChangesEnabled = false;

                        foreach (var item in model.Whitelabeluser)
                        {
                            var entry = db.utility_whitelabel_comm.Single(a => a.userid == ddlUserId && a.optcode == item.optcode);
                            entry.comm = item.comm;
                            entry.gst = item.gst;
                            db.ChangeTracker.DetectChanges();
                            db.SaveChanges();
                        }
                    }
                    finally
