                        db.Configuration.AutoDetectChangesEnabled = true;
                    }
                }
                else
                {
                    foreach (var item in model.UpdateWhitelabel)
                    {
                        db.update_All_PostpaidandUtility_comm("Whitelabel", item.optcode, item.comm, item.gst, "", 0);
                    }
                }
            }
            return RedirectToAction("PostpaidUtility_Slab_setting");
        }
