        [HttpPost]
        public ActionResult _utility_charge_type(string usertype, string rchtype)
        {
            if (rchtype != null)
            {
                bool esp = true;
                var chk = db.Utility_Charge_type.Where(aa => aa.rch_type == rchtype && aa.user_type == usertype).SingleOrDefault();
                if (chk.Fixedrs == true)
                {
                    esp = false;
                }
                chk.Fixedrs = esp;
                db.SaveChanges();
            }
            PostpaidUtilitySlab model = new PostpaidUtilitySlab();
            model.chargetype = (from com in db.Utility_Charge_type
                                select new chargetypecomm
                                {
                                    rch_type = com.rch_type,
                                    user_type = com.user_type,
                                    fixedrs = com.Fixedrs
                                }).OrderByDescending(a => a.user_type == "Retailer").ThenByDescending(a => a.user_type == "Dealer").ThenByDescending(a => a.user_type == "Master")
                                .ThenByDescending(a => a.user_type == "API").ThenByDescending(a => a.user_type == "Whitelabel").ThenBy(a => a.rch_type).ToList();

            return PartialView(model);
        }
