        #region Loan Slab Setting
        public ActionResult Loan_Slab_setting()
        {
            var data = TempData.Peek("data");
            if (data == "" || data == null)
            {
                return RedirectToAction("tran_passslabsetting");
            }
            else
            {
                var chkk = db.Utility_Charge_type;
                if (chkk.Where(aa => aa.rch_type == "Loan").SingleOrDefault().Fixedrs == true)
                {
                    ViewBag.loanf = true;
                    ViewBag.loanp = false;
                }
                else
                {
                    ViewBag.loanf = false;
                    ViewBag.loanp = true;
                }
                LoanModel model = new LoanModel();
                model.common =
               (from p in db.Loan_common_comm
                join opt in db.Operator_Code on p.optcode equals opt.Operator_id.ToString()
                select new LoanCommon
                {
                    idno = p.idno,
                    optcode = p.optcode,
                    OperatorName = opt.operator_Name,
                    mastercomm = p.mastercomm,
                    dlmcomm = p.dlmcomm,
                    retailercomm = p.retailercomm,
                    apicomm = p.apicomm,
                    whitelabelcomm = p.whitelabelcomm,
                    gst = p.gst,
                    surcharge = p.SurCharge

                }).ToList();
                return View(model);
            }
        }
        [HttpPost]
        public ActionResult Loan_Slab_setting(LoanModel model)
        {
            var chkk = db.Utility_Charge_type;
            if (chkk.Where(aa => aa.rch_type == "Loan").SingleOrDefault().Fixedrs == true)
            {
                ViewBag.loanf = true;
                ViewBag.loanp = false;
            }
            else
            {
                ViewBag.loanf = false;
                ViewBag.loanp = true;
            }
            foreach (var item in model.common)
            {
                var entry = db.Loan_common_comm.Find(item.idno);
                entry.mastercomm = item.mastercomm;
                entry.dlmcomm = item.dlmcomm;
                entry.retailercomm = item.retailercomm;
                entry.apicomm = item.apicomm;
                entry.whitelabelcomm = item.whitelabelcomm;
                entry.gst = item.gst;
                entry.SurCharge = item.surcharge;
                db.SaveChanges();
            }
            return RedirectToAction("Loan_Slab_setting");
        }
