                    model.UserId = list;
                }
                model.UpdateWhitelabel =
                 (from com in db.Loan_common_comm
                  join opt in db.Operator_Code on com.optcode equals opt.Operator_id.ToString()
                  select new UpdateLoanWhitelabel
                  {
                      idno = com.idno,
                      OperatorName = opt.operator_Name,
                      comm = com.whitelabelcomm,
                      gst = com.gst,
                      optcode = com.optcode,


                  }).OrderBy(a => a.idno).Distinct().ToList();

            }
            //End User
            return PartialView(model);
        }

        [HttpPost]
        public ActionResult _UpdateLoanSlab(LoanModel model, string ddlUserId, string role, string Retailerid)
        {
            if (role == "Master")
            {
                if (ddlUserId != "")
                {
                    foreach (var item in model.Materuser)
                    {
                        var entry = db.Loan_master_comm.Single(a => a.userid == ddlUserId && a.optcode == item.optcode);
                        entry.comm = item.comm;
                        entry.gst = item.gst;
                        db.SaveChanges();
                    }
                }
                else
                {
                    foreach (var item in model.UpdateMaster)
                    {
                        db.update_All_Loan_comm("Master", item.optcode, item.comm, item.gst, "", 0);
                    }
                }
            }
            if (role == "Dealer")
            {
                if (ddlUserId != "")
                {
                    foreach (var item in model.Dealeruser)
                    {
                        var entry = db.Loan_dealer_comm.Single(a => a.userid == ddlUserId && a.optcode == item.optcode);
                        entry.comm = item.comm;
                        entry.gst = item.gst;
                        db.SaveChanges();
                    }
                }
                else
                {
                    foreach (var item in model.UpdateDealer)
                    {
                        db.update_All_Loan_comm("Dealer", item.optcode, item.comm, item.gst, "", 0);
                    }
                }
            }
            if (role == "Retailer")
            {
                if (Retailerid != "")
                {
                    if (model.Retaileruser != null)
                    {
                        foreach (var item in model.Retaileruser)
                        {
                            var entry = db.Loan_retailer_comm.Single(a => a.userid == Retailerid && a.optcode == item.optcode);
                            entry.comm = item.comm;
                            entry.gst = item.gst;
                            entry.SurCharge = item.surcharge;
                            db.SaveChanges();
                        }
                    }
                }
                else
                {
                    foreach (var item in model.UpdateRetailer)
                    {
                        db.update_All_Loan_comm("Retailer", item.optcode, item.comm, item.gst, ddlUserId, item.surcharge);
                    }
                }
            }
            if (role == "API")
            {
                if (ddlUserId != "")
                {
                    foreach (var item in model.APIuser)
                    {
                        var entry = db.Loan_api_comm.Single(a => a.userid == ddlUserId && a.optcode == item.optcode);
                        entry.comm = item.comm;
                        entry.gst = item.gst;
                        db.SaveChanges();
                    }
                }
                else
                {
                    foreach (var item in model.UpdateAPI)
                    {
                        db.update_All_Loan_comm("API", item.optcode, item.comm, item.gst, "", 0);
                    }
                }
            }
            if (role == "Whitelabel")
            {
                if (ddlUserId != "")
                {
                    foreach (var item in model.Whitelabeluser)
                    {
                        var entry = db.Loan_whitelabel_comm.Single(a => a.userid == ddlUserId && a.optcode == item.optcode);
                        entry.comm = item.comm;
                        entry.gst = item.gst;
                        db.SaveChanges();
                    }
                }
                else
                {
                    foreach (var item in model.UpdateWhitelabel)
                    {
                        db.update_All_Loan_comm("Whitelabel", item.optcode, item.comm, item.gst, "", 0);
                    }
                }
            }
            return RedirectToAction("Loan_Slab_setting");
        }
        public ActionResult loancharge()
        {
            var chkk = db.Utility_Charge_type.Where(aa => aa.rch_type == "Loan").SingleOrDefault();
            if (chkk.Fixedrs == true)
            {
                chkk.Fixedrs = false;
            }
            else
            {
                chkk.Fixedrs = true;
            }
            db.SaveChanges();
            return RedirectToAction("Loan_Slab_setting");
        }
