        public ActionResult CashDepositSlab()
        {
            var data = TempData.Peek("data");
            if (data == "" || data == null)
            {
                return RedirectToAction("tran_passslabsetting");
            }
            else
            {
                var commonSlab = db.CashDeposit_Common_Comm.ToList();
                CashDepositCommonModel model = new CashDepositCommonModel();
                model.common = commonSlab;
                //model. = userwiseSalb;
                model.UserId = new List<SelectListItem>() { new SelectListItem { Text = "No data", Value = "No Data" } };
                return View(model);
            }
        }
