        public ActionResult AadharPanVerificationCharge()
        {
            var charges = db.PanAadharVerificationCharges.ToList();
            return View(charges);
        }
        [HttpPost]
        public ActionResult AepsAadharpayChargeSet(decimal PanCharge, decimal AadharCharge)
        {
            try
            {
                var charge = db.PanAadharVerificationCharges.FirstOrDefault();
                if (charge != null)
                {
                    charge.PanCharge = PanCharge;
                    charge.AadharCharge = AadharCharge;
                    db.SaveChanges();
                }
                return RedirectToAction("AadharPanVerificationCharge");
            }
            catch
            {
                return RedirectToAction("AadharPanVerificationCharge");
            }
        }
        public ActionResult MIcroatm_Cash_Slab()
        {
            var data = TempData.Peek("data");
            if (data == "" || data == null)
            {
                return RedirectToAction("tran_passslabsetting");
            }
            else
            {
                var commonSlab = db.mtm_Comm_comm.ToList();
                MicroatmcashCommonModel model = new MicroatmcashCommonModel();
                model.common = commonSlab;
                //model. = userwiseSalb;
                model.UserId = new List<SelectListItem>() { new SelectListItem { Text = "No data", Value = "No Data" } };
                return View(model);
            }
        }
