        #region FINO CMS
        public ActionResult FinoCMS()
        {
            var data = TempData.Peek("data");
            if (data == "" || data == null)
            {
                return RedirectToAction("tran_passslabsetting");
            }
            else
            {
                var commonSlab = (from p in db.fino_common_comm
                                  join opt in db.Operator_Code on p.optcode equals opt.Operator_id.ToString()
                                  select new FinoCommon
                                  {
                                      idno = p.id,
                                      optcode = p.optcode,
                                      OperatorName = opt.operator_Name,
                                      mastercomm = p.mastercomm,
                                      dlmcomm = p.dlmcomm,
                                      retailercomm = p.retailercomm,
                                  }).OrderBy(p => p.OperatorName).ToList();
                Fino_CMS_Slab model = new Fino_CMS_Slab();
                model.common = commonSlab;
                //model. = userwiseSalb;
                model.UserId = new List<SelectListItem>() { new SelectListItem { Text = "No data", Value = "No Data" } };
                return View(model);
            }
        }

        [HttpPost]
        public ActionResult _fino_comm(Fino_CMS_Slab model)
        {
            foreach (var item in model.common)
            {
                var entry = db.fino_common_comm.Find(item.idno);
                entry.mastercomm = item.mastercomm;
                entry.dlmcomm = item.dlmcomm;
                entry.retailercomm = item.retailercomm;
                db.SaveChanges();
            }
            Fino_CMS_Slab pmodel = new Fino_CMS_Slab();
            //pmodel.AmountRange = (from p in db.Recharge_Amount_range
            //                      select new Recharge_Amount_range_info
            //                      {
            //                          idno = p.idno,
            //                          maximum1 = p.maximum1,
            //                          maximum2 = p.maximum2
            //                      }).ToList();

            pmodel.common =
           (from p in db.fino_common_comm
            join opt in db.Operator_Code on p.optcode equals opt.Operator_id.ToString()
            select new FinoCommon
            {
                idno = p.id,
                optcode = p.optcode,
                OperatorName = opt.operator_Name,
                mastercomm = p.mastercomm,
                dlmcomm = p.dlmcomm,
                retailercomm = p.retailercomm,
            }).OrderBy(p => p.OperatorName).ToList();
            return PartialView(pmodel);
            // return RedirectToAction("Prepaid_Slab_setting");
        }





