            DateTime to_date = Convert.ToDateTime(txt_to_date).Date.AddDays(1);

            var entries = db.WalletUnloadReportAdmin(Convert.ToDateTime(txt_frm_date), Convert.ToDateTime(to_date), ddlusers, userid, ddl_status).ToList();

            DataTable dataTbl = new DataTable();
            dataTbl.Columns.Add("Role", typeof(string));
            dataTbl.Columns.Add("Firm Name", typeof(string));
            dataTbl.Columns.Add("Status", typeof(string));
            dataTbl.Columns.Add("Transfer Type", typeof(string));
            dataTbl.Columns.Add("Bank Name", typeof(string));
            dataTbl.Columns.Add("Remain Pre", typeof(string));
            dataTbl.Columns.Add("Amount", typeof(string));
            dataTbl.Columns.Add("Charge", typeof(string));
            dataTbl.Columns.Add("Remain Post", typeof(string));
            dataTbl.Columns.Add("Request Time", typeof(string));
            dataTbl.Columns.Add("Response Time", typeof(string));
            dataTbl.Columns.Add("Bank RRN", typeof(string));


            decimal total = 0;
            foreach (var item in entries)
            {
                total += item.Amount ?? 0;
                dataTbl.Rows.Add(item.RoleName, item.FirmName, item.Status, item.TransferType, item.BankName, item.Rempre, item.Amount, item.ProcessingCharge, item.RemPost, item.RequestDate, item.ResponseDate, item.BankRRN);
            }
            dataTbl.Rows.Add("Total", "", "", "", "", "", total, "", "", "", "", "");

            var grid = new GridView();
            grid.DataSource = dataTbl;
            grid.DataBind();
            Response.ClearContent();
            Response.Buffer = true;
            Response.AddHeader("content-disposition", "attachment; filename=Wallet_Unload_Report.xls");
            Response.ContentType = "application/ms-excel";
            Response.Charset = "";
            StringWriter sw = new StringWriter();
            HtmlTextWriter htw = new HtmlTextWriter(sw);
            grid.RenderControl(htw);
            Response.Output.Write(sw.ToString());
            Response.Flush();
            Response.End();
            return View();
        }


        [HttpPost]
        public ActionResult WalletAction(string reqId, string status)
        {
            try
            {
                // ----- APPROVED -----
                if (status == "Approved")
                {
                    var pendingRetailer = db.WalletToBankAmountTransferRequests
                        .Where(a => a.RequestId == reqId && a.Status == "Pending")
                        .FirstOrDefault();

                    if (pendingRetailer != null)
                    {
                        pendingRetailer.Status = "Success";
                        pendingRetailer.BankRRN = "ADMIN-" + DateTime.Now.Ticks;
                        pendingRetailer.Remark = "Approved By Admin";
                        db.SaveChanges();

                        return Json(new { status = true, message = "Wallet Unload Approved Successfully" });
                    }

                    var pendingWL = db.Whitelabel_WalletToBankAmountTransferRequestsToAdmin
                        .Where(a => a.RequestId == reqId && a.Status == "Pending")
                        .FirstOrDefault();

                    if (pendingWL != null)
                    {
                        pendingWL.Status = "Success";
                        pendingWL.BankRRN = "ADMIN-" + DateTime.Now.Ticks;
                        pendingWL.Remark = "Approved By Admin";
                        db.SaveChanges();

                        return Json(new { status = true, message = "Wallet Unload Approved Successfully" });
                    }

                    return Json(new { status = false, message = "No pending request found!" });
                }

                // ----- REJECT -----
                else if (status == "Reject")
                {
                    var pendingRetailer = db.WalletToBankAmountTransferRequests
                        .Where(a => a.RequestId == reqId && a.Status == "Pending")
                        .FirstOrDefault();

                    if (pendingRetailer != null)
                    {
                        var outStatus = new System.Data.Entity.Core.Objects.ObjectParameter("Status", typeof(string));
                        var outMsg = new System.Data.Entity.Core.Objects.ObjectParameter("Message", typeof(string));

                        db.proc_InsertWalletToBankAmountTransferRefund(pendingRetailer.Idno, outStatus, outMsg);

                        return Json(new { status = true, message = "Wallet Unload Rejected & Refunded" });
                    }

                    return Json(new { status = false, message = "No pending request found!" });
                }

                return Json(new { status = false, message = "Invalid Status" });
            }
            catch (Exception ex)
            {
                return Json(new { status = false, message = ex.Message });
            }
        }




        [HttpPost]
        public ActionResult AcceptWalletToBank(int idNo, string txnpass, string RRN, string txtcomment)
        {
            try
            {
                var chktranss = db.admin_new_pass.SingleOrDefault();
                DateTime currenttime = DateTime.Now;
                DateTime lastchangedpassdtr = Convert.ToDateTime(chktranss.lastupdatetrans);
                lastchangedpassdtr = lastchangedpassdtr.AddDays(Convert.ToInt32(chktranss.transexpdays));
                var defaultht = Decrypt(chktranss.transpass);
                if (defaultht == "1111" || (lastchangedpassdtr <= currenttime))
                {
                    var ViewResponse = new { status = "Failed", Message = "Your transaction pin is expired or have to be changed!! Please set new transaction pin" };
                    return Json(JsonConvert.SerializeObject(ViewResponse));
                }
                var password = Encrypt(txnpass);
                var tranpass = (from paa in db.admin_new_pass where paa.transpass == password select paa).Count();
                if (tranpass > 0)
                {

                    var count = db.WalletToBankAmountTransferRequests.Where(a => a.Idno == idNo).ToList();
                    if (db.VendorWalletToBankAmountTransferRequests.Any(a => a.Idno == idNo))
                    {
                        var entry = db.VendorWalletToBankAmountTransferRequests.Where(a => a.Idno == idNo).FirstOrDefault();
                        entry.Status = "Success";
                        entry.BankRRN = RRN ?? "";
                        entry.Remark = txtcomment ?? "";
                        entry.type = entry.type;
                        db.SaveChanges();
                    }
                    if (count.Count > 0)
                    {
                        var entry = db.WalletToBankAmountTransferRequests.Where(a => a.Idno == idNo).FirstOrDefault();
                        entry.Status = "Success";
                        entry.BankRRN = RRN ?? "";
                        entry.Remark = txtcomment ?? "";
                        entry.type = entry.type;
                        db.SaveChanges();
                    }
                    else
                    {
                        var Type = db.Whitelabel_WalletToBankAmountTransferRequestsToAdmin.Where(a => a.Idno == idNo).SingleOrDefault().type;
                        if (Type == "Admin")
                        {
                            var requestidwhitelabel = db.Whitelabel_WalletToBankAmountTransferRequestsToAdmin.Where(a => a.Idno == idNo).SingleOrDefault().RequestId;
                            var requestidRetailerwhitelabel = db.Whitelabel_WalletToBankAmountTransferRequests.Where(a => a.RequestId == requestidwhitelabel).SingleOrDefault().RequestId;
                            if (requestidwhitelabel == requestidRetailerwhitelabel)
                            {
                                var entry1 = db.Whitelabel_WalletToBankAmountTransferRequestsToAdmin.Where(a => a.Idno == idNo).FirstOrDefault();
                                entry1.Status = "Success";
                                entry1.BankRRN = RRN ?? "";
                                entry1.Remark = txtcomment ?? "";
                                entry1.type = entry1.type;
                                db.SaveChanges();
                                var entry11 = db.Whitelabel_WalletToBankAmountTransferRequests.Where(a => a.RequestId == requestidwhitelabel).FirstOrDefault();
                                entry11.Status = "Success";
                                //entry11.BankRRN = RRN ?? "";
                                //entry11.Remark = txtcomment ?? "";
                                entry11.Type = entry11.Type;
                                db.SaveChanges();
                            }
                            else
                            {
                                var ViewResponse1 = new { status = "Failed", Message = "Whitelabel and Whitelabel Retailer Request Id is Not Match." };
                                return Json(JsonConvert.SerializeObject(ViewResponse1));
                            }
                        }
                        else
                        {
                            var entry1 = db.Whitelabel_WalletToBankAmountTransferRequestsToAdmin.Where(a => a.Idno == idNo).FirstOrDefault();
                            entry1.Status = "Success";
                            entry1.BankRRN = RRN ?? "";
                            entry1.Remark = txtcomment ?? "";
                            entry1.type = entry1.type;
                            db.SaveChanges();
                        }
                    }
                    var ViewResponse = new { status = "Success", Message = "Accepted successfully." };
                    return Json(JsonConvert.SerializeObject(ViewResponse));
                }
                else
                {
                    var ViewResponse = new { status = "Failed", Message = "Transaction Password is Wrong" };
                    return Json(JsonConvert.SerializeObject(ViewResponse));
                }
            }
            catch (Exception ex)
            {
                var ViewResponse = new { status = "Failed", Message = "Internal error" };
                return Json(JsonConvert.SerializeObject(ViewResponse));
            }

        }
        [HttpPost]
        public ActionResult RefundWalletToBank(int idNo)
        {
            System.Data.Entity.Core.Objects.ObjectParameter status = new System.Data.Entity.Core.Objects.ObjectParameter("Status", typeof(string));
            System.Data.Entity.Core.Objects.ObjectParameter Message = new System.Data.Entity.Core.Objects.ObjectParameter("Message", typeof(string));

            var count = db.WalletToBankAmountTransferRequests.Where(a => a.Idno == idNo && a.Status == "Pending").ToList();
            if (db.VendorWalletToBankAmountTransferRequests.Any(a => a.Idno == idNo && a.Status == "Pending"))
            {
                var response = db.proc_InsertVendorWalletToBankAmountTransferRefund(idNo, status, Message).FirstOrDefault();
                if (response.Status == "Success")
                {
                    var ViewResponse = new { status = "Success", Message = "Rejected successfully." };
                    return Json(JsonConvert.SerializeObject(ViewResponse));
                }
                else
                {
                    var ViewResponse = new { status = "Failed", Message = response.Message };
                    return Json(JsonConvert.SerializeObject(ViewResponse));
                }
            }
            if (count.Count > 0)
            {
                var response = db.proc_InsertWalletToBankAmountTransferRefund(idNo, status, Message).FirstOrDefault();
                if (response.Status == "Success")
                {
                    var ViewResponse = new { status = "Success", Message = "Rejected successfully." };
                    return Json(JsonConvert.SerializeObject(ViewResponse));
                }
                else
                {
                    var ViewResponse = new { status = "Failed", Message = response.Message };
                    return Json(JsonConvert.SerializeObject(ViewResponse));
                }

            }
            else
            {
                var Type = db.Whitelabel_WalletToBankAmountTransferRequestsToAdmin.Where(a => a.Idno == idNo && a.Status == "Pending").SingleOrDefault().type;
                if (Type == "Admin")
                {
                    var Requestid = db.Whitelabel_WalletToBankAmountTransferRequestsToAdmin.Where(a => a.Idno == idNo && a.Status == "Pending").SingleOrDefault().RequestId;
                    var idnowhitelabelretailer = db.Whitelabel_WalletToBankAmountTransferRequests.Where(a => a.RequestId == Requestid && a.Status == "Pending").SingleOrDefault().Idno;

                    var response1 = db.proc_Whitelabel_InsertWalletToBankAmountTransferToAdminRefund(idNo, status, Message).FirstOrDefault();
                    if (response1.Status == "Success")
                    {
                        var response11 = db.proc_Whitelabel_InsertWalletToBankAmountTransferRefund(idnowhitelabelretailer, status, Message).FirstOrDefault();
                        if (response11.Status == "Success")
                        {
                            var ViewResponse = new { status = "Success", Message = "Rejected successfully." };
                            return Json(JsonConvert.SerializeObject(ViewResponse));
                        }
                        else
                        {
                            var ViewResponse = new { status = "Failed", Message = response11.Message };
                            return Json(JsonConvert.SerializeObject(response11));
                        }

                    }
                    else
                    {
                        var ViewResponse = new { status = "Failed", Message = response1.Message };
                        return Json(JsonConvert.SerializeObject(ViewResponse));
                    }
                }
                else
                {
                    var response1 = db.proc_Whitelabel_InsertWalletToBankAmountTransferToAdminRefund(idNo, status, Message).FirstOrDefault();
                    if (response1.Status == "Success")
                    {
                        var ViewResponse = new { status = "Success", Message = "Rejected successfully." };
                        return Json(JsonConvert.SerializeObject(ViewResponse));
                    }
                    else
                    {
                        var ViewResponse = new { status = "Failed", Message = response1.Message };
                        return Json(JsonConvert.SerializeObject(ViewResponse));
                    }
                }

            }
        }

