        public ActionResult ExcelAdminposreport(string RetailerIdpos, DateTime txt_frm_date, DateTime txt_to_date)
        {
            ViewBag.chk = "post";
            DateTime to = txt_to_date.AddDays(1);

            var ch = db.pos_ledger_report(RetailerIdpos, txt_frm_date, to).ToList();
            DataTable dataTbl = new DataTable();
            dataTbl.Columns.Add("Details", typeof(string));
            dataTbl.Columns.Add("Firm Name", typeof(string));
            dataTbl.Columns.Add("Remain Pre", typeof(string));
            dataTbl.Columns.Add("Cr", typeof(string));
            dataTbl.Columns.Add("Dr", typeof(string));
            dataTbl.Columns.Add("Amount", typeof(string));
            dataTbl.Columns.Add("Comm", typeof(string));
            dataTbl.Columns.Add("Gst", typeof(string));
            dataTbl.Columns.Add("Tds", typeof(string));
            dataTbl.Columns.Add("Remain Post", typeof(string));
            dataTbl.Columns.Add("Date", typeof(string));

            if (ch.Count > 0)
            {
                foreach (var item in ch)
                {

                    dataTbl.Rows.Add(item.Details, item.Frm_Name, item.remainpre, item.cr, item.dr, item.Amount, item.comm, item.gst, item.tds, item.remainpost, item.ledgerdate);
                }
            }
            else
            {
                dataTbl.Rows.Add("", "", "", "", "", "", "", "", "", "", "");
            }

            var grid = new GridView();
            grid.DataSource = dataTbl;
            grid.DataBind();
            Response.ClearContent();
            Response.Buffer = true;
            Response.AddHeader("content-disposition", "attachment; filename=Security_Report.xls");
            Response.ContentType = "application/ms-excel";
            Response.Charset = "";
            StringWriter sw = new StringWriter();
            HtmlTextWriter htw = new HtmlTextWriter(sw);
            grid.RenderControl(htw);
            Response.Output.Write(sw.ToString());
            Response.Flush();
            Response.End();
            return View();
        }
