        [HttpPost]
        public ActionResult SaveSignupKYC(List<string> KYCType)
        {
            using (VastwebmultiEntities db = new VastwebmultiEntities())
            {
                // Sabko OFF karo
                var list = db.SignupKYCSettings.ToList();

                foreach (var item in list)
                {
                    item.IsActive = false;
                }

                // Jo select hue unko ON karo
                if (KYCType != null)
                {
                    foreach (var item in KYCType)
                    {
                        var kyc = db.SignupKYCSettings.FirstOrDefault(x => x.KYCType == item);

                        if (kyc != null)
                        {
                            kyc.IsActive = true;
                        }
                    }
                }

                db.SaveChanges();
            }

            return Json(new
            {
                Status = true,
                Message = "KYC Setting Saved Successfully"
            });
        }

        [HttpPost]
        public ActionResult _AddTokenValue(string txtmastervalue, string txtdealervalue)
        {
            if (txtmastervalue != "" || txtdealervalue != "")
            {
                TokenValueByAdmin cc = new TokenValueByAdmin();
                var count = db.TokenValueByAdmins.ToList();
                if (count.Count() > 0)
                {
                    var id = (from tbl in db.TokenValueByAdmins select tbl).SingleOrDefault();
                    id.DistributorValue = string.IsNullOrWhiteSpace(txtdealervalue) ? id.DistributorValue : txtdealervalue;
                    id.MasterValue = string.IsNullOrWhiteSpace(txtmastervalue) ? id.MasterValue : txtmastervalue;
                    db.SaveChanges();
                }
                else
                {
                    cc.DistributorValue = txtdealervalue;
                    cc.MasterValue = txtmastervalue;
                    db.TokenValueByAdmins.Add(cc);
                    db.SaveChanges();
                }
            }

            var tokenvaluedlmmd = db.TokenValueByAdmins.ToList();
            if (tokenvaluedlmmd.Count() > 0)
            {
                ViewBag.dealervalue = tokenvaluedlmmd.SingleOrDefault().DistributorValue;
                ViewBag.mastervalue = tokenvaluedlmmd.SingleOrDefault().MasterValue;
            }
            else
            {
                ViewBag.dealervalue = 0;
                ViewBag.mastervalue = 0;
            }

            return PartialView("_AddTokenValue");
        }
