        [HttpPost]
        public ActionResult IndoNepal_Slab(List<Slab_IndoNepal> model)
        {
            foreach (var item in model)
            {
                var entry = db.Slab_IndoNepal.FirstOrDefault(a => a.idno == item.idno);
                entry.min = item.min;
                entry.max = item.max;
