        #region Insurance  Slab Setting
        public ActionResult Insurance_Slab_setting()
        {
            var data = TempData.Peek("data");
            if (data == "" || data == null)
            {
                return RedirectToAction("tran_passslabsetting");
            }
            else
            {
                var chkk = db.Utility_Charge_type;
                if (chkk.Where(aa => aa.rch_type == "Insurance").SingleOrDefault().Fixedrs == true)
                {
                    ViewBag.Insurancef = true;
                    ViewBag.Insurancep = false;
                }
                else
                {
                    ViewBag.Insurancef = false;
                    ViewBag.Insurancep = true;
                }
                InsuranceSlab model = new InsuranceSlab();
                model.common =
               (from p in db.Insurance_common_comm
                join opt in db.Operator_Code on p.optcode equals opt.Operator_id.ToString()
                select new InsuranceCommon
                {
                    idno = p.idno,
                    optcode = p.optcode,
                    OperatorName = opt.operator_Name,
                    mastercomm = p.mastercomm,
                    dlmcomm = p.dlmcomm,
                    retailercomm = p.retailercomm,
                    apicomm = p.apicomm,
                    whitelabelcomm = p.whitelabelcomm,
                    gst = p.gst,
                    surcharge = p.SurCharge

                }).ToList();
                return View(model);
            }
        }
        [HttpPost]
        public ActionResult Insurance_Slab_setting(InsuranceSlab model)
        {
            var chkk = db.Utility_Charge_type;
            if (chkk.Where(aa => aa.rch_type == "Insurance").SingleOrDefault().Fixedrs == true)
            {
                ViewBag.Insurancef = true;
                ViewBag.Insurancep = false;
            }
            else
            {
                ViewBag.Insurancef = false;
                ViewBag.Insurancep = true;
            }
            foreach (var item in model.common)
            {
                var entry = db.Insurance_common_comm.Find(item.idno);
                entry.mastercomm = item.mastercomm;
                entry.dlmcomm = item.dlmcomm;
                entry.retailercomm = item.retailercomm;
                entry.apicomm = item.apicomm;
                entry.whitelabelcomm = item.whitelabelcomm;
                entry.gst = item.gst;
                entry.SurCharge = item.surcharge;
                db.SaveChanges();
            }
            return RedirectToAction("Insurance_Slab_setting");
        }
        [HttpPost]
        public PartialViewResult _UserInsuranceSlab(string role, string userid, string Retailerid)
        {
            InsuranceSlab model = new InsuranceSlab();

            //master user
            if (role == "Master")
            {
                if (string.IsNullOrWhiteSpace(userid))
                {

                    model.Materuser =
                 (from m in db.Insurance_master_comm
                  join u in db.Users on m.userid equals u.UserId
                  join opt in db.Operator_Code on m.optcode equals opt.Operator_id.ToString()
                  select new InsuranceMaster
                  {
                      idno = m.idno,
                      userid = m.userid,
                      optcode = m.optcode,
                      gst = m.gst,
                      OperatorName = opt.operator_Name,
                      comm = m.comm,
                      Email = u.Email,
                      RolesName = "Master"
                  }).OrderByDescending(p => p.idno).ToList();

                    var list = db.Superstokist_details.Select(a => new SelectListItem { Text = a.Email, Value = a.SSId, Selected = a.SSId == userid ? true : false }).ToList();
                    model.UserId = list;



                }
                else
                {
                    model.Materuser =
                     (from m in db.Insurance_master_comm
                      join u in db.Users on m.userid equals u.UserId
                      join opt in db.Operator_Code on m.optcode equals opt.Operator_id.ToString()
                      where m.userid == userid
                      select new InsuranceMaster
                      {
                          idno = m.idno,
                          userid = m.userid,
                          optcode = m.optcode,
                          gst = m.gst,
                          OperatorName = opt.operator_Name,
