        [HttpPost]
        public ActionResult _UpdateInsuranceSlab(InsuranceSlab model, string ddlUserId, string role, string Retailerid)
        {
            if (role == "Master")
            {
                if (ddlUserId != "")
                {
                    foreach (var item in model.Materuser)
                    {
                        var entry = db.Insurance_master_comm.Single(a => a.userid == ddlUserId && a.optcode == item.optcode);
                        entry.comm = item.comm;
                        entry.gst = item.gst;
                        db.SaveChanges();
                    }
                }
                else
                {
                    foreach (var item in model.UpdateMaster)
                    {
                        db.update_All_Insurance_comm("Master", item.optcode, item.comm, item.gst, "", 0);
                    }
                }
            }
            if (role == "Dealer")
            {
                if (ddlUserId != "")
                {
                    foreach (var item in model.Dealeruser)
                    {
                        var entry = db.Insurance_dealer_comm.Single(a => a.userid == ddlUserId && a.optcode == item.optcode);
                        entry.comm = item.comm;
                        entry.gst = item.gst;
                        db.SaveChanges();
                    }
                }
                else
                {
                    foreach (var item in model.UpdateDealer)
                    {
                        db.update_All_Insurance_comm("Dealer", item.optcode, item.comm, item.gst, "", 0);
                    }
                }
            }
            if (role == "Retailer")
            {
                if (Retailerid != "")
                {
                    if (model.Retaileruser != null)
                    {
                        foreach (var item in model.Retaileruser)
                        {
                            var entry = db.Insurance_retailer_comm.Single(a => a.userid == Retailerid && a.optcode == item.optcode);
                            entry.comm = item.comm;
                            entry.gst = item.gst;
                            entry.SurCharge = item.surcharge;
                            db.SaveChanges();
                        }
                    }
                }
                else
                {
                    foreach (var item in model.UpdateRetailer)
                    {
                        db.update_All_Insurance_comm("Retailer", item.optcode, item.comm, item.gst, ddlUserId, item.surcharge);
                    }
                }
            }
            if (role == "API")
            {
                if (ddlUserId != "")
                {
                    foreach (var item in model.APIuser)
                    {
                        var entry = db.Insurance_api_comm.Single(a => a.userid == ddlUserId && a.optcode == item.optcode);
                        entry.comm = item.comm;
                        entry.gst = item.gst;
                        db.SaveChanges();
                    }
                }
                else
                {
                    foreach (var item in model.UpdateAPI)
                    {
                        db.update_All_Insurance_comm("API", item.optcode, item.comm, item.gst, "", 0);
                    }
                }
            }
            if (role == "Whitelabel")
            {
                if (ddlUserId != "")
                {
                    foreach (var item in model.Whitelabeluser)
                    {
                        var entry = db.Insurance_whitelabel_comm.Single(a => a.userid == ddlUserId && a.optcode == item.optcode);
                        entry.comm = item.comm;
                        entry.gst = item.gst;
                        db.SaveChanges();
                    }
                }
                else
                {
                    foreach (var item in model.UpdateWhitelabel)
                    {
                        db.update_All_Insurance_comm("Whitelabel", item.optcode, item.comm, item.gst, "", 0);
                    }
                }
            }
            return RedirectToAction("Insurance_Slab_setting");
        }
