        [HttpPost]
        public ActionResult FailedMove(string Operator, string Apinm)
        {
            var count = db.failed_recharge_move.Where(aa => aa.operator_code == Operator).Count();
            int optId = Convert.ToInt32(Operator);
            var OptCode = db.Operator_Code.Where(a => a.Operator_id == optId).SingleOrDefault().new_opt_code;
            var apiPort = db.SRS_API.Where(a => a.opt_code == OptCode && a.api_nm == Apinm).SingleOrDefault().apiname;
            if (count == 0)
            {
                failed_recharge_move fail = new failed_recharge_move();
                fail.api_name = Apinm;
                fail.operator_code = Operator;
                fail.status = "Y";
                fail.ApiPort = apiPort;
                db.failed_recharge_move.Add(fail);
                db.SaveChanges();
                ViewBag.msg = "Successfully Added";
            }
            else
            {
                ViewBag.msg = "This OPerator Allready Add To This list, If You Want To Change Then Edit it.";
            }
            var stands = (from dlm in db.Operator_Code select dlm).ToList();
            ViewBag.operatorcode = new SelectList(stands.Where(a => a.Operator_type == "PrePaid" || a.Operator_type == "PostPaid" || a.Operator_type == "DTH"), "Operator_id", "operator_Name");
            ViewBag.operatorcode1 = new SelectList(stands.Where(a => a.Operator_type == "PrePaid" || a.Operator_type == "PostPaid" || a.Operator_type == "DTH"), "Operator_id", "operator_Name");
            var apinm = (from dlm in db.api_name select dlm).ToList();
            ViewBag.Apinm = new SelectList(apinm, "apiname", "apiname");
            ViewBag.Apinm1 = new SelectList(apinm, "apiname", "apiname");
            var ch = db.proc_failed_Move().ToList();
            return View(ch);
        }
