        [HttpPost]
        public ActionResult Actual_Admin_income(DateTime txt_frm_date, DateTime txt_to_date, string btnExport, string hdttable)
        {
            ViewBag.chk = "post";

            DateTime frm_date = txt_frm_date.Date;
            DateTime to_date = txt_to_date.Date.AddDays(1);

            var ch = db.admin_income_report(frm_date, to_date).ToList();
            DataTable dtt = new DataTable();
            if (btnExport == "Export")
            {
                dtt.Columns.Add("Type", typeof(string));
                dtt.Columns.Add("Amount", typeof(decimal));
                dtt.Columns.Add("Purchase", typeof(decimal));
                dtt.Columns.Add("Retailer Comm", typeof(decimal));
                dtt.Columns.Add("Dealer Comm", typeof(decimal));
                dtt.Columns.Add("Master Comm", typeof(decimal));
                dtt.Columns.Add("Income", typeof(decimal));

                if (ch.Count > 0)
                {
                    foreach (var item in ch)
                    {
                        dtt.Rows.Add(item.trntype, item.amount, item.purchase, item.retailerfinal, item.dealerfinal, item.mdfinal, item.income);
                    }
                }
                else
                {
                    dtt.Rows.Add("", "", "", "", "", "", "");
                }

                var grid = new GridView();
                grid.DataSource = dtt;
                grid.DataBind();
                Response.ClearContent();
                Response.Buffer = true;
                Response.AddHeader("content-disposition", "attachment; filename=Actual_Admin.xls");
                Response.ContentType = "application/ms-excel";
                Response.Charset = "";
                StringWriter sw = new StringWriter();
                HtmlTextWriter htw = new HtmlTextWriter(sw);
                grid.RenderControl(htw);
                Response.Output.Write(sw.ToString());
                Response.Flush();
                Response.End();

            }



            return View(ch);
        }
