        public string getAuthToken()
        {
            try
            {
                var tokn = db.vastbazzartokens.SingleOrDefault();
                if (tokn == null)
                {
                    var response = tokencheck();
                    var responsechk = response.Content.ToString();
                    var responsecode = response.StatusCode.ToString();
                    if (responsecode == "OK")
                    {
                        Vastbillpay vb = new Vastbillpay();
                        dynamic json = JsonConvert.DeserializeObject(responsechk);
                        var token = json.access_token.ToString();
                        var expire = json[".expires"].ToString();
                        DateTime exp = Convert.ToDateTime(expire);
                        vastbazzartoken vast = new vastbazzartoken();
                        vast.apitoken = token;
                        vast.exptime = exp;
                        db.vastbazzartokens.Add(vast);
                        db.SaveChanges();
                        return tokn.apitoken;
                    }
                    else
                    {
                        return null;
                    }
                }
                else
                {
                    DateTime curntdate = DateTime.Now.Date;
                    DateTime expdate = Convert.ToDateTime(tokn.exptime).Date;
                    if (expdate > curntdate)
                    {
                        return tokn.apitoken;
                    }
                    else
                    {
                        var response = tokencheck();
                        var responsechk = response.Content.ToString();
                        var responsecode = response.StatusCode.ToString();
                        if (responsecode == "OK")
                        {

                            dynamic json = JsonConvert.DeserializeObject(responsechk);
                            var token = json.access_token.ToString();
                            var expire = json[".expires"].ToString();
                            DateTime exp = Convert.ToDateTime(expire);

                            tokn.apitoken = token;
                            tokn.exptime = exp;
                            db.SaveChanges();
                            return token;
                        }
                        else
                        {
                            return null;
                        }
                    }

                }
            }
            catch (Exception Ex)
            {
                return null;
            }
        }
        public void UpdateAuthToken()
        {
            var response = tokencheck();
            var responsechk = response.Content.ToString();
            var responsecode = response.StatusCode.ToString();
            if (responsecode == "OK")
            {
                var tokn = db.vastbazzartokens.SingleOrDefault();
                dynamic json = JsonConvert.DeserializeObject(responsechk);
                var token = json.access_token.ToString();
                var expire = json[".expires"].ToString();
                DateTime exp = Convert.ToDateTime(expire);
                tokn.apitoken = token;
                tokn.exptime = exp;
                db.SaveChanges();
            }
        }

        [HttpPost]
        public ActionResult ReGenerateSecuritypasssecond([Bind(Prefix = "Item3")] ChangeSecurityViewModel model)
        {
            var oldpin = db.admin_new_pass.Single().securitypass;
            var oldp = Decrypt(oldpin);
            if (oldp != model.OldSecuritypass)
            {
                TempData["error"] = "Your Old Security Password does Not Match .Please Re-Enter Your Old Security Password ";
                return RedirectToAction("tran_passslabsetting");
            }
            var msg = Encrypt(model.NewSecuritypass);
            var id = (from tbl in db.admin_new_pass
                      select tbl).SingleOrDefault();
            id.securitypass = msg;
            id.lastupdatesec = DateTime.Now;
            db.SaveChanges();
            var emailid = db.Admin_details.Single().email;
            var userid = db.Admin_details.Single().userid;
            try
            {
                CommUtilEmail emailsend = new CommUtilEmail();
                emailsend.EmailLimitChk(emailid, emailid, "Security Password", "Your New Security Password Is  " + model.NewSecuritypass, "No CallBackUrl");
            }
            catch { }
            TempData["success"] = "Your Security Password Send Successfully in Your Mail Id . Please Check Your Mail Id.";
            return RedirectToAction("tran_passslabsetting");
        }
