        [HttpPost]
        public ActionResult tran_passslabsetting(string txtcode)
        {
            ViewData["MSG1"] = TempData["error"];
            ViewData["MSG1success"] = TempData["success"];
            TempData.Remove("error");
            TempData.Remove("success");
            var chktranss = db.admin_new_pass.SingleOrDefault();
            DateTime currenttime = DateTime.Now;
            DateTime lastchangedpassdtr = Convert.ToDateTime(chktranss.lastupdatesec);
            lastchangedpassdtr = lastchangedpassdtr.AddDays(Convert.ToInt32(chktranss.secexpdays));
            var defaultht = Decrypt(chktranss.securitypass);
            if (defaultht == "1111" || (lastchangedpassdtr <= currenttime))
            {
                TempData["error"] = "Your security pin is expired or have to be changed!! Please set new security pin";
                return RedirectToAction("tran_passslabsetting");
            }
            var userid = User.Identity.GetUserId();
            var password = Encrypt(txtcode);
            TempData["data"] = txtcode;
            TempData.Keep("data");
            var tranpass = (from paa in db.admin_new_pass where paa.securitypass == password select paa).Count();
            if (tranpass > 0)
            {
                return RedirectToAction("Prepaid_Slab_setting");
            }
            else
            {
                TempData.Remove("data");
                ViewData["MSG"] = "Security Password is Wrong.";
                return View();
            }
        }



