        [HttpPost]
        public ActionResult Add_app_Slider(string Appheadercontent, string app_slidedescription, HttpPostedFileBase appsliderfile)
        {
            TempData["cueerntdtabeopen"] = "opencurrent";

            if (appsliderfile != null && !string.IsNullOrEmpty(Appheadercontent) && !string.IsNullOrEmpty(app_slidedescription))
            {
                try
                {
                    WebImage photo = new WebImage(appsliderfile.InputStream);
                    if (photo != null)
                    {
                        photo.Resize(483, 322, false, true);
                        if (photo.Height <= 322)
                        {
                            if (photo.ImageFormat == "png" || photo.ImageFormat == "PNG")
                            {
                                string _FileNames = Path.GetFileName(appsliderfile.FileName);
                                var _path = Path.Combine(Server.MapPath("~/TempraryImages"), _FileNames);
                                photo.Save(_path);
                                byte[] imageArray = System.IO.File.ReadAllBytes(_path);

                                FileInfo file = new FileInfo(_path);
                                if (file.Exists)
                                {
                                    file.Delete();
                                }

                                var base64ImageRepresentation = Convert.ToBase64String(imageArray);
                                tblAppslider model = new tblAppslider();
                                model.appheader = Appheadercontent;
                                model.Discription = app_slidedescription;
                                model.sliderimages = base64ImageRepresentation;
                                model.slidestatus = "N";
                                db.tblAppsliders.Add(model);
                                db.SaveChanges();
                            }
                            else
                            {
                                TempData["Errormsgtype"] = "PNGIMG";
                                return RedirectToAction("Notification");
                            }

                        }
                        else
                        {
                            TempData["Errormsgtype"] = "IMGSIZE";
                            return RedirectToAction("Notification");
                        }

                    }
                }
                catch (Exception ex)
                { }

            }
            return RedirectToAction("Notification");
        }


