        public ActionResult Social_Media(string socialType, string link)
        {
            var userid = User.Identity.GetUserId();
            try
            {
                var admin = "ADMIN";
                tblFooterlink alllink = new tblFooterlink();

                if (socialType == "Facebook")
                {
                    var face = db.tblFooterlinks.Where(p => p.FooterType == "Facebook" && p.UserId == userid).SingleOrDefault();
                    if (face != null)
                    {
                        var id = (from p in db.tblFooterlinks
                                  where p.FooterType == socialType && p.UserId == userid
                                  select p).SingleOrDefault();
                        id.Role = string.IsNullOrWhiteSpace(admin) ? id.Role : admin;
                        id.UserId = string.IsNullOrWhiteSpace(userid) ? id.UserId : userid;
                        id.FooterType = string.IsNullOrWhiteSpace(socialType) ? id.FooterType : socialType;
                        id.FooterLink = string.IsNullOrWhiteSpace(link) ? id.FooterLink : link;
                        db.SaveChanges();
                    }
                    else
                    {
                        alllink.Role = admin;
                        alllink.UserId = userid;
                        alllink.FooterLink = link;
                        alllink.FooterType = socialType;
