        public JsonResult delfooterlink(int Id)
        {
            var userid = User.Identity.GetUserId();
            if (Id > 0)
            {
                using (VastwebmultiEntities db = new VastwebmultiEntities())
                {
                    var v = db.tblFooterlinks.Single(m => m.Id == Id && m.UserId == userid);
                    db.tblFooterlinks.Remove(v);
                    db.SaveChanges();

                    var linkcontact = db.tblFooterlinks.Where(p => p.UserId == userid).ToList();
                    ViewBag.linkcontact = linkcontact;
                    return Json(ViewBag.linkcontact, JsonRequestBehavior.AllowGet);
                }
            }
            else
            {
                var linkcontact = db.tblFooterlinks.Where(p => p.UserId == userid).ToList();
                ViewBag.linkcontact = linkcontact;
                return Json(ViewBag.linkcontact, JsonRequestBehavior.AllowGet);
            }

        }

        public ActionResult GetPrivacyJsonData()
        {
