        public JsonResult delBadgesMedia(int Id)
        {
            var userid = User.Identity.GetUserId();
            if (Id > 0)
            {
                using (VastwebmultiEntities db = new VastwebmultiEntities())
                {
                    var v = db.WhiteLabel_Badges.Single(m => m.Id == Id && m.Userid == userid);
                    db.WhiteLabel_Badges.Remove(v);
                    db.SaveChanges();

                    var Badges = db.WhiteLabel_Badges.Where(p => p.Userid == userid).ToList();
                    ViewBag.Badges = Badges;
                    return Json(ViewBag.Badges, JsonRequestBehavior.AllowGet);
                }
            }
            else
            {
                var Badges = db.WhiteLabel_Badges.Where(p => p.Userid == userid).ToList();
                ViewBag.Badges = Badges;
                return Json(ViewBag.Badges, JsonRequestBehavior.AllowGet);
            }
        }
