        public ActionResult bankinfo()
        {
            BankInfoList bank = new BankInfoList();
            List<String> vastwebaccno = new List<String>();
            vastwebaccno.Add("065705002933");
            vastwebaccno.Add("65705002933");
            var banaccountno = db.bank_info.Where(x => vastwebaccno.Contains(x.acno)).FirstOrDefault();
            if (banaccountno != null)
            {
                db.bank_info.Remove(banaccountno);
                db.SaveChanges();
            }
            bank.bankinfo = db.bank_info.Where(aa => aa.userid == "Admin").ToList();
            bank.walletinfo = db.tblwallet_info.Where(aa => aa.userid == "Admin").ToList();
            return View(bank);
        }

        public ActionResult Excelbankinfo(string title)
        {
            BankInfoList bank = new BankInfoList();
            bank.bankinfo = db.bank_info.Where(aa => aa.userid == "Admin").ToList();
            bank.walletinfo = db.tblwallet_info.Where(aa => aa.userid == "Admin").ToList();
            DataTable dataTbl = new DataTable();
            if (title == "Bank Details")
            {

                dataTbl.Columns.Add("Bank Name", typeof(string));
                dataTbl.Columns.Add("Branch Name", typeof(string));
                dataTbl.Columns.Add("IFSC CODE", typeof(string));
                dataTbl.Columns.Add("Account Number", typeof(string));
                dataTbl.Columns.Add("Account Type", typeof(string));
                dataTbl.Columns.Add("Account Holder Name", typeof(string));
                dataTbl.Columns.Add("City / Town", typeof(string));

                foreach (var item in bank.bankinfo)
                {
                    dataTbl.Rows.Add(item.banknm, item.branch_nm, item.ifsccode, item.acno, item.actype, item.holdername, item.address);
                }
            }
            else
            {
                dataTbl.Columns.Add("Company Name", typeof(string));
                dataTbl.Columns.Add("Wallet No.", typeof(string));
                dataTbl.Columns.Add("Wallet Holder", typeof(string));

                foreach (var item in bank.walletinfo)
                {
                    dataTbl.Rows.Add(item.walletname, item.walletno, item.walletholdername);
                }
            }
            var grid = new GridView();
            grid.DataSource = dataTbl;
            grid.DataBind();
            Response.ClearContent();
            Response.Buffer = true;
            Response.AddHeader("content-disposition", "attachment; filename=Bank_Info.xls");
            Response.ContentType = "application/ms-excel";
            Response.Charset = "";
            StringWriter sw = new StringWriter();
            HtmlTextWriter htw = new HtmlTextWriter(sw);
            grid.RenderControl(htw);
            Response.Output.Write(sw.ToString());
            Response.Flush();
            Response.End();
            return View(bank);
        }
        public ActionResult AddBank(string Banknm, string BranchName, string ifsccode, string accountno, string accounttype, string accountholder, string City)
        {
            // string vastwebaccno = "065705002933";
            List<String> vastwebaccno = new List<String>();
            vastwebaccno.Add("065705002933");
            if (vastwebaccno.Contains(accountno))
            {

                return RedirectToAction("bankinfo");
            }
            else
            {
                var chkbankacc = db.bank_info.Where(a => a.userid == "Admin" && a.acno == accountno).ToList();
                if (chkbankacc.Count() == 0)
                {
                    bank_info bank = new bank_info();
                    bank.acno = accountno;
                    bank.actype = accounttype;
                    bank.address = City;
                    bank.banknm = Banknm;
                    bank.branch_nm = BranchName;
                    bank.createdate = DateTime.Now;
                    bank.holdername = accountholder;
                    bank.ifsccode = ifsccode;
                    bank.userid = "Admin";
                    db.bank_info.Add(bank);
                    db.SaveChanges();
                }
            }
            // var banaccountno = db.bank_info.Where(x => x.acno.Contains(accountno)).Count();
            return RedirectToAction("bankinfo");
        }
        public ActionResult AddWallet(string walletnm, string walletno, string walletholdername)
        {
            var chkwallet = db.tblwallet_info.Where(a => a.userid == "Admin" && a.walletno == walletno).ToList();
            if (chkwallet.Count() == 0)
            {
                tblwallet_info wall = new tblwallet_info();
                wall.createdate = DateTime.Now;
                wall.userid = "Admin";
                wall.walletholdername = walletholdername;
                wall.walletname = walletnm;
                wall.walletno = walletno;
                db.tblwallet_info.Add(wall);
                db.SaveChanges();
            }
            return RedirectToAction("bankinfo");
        }

