        public ActionResult _PaymentGateway_setting(upiChargeAndgateway model)
        {
            try
            {
                foreach (var item in model.Paymentgateway_min_maxs)
                {
                    if (item.minval <= item.maxval)
                    {
                        var chk = db.Paymentgateway_min_max.Where(aa => aa.idno == item.idno).SingleOrDefault();
                        chk.maxval = item.maxval;
                        chk.minval = item.minval;
                    }
                }
                db.SaveChanges();
            }
            catch { }
            upiChargeAndgateway model1 = new upiChargeAndgateway();
            model1.Paymentgateway_min_maxs = db.Paymentgateway_min_max.ToList();
            return PartialView(model1);
        }
