        [HttpPost]
        public ActionResult Gateway_Update_Status(string remid1, string sts1, string idno1)
        {
            bool stschange = false;
            if (sts1 == "Close")
            {
                stschange = true;
            }
            if (remid1 == "All")
            {
                int idnoo = Convert.ToInt32(idno1);
                var detailscheck = db.PaymentGateway_Status.Where(aa => aa.idno == idnoo).SingleOrDefault();
                detailscheck.PaymentStatus = stschange;
                var remlist = db.Retailer_Details.Where(aa => aa.ISDeleteuser == false).ToList();
                foreach (var item in remlist)
                {
                    var detailscheck1 = db.PaymentGateway_Status.Where(aa => aa.Retailerid == item.RetailerId && aa.Paymenttype == detailscheck.Paymenttype).SingleOrDefault();
                    detailscheck1.PaymentStatus = stschange;
                }
                db.SaveChanges();
            }
            else
            {
                int idnoo = Convert.ToInt32(idno1);
                var detailscheck = db.PaymentGateway_Status.Where(aa => aa.idno == idnoo).SingleOrDefault();
                detailscheck.PaymentStatus = stschange;
