        public ActionResult Excel_Pay_U_Gateway(string ddlname1, string Retailerid1, string ddlstatus1, DateTime txt_frm_date1, DateTime txt_to_date1)
        {

            if (ddlstatus1 == "ALL")
            {
                ddlstatus1 = "";
            }
            if (ddlname1 == "ALL")
            {
                ddlname1 = "";
            }
            upiChargeAndgateway model = new upiChargeAndgateway();
            DateTime to = txt_to_date1.AddDays(1);
            var chk11 = db.gateway_report(Retailerid1, ddlname1, txt_frm_date1, to, ddlstatus1).ToList();

            DataTable dataTbl = new DataTable();
            dataTbl.Columns.Add("Role", typeof(string));
            dataTbl.Columns.Add("User", typeof(string));
            dataTbl.Columns.Add("Status", typeof(string));
            dataTbl.Columns.Add("Mode", typeof(string));
            dataTbl.Columns.Add("Mode", typeof(string));
            dataTbl.Columns.Add("Remain Pre", typeof(string));
            dataTbl.Columns.Add("Amount", typeof(string));
            dataTbl.Columns.Add("Charges", typeof(string));
            dataTbl.Columns.Add("Pay", typeof(string));
            dataTbl.Columns.Add("Net Received", typeof(string));
            dataTbl.Columns.Add("Remain Post", typeof(string));
            dataTbl.Columns.Add("Bank RRN", typeof(string));
            dataTbl.Columns.Add("PayU ID", typeof(string));
            dataTbl.Columns.Add("Txn. Time", typeof(string));
            dataTbl.Columns.Add("Response Time", typeof(string));

            if (chk11.Count > 0)
            {
                decimal total = 0;
                decimal totalnet = 0;
                decimal totalpay = 0;
                foreach (var item in chk11)
                {
                    var sts = item.status;
                    var bankrrn = item.errormsg;
                    if (sts == "Success")
                    {
                        bankrrn = item.bankrrnno;
                    }
                    total += item.amount ?? 0;
                    totalnet += item.finalpay ?? 0;
                    totalpay += item.totalpay ?? 0;
                    dataTbl.Rows.Add(item.roles, item.Frm_Name, item.status, item.mode, item.PG_TYPE, item.remainpre, item.amount, item.charge, item.finalpay, item.totalpay, item.remainpost, @bankrrn, item.payuMoneyId, item.f_date, item.resptime);

                    dataTbl.Rows.Add("Total", "", "", "", "", "", total, "", totalnet, totalpay, "", "", "", "", "");
                }
            }
            else
            {
                dataTbl.Rows.Add("", "", "", "", "", "", "", "", "", "", "", "", "", "", "");
            }
            var grid = new GridView();
            grid.DataSource = dataTbl;
            grid.DataBind();
            Response.ClearContent();
            Response.Buffer = true;
            Response.AddHeader("content-disposition", "attachment; filename=Excel_Pay_U_Gateway_Report.xls");
            Response.ContentType = "application/ms-excel";
            Response.Charset = "";
            StringWriter sw = new StringWriter();
            HtmlTextWriter htw = new HtmlTextWriter(sw);
            grid.RenderControl(htw);
            Response.Output.Write(sw.ToString());
            Response.Flush();
            Response.End();

            return View();
        }

