        public ActionResult Payment_Gateway_UPIGATEWAYSTS(string val, int idno)
        {
            var sts = false;
            if (val== "upiandgateway")
            {
                var chk = db.UPIandGatewayStatus.Where(aa => aa.Idno == idno).SingleOrDefault();
                if (chk.Status==false)
                {
                    sts = true;
                }
                chk.Status = sts;
                db.SaveChanges();
            }
            else if (val== "upiqr")
            {
                foreach (var entry in db.UPI_QR_API.Where(aa => aa.Idno!=idno).ToList())
                {
                    entry.Sts = false;
                    db.SaveChanges();
                }

                var chk = db.UPI_QR_API.Where(aa => aa.Idno == idno).SingleOrDefault();
                if (chk.Sts == false)
                {
                    sts = true;
                }
                chk.Sts = sts;
                db.SaveChanges();
            }
            else if (val== "upiintent")
            {
                foreach (var entry in db.UPI_Intent_API.Where(aa => aa.Idno!=idno).ToList())
                {
                    entry.Sts = false;
                    db.SaveChanges();
                }

                var chk = db.UPI_Intent_API.Where(aa => aa.Idno == idno).SingleOrDefault();
                if (chk.Sts == false)
                {
                    sts = true;
                }
                chk.Sts = sts;
                db.SaveChanges();
            }
            else if (val == "upicollection")
            {
                foreach (var entry in db.UPI_Collection_API.Where(aa => aa.Idno!=idno).ToList())
                {
                    entry.sts = false;
                    db.SaveChanges();
                }
                var chk = db.UPI_Collection_API.Where(aa => aa.Idno == idno).SingleOrDefault();
                if (chk.sts == false)
                {
                    sts = true;
                }
                chk.sts = sts;
                db.SaveChanges();
            }
            else
            {
                foreach (var entry in db.Payment_GateWay_API.Where(aa => aa.idno!=idno).ToList())
                {
                    entry.Sts = false;
                    db.SaveChanges();
                }
                var chk = db.Payment_GateWay_API.Where(aa => aa.idno == idno).SingleOrDefault();
                if (chk.Sts == false)
                {
                    sts = true;
                }
                chk.Sts = sts;
                db.SaveChanges();
            }

            return Json("", JsonRequestBehavior.AllowGet);
        }
