        public JsonResult Upi_Qr_statusChange()
        {
            var upqrid = db.Upi_Qr_codeGenerator.SingleOrDefault();
            var UPApiid = db.UPI_API.SingleOrDefault() ?? null;
            if (upqrid != null)
            {
                upqrid.status = upqrid.status == true ? false : true;
                if (UPApiid != null && UPApiid.APIID == "CFREE")
                {
                    upqrid.status = true;
                }
                else if (UPApiid != null && UPApiid.APIID == "PHONEPE")
                {
                    upqrid.status = true;
                }
                else if (UPApiid != null && UPApiid.APIID == "PAYU")
                {
                    upqrid.status = false;
                }
                db.SaveChanges();
            }
            return Json(upqrid.status, JsonRequestBehavior.AllowGet);
        }
        public JsonResult Upi_Qr_API()
        {
            var upqrid = db.Upi_Qr_codeGenerator.SingleOrDefault();
            var UPApiid = db.UPI_API.SingleOrDefault() ?? null;
            if (UPApiid != null)
            {
                if (UPApiid.APIID == "ICICI")
                {
                    UPApiid.APIID = "CFREE";
                }
                else if (UPApiid.APIID == "CFREE")
                {
                    UPApiid.APIID = "PAYU";
                }
                else if (UPApiid.APIID == "PAYU")
                {
                    UPApiid.APIID = "PHONEPE";
                }
                else if (UPApiid.APIID == "PHONEPE")
                {
                    UPApiid.APIID = "ICICI";
                }
                if (upqrid != null && UPApiid.APIID == "CFREE")
                {
                    upqrid.status = true;
                }
                else if (UPApiid != null && UPApiid.APIID == "PHONEPE")
                {
                    upqrid.status = true;
                }
                else if (UPApiid != null && UPApiid.APIID == "PAYU")
                {
                    upqrid.status = false;
                }
                db.SaveChanges();
            }
            return Json(UPApiid.APIID, JsonRequestBehavior.AllowGet);
        }

