        public ActionResult Update_MicroATM_Limit(MicroATMPurchase_Max_Purchase_Limit model, string Retailer_ID)
        {

            int countvalues = 0;


            if (model.microchargelist != null)
            {

                var allrem = db.Retailer_Details.Where(aa => aa.ISDeleteuser == false).ToList();
                string chklistall = "ONE";
                foreach (var firstitem in model.microchargelist)
                {
                    Retailer_ID = firstitem.userinfo;
                    if (Retailer_ID == "ALL")
                    {
                        var findholdvaluesss = db.hold_microATM_Purchase.Where(x => x.RetailerID == "ALL" && x.CardcategoryTypes == firstitem.Card_type).FirstOrDefault();
                        findholdvaluesss.MaxLimits = firstitem.maxamount;
                        foreach (var remitem in allrem)
                        {
                            var findholdvalue = db.hold_microATM_Purchase.Where(x => x.RetailerID == remitem.RetailerId && x.CardcategoryTypes == firstitem.Card_type).FirstOrDefault();
                            findholdvalue.MaxLimits = firstitem.maxamount;
                            if (findholdvalue != null)
                            {

                                findholdvalue.MaxLimits = firstitem.maxamount;
                                chklistall = "ALL";
                            }
                            else
                            {
                                hold_microATM_Purchase tblmodel = new hold_microATM_Purchase();
                                tblmodel.RetailerID = remitem.RetailerId;
                                tblmodel.CardcategoryTypes = firstitem.Card_type;
                                tblmodel.MaxLimits = firstitem.maxamount;

                                db.hold_microATM_Purchase.Add(tblmodel);
                                countvalues = db.SaveChanges();
                            }
                        }


                    }


                }

                if (!string.IsNullOrEmpty(Retailer_ID) && chklistall == "ONE")
                {
                    foreach (var itemsss in model.microchargelist)
                    {


                        var findholdvalue = db.hold_microATM_Purchase.Where(x => x.RetailerID == itemsss.userinfo && x.CardcategoryTypes == itemsss.Card_type).FirstOrDefault();

                        if (findholdvalue != null)
                        {

                            findholdvalue.MaxLimits = itemsss.maxamount;
                        }
                        else
                        {
                            hold_microATM_Purchase tblmodel = new hold_microATM_Purchase();
                            tblmodel.RetailerID = itemsss.userinfo;
                            tblmodel.CardcategoryTypes = itemsss.Card_type;
                            tblmodel.MaxLimits = itemsss.maxamount;

                            db.hold_microATM_Purchase.Add(tblmodel);
                            db.SaveChanges();
                        }

                    }

                }
                countvalues = db.SaveChanges();

                if (countvalues > 0)
                {
                    return Json(new { list = model.microchargelist, status = "Success" }, JsonRequestBehavior.AllowGet);
                }
                else
                {
                    return Json(new { list = model.microchargelist, status = "Failed" }, JsonRequestBehavior.AllowGet);
                }


            }




            return Json("", JsonRequestBehavior.AllowGet);
        }
        private List<SelectListItem> PopulateRetailer_details()
        {

            List<SelectListItem> items = new List<SelectListItem>();

            var query = db.Retailer_Details.Where(aa => aa.ISDeleteuser == false).ToList();
            foreach (var item in query)
            {
                items.Add(new SelectListItem
                {

                    Text = item.Frm_Name + "--" + item.Mobile,
                    Value = item.RetailerId
                });
            }

            return items;

        }

