        public ActionResult MicroAtm_Device_info()
        {
            ViewBag.remid = new SelectList(db.select_retailer_for_ddl("Admin"), "RetailerId", "Frm_Name", null);
            var token = getAuthToken();
            var client = new RestClient("http://api.vastbazaar.com/api/MicroATM/Devicelist");
            var request = new RestRequest(Method.POST);
            request.AddHeader("Authorization", "Bearer " + token);
            IRestResponse response = client.Execute(request);
            dynamic resp = JsonConvert.DeserializeObject(response.Content);
            var output = resp.Content.ADDINFO;
            ViewBag.deviceid = new SelectList(output);
            var planlist = db.Micro_atm_device_plan.ToList();
            ViewBag.planchk = new SelectList(planlist, "planname", "planname", null);

            return View();
        }
        [HttpPost]
        public ActionResult Insert_microAtm_deviceinfo(string Remid, string deviceid, string plannm, DateTime txt_frm_date, string chargetype)
        {
            var chkkdate = (from exdate in db.Micro_atm_device_plan where exdate.planname == plannm select exdate).SingleOrDefault();

            dynamic days = chkkdate.noofdays;
            DateTime expiredate = txt_frm_date.AddDays(days);
            GetAllDeviceinfo d = new GetAllDeviceinfo();
            if (txt_frm_date >= DateTime.Today)
            {
                var ch = (from gg in db.MIcroatm_admin_device_info where gg.deviceid == deviceid select gg).Count();
                if (ch == 0)
                {
                    MIcroatm_admin_device_info ds = new MIcroatm_admin_device_info();
                    ds.userid = Remid;
