        public ActionResult ExcelMicroATMUnholdHistoryReport(DateTime txt_frm_date, DateTime txt_to_date)
        {
            var result = db.Show_MicroAtM_UnholdHistory(txt_frm_date, txt_to_date.AddDays(1)).ToList();

            DataTable dataTbl = new DataTable();
            dataTbl.Columns.Add("Firm Name", typeof(string));
            dataTbl.Columns.Add("Unhold By", typeof(string));
            dataTbl.Columns.Add("Bank RRN", typeof(string));
            dataTbl.Columns.Add("Transection Type", typeof(string));
            dataTbl.Columns.Add("Payment Mehod", typeof(string));
            dataTbl.Columns.Add("Amount", typeof(string));
            dataTbl.Columns.Add("Card Payment Type", typeof(string));
            dataTbl.Columns.Add("Masked pen", typeof(string));
            dataTbl.Columns.Add("Retailer pre", typeof(string));
            dataTbl.Columns.Add("Retailer post", typeof(string));
            dataTbl.Columns.Add("Card Usage Type", typeof(string));
            dataTbl.Columns.Add("Card Type", typeof(string));
            dataTbl.Columns.Add("Unhold Time", typeof(string));

            decimal total = 0;
            foreach (var item in result)
            {
                total += item.amount ?? 0;
                dataTbl.Rows.Add(item.frmname, item.Person_name, item.rrn, item.transaction_type, item.payment_method, item.amount, item.card_payment_type, item.masked_pan, item.retailer_remain_pre, item.retailer_remain_post, item.network, item.card_usage_type, item.unhold_transection_time);

            }
            dataTbl.Rows.Add("Total", "", "", "", "", total, "", "", "", "", "", "", "");

            var grid = new GridView();
            grid.DataSource = dataTbl;
            grid.DataBind();
            Response.ClearContent();
            Response.Buffer = true;
            Response.AddHeader("content-disposition", "attachment; filename=Excel_MicroATM_UnholdHistory_Report.xls");
            Response.ContentType = "application/ms-excel";
            Response.Charset = "";
            StringWriter sw = new StringWriter();
            HtmlTextWriter htw = new HtmlTextWriter(sw);
            grid.RenderControl(htw);
            Response.Output.Write(sw.ToString());
            Response.Flush();
            Response.End();
            return View();
        }

