        public ActionResult Update_UPID_REQ(int? hideupiidres, string hideupiidrestypes, string txtcode)
        {
            var chktranss = db.admin_new_pass.SingleOrDefault();
            DateTime currenttime = DateTime.Now;
            DateTime lastchangedpassdtr = Convert.ToDateTime(chktranss.lastupdatetrans);
            lastchangedpassdtr = lastchangedpassdtr.AddDays(Convert.ToInt32(chktranss.transexpdays));
            var defaultht = Decrypt(chktranss.transpass);
            if (defaultht == "1111" || (lastchangedpassdtr <= currenttime))
            {
                TempData["error"] = "Your transaction pin is expired or have to be changed!! Please set new transaction pin";
                return RedirectToAction("ChangeSecurityPassword");
            }
            var password = Encrypt(txtcode);
            string statusssss = "";
            var tranpass = (from paa in db.admin_new_pass where paa.transpass == password select paa).Count();
            if (tranpass > 0)
            {
                var Rem_UPI_REQUEST = db.Rem_UPI_REQUEST.Where(x => x.id == hideupiidres).SingleOrDefault();
                if (Rem_UPI_REQUEST != null)
                {
                    if (hideupiidrestypes == "APPROVED" || hideupiidrestypes == "REJECTED")
                    {
                        System.Data.Entity.Core.Objects.ObjectParameter output = new System.Data.Entity.Core.Objects.ObjectParameter("Output", typeof(string));
                        statusssss = db.Update_UPI_REQ(hideupiidres, hideupiidrestypes, output).SingleOrDefault().msg;
                        try
                        {
                            var retailerdetails = db.Retailer_Details.Where(aa => aa.RetailerId == Rem_UPI_REQUEST.retailerid).SingleOrDefault();
                            var dealerdetails = db.Dealer_Details.Where(aa => aa.DealerId == retailerdetails.DealerId).SingleOrDefault();

                            var remdetails = db.Remain_reteller_balance.Where(aa => aa.RetellerId == Rem_UPI_REQUEST.retailerid).SingleOrDefault();
                            var dlmdetails = db.Remain_dealer_balance.Where(aa => aa.DealerID == retailerdetails.DealerId).SingleOrDefault();

                            var admininfo = db.Admin_details.SingleOrDefault();
                            Backupinfo back = new Backupinfo();

                            var model = new Backupinfo.Addinfo
                            {

                                Websitename = admininfo.WebsiteUrl,
                                RetailerID = Rem_UPI_REQUEST.retailerid,
                                Email = retailerdetails.Email,
                                Mobile = retailerdetails.Mobile,
                                Details = "Fund Recived",
                                RemainBalance = (decimal)remdetails.Remainamount,
                                Usertype = "Retailer"
                            };
                            back.Fundtransfer(model);

                            var model1 = new Backupinfo.Addinfo
                            {
                                Websitename = admininfo.WebsiteUrl,
                                RetailerID = dealerdetails.DealerId,
                                Email = dealerdetails.Email,
                                Mobile = dealerdetails.Mobile,
                                Details = "Fund Transfer ",
                                RemainBalance = Convert.ToDecimal(dlmdetails.Remainamount),
                                Usertype = "Dealer"
                            };
                            back.Fundtransfer(model1);


                        }
                        catch { }

                    }
                }
                var retailer = db.Retailer_Details.Where(aa => aa.RetailerId == Rem_UPI_REQUEST.retailerid).SingleOrDefault();
                var newremain = db.Remain_reteller_balance.Where(aa => aa.RetellerId == Rem_UPI_REQUEST.retailerid).SingleOrDefault().Remainamount.ToString();
                var AdminDetails = db.Admin_details.SingleOrDefault();

                if (statusssss == "Fund Transfer Successfully")
                {
                    //try
                    //{

                    //    string msgssss = "";
                    //    string tempid = "";
                    //    string urlss = "";

                    //    var smsapionsts = db.apisms.Where(x => x.sts == "Y").SingleOrDefault();
                    //    var smsstypes = db.Sending_SMS_Templates.Where(x => x.SMS_TYPE == "UPITRANSFERSUCCESSFULLY" && x.SMSAPIID == smsapionsts.id).SingleOrDefault();
                    //    if (smsstypes != null)
                    //    {



                    //        msgssss = string.Format(smsstypes.Templates, Rem_UPI_REQUEST.amount, newremain);
                    //        tempid = smsstypes.Templateid;
                    //        urlss = smsapionsts.smsapi;

                    //        smssend.sendsmsallnew(retailer.Mobile, msgssss, urlss, tempid);
                    //    }

                    //    // smssend.sendsmsall(retailer.Mobile, "UPI Transfer Rs." + Rem_UPI_REQUEST.amount + " SuccessFully .New Balance is " + newremain + "", "Fund Transfer");
                    //}
                    //catch { }

                    smssend.sms_init("Y", "Y", "UPITRANSFERSUCCESSFULLY", retailer.Mobile, Rem_UPI_REQUEST.amount, newremain);

                    try
                    {
                        smssend.SendEmailAll(retailer.Email, "UPI Transfer Rs." + Rem_UPI_REQUEST.amount + " SuccessFully .New Balance is " + newremain + "", "Fund Transfer", AdminDetails.email);
                    }
                    catch { }
                }
                else if (statusssss == "REJECTED")
                {

                    //try
                    //{

                    //    string msgssss = "";
                    //    string tempid = "";
                    //    string urlss = "";

                    //    var smsapionsts = db.apisms.Where(x => x.sts == "Y").SingleOrDefault();
                    //    var smsstypes = db.Sending_SMS_Templates.Where(x => x.SMS_TYPE == "UPITRANSFERFAILED" && x.SMSAPIID == smsapionsts.id).SingleOrDefault();
                    //    if (smsstypes != null)
