        public ActionResult AddUpiSelf(decimal min, decimal max, int perdaytxncount)
        {
            UPI_status_setting model = new UPI_status_setting();
            if (min >= 10 && max <= 3000 && max > min)
            {
                var chk = db.Admin_UPI.SingleOrDefault();
                if (chk != null)
                {
                    chk.minamount = min;
                    chk.maxamount = max;
                    chk.PerdayTxnCount = perdaytxncount;
                    chk.txndate = DateTime.Now;
                    db.SaveChanges();
                }
                else
                {

                    Admin_UPI ad = new Admin_UPI();
                    ad.minamount = min;
                    ad.maxamount = max;
                    ad.PerdayTxnCount = perdaytxncount;
                    ad.txndate = DateTime.Now;
                    db.Admin_UPI.Add(ad);
                    db.SaveChanges();
                }
                model.msg = "DONE";
            }
            else
            {
                model.msg = "Please select valid amount range";
            }

