        public ActionResult UpdateAllEntery(string dealer, string retailer, string aeps, string aadhar)
        {
            decimal aepsvalue = Convert.ToDecimal(aeps);
            decimal aadharvalue = Convert.ToDecimal(aadhar);
            if (!string.IsNullOrEmpty(dealer) && string.IsNullOrEmpty(retailer))
            {
                var entry = db.Aeps_aadharpay_comm.Where(x => x.DealerId == dealer).ToList();
                if (entry != null)
                {
                    for (int i = 0; i < entry.Count; i++)
                    {
                        entry[i].AepsCharge = aepsvalue;
                        entry[i].AadharpayCharge = aadharvalue;
                        db.SaveChanges();
                    }
                }

            }
            else if (!string.IsNullOrEmpty(dealer) && !string.IsNullOrEmpty(retailer))
            {
                var entry = db.Aeps_aadharpay_comm.Where(x => x.DealerId == dealer && x.RetailerId == retailer).FirstOrDefault();
                if (entry != null)
                {
                    entry.AepsCharge = aepsvalue;
                    entry.AadharpayCharge = aadharvalue;
                    db.SaveChanges();
                }
            }
            return Json(new { success = true, dealerid = dealer }, JsonRequestBehavior.AllowGet);
        }
