        public ActionResult Gateway_Update_Status(string txnid, string ddlname1, string Retailerid, string ddlstatus, DateTime txt_frm_date, DateTime txt_to_date)
        {
            if (ddlstatus == "ALL")
            {
                ddlstatus = "";
            }
            if (ddlname1 == "ALL")
            {
                ddlname1 = "";
            }
            try
            {
                var websitename = db.Admin_details.SingleOrDefault();
                var gatewayinfo = db.Gateway_Auth.SingleOrDefault();
                var command = "verify_payment";

                string hashString = gatewayinfo.merchantkey + "|" + command + "|" + txnid + "|" + gatewayinfo.merchantsalt;
                string hashchk = Generatehash512(hashString);
                var client = new RestClient("https://info.payu.in/merchant/postservice.php?form=2");
                client.Timeout = -1;
                var request = new RestRequest(Method.POST);
                request.AddHeader("Content-Type", "application/x-www-form-urlencoded");
                request.AddParameter("key", gatewayinfo.merchantkey);
                request.AddParameter("command", command);
                request.AddParameter("var1", txnid);
                request.AddParameter("hash", hashchk);
                IRestResponse response = client.Execute(request);
                WriteLoggateway("Status CHECK Response " + response.Content, websitename.WebsiteUrl);
                dynamic resp = JsonConvert.DeserializeObject(response.Content);
                var status = (string)resp.transaction_details[txnid].status;
                string mode = resp.transaction_details[txnid].mode;
                string bankcode = resp.transaction_details[txnid].bankcode;
                string bank_ref_num = resp.transaction_details[txnid].bank_ref_num;
                var error_Message = "";
                error_Message = resp.transaction_details[txnid].error_Message;
                if (error_Message == null)
                {
                    error_Message = status;
                }
                var payuMoneyId = "";
                payuMoneyId = resp.transaction_details[txnid].payuMoneyId;
                if (payuMoneyId == null)
                {
                    payuMoneyId = resp.transaction_details[txnid].mihpayid;
                }
                string PG_TYPE = resp.transaction_details[txnid].PG_TYPE;
                if (status == "success")
                {
                    System.Data.Entity.Core.Objects.ObjectParameter output = new
    System.Data.Entity.Core.Objects.ObjectParameter("Output", typeof(string));
                    db.PaymentGateway_Fund(txnid, mode, bankcode, status, bank_ref_num, error_Message, "", "", payuMoneyId, PG_TYPE, output);
                    try
                    {
                        var retailerdetails = db.Retailer_Details.Where(aa => aa.RetailerId == Retailerid).SingleOrDefault();
                        var dealerdetails = db.Dealer_Details.Where(aa => aa.DealerId == retailerdetails.DealerId).SingleOrDefault();
                        var remdetails = db.Remain_reteller_balance.Where(aa => aa.RetellerId == Retailerid).SingleOrDefault();
                        var dlmdetails = db.Remain_dealer_balance.Where(aa => aa.DealerID == retailerdetails.DealerId).SingleOrDefault();

                        var admininfo = db.Admin_details.SingleOrDefault();
                        Backupinfo back = new Backupinfo();

                        var modeln = new Backupinfo.Addinfo
                        {

                            Websitename = admininfo.WebsiteUrl,
                            RetailerID = Retailerid,
                            Email = retailerdetails.Email,
                            Mobile = retailerdetails.Mobile,
                            Details = "Fund Recived",
                            RemainBalance = (decimal)remdetails.Remainamount,
                            Usertype = "Retailer"
                        };
                        back.Fundtransfer(modeln);

                        var model1 = new Backupinfo.Addinfo
                        {
                            Websitename = admininfo.WebsiteUrl,
                            RetailerID = dealerdetails.DealerId,
                            Email = dealerdetails.Email,
                            Mobile = dealerdetails.Mobile,
                            Details = "Fund Transfer",
                            RemainBalance = Convert.ToDecimal(dlmdetails.Remainamount),
                            Usertype = "Dealer"
                        };
                        back.Fundtransfer(model1);

                    }
                    catch { }

                }

                else if (status == "failure" || status == "Not Found")
                {
                    System.Data.Entity.Core.Objects.ObjectParameter output = new
    System.Data.Entity.Core.Objects.ObjectParameter("Output", typeof(string));
                    db.PaymentGateway_Fund(txnid, "", "", "Failure", "", error_Message, "", "", payuMoneyId, "", output);
                }
            }
            catch (Exception ex)
            { }

            DateTime to = txt_to_date.AddDays(1);
            upiChargeAndgateway model = new upiChargeAndgateway();
            var chk11 = db.gateway_report(Retailerid, ddlname1, txt_frm_date, to, ddlstatus).ToList();
            model.GATEWAYREPORT = chk11;
            return PartialView("_Gateway_report", model);

        }

        public string Generatehash512(string text)
        {
            byte[] message = Encoding.UTF8.GetBytes(text);
            UnicodeEncoding UE = new UnicodeEncoding();
            byte[] hashValue;
            SHA512Managed hashString = new SHA512Managed();
            string hex = "";
            hashValue = hashString.ComputeHash(message);
            foreach (byte x in hashValue)
            {
                hex += String.Format("{0:x2}", x);
            }
            return hex;
        }

        public static void WriteLoggateway(string strMessage, string websitename)
        {
            try
            {
                StreamWriter log;
                FileStream fileStream = null;
                DirectoryInfo logDirInfo = null;
                FileInfo logFileInfo;
                string logFilePath = "C:\\Logs\\";
                logFilePath = logFilePath + " STATUSCHECK_PAYMENTGATEWAY " + websitename + " - " + System.DateTime.Today.ToString("MM-dd-yyyy") + "." + "txt";
                logFileInfo = new FileInfo(logFilePath);
                logDirInfo = new DirectoryInfo(logFileInfo.DirectoryName);
                if (!logDirInfo.Exists) logDirInfo.Create();
                if (!logFileInfo.Exists)
                {
                    fileStream = logFileInfo.Create();
                }
                else
                {
                    fileStream = new FileStream(logFilePath, FileMode.Append);
                }
                log = new StreamWriter(fileStream);
                log.WriteLine(strMessage);
                log.Close();
            }
            catch (Exception ex)
            {
            }
        }
