        [HttpPost]
        public ActionResult _Add_purchase(string Apinm, string Banknm, string payeenm, string accountnm, string ifsccode, string comment, string hideemail, string hidephone, string OTP)
        {
            var apinm = db.api_name.Where(aa => aa.apiname.ToUpper() != "VASTBAZAAR").ToList();
            IEnumerable<SelectListItem> selectListss1 = from s in apinm
                                                        select new SelectListItem
                                                        {
                                                            Value = s.apiname,
                                                            Text = s.apiname
                                                        };
            ViewBag.apinm = new SelectList(selectListss1, "Value", "Text");
            var chkotp = db.MobileOtps.Where(aa => aa.Userid == Apinm).OrderByDescending(aa => aa.Date).Take(1).SingleOrDefault().Otp;
            var msg = "";
            if (OTP == chkotp)
            {
                var chkinfobank = db.Purchase_Account_info.Where(aa => aa.APINAME == Apinm).SingleOrDefault();
                if (chkinfobank == null)
                {
                    Purchase_Account_info info = new Purchase_Account_info();
                    info.AccountNo = accountnm;
                    info.APINAME = Apinm;
                    info.bankname = Banknm;
                    info.Comment = comment;
                    info.Ifsccode = ifsccode;
                    info.Payeename = payeenm;
                    info.Status = "Y";
                    info.Mobile = hidephone;
                    info.Email = hideemail;
                    db.Purchase_Account_info.Add(info);
                    db.SaveChanges();
                }
                else
                {
                    msg = "notAllow";
                }
            }
            else
            {
                msg = "OtpMissMatch";
            }
            Purchase_Account model = new Purchase_Account();
            model.infoaccount = db.Purchase_Account_info.ToList();
            model.msg = msg;
            return PartialView("_add_Purchase_Bank", model);
