                    //        //string getallsms = smsstypes.Templates;
                    //        //var regex = new Regex(Regex.Escape("{verb}"));
                    //        //var firststring = regex.Replace(getallsms, mobileno, 1);
                    //        //var secondstr = regex.Replace(firststring, Amount, 1);
                    //        //var fuulmsg = regex.Replace(secondstr, remainbal.ToString(), 1);

                    //        msgssss = string.Format(smsstypes.Templates, hideamt, hidepaymode, infochk.AccountNo, admininfo.Companyname);
                    //        tempid = smsstypes.Templateid;
                    //        urlss = smsapionsts.smsapi;

                    //        //  urlss = smsapionsts.smsapi.Replace("mmm", RetailerDetails.Mobile).Replace("ttt", msgssss).Replace("iii", tempid);



                    //        //  var regex = new Regex(Regex.Escape("{verb}"));
                    //        // regex.Replace(msgbody,)

                    //        smssend.sendsmsallnew(infochk.Mobile, msgssss, urlss, tempid);
