                    smssend.sms_init("Y", "Y", "APIPURCHASE", infochk.Mobile, hideamt, hidepaymode, infochk.AccountNo, admininfo.Companyname);


                    smssend.SendEmailAll(infochk.Email, message, "Recharge", Email);
                    if (status == "Success" || status == "Failed")
