        [HttpPost]
        public ActionResult _Scheduler_add(string Apinm1, string mode, int minhours = 0, decimal minfund = 0, string timerId = "", int sfrequency = 0, int SDaily = 0, decimal samount = 0)
        {
            var bank = db.Purchase_Account_info.Where(aa => aa.Status == "Y").ToList();
            IEnumerable<SelectListItem> selectListss11 = from s in bank
                                                         select new SelectListItem
                                                         {
                                                             Value = s.APINAME,
                                                             Text = s.APINAME
                                                         };
            ViewBag.apinm1 = new SelectList(selectListss11, "Value", "Text");
            SchduleFundInfo model = new SchduleFundInfo();
            int chk = db.schdule_fund.Where(aa => aa.type == mode && aa.Apiname == Apinm1).Count();
            if (chk == 0)
            {
                DateTime dt = DateTime.Now;
                if (timerId != "")
                {
                    dt = Convert.ToDateTime(timerId);
                }
                schdule_fund fund = new schdule_fund();
                fund.Apiname = Apinm1;
                fund.dailysch = SDaily;
                fund.maxhours = minhours;
                fund.minfund = minfund;
                fund.schdulefre = sfrequency;
                fund.status = "Y";
                if (timerId != "")
                {
                    fund.timeset = dt;
                }
                fund.type = mode;
                fund.amount = samount;
                db.schdule_fund.Add(fund);
                db.SaveChanges();
            }
            else
            {
                model.msg = "NotAllow";
                //not allow
            }
            model.infoaccount_Schdule = db.schdule_fund.ToList();
            return PartialView("_Scheduler_History", model);
        }
