        public ActionResult Print_QR(string useriddata)
        {

            var split = useriddata.Split(',');
            QRCODE_Details model = new QRCODE_Details();
            IList<details> lis = new List<details>();

            var remdetails = db.Retailer_Details.Where(aa => aa.ISDeleteuser == false).ToList();
            for (int i = 0; i < split.Length; i++)
            {
                var userid = split[i].ToString();
                var checkapi = "";
                var upi_api = db.UPI_API.SingleOrDefault() ?? null;
                if (upi_api != null)
                {
                    checkapi = db.UPI_API.SingleOrDefault().APIID;
                }
                if (checkapi == "ICICI")
                {
                    var item = db.UPI_Ref_details.Where(aa => aa.userid == userid).SingleOrDefault();
                    details m = new details();
                    m.userid = item.userid;
                    var frmname = remdetails.Where(aa => aa.RetailerId == item.userid).Single().Frm_Name;
                    if (string.IsNullOrEmpty(frmname))
                    {
                        frmname = remdetails.Where(aa => aa.RetailerId == item.userid).Single().RetailerName;
                    }
                    m.firmname = frmname;
                    m.Mobile = remdetails.Where(aa => aa.RetailerId == item.userid).Single().Mobile;
                    var finaltxn = item.UPITxnid;
                    var upiinfo = db.Upi_info.SingleOrDefault();
                    m.MerchantVPA = upiinfo.MerchantVPA;
                    var upitxt = "upi://pay?pa=" + upiinfo.MerchantVPA + "&pn=test&tr=" + finaltxn + "&am=&cu=INR&mc=5411";
                    var barcodeWriter = new BarcodeWriter();
                    barcodeWriter.Format = BarcodeFormat.QR_CODE;
                    barcodeWriter.Options = new ZXing.Common.EncodingOptions
                    {
                        Width = 400,
                        Height = 400,
                        Margin = 4
                    };
                    var result = barcodeWriter.Write(upitxt);
                    var barcodeBitmap = new Bitmap(result);
                    using (MemoryStream memory = new MemoryStream())
                    {
                        using (Bitmap bitMap = barcodeBitmap)
                        {

                            bitMap.Save(memory, ImageFormat.Png);
                            m.QRCODE = "data:image/png;base64," + Convert.ToBase64String(memory.ToArray());
                        }
                    }
                    lis.Add(m);
                }
                else if (checkapi == "PAYU")
                {
                    var item = db.PAYU_QR_info.Where(aa => aa.userid == userid).SingleOrDefault();
                    var frmname = remdetails.Where(aa => aa.RetailerId == item.userid).Single().Frm_Name;
                    if (string.IsNullOrEmpty(frmname))
                    {
                        frmname = remdetails.Where(aa => aa.RetailerId == item.userid).Single().RetailerName;
                    }
                    details m = new details();
                    m.firmname = frmname;
                    m.Mobile = remdetails.Where(aa => aa.RetailerId == item.userid).Single().Mobile;

                    m.userid = item.userid;
                    m.MerchantVPA = item.VPAID;
                    m.QRCODE = item.QRCODE;
                    lis.Add(m);
                }
            }

            model.QRDetails = lis;
            var logoimage = "";
            var logo = db.tblHeaderLogoes.Where(p => p.Role == "ADMIN").ToList();
            if (logo.Count > 0)
            {
                if (logo.SingleOrDefault().Role == "ADMIN")
                {
                    logoimage = logo.Where(p => p.Role == "ADMIN").SingleOrDefault().LogoImage;
                }
            }
            else
            {
                logoimage = "";
            }
            model.logoimage = logoimage;

            ViewBag.allretailer = new SelectList(db.select_retailer_for_ddl("Admin"), "RetailerId", "Frm_Name", null);

            return new ViewAsPdf("Print_QR", model);
        }
