        public ActionResult getapibal(string apinm)
        {
            string bal = "0";
            var apiurl = db.api_name.Where(aa => aa.apiname == apinm).SingleOrDefault().viewbill;
            if (apinm.ToUpper() == "VASTBAZAAR")
            {
                var client = new RestClient("http://api.vastbazaar.com/api/Web/ApiRemain");
                var request = new RestRequest(Method.POST);
                var token = getAuthToken();
                request.AddHeader("Authorization", "Bearer " + token);
                IRestResponse response = client.Execute(request);
                var resp = response.Content;
                dynamic chk = JsonConvert.DeserializeObject(resp);
                bal = chk.Content.ADDINFO;
            }
            else if (apinm == "apiworld")
            {
                var webcontent = callApi(apiurl);
                bal = String.Format("{0:0.00}", Convert.ToDecimal(webcontent.Split(':')[1].Trim()));
            }
            else if (apinm == "mofuse")
            {
                var webcontent = callApi(apiurl);
                dynamic stuff = Newtonsoft.Json.JsonConvert.DeserializeObject(webcontent);
                bal = String.Format("{0:0.00}", Convert.ToDecimal(stuff.bal.ToString()));
            }
            else if (apinm == "Mangalam")
            {
                var webcontent = callApi(apiurl);
                bal = String.Format("{0:0.00}", Convert.ToDecimal(webcontent.Split('|')[0].Trim()));
            }
            else if (apinm == "dukanpay" || apinm == "pay4you")
            {
                Recharge_API_URLS api = db.Recharge_API_URLS.Where(a => a.API_Name == apinm).FirstOrDefault();
                string body = "{\r\n    \"userid\": \"" + api.API_ID + "\",\r\n    \"tokenid\": \"" + api.Token + "\"\r\n}";
                var webcontent = callApi(apiurl, "POST", body);
                dynamic stuff = Newtonsoft.Json.JsonConvert.DeserializeObject(webcontent);
                bal = String.Format("{0:0.00}", Convert.ToDecimal(stuff.Remain.ToString()));
            }
            return Json(bal, JsonRequestBehavior.AllowGet);
        }
        private string callApi(string url, string type = "GET", string body = null)
        {
            if (type.ToUpper() == "GET")
            {
                ServicePointManager.SecurityProtocol = (SecurityProtocolType)3072;
                HttpWebRequest WebRequestObject = (HttpWebRequest)HttpWebRequest.Create(url);
                WebRequestObject.Timeout = (System.Int32)TimeSpan.FromSeconds(125).TotalMilliseconds;
                WebResponse Response = WebRequestObject.GetResponse();
                Stream WebStream = Response.GetResponseStream();
                StreamReader Reader = new StreamReader(WebStream);
                return Reader.ReadToEnd();
            }
            else
            {
                var client = new RestClient(url);
                client.Timeout = -1;
                var request = new RestRequest(Method.POST);
                request.AddHeader("Content-Type", "application/json");
                request.AddParameter("application/json", body, ParameterType.RequestBody);
                IRestResponse response = client.Execute(request);
                return response.Content;
            }
        }
        protected void ApiUserResponse(int Idno, string rch_from, string fid, string status, string operatorId)
        {
            var role = (from rol in db.Roles join user in db.UserRoles on rol.RoleId equals user.RoleId where user.UserId == rch_from select rol.Name).SingleOrDefault().ToString();
            if (role == "API")
            {
                try
                {
                    var url = db.Recharge_Update_Url.Where(aa => aa.UserId == rch_from).SingleOrDefault().responseurl.ToString();
                    var curentbal = db.api_remain_amount.Where(aa => aa.apiid == rch_from).SingleOrDefault().balance.ToString();
                    url = url.Replace("rrr", fid);
                    url = url.Replace("sss", status);
                    url = url.Replace("ooo", operatorId);
                    url = url.Replace("bbb", curentbal);
                    HttpWebRequest WebRequestObject = (HttpWebRequest)HttpWebRequest.Create(url);
                    WebRequestObject.Timeout = (System.Int32)TimeSpan.FromSeconds(25).TotalMilliseconds;
                    WebResponse Response = WebRequestObject.GetResponse();
                    Stream WebStream = Response.GetResponseStream();
                    StreamReader Reader = new StreamReader(WebStream);
                    var webcontent = Reader.ReadToEnd();

                    var liveId = db.Recharge_info.Where(a => a.idno == Idno).SingleOrDefault();
                    if (liveId != null)
                    {
                        Recharge_info obj = (from p in db.Recharge_info where p.idno == Idno select p).SingleOrDefault();
                        obj.API_response = webcontent.ToString();
                        obj.Api_Response_output = url.ToString();
                        db.SaveChanges();
                    }
                    var OldId = db.Recharge_info_old.Where(a => a.idno == Idno).SingleOrDefault();
                    if (OldId != null)
                    {
                        Recharge_info_old obj = (from p in db.Recharge_info_old where p.idno == Idno select p).SingleOrDefault();
                        obj.API_response = webcontent.ToString();
                        obj.Api_Response_output = url.ToString();
                        db.SaveChanges();
                    }
                }
                catch
                {

                }
            }
        }
        public ActionResult timealert()
        {
            var info = db.schdule_fund.Where(aa => aa.status == "Y" && aa.type == "TIME").ToList();
            if (info.Count() > 0)
            {
                foreach (var item in info)
                {
                    var time = item.timeset;
                    var data_time = Convert.ToDateTime(time).ToShortTimeString();
                    DateTime currenttime = DateTime.Now;
                    var cu_time = currenttime.ToShortTimeString();
                    DateTime ddate = Convert.ToDateTime(data_time);
                    DateTime cdate = Convert.ToDateTime(cu_time);
                    if (cdate >= ddate)
                    {
                        var chkinfo = db.Auto_fund_transfer.Where(aa => aa.apiname == item.Apiname && aa.Mode == "TIME").OrderByDescending(aa => aa.txndate).Take(1).SingleOrDefault();
                        double lasthor = 0;
                        double chkhours = 0;
                        if (chkinfo != null)
                        {
                            var current = DateTime.Now;
                            var lasttime = Convert.ToDateTime(chkinfo.txndate);
                            lasthor = (current - lasttime).TotalHours;

                            int schfreq = Convert.ToInt32(item.schdulefre);
                            if (schfreq == 1)
                            {
                                int dailyfreq = Convert.ToInt32(item.dailysch);
                                chkhours = 24 / dailyfreq;
                            }
                            else
                            {
                                chkhours = schfreq * 24;
                            }
                        }
                        if (lasthor >= chkhours)
                        {
                            Vastbillpay pay = new Vastbillpay();
                            var infochk = db.Purchase_Account_info.Where(aa => aa.APINAME == item.Apiname && aa.Status == "Y").SingleOrDefault();
                            if (infochk != null)
                            {
                                var tokn = Responsetoken.gettoken();
                                var Email = db.Admin_details.SingleOrDefault().email;
                                var modee = "IMPS";
                                string ProjectName = Path.GetDirectoryName(Path.GetDirectoryName(Server.MapPath(@"~/HomeControllers.cs")));
                                ProjectName = ProjectName.Substring(ProjectName.LastIndexOf("\\") + 1);
                                var RequestId = DateTime.Now.ToString("dd-MM-yyy hh-mm-ss").Replace("-", "").Replace(" ", "") + ProjectName.Substring(0, 4);

                                var apirequest = "{\r\n  \"customerid\": \"" + Email + "\",\r\n  \"amount\":\"" + item.amount + "\",\r\n  \"comment\":\"" + infochk.Comment + "\",\r\n  \"customeraccountno\":\"" + infochk.AccountNo + "\",\r\n  \"Type\":\"" + modee + "\",\r\n  \"customerbankname\":\"" + infochk.bankname + "\",\r\n  \"customerifsccode\":\"" + infochk.Ifsccode + "\",\r\n  \"accountholdername\":\"" + infochk.Payeename + "\",\r\n  \"Reqid\":\"" + RequestId + "\",\r\n}";

                                System.Data.Entity.Core.Objects.ObjectParameter output = new System.Data.Entity.Core.Objects.ObjectParameter("Output", typeof(string));
                                var idno = db.insert_Auto_fund_transfer(item.amount, apirequest, infochk.AccountNo, infochk.Ifsccode, infochk.Payeename, infochk.bankname, infochk.Comment, item.Apiname, "TIME", output).SingleOrDefault().msg;
                                int inn = Convert.ToInt32(idno);
                                if (inn > 0)
                                {
                                    var responsechk1 = pay.WalletUnloadrRquest(tokn, Email, Convert.ToDecimal(item.amount), infochk.Comment, infochk.AccountNo, infochk.bankname, infochk.Ifsccode, infochk.Payeename, RequestId, "IMPS");
                                    var apiresponse = responsechk1.Content.ToString();
                                    dynamic json = JsonConvert.DeserializeObject(apiresponse);
                                    var respcode = json.Content.ResponseCode.ToString();
                                    var ADDINFO = json.Content.ADDINFO.ToString();
                                    dynamic json1 = JsonConvert.DeserializeObject(ADDINFO);
                                    var status = json1.Status.ToString();
                                    var bankrrn = json1.Message.ToString();
                                    if (status == "Success" || status == "Failed")
                                    {
                                        db.update_Auto_fund_transfer(inn, status, bankrrn, apiresponse);
                                    }
                                }
                            }
                        }
                    }
                }
            }
            return Json("", JsonRequestBehavior.AllowGet);
        }
        public ActionResult FindQR(string amount)
        {
            var qrcode = "";
            var tokenapi = Responsetoken.gettoken();

            var client = new RestClient("http://api.vastbazaar.com/api/Web/findqr");
            var request = new RestRequest(Method.POST);
            request.AddHeader("Authorization", "Bearer " + tokenapi);
            request.AddHeader("Content-Type", "application/json");
            IRestResponse response = client.Execute(request);
            var responsechk = response.Content;
            dynamic outp = JsonConvert.DeserializeObject(responsechk);
            string val = outp.Content.ADDINFO;
            var upitxt = "upi://pay?pa=VWIPL@icici&pn=test&tr=" + val + "&am=" + amount + "&cu=INR&mc=5411";
            var barcodeWriter = new BarcodeWriter();
            barcodeWriter.Format = BarcodeFormat.QR_CODE;
            barcodeWriter.Options = new ZXing.Common.EncodingOptions
            {
                Width = 250,
                Height = 250,
                Margin = 4
            };
            var result = barcodeWriter.Write(upitxt);
            var barcodeBitmap = new Bitmap(result);
            using (MemoryStream memory = new MemoryStream())
            {
                using (Bitmap bitMap = barcodeBitmap)
                {

                    bitMap.Save(memory, ImageFormat.Png);
                    qrcode = "data:image/png;base64," + Convert.ToBase64String(memory.ToArray());
                }
            }
            return Json(qrcode, JsonRequestBehavior.AllowGet);
        }
