        public ActionResult websitepayment(int month, string noofdays, bool gststs)
        {
            VastBazaar1 cb1 = new VastBazaar1();
            var tokenapi = Responsetoken.gettoken();
            var websiteurl = db.Admin_details.SingleOrDefault().WebsiteUrl;
            var totalbusiness = db.totalbusiness().SingleOrDefault().total;

            var client = new RestClient("http://api.vastbazaar.com/api/Web/PaymentNEW");
            var request = new RestRequest(Method.POST);
            request.AddHeader("Authorization", "Bearer " + tokenapi);
            request.AddHeader("Content-Type", "application/json");
            var resp = new
            {
                websiteurl = websiteurl,
                totalbusiness = totalbusiness,
                month = month,
                gststs = gststs,
                type = "WB Manual",
                noofday = noofdays
            };

            var reqbody = JsonConvert.SerializeObject(resp);
            request.AddParameter("application/json", reqbody, ParameterType.RequestBody);
            IRestResponse response = client.Execute(request);
            var responsechk = response.Content;
            dynamic outp = JsonConvert.DeserializeObject(responsechk);
            string val = outp.Content.ADDINFO;
            if (val == "LOW")
            {
                val = "Your Remain Balance Low.";
            }
            else if (val.Contains("Not Enable Now"))
            {
                val = val;
            }
            else
            {
                val = "Your Next Due Date is " + val;
            }

            return Json(val, JsonRequestBehavior.AllowGet);
        }
        public ActionResult websitepaymentAuto()
        {
            try
            {
                bool? sts = false;
                var websts = db.website_auto.SingleOrDefault();
                if (websts != null)
                {
                    sts = websts.Status;
                }
                if (sts == true)
                {
                    var renewaldate = db.Admin_details.SingleOrDefault().RenivalDate;
                    DateTime now = DateTime.Now;
                    DateTime ren = Convert.ToDateTime(renewaldate);

                    double lasthor = (ren - now).TotalHours;
                    if (lasthor < 24)
                    {
                        var tokenapi = Responsetoken.gettoken();
                        var websiteurl = db.Admin_details.SingleOrDefault().WebsiteUrl;
                        var totalbusiness = db.totalbusiness().SingleOrDefault().total;

                        var client = new RestClient("http://api.vastbazaar.com/api/Web/PaymentNEW");
                        var request = new RestRequest(Method.POST);
                        request.AddHeader("Authorization", "Bearer " + tokenapi);
                        request.AddHeader("Content-Type", "application/json");
                        var resp = new
                        {
                            websiteurl = websiteurl,
                            totalbusiness = totalbusiness,
                            month = 1,
                            gststs = true,
                            type = "WB Manual AUTO",
                            noofday = "AUTO"
                        };

                        var reqbody = JsonConvert.SerializeObject(resp);
                        request.AddParameter("application/json", reqbody, ParameterType.RequestBody);
                        IRestResponse response = client.Execute(request);
                        var responsechk = response.Content;
                        dynamic outp = JsonConvert.DeserializeObject(responsechk);
                        string val = outp.Content.ADDINFO;
                        if (val == "LOW")
                        {
                            val = "Your Remain Balance Low.";
                        }
                        else if (val.Contains("Not Enable Now"))
                        {
                            val = val;
                        }
                        else
                        {
                            val = "Your Next Due Date is " + val;
                        }
                    }
                }
                return Json("", JsonRequestBehavior.AllowGet);
            }
            catch { return Json("", JsonRequestBehavior.AllowGet); }
        }

