        public ActionResult PurchaseToken(string service, int quantity)
        {
            if (service == "IRCTC")
            {
                var token = getAuthToken();
                var client = new RestClient("http://api.vastbazaar.com/api/IRCTC/PurchaseToken");
                client.Timeout = -1;
                var request = new RestRequest(Method.POST);
                request.AddHeader("Authorization", "Bearer " + token);
                request.AddHeader("Content-Type", "application/json");
                var req = new
                {
                    Quantity = quantity
                };
                var body = JsonConvert.SerializeObject(req);
                request.AddParameter("application/json", body, ParameterType.RequestBody);
                IRestResponse response = client.Execute(request);
                dynamic resp = JsonConvert.DeserializeObject(response.Content);
                var addinfo = resp.Content.ADDINFO;
                var msg = JsonConvert.SerializeObject(addinfo.Message);
                return Json("", JsonRequestBehavior.AllowGet);
            }
            else
            {
                return Json("", JsonRequestBehavior.AllowGet);
            }
        }
