            {
                ViewBag.localgst = "Y";
            }
            double total = Convert.ToDouble(entries.Where(aa => aa.hsn != "0000").Sum(aa => aa.amount) + (entries.Where(aa => aa.hsn != "0000").Sum(aa => aa.gst)));
            string s = words(total, true).Substring(0, 3);
            if (s == "and")
            {
                s = words(total, true).Remove(0, 4);
            }
            else
            {
                s = words(total, true);
            }
            ViewBag.finalword = s;
