        public ActionResult AdminLogin()
        {
            var chkinfo = db.Login_setting_email_phone.ToList();
            // return View(chkinfo);
            return PartialView("_Modelpopupshowadminsetting", chkinfo);
        }
        public ActionResult updateadminlogin(string name)
        {
            if (name == "mobile")
            {
                var nm = true;
                var chk = db.Login_setting_email_phone.SingleOrDefault();
                if (chk.mobile == true)
                {
                    nm = false;
                }
                if (chk.email == true)
                {
                    chk.mobile = nm;
                }
                db.SaveChanges();
            }
            else if (name == "email")
            {
                var nm = true;
                var chk = db.Login_setting_email_phone.SingleOrDefault();
                if (chk.email == true)
                {
                    nm = false;
                }
                if (chk.mobile == true)
                {

                    chk.email = nm;
                }
                db.SaveChanges();
            }
            var chkinfo = db.Login_setting_email_phone.ToList();
            return PartialView("_Modelpopupshowadminsetting", chkinfo);
            //  return Json("", JsonRequestBehavior.AllowGet);
        }

        public ActionResult RetailerblockIMEI(string typeuser)
        {
            if (typeuser == "Dealer")
            {
                ViewBag.usertype = "Dealer";
                var remlist = db.Dealer_Details.ToList();
                IEnumerable<SelectListItem> selectList = from s in remlist
                                                         select new SelectListItem
                                                         {
                                                             Value = s.DealerId,
                                                             Text = s.FarmName.ToString()
                                                         };

                ViewBag.apiid = new SelectList(selectList, "Value", "Text");
                var chk = (from applogin in db.App_login_imei
                           join dealer in db.Dealer_Details on applogin.userid equals dealer.DealerId
                           select new App_login_Allow_imei
                           {
                               idno = applogin.idno,
                               firmname = dealer.FarmName,
                               email = dealer.Email,
                               userid = applogin.userid,
                               role = "Dealer",
                               imeino = applogin.imeino
                           }).ToList();
                return PartialView("_adminmenu_Block_Imei", chk);
            }
            else if (typeuser == "Master")
            {
                ViewBag.usertype = "Master";
                var remlist = db.Superstokist_details.ToList();
                IEnumerable<SelectListItem> selectList = from s in remlist
                                                         select new SelectListItem
                                                         {
                                                             Value = s.SSId,
                                                             Text = s.FarmName.ToString()
                                                         };

                ViewBag.apiid = new SelectList(selectList, "Value", "Text");
                var chk = (from applogin in db.App_login_imei
                           join master in db.Superstokist_details on applogin.userid equals master.SSId
                           select new App_login_Allow_imei
                           {
                               idno = applogin.idno,
                               firmname = master.FarmName,
                               email = master.Email,
                               userid = applogin.userid,
                               role = "Master",
                               imeino = applogin.imeino
                           }).ToList();
                return PartialView("_adminmenu_Block_Imei", chk);
            }
            else
            {
                ViewBag.usertype = "Retailer";
                var remlist = db.Retailer_Details.Where(aa => aa.ISDeleteuser == false).ToList();
                IEnumerable<SelectListItem> selectList = from s in remlist
                                                         select new SelectListItem
                                                         {
                                                             Value = s.RetailerId,
                                                             Text = s.Frm_Name.ToString()
                                                         };

                ViewBag.apiid = new SelectList(selectList, "Value", "Text");
                var chk = (from applogin in db.App_login_imei
                           join retailer in db.Retailer_Details on applogin.userid equals retailer.RetailerId
