        [HttpPost]
        public ActionResult _common_PaymentGatewaySlab(GatewayPayment model)
        {
            foreach (var item in model.common)
            {
                var entry = db.PaymentGatewaycharge_new_common.Where(aa => aa.userid == item.userid).SingleOrDefault();
                entry.CreditCardsts = item.CreditCardsts;
                entry.DebitCardsts = item.DebitCardsts;
                entry.netbankingsts = item.netbankingsts;
                entry.cashcardsts = item.cashcardsts;
                entry.walletsts = item.walletsts;
                entry.debitupto2000 = item.debitupto2000;
                entry.debitabove2000 = item.debitabove2000;
                entry.rupaydebit = 0;
                entry.creditcard = item.creditcard;
                entry.netbanking = item.netbanking;
                entry.wallet = item.wallet;
                entry.UPI = item.UPI;
                entry.creditcardmin = 100;
                entry.creditcardmax = item.creditcardmax;
                entry.netbankmin = 100;
                entry.netbankmax = item.netbankmax;
                entry.debitmin = 100;
                entry.debitmax = item.debitmax;
                entry.walletmin = 100;
                entry.walletmax = item.walletmax;
                entry.axis = item.axis;
                entry.others = item.others;
                entry.upists = item.upists;
                entry.upimin = 100;
                entry.upimax = item.upimax;
                entry.creditsettlement = item.creditsettlement;
                db.SaveChanges();
            }
            var commonSlab = db.PaymentGatewaycharge_new_common.ToList();
            model.common = commonSlab;
            return PartialView(model);
        }
