        public ActionResult WhatsappPurchase()
        {
            var fromchk = DateTime.Now.Date;
            var tochk = fromchk.AddDays(1);
            ViewBag.API = new SelectList(db.API_all_apiid(), "apiid", "farmname");
            var model = (from m in db.Whatsapp_purchase.
                         Where(aa => aa.purchasedate >= fromchk && aa.purchasedate < tochk)
                         join u in db.api_user_details on m.apiid equals u.apiid
                         select new whatsapppurinfo
                         {
                             apiid = m.apiid,
                             farmname = u.farmname,
                             planname = m.planname,
                             planprice = m.planprice,
                             gst = m.gst,
                             remainpre = m.remainpre,
                             remainpost = m.remainpost,
                             purchasedate = m.purchasedate,
                             renewaldate = m.renewaldate,
                             status = m.status
                         }).OrderByDescending(aa => aa.purchasedate).ToList();
            return View(model);
        }
        [HttpPost]
        public ActionResult WhatsappPurchase(string API, DateTime txt_frm_date, DateTime txt_to_date)
        {
            ViewBag.chk = "post";
            var tochk = txt_to_date.AddDays(1);
            ViewBag.API = new SelectList(db.API_all_apiid(), "apiid", "farmname");
            var model = (from m in db.Whatsapp_purchase.
                         Where(aa => aa.purchasedate >= txt_frm_date && aa.purchasedate < tochk && aa.apiid.Contains(API))
                         join u in db.api_user_details on m.apiid equals u.apiid
                         select new whatsapppurinfo
                         {
                             apiid = m.apiid,
                             farmname = u.farmname,
                             planname = m.planname,
                             planprice = m.planprice,
                             gst = m.gst,
                             remainpre = m.remainpre,
                             remainpost = m.remainpost,
                             purchasedate = m.purchasedate,
                             renewaldate = m.renewaldate,
                             status = m.status
                         }).OrderByDescending(aa => aa.purchasedate).ToList();
            return View(model);
        }

        public ActionResult Gst_Report()
        {
            var date = DateTime.Now.AddMonths(-1);
            var month = date.Month;
            var year = date.Year;
            string d = year + "-" + month + "-01";
            var from = DateTime.Parse(d);
            var to = from.AddMonths(1);
            var list = db.gstreport_monthly(from, to, "retailer").ToList();
            return View(list);
        }

        public ActionResult _Gst_Report(string _date, string role)
        {
            try
            {
                var date = DateTime.Parse(_date);
                var month = date.Month;
                var year = date.Year;
                string d = year + "-" + month + "-01";
                var from = DateTime.Parse(d);
                var to = from.AddMonths(1);
                var list = db.gstreport_monthly(from, to, role).ToList();
                return PartialView(list);
            }
            catch
            {
                var list = new List<gstreport_monthly_Result>();
                return PartialView(list);
            }
        }

