        public object UpdateFields(string set, string set1, string sess)
        {
            char setd = Convert.ToChar("स");
            var save = set.Split(setd);
            var sdddf = "";
            //foreach(var i in save)
            //{
            //    sdddf += i;
            //}
            string[] it = new string[(save.Length / 2)];
            string[] it1 = new string[(save.Length / 2)];
            var it2 = set1.Split(setd);
            var i = 0;
            var i1 = 0;
            var j = 0;
            var j1 = 0;
            foreach (var isd in save)
            {
                if (i % 2 == 0 && isd != "")
                {
                    it[i1] = isd;
                    i1++;
                }
                i++;
            }
            foreach (var isd1 in save)
            {
                if (j % 2 != 0 && isd1 != "")
                {

                    it1[j1] = isd1;
                    j1++;
                }
                j++;
            }

            var check = db.SERVICECOLUMNs.Where(s => s.SERVICESNAME == sess).ToList();
            var checkse = db.SERVICES_DATA_INFO.Where(s => s.SERVICESNAME == sess).ToList();
            if (checkse.Count == 0)
            {
                for (int z = 0; z < it.Length; z++)
                {
                    var values = it[z];
                    var values1 = it1[z];
                    var values3 = it2[z];

                    var check1 = db.SERVICECOLUMNs.Where(s => s.SERVICESNAME == sess && s.header == values).Take(1).SingleOrDefault();
                    check1.header = values1;
                    check1.TYPE = values3;
                    db.SaveChanges();

                }
                return new { Message = "Successfully Updated" };
            }
            else
            {
                return new { Message = "You Cant Update" };
            }

        }

