                var chk1 = db.walletunloadlimits.Where(s => s.userid == i.RetailerId).ToList();
                walletunloadlimit d1 = new walletunloadlimit();
                if (chk1.Count == 0)
                {
                    d1.userid = i.RetailerId;
                    d1.limit = null;
                    d1.updatedate = DateTime.Now;
                    db.walletunloadlimits.Add(d1);
                    db.SaveChanges();
                }
            }
            var chk2 = db.walletunloadlimits.ToList();
            foreach (var i in chk2)
            {
                var chk3 = db.Retailer_Details.Where(s => s.RetailerId == i.userid && s.ISDeleteuser == false).ToList();
                if (chk3.Count == 0)
                {
                    var del = db.walletunloadlimits.Where(s => s.userid == i.userid).Single();
                    db.walletunloadlimits.Remove(del);
                    db.SaveChanges();
                }
            }


            ViewBag.alldealer = new SelectList(db.select_Dealer_for_ddl(), "Dealerid", "FarmName", null).ToList();

            var chk = db.walletunloadlimits.ToList();

            return View(chk);
        }

