        public JsonResult updatemanatroryfild(string fild)
        {
            try
            {
                if (!string.IsNullOrEmpty(fild))
                {
                    var chk = db.manatorypermisions.ToList();
                    if (chk.Count == 0)
                    {
                        manatorypermision d1 = new manatorypermision();
                        d1.skips = "N";
                        d1.gst = "N";
                        d1.agreement = "N";
                        d1.addressproof = "N";
                        db.manatorypermisions.Add(d1);
                        db.SaveChanges();
                    }
                    var chk1 = db.manatorypermisions.SingleOrDefault();
                    if (fild == "S")
                    {
                        if (chk1.skips == "N")
                        {
                            chk1.skips = "Y";
                        }
                        else
                        {
                            chk1.skips = "N";
                        }
                    }
                    else if (fild == "g")
                    {
                        if (chk1.gst == "N")
                        {
                            chk1.gst = "Y";
                        }
                        else
                        {
                            chk1.gst = "N";
                        }
                    }
                    else if (fild == "a")
                    {
                        if (chk1.agreement == "N")
                        {
                            chk1.agreement = "Y";
                        }
                        else
                        {
                            chk1.agreement = "N";
                        }
                    }
                    else if (fild == "p")
                    {
                        if (chk1.addressproof == "N")
                        {
                            chk1.addressproof = "Y";
                        }
                        else
                        {
                            chk1.addressproof = "N";
                        }
                    }
                    else
                    {

                    }
                    db.SaveChanges();
                    chk1 = db.manatorypermisions.SingleOrDefault();
                    return Json(new { Mess = "Success", skip = chk1.skips, gsts = chk1.gst, agreement = chk1.agreement, address = chk1.addressproof }, JsonRequestBehavior.AllowGet);
                }
                else
                {
                    var chk1 = db.manatorypermisions.SingleOrDefault();
                    return Json(new { Mess = "Filed null", skip = chk1.skips, gsts = chk1.gst, agreement = chk1.agreement, address = chk1.addressproof }, JsonRequestBehavior.AllowGet);

                }
            }
            catch
            {
                var chk1 = db.manatorypermisions.SingleOrDefault();
                return Json(new { Mess = "Failed", skip = chk1.skips, gsts = chk1.gst, agreement = chk1.agreement, address = chk1.addressproof }, JsonRequestBehavior.AllowGet);

            }
        }
