        public JsonResult backgroundcolorappsave(string otp, string appc1, string appc2)
        {
            try
            {
                var chj = db.appicons.ToList();
                if (chj[0].users.Trim() == otp.Trim() && !string.IsNullOrEmpty(chj[0].users))
                {

                    var iconData = db.appicons.FirstOrDefault();
                    if (iconData != null)
                    {
                        iconData.updatedate = DateTime.Now;
                    }



                    if (!string.IsNullOrEmpty(appc1) && !string.IsNullOrEmpty(appc2))
                    {
                        var chk = db.backroundColorofapps.ToList();
                        if (chk.Count == 0)
                        {
                            backroundColorofapp d1 = new backroundColorofapp();
                            d1.background_color1 = appc1;
                            d1.background_color2 = appc2;
                            d1.valuex = "";
                            d1.valuey = "";
                            db.backroundColorofapps.Add(d1);
                            db.SaveChanges();
                        }
                        else
                        {
                            var chk1 = db.backroundColorofapps.SingleOrDefault();
                            chk1.background_color1 = appc1;
                            chk1.background_color2 = appc2;
                            db.SaveChanges();
                        }

                        db.SaveChanges();

                        return Json("Success", JsonRequestBehavior.AllowGet);
                    }
                    else
                    {
                        return Json("Please Select Color", JsonRequestBehavior.AllowGet);
                    }
                }
                else
                {
                    return Json("Otp not matched", JsonRequestBehavior.AllowGet);
                }
            }
            catch
            {
                return Json("Failed", JsonRequestBehavior.AllowGet);
            }
        }
        public ActionResult PANAadharVerificationReport()
        {
            DateTime fromdate = DateTime.Today;
            DateTime todate = DateTime.Today.AddDays(1);
            List<PanAadharReportViewModel> result = (from a in db.PANAADHARVERIFICATIONREPORTs
                                                     join b in db.Retailer_Details
                                                     on a.RetailerId equals b.RetailerId
                                                     where a.CreatedAt >= fromdate && a.CreatedAt <= todate
                                                     select new PanAadharReportViewModel
                                                     {
                                                         RetailerId = a.RetailerId,
                                                         TransactionId = a.TransactionId,
                                                         PanCharge = (decimal)a.PanCharge,
                                                         AadharCharge = (decimal)a.AadharCharge,
                                                         ChargeType = a.ChargeType,
                                                         CreatedAt = a.CreatedAt.ToString(),
                                                         RetailerName = b.RetailerName,
                                                         Email = b.Email,
                                                         Mobile = b.Mobile,
                                                         Frm_Name = b.Frm_Name
                                                     }).ToList();
            return View(result);
        }

