        public ActionResult rediantdisform()
        {
            var cheks = db.rediantdistresponses.ToList();
            if (cheks.Count > 0 && (cheks[0].status.ToUpper() == "PENDING" || cheks[0].status.ToUpper() == "APPROVE"))
            {
                return RedirectToAction("Profile");
            }
            ViewBag.message = "";
            var radiantauthchk = db.radiantauths.SingleOrDefault();
            Radiantdmt data = new Radiantdmt();
            var chek = data.Radiantstate(radiantauthchk.clientID, radiantauthchk.clientSecret, radiantauthchk.APIKey);
            if (chek.StatusCode == HttpStatusCode.OK)
            {
                dynamic responseData = Newtonsoft.Json.JsonConvert.DeserializeObject(chek.Content);
                var dis = responseData.dst;
                var states = responseData.states;
                List<rediantdisids> rediantstateList = new List<rediantdisids>();
                foreach (var item in states)
                {
                    rediantdisids d1 = new rediantdisids();
                    d1.id = item.id;
                    d1.state_code = item.state_code;

                    d1.state = item.state;

                    rediantstateList.Add(d1);
                }
                // Use rediantstateList instead of rediantstateids in the Select method
                ViewBag.state = rediantstateList.Select(a => new SelectListItem
                {
                    Text = a.state,
                    Value = a.state_code.ToString()
                }).ToList();
            }
            else
            {
                ViewBag.message = "Server issue";
            }
            return View();
        }
        public ActionResult readiantdstss(int state)
        {
            var radiantauthchk = db.radiantauths.SingleOrDefault();
            Radiantdmt data = new Radiantdmt();
            var chek = data.Radiantstate(radiantauthchk.clientID, radiantauthchk.clientSecret, radiantauthchk.APIKey);

            dynamic responseData = Newtonsoft.Json.JsonConvert.DeserializeObject(chek.Content);
            var dis = responseData.dst;
            List<rediantstateids> rediantstateList = new List<rediantstateids>();

            foreach (var item in dis)
            {
                rediantstateids d1 = new rediantstateids();
                d1.id = item.id;
                d1.state_code = item.state_code;
                d1.dist = item.dist;
                d1.state = item.state;
                rediantstateList.Add(d1);
            }
            var entry = rediantstateList.Where(a => a.state_code == state).ToList();



            return Json(entry, 0);
        }
        [HttpPost]
        public ActionResult rediantdisform(string firstname, string lastname, string email, string phoneno, string address, string dob, string pincode, string landmark, string state, string district, HttpPostedFileBase file, HttpPostedFileBase file1)
        {
            var cheks = db.rediantdistresponses.ToList();
            if (cheks.Count>0 && (cheks[0].status.ToUpper() == "PENDING" || cheks[0].status.ToUpper() == "APPROVE"))
            {
                return RedirectToAction("Profile");
            }
            if (file != null && file.ContentLength > 0)
            {
                if (file1 != null && file1.ContentLength > 0)
                {
                    byte[] fileBytes;
                    using (var ms = new MemoryStream())
                    {
                        file.InputStream.CopyTo(ms);
                        fileBytes = ms.ToArray();
                    }

                    var base64 = Convert.ToBase64String(fileBytes);

                    byte[] fileBytes1;
                    using (var ms = new MemoryStream())
                    {
                        file1.InputStream.CopyTo(ms);
                        fileBytes1 = ms.ToArray();
                    }

                    var base642 = Convert.ToBase64String(fileBytes1);
                    var radiantauthchk1 = db.radiantauths.SingleOrDefault();
                    Radiantdmt data1 = new Radiantdmt();
                    var chek1 = data1.RadiantDistributorCreate(firstname, lastname, email, phoneno, address, dob, pincode, landmark, state, district, base64, base642, radiantauthchk1.clientID, radiantauthchk1.clientSecret, radiantauthchk1.APIKey);
                    dynamic responseData = Newtonsoft.Json.JsonConvert.DeserializeObject(chek1.Content);
                    if (chek1.StatusCode == HttpStatusCode.OK)
                    {
                        var status = responseData.success;
                        var code = responseData.data.code;
                        var statusresponse = responseData.data.status;
                        var id = responseData.data.id;

                        if (status == true)
                        {
                            rediantdistresponse d1 = new rediantdistresponse();
                            d1.id = id;
                            d1.status = statusresponse;
                            d1.requesttime = DateTime.Now;
                            d1.code = code;
                            db.rediantdistresponses.Add(d1);
                            db.SaveChanges();
                        }


                    }

                    ViewBag.message = responseData.message;
                    if (ViewBag.message == "" || ViewBag.message == null)
                    {
                        var erroes = responseData.errors;
                        var set = "";
                        foreach (var item in erroes)
                        {
                            set += item;
                        }
                        ViewBag.message = set;

                    }
                }
                else
                {
                    ViewBag.message = "No Kyc back file provided";
                }
            }
            else
            {
                ViewBag.message = "No Kyc front file provided";
            }
            var radiantauthchk = db.radiantauths.SingleOrDefault();
            Radiantdmt data = new Radiantdmt();
            var chek = data.Radiantstate(radiantauthchk.clientID, radiantauthchk.clientSecret, radiantauthchk.APIKey);
            if (chek.StatusCode == HttpStatusCode.OK)
            {
                dynamic responseData = Newtonsoft.Json.JsonConvert.DeserializeObject(chek.Content);
                var dis = responseData.dst;
                var states = responseData.states;
                List<rediantdisids> rediantstateList = new List<rediantdisids>();
                foreach (var item in states)
                {
                    rediantdisids d1 = new rediantdisids();
                    d1.id = item.id;
                    d1.state_code = item.state_code;

                    d1.state = item.state;

                    rediantstateList.Add(d1);
                }
                //Use rediantstateList instead of rediantstateids in the Select method
                ViewBag.state = rediantstateList.Select(a => new SelectListItem
                {
                    Text = a.state,
                    Value = a.state_code.ToString()
                }).ToList();
            }
            if (ViewBag.message == "Distributor Created Successfully.")
            {
                return RedirectToAction("Profile");
            }
            return View();
        }

