        public ActionResult AddSliderImage(string Image, string catagory, string type, string Language)
        {
            var ImageList = db.sliderimages.ToList();
            if (ImageList.Count < 5)
            {
                var CheckImage = ImageList.Where(x => x.images == Image).FirstOrDefault();
                if (CheckImage == null)
                {
                    var NewImage = new sliderimage()
                    {
                        Category = catagory,
                        Language = Language,
                        Type = type,
                        images = Image
                    };
                    db.sliderimages.Add(NewImage);
                    db.SaveChanges();
                    var UpdateImage = db.sliderimages.ToList();
                    return Json(new { Status = true, data = UpdateImage, Message = "Image Add Successfully." });
                }
                else
                {
                    return Json(new { Status = false, data = ImageList, Message = "This Image Alredy Added" });
                }
            }
            else
            {
                return Json(new { Status = false, data = ImageList, Message = "You can not add more then 5 image." });
            }

        }
        public ActionResult DeleteSliderImage(int idno, string image)
        {
            var ImageList = db.sliderimages.ToList();
            var Image = ImageList.Where(x => x.idno == idno && x.images == image).FirstOrDefault();
            if (Image != null)
            {
                db.sliderimages.Remove(Image);
                db.SaveChanges();
                var UpdateImage = db.sliderimages.ToList();
                return Json(new { Status = true, data = UpdateImage, Message = "Image delete Successfully." });
            }
            else
            {
                return Json(new { Status = false, data = ImageList, Message = "image not found." });
            }
        }

