            if (chk1.Count == 0)
            {
                daywisesettelecomm d1 = new daywisesettelecomm();
                d1.dayscounts = 0;
                d1.minamount = 0;
                d1.maxamount = 0;
                d1.sts = false;
                var dateAndTime1 = DateTime.Now;
                var date1 = dateAndTime1.Date;
                d1.insertdate = date1;
                db.daywisesettelecomms.Add(d1);
                db.SaveChanges();
            }


            var chk = db.daywisesettelecomms.SingleOrDefault();

            chk.dayscounts = dayscount;
            chk.minamount = minimums;
            chk.maxamount = maximum;
            var coutdys = Convert.ToDouble(dayscount);
            var dateAndTime = DateTime.Now;
            var date = dateAndTime.Date;

            chk.insertdate = date.AddDays(coutdys);
            db.SaveChanges();


            return RedirectToAction("daywisecomm");
        }

