        public ActionResult RadiantReferenceLocation()
        {
            var stateList = db.State_Desc
   .Select(a => new SelectListItem { Text = a.State_name, Value = a.State_id.ToString() })
   .ToList();
            ViewBag.state1 = stateList;

            var token = getAuthToken();
            var Url = "http://api.vastbazaar.com";
            var client = new RestClient(Url);
            var request = new RestRequest("/api/Radiant/Clientinfo", Method.POST);
            request.AddHeader("Authorization", "Bearer " + token);
            IRestResponse response = client.Execute(request);
            dynamic resp = JsonConvert.DeserializeObject<dynamic>(response.Content);
            var loiClients = ((IEnumerable<dynamic>)resp.Content.ADDINFO)
    .Select(a => new SelectListItem
    {
        Text = a.ClientName.ToString(),
        Value = a.ClientName.ToString()
    })
    .ToList();

            ViewBag.LOIClient = loiClients;
            var list = db.Loilistreport("").ToList();
            return View(list);
        }
        [HttpPost]
        public ActionResult Add_new_LOI(Insertnewloi Model)
        {
            using (VastwebmultiEntities db = new VastwebmultiEntities())
            {
                var eminfo = db.Admin_details.SingleOrDefault();

                string name = eminfo.Name;
                string cleanName = Regex.Replace(name, @"\s+", "");
                string shortName = cleanName.Length <= 3 ? cleanName : cleanName.Substring(0, 3);
                string uniqueId =
    DateTime.Now.ToString("yyyyMMddHHmmssfff") +
    new Random().Next(1000, 9999);
                uniqueId = shortName + uniqueId;

                var token = getAuthToken();
                var Url = "http://api.vastbazaar.com";
                var client = new RestClient(Url);
                var request = new RestRequest("/api/Radiant/InsertLOIList", Method.POST);
                var json = new
                {
                    Mobile = "Admin",
                    CustomerName = "",
                    PickupAddress = Model.txtpointaddress,
                    Pincode = Model.txtpincode,
                    WorkMode = Model.workmode,
                    CashLimit = Model.txtcashlimit,
                    DepositionMode = Model.Depositmode,
                    AdditionalRequirement = Model.txtAdditionalRequirement,
                    StateId = Model.state1,
                    DistrictId = Model.district1,
                    CityName = Model.txtcity,
                    ClientName = Model.LOIClient,
                    PointMobile = Model.txtpointmobilenumber,
                    PointName = Model.txtpointcontactname,
                    DCCode = Model.txtdiscode,
                    SubDescription = Model.txtSubDescrtion,
                    Reqid = uniqueId,
                    Latitude = Model.txtlat,
                    Longitude = Model.txtlong

                };
                request.AddHeader("Authorization", "Bearer " + token);
                var info = JsonConvert.SerializeObject(json);
                request.AddParameter("application/json", info, ParameterType.RequestBody);
                IRestResponse response = client.Execute(request);
                var sts = false; var msg = "Please Try After Sometime";
                if (response.StatusCode == HttpStatusCode.OK)
                {
                    LoiList list = new LoiList();
                    list.Refnumber = "";
                    list.Insertdate = DateTime.Now;
                    list.Customername = "";
                    list.pickupaddress = Model.txtpointaddress;
                    list.Pincode = Model.txtpincode;
                    list.WorkMode = Model.workmode;
                    list.Cashlimit = Model.txtcashlimit;
                    list.Depositionmode = Model.Depositmode;
                    list.AdditionalRequirement = Model.txtAdditionalRequirement;
                    list.Stateid = Model.state1;
                    list.Districtid = Model.district1;
                    list.CityName = Model.txtcity;
                    list.ClientName = Model.LOIClient;
                    list.PointMobile = Model.txtpointmobilenumber;
                    list.PointName = Model.txtpointcontactname;
                    list.DCCode = Model.txtdiscode;
                    list.SubDescrtion = Model.txtSubDescrtion;
                    list.Status = "Pending";
                    list.Retailerid = "Admin";
                    list.Requestid = uniqueId;
                    list.Latitude = Model.txtlat;
                    list.Longitude = Model.txtlong;
                    db.LoiLists.Add(list);
                    db.SaveChanges();
                    sts = true;
                    msg = "Insert Done";
                }
                var data = new
                {
                    sts,
                    msg
                };
                return RedirectToAction("RadiantReferenceLocation");
            }

        }
