        [HttpGet]
        public async Task<ActionResult> District_Bind(int state_id)
        {
            var districtList = await db.District_Desc
                .Where(d => d.State_id == state_id)
                .Select(d => new
                {
                    text = d.Dist_Desc,
                    value = d.Dist_id
                })
                .ToListAsync();
            return Json(districtList, JsonRequestBehavior.AllowGet);

        }
